/* ==================== ##Clients ==================== */

.wgl-cases {
    display: flex;
    flex-wrap: wrap;
    &:not([data-carousel="yes"]){
        display: grid;
        grid-template-columns: repeat(3, 1fr);
    }
    &__link{
        position: absolute;
        z-index: 2;
        width: 100%;
        height: 100%;
        left: 0;
        top: 0;
    }
    &__button_wrapper{
        width: 100%;
    }
    .read-more-icon{
        font-weight: normal;
        letter-spacing: 0;
    }
    .image_wrapper {
        position: relative;
        z-index: 1;
        display: inline-flex;
        align-items: center;
        overflow: hidden;
        max-width: 100%;
        .icon-wrapper {
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            .wgl-icon {
                position: relative;
                display: flex;
                align-items: center;
                justify-content: center;
                gap: 15px;
                background: transparent;
            }
            .wgl-text_over_image{
                font-family: var(--burido-header-font-family);
                font-weight: var(--burido-header-font-weight);
                font-size: 15px;
                color: transparent;
                transition: inherit;
            }
        }
        .wgl-image-box_img{
            transition: box-shadow .5s;
        }
    }
    .icon_wrapper {
        .wgl-icon {
            position: relative;
            &::after {
                --bubble-top: 0;
                --bubble-left: 0;
                display: none;
                content: '';
                position: absolute;
                top: -1000px;
                left: -1000px;
                right: -1000px;
                bottom: -1000px;
                margin: auto;
                z-index: -1;
                border-radius: 50%;
                transition: 0.4s;
                background-color: #ffffff;
                transform: translate(var(--bubble-left), var(--bubble-top));
            }
        }

    }
    .case_bg_text {
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        z-index: 0;
        font-family: var(--burido-header-font-family);
        font-weight: var(--burido-header-font-weight);
        font-size: 200px;
        letter-spacing: 0;
        line-height: 1em;
        transition: 0.4s;
        height: fit-content;
        margin: auto;
        pointer-events: none;
    }
    .case_title{
        position: relative;
        z-index: 1;
        font-size: 24px;
        line-height: 1.25em;
        font-weight: 600;
        transition: 0.4s;
        span{
            font: inherit;
            line-height: inherit;
            color: inherit;
            letter-spacing: inherit;
            text-decoration: inherit;
            text-transform: inherit;
            transition: text-decoration-color 0.3s;
        }
    }
    .case_subtitle{
        position: relative;
        z-index: 1;
        font-size: 14px;
        line-height: 1.5em;
        font-weight: 500;
        transition: 0.4s;
        span{
            font: inherit;
            line-height: inherit;
            color: inherit;
            letter-spacing: inherit;
            text-decoration: inherit;
            text-transform: inherit;
            transition: text-decoration-color 0.3s;
        }
    }
    .wgl-carousel_wrapper {
        width: 100%;
        overflow: visible;
    }
    .case_items {
        float: left;
        pointer-events: none;
        overflow: hidden;

        &:hover{
            .image_wrapper .wgl-icon{
                background: var(--burido-primary-color);
                .wgl-text_over_image{
                    color: var(--burido-tertiary-color);
                }
            }
        }
    }
    .case_button__wrapper{
        width: 100%;
    }
    .case_items__inner_wrapper {
        display: flex;
        flex-direction: column;
        justify-content: flex-end;
        position: relative;
        pointer-events: auto;
        overflow: hidden;
        &::before {
            content: "";
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            border-radius: inherit;
            transition: inherit;
            transition-property: opacity;
            pointer-events: none;
        }
        &::after {
            content: "";
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            border-radius: inherit;
            transition: inherit;
        }
    }
    .hover_image {
        display: none;
        position: absolute;
        z-index: 1;
        top: 0;
        left: 0;
        visibility: hidden;
    }
    img {
        transition: inherit;
    }
}
.elementor-widget-wgl-cases{
    &.button_{
        &left .case_button__wrapper{
            text-align: left;
        }
        &center .case_button__wrapper{
            text-align: center;
        }
        &right .case_button__wrapper{
            text-align: right;
        }
        &left,
        &center,
        &right {
            .wgl-button {
                width: auto;
            }
            .button__content{
                justify-content: center;
                width: auto;
            }
        }
        &justify {
            .wgl-button {
                width: 100%;
            }
            .button__content{
                justify-content: center;
                width: auto;
            }
        }
        &space-around,
        &space-evenly,
        &space-between {
            .wgl-button,
            .button__content{
                width: 100%;
            }
        }
        &space-around {
            .button__content{
                justify-content: space-around;
            }
        }
        &space-evenly {
            .button__content{
                justify-content: space-evenly;
            }
        }
        &space-between {
            .button__content{
                justify-content: space-between;
            }
        }
    }
}
.elementor-section-full_width {
    .elementor-column-gap-no {
        .elementor-widget-wgl-cases {
            .wgl-carousel {
                .swiper-container{
                    overflow: visible;
                }
            }
        }
    }
}
