/* ==================== ##Button ==================== */

.wgl-button{
    display: inline-flex;
    justify-content: center;
    align-items: center;
    position: relative;
    z-index: 1;
    --button-padding: 22px 29px 22px 29px;
    padding: var(--button-padding, 0);
    --border-color: var(--burido-button-border-idle, 'unset');
    border: 1px solid var(--border-color);
    border-radius: var(--button-border-radius, 15px);
    font-family: var(--burido-header-font-family);
    font-weight: var(--burido-header-font-weight);
    font-size: 14px;
    line-height: 1em;
    letter-spacing: 0.05em;
    color: var(--burido-button-color-idle);
    background-color: var(--burido-button-bg-idle);
    transition: 0.4s;
    gap: var(--wgl-icon-gap, 10px);
    --icon-size: 26px;

    &::after {
        position: absolute;
        z-index: -1;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        border-radius: inherit;
        transition: inherit;
    }
    &:focus,
    &:hover,
    &:active {
        color: var(--burido-button-color-hover);
        background-color: var(--burido-button-bg-hover);
        --border-color: var(--burido-button-border-hover);
        .wgl-icon {
            color: var(--burido-button-color-hover);
        }
    }
    .wgl-icon{
        font-size: var(--icon-size);
        display: inline-flex;
        align-items: center;
        line-height: 0;
        margin: 0;
        padding: 5px;
        border-radius: 10px;
        color: var(--burido-button-color-idle);
        fill: currentColor;
        transition: 0.4s;
        transform: translateY(var(--icon-translate-y, 0)) rotate(var(--icon-rotate, 0)) scale(var(--icon-scale, 1));
        &:not([class*='fa-']){
            font-weight: normal;
        }
    }
    .button__content {
        display: flex;
        justify-content: center;
        align-items: center;
        gap: var(--wgl-icon-gap, 10px);
        position: relative;
        z-index: 2;
        user-select: none;
        transition: gap .5s;
    }

    body &.btn-size {
        &-xl {
            --button-padding: 22px 15px 22px 29px;
            .has-bg_animation.wgl-icon-box & {
                --button-padding: 21px 22px 21px 19px;
                --bg-size: 56px;
            }
        }
        &-lg {
            --button-padding: 20px 14px 20px 24px;
            --wgl-icon-wrapper: 56px;
            .has-bg_animation.wgl-icon-box & {
                --button-padding: 18px 22px 18px 17px;
                --bg-size: 52px;
            }
        }
        &-md {
            font-size: 13px;
            --button-padding: 19px 13px 18px 19px;
            --wgl-icon-wrapper: 52px;
            .has-bg_animation.wgl-icon-box & {
                --button-padding: 16px 26px 16px 16px;
                --bg-size: 48px;
            }
            .wgl-icon {
                --icon-size: 24px;
            }
        }
        &-sm {
            font-size: 12px;
            --button-padding: 17px 12px 17px 19px;
            --wgl-icon-wrapper: 48px;
            .has-bg_animation.wgl-icon-box & {
                --button-padding: 15px 24px 15px 15px;
                --bg-size: 45px;
            }
            .wgl-icon {
                --icon-size: 22px;
            }
        }
    }

    &.align-icon {
        &-left .button__content {
            .wgl-icon {
                text-align: left;
            }
            .button__text{
                text-align: right;
            }
        }
        &-right .button__content {
            flex-direction: row-reverse;
            .wgl-icon {
                text-align: right;
            }
            .button__text{
                text-align: left;
            }
        }
    }
    .icon-wrapper {
        display: inline-flex;
        align-items: center;
        line-height: 0;
        font-weight: normal;
        margin: -1em 0;
        &:empty {
            display: none;
        }
    }
}
.wgl-block-button{
    & > a{
        display: inline-flex;
        justify-content: center;
        align-items: center;
        position: relative;
        z-index: 1;
        padding: 19px 40px;
        border-radius: var(--button-border-radius, 15px);
        font-family: var(--burido-header-font-family);
        font-weight: 600;
        font-size: 16px;
        line-height: 1em;
        letter-spacing: 0;
        transition: 0.4s;
        color: var(--burido-button-color-idle);
        background-color: var(--burido-button-bg-idle);
        border: 1px solid var(--burido-button-border-idle);
        &:focus,
        &:hover,
        &:active {
            color: var(--burido-button-color-hover);
            background-color: var(--burido-button-bg-hover);
            border: 1px solid var(--burido-button-border-hover);
        }
    }
    &.wgl-circle{
        & > a{
            --wgl-circle-size: 122px;
            width: var(--wgl-circle-size);
            height: var(--wgl-circle-size);
        }
        &.has-small-font-size > a{
            --wgl-circle-size: 122px;
        }
        &.has-medium-font-size > a{
            --wgl-circle-size: 150px;
        }
        &.has-large-font-size > a{
            --wgl-circle-size: 180px;
        }
        &.has-x-large-font-size > a{
            --wgl-circle-size: 210px;
        }
    }
}

.elementor-widget-wgl-button {
    .elementor-widget-container {
        font-size: 0;
    }

    &.button-animation-enabled {
        .wgl-button {
            background-repeat: no-repeat;
            background-size: 0 100%;
            background-position: 0 100%;
            transition: 0.8s, background-size 0.8s cubic-bezier(0.65, 0.05, 0.36, 1);
            &:hover {
                background-size: 100% 100%;
            }
        }
    }
}

.has-separated {
    --wgl-icon-gap: -1px;
    --wgl-icon-wrapper: 60px;
    .button__content{
        position: static;
    }
    .media-wrapper{
        position: absolute;
        top: 0;
        bottom: 0;
        margin: auto 0;
    }
    .align-icon-right{
        margin-right: calc(var(--wgl-icon-wrapper) + var(--wgl-icon-gap));
        .media-wrapper{
            left: calc(100% + var(--wgl-icon-gap));
        }
        body .elementor-widget-wgl-button.aspace-around .wgl-button,
        body .elementor-widget-wgl-button.aspace-around .button__content,
        body .elementor-widget-wgl-button.aspace-evenly .wgl-button,
        body .elementor-widget-wgl-button.aspace-evenly .button__content,
        body .elementor-widget-wgl-button.aspace-between .wgl-button,
        body .elementor-widget-wgl-button.aspace-between .button__content{

        }
    }
    .align-icon-left{
        margin-left: calc(var(--wgl-icon-wrapper) + var(--wgl-icon-gap));
        .media-wrapper{
            right: calc(100% + var(--wgl-icon-gap));
        }
    }
    .wgl-icon{
        display: flex;
        align-items: center;
        justify-content: center;
        min-height: var(--wgl-icon-wrapper);
        min-width: var(--wgl-icon-wrapper);
        border-radius: var(--wgl-icon-wrapper);
        color: var(--burido-button-color-idle);
        background-color: var(--burido-button-bg-idle);
    }
    .wgl-button{
        &.btn-size {
            &-xl {
                --button-padding: 22px 29px 22px 29px;
            }
            &-lg {
                --button-padding: 20px 24px 20px 24px;
                .wgl-icon{
                    padding: 15px 14.65px;
                }
            }
            &-md {
                --button-padding: 19px 19px 18px 19px;
                .wgl-icon{
                    padding: 14px 13.65px;
                }
            }
            &-sm {
                --button-padding: 17px 19px 17px 19px;
                .wgl-icon{
                    padding: 13px 12.65px;
                }
            }
        }
        &:focus,
        &:hover,
        &:active {
            .wgl-icon {
                color: var(--burido-button-color-hover);
                background-color: var(--burido-button-bg-hover);
            }
        }
    }
}

.has-highlight_animation {
    .highlight_svg {
        position: absolute;
        top: -55px;
        left: -20px;
        width: calc(100% + 50px);
        height: calc(100% + 110px);
        overflow: visible;
        path {
            stroke: white;
            stroke-width: 2;
            fill: none;
            opacity: 0;
            stroke-dasharray: 0 1500;
            transition: 0.3s;
        }
        &.active {
            path {
                animation: wgl-headline-dash forwards;
                animation-duration: var(--animation-duration, 1.2s);
                animation-iteration-count: 1;
                + path {
                    animation-delay: 350ms;
                }
            }
        }
        &.hide-highlight {
            path {
                opacity: 1;
                stroke-dasharray: 1500 1500;
                animation: wgl-hide-highlight 0.4s forwards;
                animation-iteration-count: 1;
            }
        }
    }
    @media (max-width: 1024px) {
        .highlight_svg:not(.active) {
            path {
                animation: wgl-headline-dash forwards;
                animation-duration: var(--animation-duration, 1.2s);
                animation-iteration-count: 1;
            }
        }
        .highlight_svg.active {
            path {
                opacity: 1;
                stroke-dasharray: 1500 1500;
                animation: wgl-hide-highlight 0.4s forwards;
                animation-iteration-count: 1;
            }
        }
    }
}

.has-bg_animation{
    .wgl-button{
        background-color: transparent;
        border: unset !important;
        --button-padding: 21px 25px 21px;
        --border-color: var(--burido-button-bg-idle);
        color: var(--burido-header-font-color);
        &::after{
            content: '';
            background-color: var(--burido-button-bg-idle);
            width: var(--bg-size, 56px);
            height: var(--bg-size, 56px);
            border: 1px solid var(--border-color);
        }
        &:focus,
        &:hover,
        &:active{
            color: var(--burido-button-color-idle);
            .wgl-icon{
                color: var(--burido-button-color-idle);
            }
        }
        .wgl-icon{
            color: var(--burido-button-color-idle);
        }
        .button__content{
            --wgl-icon-gap: 30px;
        }
    }
}
.has-border_animation{
    .wgl-button{
        --ab-width: 1;
        --ab-offset: 6;
        --ab-extend: 4;
        --ab-color: var(--burido-button-border-hover);
        color: var(--burido-button-color-hover);
        background-color: var(--burido-button-bg-hover);
        border-color: var(--burido-button-border-hover);
        &::before,
        &::after{
            content: '';
            color: var(--ab-color);
            position: absolute;
            pointer-events: none;
            opacity: 1;
            transition: .7s cubic-bezier(0.65, 0, 0.6, 1.55);
        }
        &::before{
            top: 0;
            left: 100%;
            width: calc(1px * var(--ab-width));
            height: calc(100% + calc(1px * var(--ab-extend)));
            border-right: calc(1px * var(--ab-width)) solid currentColor;
            transform: translate(calc(1px * var(--ab-offset)), calc(1px * var(--ab-offset) + 4px));
        }
        &::after{
            top: 100%;
            left: 0;
            width: calc(100% + calc(1px * var(--ab-extend)));
            height: calc(1px * var(--ab-width));
            border-bottom: calc(1px * var(--ab-width)) solid currentColor;
            transform: translate(calc(1px * var(--ab-offset) + 4px), calc(1px * var(--ab-offset)));
        }
        &:focus,
        &:hover,
        &:active{
            &::before{
                height: 0;
                transform: translate(calc(1px * var(--ab-offset)), -16px);
            }
            &::after{
                width: 0;
                transform: translate( -16px, calc(1px * var(--ab-offset)));
            }
            &::before,
            &::after{
                opacity: 0;
                transition: .5s, opacity .3s .2s;
            }
        }
    }
    &.revers .wgl-button{
        &::before{
            height: 0;
            transform: translate(calc(1px * var(--ab-offset)), -16px);
        }
        &::after{
            width: 0;
            transform: translate( -16px, calc(1px * var(--ab-offset)));
        }
        &::before,
        &::after{
            opacity: 0;
            transition: .7s .2s, opacity .5s .4s;
        }
        &:focus,
        &:hover,
        &:active{
            &::before{
                height: calc(100% + 4px);
                transform: translate(calc(1px * var(--ab-offset)), calc(1px * var(--ab-offset) + 4px));
            }
            &::after{
                width: calc(100% + 4px);
                transform: translate(calc(1px * var(--ab-offset) + 4px), calc(1px * var(--ab-offset)));
            }
            &::before,
            &::after{
                opacity: 1;
                transition: .7s cubic-bezier(0.65, 0, 0.6, 1.55);
            }
        }
    }
}
.has-magnetic {
    .wgl-button{
        transition: all .4s, transform .2s;
    }
}
.has-icon_visibility {
    &.icon-visibility {
        &-default,
        &-revert{
            .wgl-button {
                .button__content{
                    transition: gap 0.4s;
                }
                .wgl-icon {
                    width: var(--icon-wr-size, var(--icon-size));
                    height: var(--icon-size);
                    box-sizing: content-box;
                }
                .icon-wrapper{
                    margin: -1em 0 !important;
                }
            }
        }
        &-default {
            .wgl-infobox__link:not(:hover) ~ .wgl-infobox_wrapper .wgl-button,
            .wgl-infobox_wrapper:first-child .wgl-button:not(:hover),

            .wgl-cases__link:not(:hover) ~ .case_button__wrapper .wgl-button,
            .wgl-cases__link:first-child .wgl-button:not(:hover),

            .wgl-striped__link:not(:hover) ~ .service-item_wrapper .wgl-button,
            .wgl-striped__link:first-child .wgl-button:not(:hover),

            &.elementor-widget-wgl-button .wgl-button:not(:hover){
                .button__content{
                    --wgl-icon-gap: 0 !important;
                }
                .wgl-icon {
                    transform: translateY(var(--icon-translate-y, 0)) rotate(var(--icon-rotate, 0)) scale(0);
                    --icon-wr-size: 0;
                    opacity: 0;
                    padding-right: 0;
                    padding-left: 0;
                }
            }
        }
        &-revert {
            .wgl-infobox__link:hover ~ .wgl-infobox_wrapper .wgl-button,
            .wgl-cases__link:hover ~ .case_button__wrapper .wgl-button,
            .wgl-striped__link:hover ~ .service-item_wrapper .wgl-button,
            .wgl-button:hover{
                .button__content{
                    --wgl-icon-gap: 0 !important;
                }
                .wgl-icon {
                    transform: translateY(var(--icon-translate-y, 0)) rotate(var(--icon-rotate, 0)) scale(0);
                    --icon-wr-size: 0;
                    opacity: 0;
                    padding-right: 0;
                    padding-left: 0;
                }
            }
        }
    }
}

.has-icon_size_animation .wgl-button,
.rm_has-icon_size_animation .button-read-more{
    --wgl-icon-gap: 12px;
    --button-padding: 21px 19px 21px 26px;
    .wgl-icon {
        --icon-bg-size: 8;
        --icon-scale: 0;
        position: relative;
        color: var(--burido-button-bg-idle);
        &::before {
            content: '';
            position: absolute;
            top: -100px;
            right: -100px;
            bottom: -100px;
            left: -100px;
            margin: auto;
            font-size: calc(var(--icon-bg-size) * 1px);
            width: 1em;
            height: 1em;
            border-radius: 50%;
            background-color: var(--burido-button-color-idle);
            pointer-events: none;
            transform: translateY(var(--icon-translate-y, 0)) scale( var(--icon-bg-scale, 1) );
            transition: background-color 0.4s, transform 0.4s;
        }
    }
    .wgl-icon {
        background: unset !important;
        border: unset !important;
        padding: 0 !important;
    }
    &:hover,
    &:focus,
    &:active {
        .wgl-icon {
            --icon-scale: 0;
        }
    }
}

// ↓ Alignment
body {
    @mixin wgl-button-responsive($media) {
        .elementor-widget-wgl-button {
            &.a#{$media} {
                &left,
                &center,
                &right {
                    .wgl-button {
                        width: auto;
                    }
                    .button__content{
                        width: auto;
                    }
                }
                &justify {
                    .wgl-button {
                        width: 100%;
                    }
                    .button__content{
                        width: auto;
                    }
                }
                &space-around,
                &space-evenly,
                &space-between {
                    .wgl-button,
                    .button__content{
                        width: 100%;
                    }

                    &.has-separated .wgl-button{
                        width: calc(100% - var(--wgl-icon-wrapper) - var(--wgl-icon-gap));
                    }
                }
            }
        }
    }
    @include wgl-button-responsive('');
    &:is(
        [data-elementor-device-mode='tablet_extra'],
        [data-elementor-device-mode='tablet'],
        [data-elementor-device-mode='mobile_extra'],
        [data-elementor-device-mode='mobile']) {
        @include wgl-button-responsive('-tablet');
    }
    &:is(
        [data-elementor-device-mode='mobile_extra'],
        [data-elementor-device-mode='mobile']) {
        @include wgl-button-responsive('-mobile');
    }
}
// ↑ alignment

@keyframes wgl-headline-dash {
    from {
        stroke-dasharray: 0 1500;
        opacity: 1;
    }
    to {
        stroke-dasharray: 1500 1500;
        opacity: 1;
    }
}

@keyframes wgl-hide-highlight {
    from {
        opacity: 1;
        stroke-dasharray: 1500 1500;
    }
    to {
        opacity: 0;
        filter: blur(10px);
    }
}


/* WIDGETS READ MORE*/
.button-read-more {
    --icon-size: 20px;
    .wgl-infobox &,
    .wgl-cases &,
    .wgl-timeline-vertical &,
    .wgl-striped-services &,
    .wgl-flipbox &{
        gap: var(--wgl-icon-gap, 4px);
        margin: 0;
        padding: 0;
        &::after{
            display: none;
        }
    }
    .wgl-icon{
        font-size: var(--icon-size);
        display: inline-flex;
        align-items: center;
        line-height: 0;
        margin: -0.5em 0;
        padding: 0;
        transition: 0.4s;
        transform: translateY(var(--icon-translate-y, 0)) rotate(var(--icon-rotate, 0)) scale(var(--icon-scale, 1));
    }
    .read-more-icon{
        &:not([class*='fa-']){
            font-weight: normal;
        }
    }
}
.rm_has-underline_animation{
    .button-read-more{
        &::before {
            display: block;
            content: "";
            position: absolute;
            z-index: 0;
            bottom: 0;
            left: -3px;
            width: 100%;
            height: 4px;
            background: var(--burido-primary-color);
            transition: 0.4s;
        }
    }
    .button-read-more:hover,
    .wgl-infobox__link:hover ~ .wgl-infobox_wrapper .button-read-more{
        --icon-rotate: -45deg;
        &::before {
            height: 100%;
        }
    }
}
