/* ==================== ##Combo Menu ==================== */

.wgl-combo-menu{
	.menu-item{
		display: flex;
		align-items: center;
		&:first-child{
			margin-top: 0 !important;
		}
		&:last-child{
			margin-bottom: 0 !important;
		}
		&:hover{
			.menu-item_title{
				color: var(--burido-header-font-color);
			}
		}
		&_title{
			font-family: var(--burido-header-font-family);
			margin-right: 20px;
			font-size: 20px;
			font-weight: 500;
			line-height: 1.333;
			transition: 0.4s;
			color: var(--burido-header-font-color);
			letter-spacing: 0;
			order: 1;
		}
		&_price{
			order: 3;
			margin-left: 20px;
			font-family: var(--burido-header-font-family);
			font-weight: 500;
			font-size: 20px;
			line-height: 1.333;
			color: var(--burido-tertiary-color);
		}
		&_desc{
			font-size: 13px;
			font-weight: 500;
			color: #949494;
			line-height: 1.4em;
		}
		&_content{
			display: flex;
			align-items: baseline;
			&::after{
				content: '';
				width: 100%;
				min-width: 20px;
				height: 1px;
				flex: 1;
				order: 2;
				border-bottom: 1px solid;
				border-color: var(--burido-primary-color);
			}
		}
		&_content-wrap{
			flex: 1;
		}
		&_image-wrap{
			align-self: flex-start;
		}
	}
}