//* ==================== ##Instagram ==================== */

.wgl-instagram {
    position: relative;
    .instagram__wrapper {
        transition: 0.4s;
        &.wgl_col-12{
            &:nth-child(2),
            &:nth-child(n + 3) {
                clear: left;
            }
        }
        &.wgl_col-6{
            &:nth-child(3),
            &:nth-child(2n + 5) {
                clear: left;
            }
        }
        &.wgl_col-4{
            &:nth-child(4),
            &:nth-child(3n + 7) {
                clear: left;
            }
        }
        &.wgl_col-3{
            &:nth-child(5),
            &:nth-child(4n + 9) {
                clear: left;
            }
        }
        &.wgl_col-1-5{
            &:nth-child(6),
            &:nth-child(5n + 11) {
                clear: left;
            }
        }
    }
    .instagram__item {
        position: relative;
        z-index: 1;
        transform: translate(0);
        transition: inherit;
        &::before{
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            pointer-events: none;
            z-index: 1;
        }
        &:hover{
            .item__icon{
                &::after{
                    animation-play-state: running;
                }
            }
        }
    }
    .item__header{
        display: flex;
        justify-content: space-between;
        align-items: center;
    }
    .item__content{
        .item_image{
            position: relative;
            overflow: hidden;
            display: inline-block;
            vertical-align: top;
            img{
                transition: transform .3s ease-in-out;
            }

            &::after,&::before{
                content: '';
                position: absolute;
                left: 0;
                top: 0;
                right: 0;
                bottom: 0;
                pointer-events: none;
                transition: 0.4s;
            }
            &::after{
                opacity: 0;
                background-color: rgba(var(--burido-secondary-rgb), 0.3);
            }
            &:hover {
                &::before{
                    opacity: 0;
                }
                &::after{
                    opacity: 1;
                }
            }
        }
    }
    .item__author {
        display: flex;
        align-items: center;
        justify-content: center;
        line-height: 1;
    }
    .author__meta {
        display: flex;
        flex-direction: column;
    }
    .author__name {
        font-size: 14px;
        line-height: 1.3;
        font-weight: var(--burido-header-font-weight);
        transition: 0.4s;
        padding-bottom: 19px;
        color: var(--burido-header-font-color);
        font-family: var(--burido-header-font-family);
        a {
            font-weight: inherit;
            font-family: inherit;
            color: inherit;
            line-height: inherit;
            font-size: inherit;
        }
        @media (max-width: 600px) {
            font-size: 18px;
        }
    }
    .item__icon{
        display: block;
        font-size: 24px;
        line-height: 1em;
        position: absolute;
        z-index: 2;
        right: 0;
        margin: -15px -8px 0 0px;
        &::before{
            display: inline-block;
            content: '\f16d';
            font-family: 'Font Awesome 5 Brands';
            position: static;
            min-width: 1em;
            min-height: 1em;
            line-height: 1em;
            font-style: normal;
            color: var(--burido-primary-color);
        }
        &::after{
            content: '';
            position: absolute;
            top: 0.36em;
            left: 0.37em;
            width: .8em;
            height: .8em;
            z-index: -1;
            background-color: rgba(var(--burido-primary-rgb), 0.08);
            border-radius: 50%;
            transition: 0.4s;
        }
        a{
            display: block;
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
        }
    }
    .item__info {
        position: relative;
        font-size: 14px;
        line-height: 1.857142em;
        color: var(--burido-primary-color);
        p:last-child {
            margin-bottom: 0;
        }

        .likes_count{
            font-size: 14px;
            font-family: var(--burido-header-font-family);
            font-weight: var(--burido-header-font-weight);
            color: var(--burido-header-font-color);
            margin: 0 0 6px 0;
            &.show_icon{
                .wgl-svg-icon{
                    display: inline-block;
                }
            }
            .wgl-svg-icon{
                display: none;
                font-size: 1em;
                color: inherit;
                margin-right: 6px;
                transform: translateY(2px);
            }
        }
    }
    .author__thumbnail {
        flex-shrink: 0;
        padding-right: 17px;
        padding-bottom: 19px;
        img {
            display: inline-block;
        }
    }

    .wgl-carousel:not(.animation-style-3d) {
        .wgl-carousel_wrapper {
            overflow: visible;
            margin: 0 -15px;
            .swiper-wrapper {
                padding: 0 15px;
            }
        }
    }
}

@media (max-width: 1300px) {
    .wgl-instagram {
        .row{
            .wgl_col-1-5 {
                width: 33.333333%;

                &:nth-child(4),
                &:nth-child(3n + 7) {
                    clear: left;
                }
                &:nth-child(6),
                &:nth-child(5n + 11) {
                    clear: none;
                }
            }
        }

    }
}


@media (max-width: 1024px) {
    .wgl-instagram {
        .row{
            .wgl_col-3{
                width: 33.333333%;
                &:nth-child(5),
                &:nth-child(4n + 9) {
                    clear: none;
                }
                &:nth-child(4),
                &:nth-child(3n + 7) {
                    clear: left;
                }
            }
        }
    }
}


@media (max-width: 768px) {
    .wgl-instagram {
        .row{
            .wgl_col-3,
            .wgl_col-4,
            .wgl_col-1-5 {
                width: 100%;
            }
        }

    }
}
