/* ==================== ##Page Title ==================== */

.page-header {
    display: flex;
    align-items: center;
    position: relative;
    z-index: 1;
    padding: 10px 0;
    &_wrapper {
        height: inherit;
        .wgl-container {
            height: 100%;
        }
    }
    .page-header_content {
        height: 100%;
        position: relative;
        z-index: 1;
    }

    &_align_left {
        justify-content: flex-start;
        .page-header_content {
            align-items: flex-start;
            text-align: left;
        }
    }
    &_align_center {
        justify-content: center;
        .page-header_content {
            align-items: center;
            text-align: center;
        }
    }
    &_align_right {
        justify-content: flex-end;
        .page-header_content {
            align-items: flex-end;
            text-align: right;
        }
    }

    &.breadcrumbs_align_left .page-header_breadcrumbs {
        align-self: flex-start;
        text-align: left;
    }
    &.breadcrumbs_align_center .page-header_breadcrumbs {
        align-self: center;
        text-align: center;
    }
    &.breadcrumbs_align_right .page-header_breadcrumbs {
        align-self: flex-end;
        text-align: right;
    }

    &.breadcrumbs_inline {
        .page-header_content {
            flex-direction: row;
            align-items: center;
            display: flex;
            .page-header_title {
                padding: 0;
            }
            @media (max-width: 767px) {
                flex-direction: column;
                .page-header_breadcrumbs {
                    text-align: center;
                }
                .page-header_title {
                    text-align: center;
                    padding-bottom: 15px;
                }
            }
            .page-header_breadcrumbs {
                align-self: auto;
            }
        }
        &.page-header_align_left {
            .page-header_content {
                justify-content: space-between;
            }
        }
        &.page-header_align_right {
            .page-header_content {
                justify-content: space-between;
                flex-direction: row-reverse;
            }
        }
        &.page-header_align_center {
            .page-header_breadcrumbs {
                margin-left: 20px;
            }
        }
    }
    &_title {
        font-family: var(--burido-header-font-family);
        font-weight: var(--burido-header-font-weight);
        color: inherit;
        font-size: clamp(40px, 7.3vw, var(--pt-font-size));
        line-height: clamp(50px, 8.35vw, var(--pt-line-height));
        & + .page-header_breadcrumbs {
            padding-top: 12px;
        }
    }
    &_breadcrumbs {
        .breadcrumbs {
            white-space: nowrap;
            font-weight: 600;
            .current {
                cursor: default;
                background-repeat: no-repeat;
                background-size: 100% 0.25em;
                background-position: 0% 80%;
                transition: background-size 0.8s 0s;
                background-image: linear-gradient(to top, var(--burido-primary-color), var(--burido-primary-color));
            }
            > a {
                color: inherit;
                letter-spacing: inherit;
                background-repeat: no-repeat;
                background-size: 0% 0.25em;
                background-position: 0% 80%;
                transition: background-size 0.8s 0s;
                background-image: linear-gradient(to top, var(--burido-primary-color), var(--burido-primary-color));
                &:hover {
                    color: inherit;
                    background-size: 100% 0.25em;
                }
            }
        }
        .divider:not(:last-child) {
            color: inherit;
            margin: 0 10px;
            transform: translateY(4px);
            display: inline-block;
            font-size: 18px;
        }
    }
    &_wrapper_product {
        .page-header_breadcrumbs {
            margin-top: 23px;
        }
    }
}
@keyframes pagetitle_dot {
    0% {
        opacity: 1;
    }
    100% {
        opacity: 0;
    }
}