/* ==================== ##Lists Style ==================== */

body {
    ul,
    ol {
        margin-left: 0;
        padding-left: 1em;
        li {
            position: relative;
            z-index: 1;
            margin-bottom: 0.7em;
        }
        > li:last-child {
            padding-bottom: 0;
            margin-bottom: 0;
        }
    }
    ol {
        list-style: none;
        padding-left: 0.9em;
    }
}
ol,
ul[class*='burido_']{
    li{
        --burido-list-icon-color: currentColor;
        &::before {
            color: var(--burido-list-icon-color);
        }
    }
    &.list_primary_color li {
        --burido-list-icon-color: var(--burido-primary-color);
    }
    &.list_secondary_color li {
        --burido-list-icon-color: var(--burido-secondary-color);
    }
    &.list_tertiary_color li {
        --burido-list-icon-color: var(--burido-content-color);
    }
    &.list_quaternary_color li {
        --burido-list-icon-color: var(--burido-header-font-color);
    }
    &.list_heading_color li {
        --burido-list-icon-color: var(--burido-header-font-color);
    }
    .burido_disabled_item {
        &,
        &::before,
        &::after,
        span, div, b, strong, i {
            color: #858585;
            --burido-list-icon-color: currentColor;
        }
        &::before,
        &::after{
            opacity: 0.7;
        }
    }
}
ul {
    &[class*='burido_'] {
        --icon-size: 1em;
        --icon-position: calc(0px);
        --burido-list-padding: calc(1em + 10px);
        margin-left: 0;
        padding-left: 0;
        li {
            list-style: none;
            padding-left: var(--burido-list-padding);
            &::before {
                content: '';
                position: absolute;
                z-index: 1;
                border-radius: unset;
                font-family: 'Font Awesome 5 Free';
                font-weight: normal;
                box-sizing: border-box;
                transform: translateY(var(--icon-position));
            }
        }
        &.icon_right {
            li {
                padding-left: 0;
                padding-right: var(--burido-list-padding);
                &::before {
                    left: unset;
                    right: 0;
                }
            }
        }
    }
    &.burido_dot li {
        --icon-size: 8px;
        --burido-list-padding: calc(1em + 4px);
        &::before {
            top: 0.7em;
            left: 0;
            width: var(--icon-size);
            height: var(--icon-size);
            border-radius: 50%;
            background-color: var(--burido-list-icon-color);
        }
    }
    &.burido_hyphen {
        --icon-size: 1em;
        --burido-list-padding: calc(1em + 4px);
        li::before {
            content: '-';
            top: -0.15em;
            left: 0;
            font-size: var(--icon-size);
        }
    }
    &.burido_plus {
        --icon-size: 1.1em;
        li::before {
            display: block;
            content: "";
            mask-image: var(--burido-close-h);
            mask-position: center center;
            mask-size: 1em;
            mask-repeat: no-repeat;
            width: 1em;
            height: 1em;
            padding: 0;
            box-shadow: none;
            background-color: currentColor;
            font-style: normal;
            font-variant: normal;
            text-transform: none;
            line-height: 1;
            font-size: var(--icon-size);
            top: 0.35em;
            left: -0.1em;
            transform: rotate(45deg);
        }
    }
    &.burido_line {
        --icon-size: calc(1em - 2px);
        li::before {
            top: 0.9em;
            left: 0;
            width: var(--icon-size);
            height: 2px;
            background-color: var(--burido-list-icon-color);
        }
    }
    &.burido_circle  {
        --icon-size: 12px;
        li::before {
            top: 0.6em;
            left: 0;
            width: var(--icon-size);
            height: var(--icon-size);
            border-radius: 50%;
            border: 2px solid var(--burido-list-icon-color);
            background-color: transparent;
        }
    }
    &.burido_square {
        --icon-size: 8px;
        --burido-list-padding: calc(1em + 4px);
        li::before {
            top: 0.75em;
            left: 0;
            width: var(--icon-size);
            height: var(--icon-size);
            background-color: var(--burido-list-icon-color);
        }
    }
    &.burido_rhombus {
        --icon-size: 5px;
        --burido-list-padding: calc(1em + 4px);
        li::before {
            top: 0.8em;
            left: 1px;
            width: var(--icon-size);
            height: var(--icon-size);
            transform: rotate(45deg);
            background: var(--burido-list-icon-color);
        }
    }
    &.burido_check {
        --icon-size: 1em;
        li::before {
            display: block;
            content: "";
            mask-image: var(--burido-check-h);
            mask-position: center center;
            mask-size: 1em;
            mask-repeat: no-repeat;
            width: 1em;
            height: 1em;
            padding: 0;
            box-shadow: none;
            background-color: currentColor;
            font-style: normal;
            font-variant: normal;
            font-size: var(--icon-size);
            text-transform: none;
            line-height: 1;
            top: 0.5em;
            left: -0.3em;
        }
    }
    &.burido_arrow {
        --icon-size: 1.2em;
        li::before {
            display: block;
            content: "";
            mask-image: var(--burido-arrow-down-right-h);
            mask-position: center center;
            mask-size: 1em;
            mask-repeat: no-repeat;
            width: 1em;
            height: 1em;
            padding: 0;
            box-shadow: none;
            background-color: currentColor;
            font-style: normal;
            font-variant: normal;
            text-transform: none;
            line-height: 1;
            font-size: var(--icon-size);
            top: 0.3em;
            left: -0.1em;
        }
    }
    &.burido_star {
        --icon-size: 1.1em;
        --burido-list-padding: calc(1em + 4px);
        li::before {
            content: "*";
            font-family: var(--burido-header-font-family);
            top: 0.55em;
            left: 0;
            font-size: var(--icon-size);
            font-weight: 700;
            line-height: 1.05;
            background: transparent;
        }
    }
    &.no-list-style {
        padding: 0;
        li {
            padding: 0;
            list-style: none;
            &::before {
                display: none;
            }
        }
    }
    &.icon_inline {
        li {
            padding: 0;
            &::before,
            &::after {
                margin-right: 10px;
                margin-bottom: 1px;
                display: inline-block;
                position: initial;
            }
        }
        &.burido_star {
            li::before {
                transform: translateY(6px);
                line-height: 0;
            }
        }
    }
    &.list_primary_bg_color {
        li {
            padding-left: 3em;
            letter-spacing: -0.03em;
            &::before,
            &::after {
                width: 2.125em;
                height: 2.125em;
                line-height: 2.125em;
                top: -0.15em;
                left: 0;
            }
            &::after {
                content: '';
                position: absolute;
                z-index: 0;
                text-align: center;
                border-radius: 50%;
                background: var(--burido-primary-color);
            }
            &:not(:last-child) {
                margin-bottom: 1.2em;
            }
        }
    }
}
body ol {
    counter-reset: li;
    @for $i from 1 through 30 {
        &[start='#{$i}'] {
            $i: $i - 1;
            counter-reset: li $i;
        }
    }
    > li {
        position: relative;
        counter-increment: li;
        &::before {
            //* https://www.w3.org/Style/Examples/007/color-bullets.en.html
            content: '.' counter(li);
            display: inline-block;
            position: static;
            width: auto;
            height: auto;
            margin-left: -0.9em;
            margin-right: calc(0.25em + 6px);
            line-height: inherit;
            font-weight: 500;
            direction: rtl;
        }
    }
}
body ul ol > li::before {
    top: 0;
    background-color: transparent !important;
}
body li {
    ul{
        margin-top: 10px;
        margin-bottom: 10px;
    }
    ol {
        margin-top: 10px;
        margin-bottom: 10px;
        padding-bottom: 0;
    }
}
