/* ==================== ##Showcase ==================== */
@mixin showcase_hover {
    .showcase__title{
        color: rgba(var(--burido-header-rgb), 1);
    }
    .showcase__title,
    .showcase__button{
        position: relative;
        z-index: 5;
        transition: z-index 0s 0s;
    }
    .showcase__subtitle{
        color: var(--burido-secondary-color);
    }
    .showcase__image{
        opacity: 1;
        transition: all .45s, opacity .25s .2s;
        img{
            transform: translateX(0);
        }
        &::after{
            opacity: 1;
            transition: all .4s, transform .4s .2s;
        }
    }
}


.admin-bar .wgl-showcase-height-full .wgl-showcase.slide-showcase .showcase__wrapper{
    height: calc(100vh - 32px);
}

.wgl-showcase {
    position: relative;
    &.slide-showcase{
        .showcase__wrapper{
            position: relative;
            width: 100%;
            display: inline-block;
            visibility: hidden;
            vertical-align: top;
            .wgl-showcase-height-full & {
                height: 100vh;
            }
        }
        &.showcase__init{
            .showcase__wrapper{
                visibility: visible;
            }
        }
        .showcase__item-inner{
            white-space: nowrap;
            transition: inherit;
        }
        .showcase__items{
            position: absolute;
            z-index: 2;
            top: 0;
            left: 0;
            width: 39%;
            height: 100%;
            display: flex;
            flex-direction: column;
            overflow-y: auto;
            overflow-x: hidden;
            scrollbar-width: none;
            @media (max-width: 992px) {
                width: 100% !important;
            }
            &::-webkit-scrollbar {
                display: none;
            }
            .showcase__item{
                display: inline-block;
                position: relative;
                padding: 15px 40px 15px 12px;
                margin: 14px 0;
                transition: all .45s;
                max-width: max-content;
                &:first-child{
                    margin-top: auto !important;
                }
                &:last-child{
                    margin-bottom: auto !important;
                }
                .showcase__subtitle{
                    font-family: var(--burido-header-font-family);
                    font-weight: var(--burido-header-font-weight);
                    font-size: 14px;
                    line-height: 1.25em;
                    display: inline-block;
                    position: relative;
                    letter-spacing: 0;
                    color: var(--burido-secondary-color);
                    transition: all .4s;
                }
            }
        }
        .showcase__images{
            position: relative;
            width: 61%;
            height: 100%;
            overflow: hidden;
            margin-left: auto;
            .showcase__image {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background-size: cover;
                background-position: center;
                background-repeat: no-repeat;
                opacity: 0;
                animation: wgl-split-to-left .7s cubic-bezier(0.81,.065,.21,1) forwards;
                transition: opacity 0s .7s;
                &:hover{
                    &::before{
                        opacity: 0;
                    }
                    &::after{
                        opacity: 1;
                    }
                }
                &::before, &::after{
                    content: '';
                    position: absolute;
                    left: 0;
                    top: 0;
                    right: 0;
                    bottom: 0;
                    transition: 0.4s;
                }
                img{
                    display: none;
                }
                &.active{
                    opacity: 1;
                    z-index: 1;
                    transition: opacity 0s;
                    animation: wgl-split-from-left .7s cubic-bezier(0.81,.065,.21,1) forwards;
                }
            }
        }
        .showcase__button{
            display: inline-block;
        }
    }
    &.interactive-showcase{
        display: flex;
        flex-direction: column;
        pointer-events: none;
        .showcase__wrapper{
            position: relative;
        }
        .showcase__title,
        .showcase__button{
            position: relative;
            z-index: 2;
            transition: z-index 0s .1s;
        }

        .showcase__image-inner{
            overflow: hidden;
        }
        .showcase__image{
            --wgl-image-position: 20%;
            position: absolute;
            top: 50%;
            height: auto;
            left: var(--wgl-image-position);
            z-index: 4;
            opacity: 0;
            transform: translateY(-50%) rotate(var(--wgl-image-rotate, 0deg));
            transform-origin: top center;
            pointer-events: none;
            background: unset !important;
            transition: all .45s, opacity .2s .25s;
            img{
                border-radius: inherit;
                max-width: unset;
                transform: translateX(-100%);
                transition: transform 0.45s;
            }

            &::after{
                content: '';
                position: absolute;
                top: -1000px;
                right: -1000px;
                bottom: -1000px;
                left: -1000px;
                margin: auto;
                --wgl-hl-size: 565px;
                width: var(--wgl-hl-size);
                height: var(--wgl-hl-size);
                z-index: -2;
                background-image: radial-gradient(circle closest-side, var(--wgl-hl-color, rgba(var(--burido-primary-rgb), 0.4)) 0, transparent 100%);
                transform: translate(var(--wgl-hl-hor-pos, 200px), var(--wgl-hl-vert-pos, 50px)) scale(var(--wgl-hl-scale, 0.5));
                opacity: 0;
                transition: all .4s;
            }
        }
        .showcase__item{
            display: flex;
            align-items: baseline;
        }
        .showcase__subtitle{
            font-family: var(--burido-header-font-family);
            font-weight: 600;
            font-size: 14px;
            line-height: 1.5em;
            display: inline-block;
            position: relative;
            letter-spacing: 0;
            color: var(--burido-content-color);
            transition: all .4s;
            margin-right: 0.4em;
            white-space: normal;
        }
        .showcase__title{
            display: inline-flex;
            align-items: center;
            white-space: normal;
            text-transform: inherit;
            transition: all .4s, z-index 0s 0s;
            .title{
                font-size: 96px;
                color: rgba(var(--burido-header-rgb), 0.2);
                white-space: normal;
                letter-spacing: -0.05em;
                transition: inherit;
            }
        }
        .showcase__item {
            position: relative;
            padding: 10px 0;
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin: 0;
            width: 100%;
            pointer-events: auto;
        }

        &:not(:hover) .active,
        .showcase__item:hover{
            @include showcase_hover;
        }
    }
    .showcase__link{
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        z-index: 6;
    }
    .showcase__subtitle{
        flex-shrink: 0;
    }
    .showcase__title{
        padding-right: calc(var(--title-p-r, 0px) + var(--title-a-o, 0px)) !important;
    }
    .showcase__content{
        font-weight: 500;
        padding-right: calc(var(--content-p-r, 0px) + var(--content-a-o, 0px)) !important;
    }
    .showcase__button{
        position: relative;
        .wgl-showcase_button{
            &.icon-read-more{
                line-height: 0;
                font-size: 0;
                display: flex;
                align-items: center;
                justify-content: center;
                transition: all .4s;
                will-change: transform;
                background-color: transparent;
                color: var(--burido-tertiary-color);
                border-radius: 50%;
                i, span{
                    text-align: center;
                    display: inline-block;
                    box-sizing: content-box;
                    transition: 0s;
                    &::before{
                        display: block;
                        transition: transform .4s;
                        will-change: transform;
                        line-height: inherit;
                    }
                }
            }
        }
    }
}


@keyframes wgl-split-to-left  {
    from { clip-path: inset(0 0 0 0); }
    to { clip-path: inset(0 100% 0 0); }
}

@keyframes wgl-split-from-left  {
    from { clip-path: inset(0 0 0 100%); }
    to { clip-path: inset(0 0 0 0); }
}

@mixin wgl-showcase-responsive($media) {
    body[data-elementor-device-mode='#{$media}'] .elementor-widget-wgl-showcase .wgl-showcase.breakpoint_on-#{$media}{
        &.interactive-showcase{
            .showcase__item{
                flex-direction: column;
                width: 100%;
            }
            .showcase__image {
                position: static;
                order: -1;
                opacity: 1;
                transform: unset;
            }

            @include showcase_hover;
        }
    }
}

@include wgl-showcase-responsive('widescreen');
@include wgl-showcase-responsive('desktop');
@include wgl-showcase-responsive('tablet_extra');
@include wgl-showcase-responsive('tablet');
@include wgl-showcase-responsive('mobile_extra');
@include wgl-showcase-responsive('mobile');
