@mixin placeholder {
    &::placeholder {
        font: inherit;
        line-height: inherit;
        color: inherit;
        outline: none;
        -webkit-appearance: none;
        transition: .4s;
        transform: translateY(0) scale(1);
        transform-origin: left bottom;
    }
    &:active,
    &:focus{
        background-color: transparent !important;
        box-shadow: unset !important;
        border-color: var(--burido-header-font-color);
        color: var(--burido-header-font-color);
        &::placeholder {
            opacity: 0;
        }
    }
}

@mixin search_button {
    .search-button {
        position: absolute;
        z-index: 1;
        height: 42px;
        width: 24px;
        top: 0;
        left: 0;
        margin: 0;
        border: none;
        outline: none;
        padding: 0;
        font-size: 0;
        box-shadow: none;
        cursor: pointer;
        background: transparent;
        &:focus,
        &:active {
            box-shadow: none;
        }
    }
}

@mixin search_icon {
    .search__icon,
    .wc-block-product-search__button {
        position: absolute;
        z-index: 1;
        top: 0;
        left: 0;
        height: 42px;
        width: 1em;
        font-size: 17px;
        line-height: 42px;
        font-style: normal;
        text-align: center;
        opacity: 1;
        transition: 0.4s;
        pointer-events: none;
        border-radius: 0;
        color: var(--burido-header-font-color);
    }
}

@mixin widget_list_dot {
    padding-left: 17px;
    &::before {
        content: '';
        position: absolute;
        z-index: 1;
        display: block;
        top: 10px;
        left: 2px;
        width: 6px;
        height: 6px;
        border-radius: 0;
        background: currentColor;
        transition: background-color 0.3s;
    }
    &:hover::before {
        background-color: var(--burido-secondary-color);
    }
}

@mixin widget_post_count {
    a {
        position: relative;
        line-height: 24px;
        z-index: 1;
        .post_count {
            z-index: 1;
            letter-spacing: inherit;
            line-height: 19px;
            display: inline-block;
            text-align: center;
            margin-left: 10px;
            padding: 1px 6px !important;
            transform: translateY(-1px);
            border-radius: 0;
            transition: 0.3s;
            min-width: 24px;
            background: var(--burido-form-bg-color);
        }
        &:hover {
            .post_count {
                border-radius: 20px;
                background: var(--burido-primary-color);
            }
        }
    }
}

@mixin list_widget_font {
    a,
    label{
        font-size: 16px;
        font-weight: 500;
        color: var(--burido-header-font-color);
        display: inline-block !important;
        padding: 5px 0;
        &::before {
            display: inline-block;
            content: "";
            mask-image: var(--burido-arrow-down-right-h);
            mask-position: center center;
            mask-size: 1em;
            mask-repeat: no-repeat;
            width: 1em;
            height: 1em;
            padding: 0;
            box-shadow: none;
            background-color: currentColor;
            font-style: normal;
            font-variant: normal;
            text-transform: none;
            line-height: 0;
            font-size: 18px;
            transition:  .4s;
            transform: translateX(-10px) scale(0.5);
            position: absolute;
            z-index: 1;
            top: 7px;
            left: 0;
            opacity: 0;
        }
        &:hover {
            padding-left: 28px;
            margin-right: -28px;
            &::before {
                transform: translateX(1px) scale(1);
                opacity: 1;
            }
        }
    }
    &.current-cat > a,
    &.chosen > a,
    a:hover,
    &.checked label,
    label:hover{
        color: var(--burido-header-font-color);
    }
}

@mixin content_fs {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    right: 0;
    bottom: 0;
}

@mixin hexagon {
    width: var(--hex-size);
    height: calc(var(--hex-size) * 1.134);
    clip-path: polygon(-1% 25%, -1% 75%, 50% 100%, 101% 75%, 101% 25%, 50% 0%);
}