@use "mixins";

/* ==================== ##Gallery ==================== */
.elementor-widget-wgl-gallery {
    .wgl-gallery {
        &_items {
            &:not(.gallery-carousel){
                display: flex;
                flex-wrap: wrap;
            }
            &.gallery-justified{
                .wgl-gallery_item{
                    position: absolute;
                    box-sizing: content-box;
                    width: 100%;
                    height: 100%;
                }
            }
        }
        &_item-wrapper {
            > a {
                display: flex;
                width: fit-content;
                margin-left: auto;
                margin-right: auto;
                flex-direction: column;
            }
        }
        &_item {
            position: relative;
            z-index: 1;
            overflow: hidden;
            > img {
                display: block;
                margin-right: auto;
                margin-left: auto;
            }
            &::before,
            &::after{
                @include mixins.content_fs;
                transition: 0.4s;
            }
            &::after{
                opacity: 0;
            }
        }
        &_image {
            &-info {
                position: absolute;
                z-index: 1;
                left: 0;
                top: 0;
                right: 0;
                bottom: 0;
                display: flex;
                flex-direction: column;
                transition: 0.4s;
                opacity: 0;
                visibility: hidden;
                &.show_until_hover,
                &.show_always {
                    opacity: 1;
                    visibility: visible;
                }
                &.show_disable{
                    opacity: 0 !important;
                    visibility: hidden !important;
                }
            }
            &-title{
                line-height: 1.1;
                font-size: 1.1em;
                font-weight: 600;
                color: var(--burido-header-font-color);
                transition: .4s;
                + .wgl-gallery_image-descr{
                    margin-top: 5px;
                }
            }
            &-descr{
                line-height: 1;
                color: var(--burido-header-font-color);
                transition: .4s;
            }
        }
        &_item:hover {
            &::before{
                opacity: 0;
            }
            &::after{
                opacity: 1;
            }
            .wgl-gallery_image-info {
                opacity: 1;
                visibility: visible;
                &.show_until_hover {
                    opacity: 0;
                    visibility: hidden;
                }
            }
        }
        //* Appear Animation
        &_items.appear-animation {
            .wgl-gallery_item-wrapper {
                opacity: 0;
            }
            &.fade-in {
                .wgl-gallery_item-wrapper.animate {
                    animation: fade_in 0.9s ease forwards;
                }
            }
            &.slide-top {
                .wgl-gallery_item-wrapper.animate {
                    animation: slide_top 0.5s ease forwards;
                    transform: translateY(50px);
                }
            }
            &.slide-bottom {
                .wgl-gallery_item-wrapper.animate {
                    animation: slide_bottom 0.5s ease forwards;
                    transform: translateY(-50px);
                }
            }
            &.slide-left {
                .wgl-gallery_item-wrapper.animate {
                    animation: slide_left 0.5s ease forwards;
                    transform: translateX(50px);
                }
            }
            &.slide-right {
                .wgl-gallery_item-wrapper.animate {
                    animation: slide_right 0.5s ease forwards;
                    transform: translateX(-50px);
                }
            }
            &.zoom {
                .wgl-gallery_item-wrapper.animate {
                    animation: zoom_in 0.5s ease forwards;
                    transform: scale(0.5);
                }
            }
        }
    }

    .wgl-gallery_item {
        transition-duration: var(--wgl-gallery-duration, 800ms) !important;
    }
    .swiper-slide{
        --wgl-gallery-scale-size: 0.7;
    }
    &.layout-scale_even {
        .swiper-slide:nth-child(even) {
            .wgl-gallery_item {
                transform: scale(var(--wgl-gallery-scale-size));
            }
        }
    }
    &.layout-scale_odd {
        .swiper-slide:nth-child(odd) {
            .wgl-gallery_item {
                transform: scale(var(--wgl-gallery-scale-size));
            }
        }
    }
    &.layout-scale_active {
        .swiper-slide:not(.swiper-slide-active) {
            .wgl-gallery_item {
                transform: scale(var(--wgl-gallery-scale-size));
            }
        }
    }

    &.col {
        &-1 .wgl-gallery_item-wrapper {
            width: 100%;
        }
        &-2 .wgl-gallery_item-wrapper {
            width: 50%;
        }
        &-3 .wgl-gallery_item-wrapper {
            width: 33.333333%;
        }
        &-4 .wgl-gallery_item-wrapper {
            width: 25%;
        }
        &-5 .wgl-gallery_item-wrapper {
            width: 20%;
        }
        @media (max-width: 1024px) {
            &-tablet-1 .wgl-gallery_item-wrapper {
                width: 100%;
            }
            &-tablet-2 .wgl-gallery_item-wrapper {
                width: 50%;
            }
            &-tablet-3 .wgl-gallery_item-wrapper {
                width: 33.333333%;
            }
            &-tablet-4 .wgl-gallery_item-wrapper {
                width: 25%;
            }
            &-tablet-5 .wgl-gallery_item-wrapper {
                width: 20%;
            }
        }
        @media (max-width: 767px) {
            &-mobile-1 .wgl-gallery_item-wrapper {
                width: 100%;
            }
            &-mobile-2 .wgl-gallery_item-wrapper {
                width: 50%;
            }
            &-mobile-3 .wgl-gallery_item-wrapper {
                width: 33.333333%;
            }
            &-mobile-4 .wgl-gallery_item-wrapper {
                width: 25%;
            }
            &-mobile-5 .wgl-gallery_item-wrapper {
                width: 20%;
            }
        }
    }
}
/* justifiedGallery */
.justified-gallery {
    width: 100%;
    position: relative;
    overflow: hidden;
}
.justified-gallery > a,
.justified-gallery > div,
.justified-gallery > figure {
    position: absolute;
    display: inline-block;
    filter: 'alpha(opacity=10)';
    opacity: 0.1;
    margin: 0;
    padding: 0;
}
.justified-gallery > a > img,
.justified-gallery > div > img,
.justified-gallery > figure > img,
.justified-gallery > a > a > img,
.justified-gallery > div > a > img,
.justified-gallery > figure > a > img,
.justified-gallery > a > svg,
.justified-gallery > div > svg,
.justified-gallery > figure > svg,
.justified-gallery > a > a > svg,
.justified-gallery > div > a > svg,
.justified-gallery > figure > a > svg {
    position: absolute;
    top: 50%;
    left: 50%;
    margin: 0;
    padding: 0;
    border: none;
    filter: 'alpha(opacity=0)';
    opacity: 0;
}
.justified-gallery > .jg-entry-visible {
    filter: 'alpha(opacity=100)';
    opacity: 1;
    background: none;
}
.justified-gallery > .jg-entry-visible > img,
.justified-gallery > .jg-entry-visible > a > img,
.justified-gallery > .jg-entry-visible > svg,
.justified-gallery > .jg-entry-visible > a > svg {
    filter: 'alpha(opacity=100)';
    opacity: 1;
    -webkit-transition: opacity 500ms ease-in;
    -moz-transition: opacity 500ms ease-in;
    -o-transition: opacity 500ms ease-in;
    transition: opacity 500ms ease-in;
}
.justified-gallery > .jg-spinner {
    position: absolute;
    bottom: 0;
    margin-left: -24px;
    padding: 10px 0 10px 0;
    left: 50%;
    filter: 'alpha(opacity=100)';
    opacity: 1;
    overflow: initial;
}
.justified-gallery > .jg-spinner > span {
    display: inline-block;
    filter: 'alpha(opacity=0)';
    opacity: 0;
    width: 8px;
    height: 8px;
    margin: 0 4px 0 4px;
    background-color: #000;
    border-radius: 6px;
}
