/* ==================== #Banner ==================== */

.banner-widget_wrapper {
    display: block;
    position: relative;
    padding-top: 42px;
    padding-bottom: 110px;
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
    background-color: transparent;
    max-width: 270px;
    margin-top: 10px;
    margin-left: auto;
    margin-right: auto;
    text-align: center;
    overflow: hidden;
    border-radius: 0;
    transition: 0.4s;
    color: var(--burido-tertiary-color);
    .banner-widget_img-wrapper {
        display: block;
        margin: 0 -10px;
        margin-bottom: 26px;
        line-height: 0;
    }
    .banner-widget_text_sub {
        font-size: 20px;
        line-height: 1.5em;
        letter-spacing: 0.05em;
        font-family: var(--burido-header-font-family);
        font-weight: var(--burido-header-font-weight);
        & + .banner-widget_text{
            margin-top: 22px;
        }
    }
    .banner-widget_text {
        font-size: 22px;
        line-height: 32px;
        font-weight: 600;
        padding: 0 25px;
        color: inherit;
    }
    .banner-widget_button {
        display: inline-block;
        position: relative;
        z-index: 1;
        transition: 0.4s;
        text-align: center;
        white-space: nowrap;
        width: auto;
        font-size: 14px;
        margin-top: 22px;
        line-height: 52px;
        &.text {
            padding: 0 20px;
            font-weight: 600;
            font-size: 15px;
            letter-spacing: var(--burido-h2-letter-spacing);
            font-family: var(--burido-header-font-family);
            color: var(--burido-button-color-idle);
            background-color: var(--burido-button-bg-idle);
            border-radius: 15px;
            position: relative;
            z-index: 1;
            width: calc(100% - 40px);
            text-align: left;
            letter-spacing: 0;
            &::before {
                --icon-bg-size: 8;
                content: "";
                position: absolute;
                top: -100px;
                right: 20px;
                bottom: -100px;
                margin: auto;
                font-size: calc(var(--icon-bg-size) * 1px);
                width: 1em;
                height: 1em;
                border-radius: 50%;
                color: var(--burido-button-color-idle);
                background-color: currentColor;
                pointer-events: none;
                transform: translateY(var(--icon-translate-y, 0)) scale(var(--icon-bg-scale, 1));
                transition: background-color 0.4s, transform 0.4s;
            }
        }
        &.icon {
            width: 60px;
            height: 60px;
            color: var(--burido-secondary-color);
            &::before,
            &::after {
                display: block;
                content: "";
                transition: 0.4s;
                width: 60px;
                height: 60px;
                line-height: 60px;
                border-radius: 50%;
                position: absolute;
                z-index: 1;
                left: 0;
                top: 0;
            }
            &::after {
                mask-image: var(--burido-arrow-down-right-h);
                mask-position: center center;
                mask-size: 1em;
                mask-repeat: no-repeat;
                padding: 0;
                box-shadow: none;
                background-color: currentColor;
                font-style: normal;
                font-variant: normal;
                text-transform: none;
                font-size: 26px;
            }
            &::before {
                background: var(--burido-tertiary-color);

            }
        }
    }
    .banner-widget__link {
        position: absolute;
        z-index: 2;
        top: 0;
        bottom: 0;
        left: 0;
        right: 0;
        border-radius: inherit;
    }
    &:hover {
        border-radius: 15px;
        .banner-widget_button {
            &.icon {
                &::after {
                    transform: rotate(-45deg);
                }
            }
            &.text {
                color: var(--burido-tertiary-color);
                background: var(--burido-secondary-color);
                &::before {
                    --icon-bg-scale: 1.25;
                }
            }
        }
    }
    &:empty {
        display: none;
    }
}
