/* ==================== ##Accordion Services ==================== */

.wgl-accordion-services {
    display: flex;
    flex-wrap: wrap;
    flex-direction: row;
    margin: 0 -10px;
    .service__item {
        display: flex;
        position: relative;
        z-index: 1;
        margin-bottom: 15px;
        transition: 0.5s;
        &.active {
            .service__content {
                opacity: 1;
                visibility: visible;
                transition: 0.5s;
                transition-delay: 0.3s;
            }
        }
        &:not(.active) {
            .service__thumbnail {
                border-top-right-radius: inherit;
                border-bottom-right-radius: inherit;
            }
        }
    }
    .service__thumbnail {
        position: absolute;
        z-index: 1;
        left: 10px;
        top: 0;
        width: calc(100% - 15px);
        height: 100%;
        border-top-left-radius: inherit;
        border-bottom-left-radius: inherit;
        transition: 0.3s;
        background-color: var(--burido-header-font-color);
    }
    .content__title {
        color: var(--burido-header-font-color);
    }
    .service__content {
        display: flex;
        flex-direction: column;
        justify-content: flex-end;
        position: relative;
        z-index: 1;
        left: -5px;
        width: 100%;
        border-top-right-radius: inherit;
        border-bottom-right-radius: inherit;
        opacity: 0;
        visibility: hidden;
        transform: translateX(100%);
        transition: 0.2s;
    }
    .content__media {
        line-height: 1;
        color: var(--burido-primary-color);
        svg{
            width: 1em;
            height: 1em;
            display: block;
        }
    }
    .content__button {
        align-self: baseline;
        color: #fff;
        background-color: var(--burido-secondary-color);
        &:hover{
            color: #fff;
            background-color: var(--burido-primary-color);
        }
    }
}
.elementor-widget-wgl-accordion-service {
    &.grid-col {
        &-2 .service__item {
            width: 33.333333%;
            &.active {
                margin-right: 33.333333%;
            }

            &:nth-child(1):not(.active) + .service__item:nth-child(2):not(.active),
            &:nth-child(3):not(.active) + .service__item:nth-child(4):not(.active),
            &:nth-child(5):not(.active) + .service__item:nth-child(6):not(.active),
            &:nth-child(7):not(.active) + .service__item:nth-child(8):not(.active) {
                margin-right: 33.333333%;
                .service__content {
                    opacity: 1;
                    visibility: visible;
                }
            }
        }
        &-3 .service__item {
            width: 25%;
            &.active {
                margin-right: 25%;
            }
            @media only screen and (min-width: 1201px) {
                &:nth-child(1):not(.active) + .service__item:nth-child(2):not(.active) + .service__item:nth-child(3):not(.active),
                &:nth-child(4):not(.active) + .service__item:nth-child(5):not(.active) + .service__item:nth-child(6):not(.active),
                &:nth-child(7):not(.active) + .service__item:nth-child(8):not(.active) + .service__item:nth-child(9):not(.active) {
                    margin-right: 25%;
                    .service__content {
                        opacity: 1;
                        visibility: visible;
                    }
                }
            }
        }
        &-4 .service__item {
            width: 20%;
            &.active {
                margin-right: 20%;
            }
            @media only screen and (min-width: 1301px) {
                &:nth-child(1):not(.active) + .service__item:nth-child(2):not(.active) + .service__item:nth-child(3):not(.active) + .service__item:nth-child(4):not(.active),
                &:nth-child(5):not(.active) + .service__item:nth-child(6):not(.active) + .service__item:nth-child(7):not(.active) + .service__item:nth-child(8):not(.active),
                &:nth-child(9):not(.active) + .service__item:nth-child(10):not(.active) + .service__item:nth-child(11):not(.active) + .service__item:nth-child(12):not(.active) {
                    margin-right: 20%;
                    .service__content {
                        opacity: 1;
                        visibility: visible;
                    }
                }
            }
        }
    }
    @media only screen and (min-width: 1201px) and (max-width: 1300px) {
        &.grid-col-4 .service__item {
            width: 25%;
            &.active {
                margin-right: 25%;
            }
            &:nth-child(1):not(.active) + .service__item:nth-child(2):not(.active) + .service__item:nth-child(3):not(.active),
            &:nth-child(4):not(.active) + .service__item:nth-child(5):not(.active) + .service__item:nth-child(6):not(.active),
            &:nth-child(7):not(.active) + .service__item:nth-child(8):not(.active) + .service__item:nth-child(9):not(.active) {
                margin-right: 25%;
                .service__content {
                    opacity: 1;
                    visibility: visible;
                }
            }
        }
    }
    @media only screen and (min-width: 993px) and (max-width: 1200px) {
        &.grid-col {
            &-3,
            &-4 {
                .service__item {
                    width: 33.333333%;
                    &.active {
                        margin-right: 33.333333%;
                    }
                    &:nth-child(1):not(.active) + .service__item:nth-child(2):not(.active),
                    &:nth-child(3):not(.active) + .service__item:nth-child(4):not(.active),
                    &:nth-child(5):not(.active) + .service__item:nth-child(6):not(.active),
                    &:nth-child(7):not(.active) + .service__item:nth-child(8):not(.active) {
                        margin-right: 33.333333%;
                        .service__content {
                            opacity: 1;
                            visibility: visible;
                        }
                    }
                }
            }
        }
    }
    @media only screen and (max-width: 992px) {
        &.grid-col {
            &-2,
            &-3,
            &-4 {
                .service__item {
                    width: 100%;
                    margin-right: 0 !important;
                    .service__content {
                        opacity: 1;
                        visibility: visible;
                        transform: translateX(0);
                    }
                    .service__thumbnail {
                        position: relative;
                        min-height: inherit;
                        height: auto;
                    }
                }
            }
        }
    }
    @media only screen and (max-width: 767px) {
        &.grid-col {
            &-2,
            &-3,
            &-4 {
                .service__item {
                    flex-direction: column;
                    .service__thumbnail,
                    .service__content {
                        position: static;
                        width: 100%;
                    }
                }
            }
        }
    }
}
