/* ==================== ## WGL Tabs ==================== */
@mixin simple_lavalamp {
    .wgl-tabs_header {
        &::after {
            content: '';
            display: block;
            width: 60px;
            height: 1px;
            position: absolute;
            left: 0;
            bottom: -1px;
            margin-left: 0;
            border-radius: 0;
            transition: all .45s;
            transform: scalex(0.8) translateY(-15px);

        }
        &.active {
            &::after {
                transform: scalex(1) translateY(0);
                background-color: var(--burido-primary-color);
            }
        }
    }
}

.wgl-tabs {
    .wgl-tabs_headings {
        display: inline-block;
        white-space: nowrap;
        width: auto;
        min-width: fit-content;
        &-wrap{
            overflow: visible;
        }
    }
    &.wgl-tabs_swiper-wrapper{
        overflow: hidden;
    }
    &.has-divider{
        @include simple_lavalamp;
    }
    .lavalamp {
        position: relative;
        &-object {
            position: absolute;
            z-index: 1;
            right: 0;
            bottom: 8px;
            left: 0;
            margin: auto auto -1px 0;
            opacity: 0;
            font-size: 0;
            line-height: 0;
            &::after{
                content: '';
                position: static;
                width: 100%;
                max-width: 100%;
                height: 3px;
                background-color: var(--burido-primary-color);
                border-radius: 0;
                display: inline-block;
            }
        }
        &_animate {
            .lavalamp-object {
                opacity: 1;
            }
        }
    }
    .wgl-tabs_header {
        display: inline-flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        width: fit-content;
        min-width: fit-content;
        position: relative;
        text-align: center;
        font-family: var(--burido-header-font-family);
        font-size: 22px;
        font-weight: 500;
        line-height: 1.3;
        margin: 0;
        cursor: pointer;
        transition: 0.4s;
        z-index: 1;
        color: rgba(var(--burido-header-rgb), .4);
        border-radius: 0;
        letter-spacing: -0.02em;
        &:first-child {
            margin-left: 0 !important;
        }
        &:last-child {
            margin-right: 0 !important;
        }
        &:hover,
        &.active{
            color: var(--burido-header-font-color);
        }
    }
    .wgl-tabs_content {
        padding: 31px 0 15px 0;
        display: block;
        > .elementor {
            margin: 0;
            .elementor-column-gap-default > .elementor-row > .elementor-column > .elementor-element-populated,
            .elementor-column-gap-default > .elementor-column > .theiaStickySidebar > .elementor-element-populated,
            .elementor-column-gap-default > .elementor-column > .elementor-element-populated{
                padding-left: 0;
                padding-right: 0;
            }
        }
    }
    .wgl-tabs_content-wrap {
        min-height: fit-content;
        transition: height .6s ease-in-out;
    }
    .wgl-tabs_icon {
        line-height: 1;
        color: inherit;
        transition: 0.4s;
        svg {
            width: 1em;
            height: 1em;
            fill: currentColor;
            transition: inherit;
        }
    }
    .wgl-tabs_title {
        font: inherit;
        color: inherit;
        line-height: inherit;
        text-transform: inherit;
        letter-spacing: inherit;
    }
}

body {
    @mixin wgl-tabs-responsive($media) {
        .wgl-tabs.tabs_align#{$media} {
            &-left {
                .wgl-tabs_headings-wrap{ text-align: left; }
                .wgl-tabs_headings {
                    display: inline-block;
                    .wgl-tabs_header {
                        flex: none;
                        &:last-child { margin-right: 0 !important; }
                        &:first-child { margin-left: auto !important; }
                    }
                }
            }
            &-right {
                .wgl-tabs_headings-wrap{ text-align: right; }
                .wgl-tabs_headings {
                    display: inline-block;
                    .wgl-tabs_header {
                        flex: none;
                        &:last-child { margin-right: auto !important; }
                        &:first-child { margin-left: 0 !important; }
                    }
                }
            }
            &-center {
                .wgl-tabs_headings-wrap{ text-align: center; }
                .wgl-tabs_headings {
                    display: inline-block;
                    .wgl-tabs_header {
                        flex: none;
                        &:last-child { margin-right: 0 !important; }
                        &:first-child { margin-left: 0 !important; }
                    }
                }
            }
            &-justify {
                .wgl-tabs_headings-wrap{ text-align: left; }
                .wgl-tabs_headings {
                    display: inline-flex;
                    .wgl-tabs_header {
                        flex: 1;
                        &:last-child { margin-right: 0 !important; }
                        &:first-child { margin-left: 0 !important; }
                    }
                }
            }
        }
    }
    @include wgl-tabs-responsive('');
    &:not(
        [data-elementor-device-mode="widescreen"],
        [data-elementor-device-mode="desktop"]
    ) {
        @include wgl-tabs-responsive('-tablet');
    }
    &:is(
        [data-elementor-device-mode="mobile_extra"],
        [data-elementor-device-mode="mobile"]
    ) {
        @include wgl-tabs-responsive('-mobile');
    }
}