/* ==================== ##Scroll Up ==================== */

#scroll_up {
    position: fixed;
    right: 0;
    bottom: 0;
    z-index: 20;
    text-align: center;
    cursor: pointer;
    opacity: 0;
    transition: 0.4s;
    display: flex;
    justify-content: center;
    align-items: center;
    line-height: 1;
    top: 100%;
    min-height: fit-content;
    transform: translate(-30px, 5px);
    white-space: nowrap;
    padding: 0;
    color: var(--burido-back-to-top-color);
    background-color: var(--burido-back-to-top-color-bg);
    &.scroll_up-text {
        font-family: var(--burido-header-font-family);
        font-weight: 600;
        font-size: 14px;
        letter-spacing: 0.05em;
        right: 40px;
        bottom: 40px;
        writing-mode: vertical-rl;
        transform: rotate(180deg) translate3D(-205%, 40px, 0);
        transform-origin: 0 0;
        border: unset;
        background: unset;
        @media (max-width: 1200px) {
            transform: rotate(180deg) translate3D(-205%, 20px, 0);
        }
        span {
            padding: 28px 23px;
            border-radius: 15px;
            background-color: var(--burido-back-to-top-color-bg);
            @media (max-width: 1200px) {
                display: none;
            }
        }
        .wgl-svg-icon {
            z-index: 1;
            width: 60px;
            height: 60px;
            line-height: 60px;
            display: inline-block;
            transition: 0.4s;
            font-size: 26px;
            font-weight: normal;
            border-radius: 50%;
            background-color: var(--burido-back-to-top-color-bg);
            color: var(--burido-back-to-top-color);
            svg {
                transition: 0.4s;
                transform: translateY(-1px) rotate(45deg);
            }
            @media (max-width: 767px) {
                width: 50px;
                height: 50px;
                line-height: 50px;
            }
        }
        &:hover {
            color: var(--burido-back-to-top-color);
            .wgl-svg-icon {
                animation: back_to_top ease-in 1s infinite;
            }
        }
    }
    &.scroll_up-icon {
        width: 50px;
        height: 50px;
        font-size: 26px;
        font-weight: normal;
        border-radius: 50px;
        transition: 0.4s, clip-path 0s;
        transform: translate(-30px, 5px);
        overflow: hidden;
        @media (max-width: 767px) {
            transform: translate(-20px, 5px);
            width: 30px;
            height: 30px;
            font-size: 18px;
        }
        svg {
            transform: rotate(-135deg);
            pointer-events: none;
            transition: 0.4s;
        }
        &:hover {
            .wgl-svg-icon {
                animation: back_to_top ease-in 1s infinite;
            }
        }
    }
    &.active {
        opacity: 1;
        &.scroll_up-icon {
            transform: translate(-30px, -80px);
            @media (max-width: 767px) {
                transform: translate(-20px, -50px);
            }
        }
        &.scroll_up-text {
            transform: rotate(180deg) translate3D(-100%, 40px, 0);
            @media (max-width: 1200px) {
                transform: rotate(180deg) translate3D(-80px, 20px, 0);
            }
        }
    }
}
@keyframes back_to_top {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(6px);
    }
    100% {
        transform: translateY(0);
    }
}
