/* ==================== ##Circuit Services ==================== */

.wgl-circuit-service {
    position: relative;
    z-index: 1;
    height: 0;
    padding-top: 100%;
    &::before {
        content: '';
        position: absolute;
        z-index: -1;
        left: 10%;
        top: 10%;
        width: 80%;
        height: 80%;
        border-radius: 50%;
        border: 1px solid #dee1ed;
    }
	.wgl-services {
		&_icon-wrap {
			position: absolute;
			z-index: 1;
			left: 41%;
			top: 41%;
			width: 18%;
			height: 18%;
			font-size: 40px;
			border-radius: 50%;
			box-shadow: 0px 6px 13px rgba(145, 145, 145, 0.2);
			cursor: pointer;
            transition: 0.4s;
            display: flex;
            justify-content: center;
            align-items: center;
			background-color: #fff;
			.services_icon {
				transform: translate(-50%,-50%);
				left: 50%;
				top: 50%;
				position: absolute;
				z-index: 1;
				transition: 0.6s;
				line-height: 1;
			}
		}
		&_content-wrap {
			position: absolute;
			top: 0;
			left: 0;
			width: 100%;
			height: 100%;
			padding: 25% 29%;
			display: flex;
			flex-direction: column;
			text-align: center;
			justify-content: center;
			opacity: 0;
			visibility: hidden;
			transition: 0.6s;
        }
        &_icon{
			color: var(--burido-primary-color);
        }
		&_item {
			&.active {
				.wgl-services_icon{
					color: #fff;
				}
				.wgl-services_icon-wrap{
					background-color: var(--burido-primary-color);
				}
				.wgl-services_icon-wrap {
					& + .wgl-services_content-wrap {
						opacity: 1;
						visibility: visible;
					}
				}
			}
        }
		&_title {
			margin-bottom: 10px;
			font-size: 24px;
			line-height: 1.4;
			font-weight: 600;
			color: var(--burido-header-font-color);
        }
        &_text{
            font-size: 14px;
			color: var(--burido-content-color);
        }
	}
	&.tablet_resp {
		.services_descr { display: none }
		.services_title {
			margin-bottom: 0;
			font-size: 22px;
		}
		.services_icon { font-size: 75% }
	}
	&.mobile_resp {
		.services_title {
			margin-bottom: 0;
			font-size: 18px;
			line-height: 26px;
		}
		.services_subtitle { font-size: 13px }
		.services_icon { font-size: 55% }
		.services_descr { display: none }
	}
}