/* ==================== ##Physics Button ==================== */

@property --bph-button-first {
    syntax: '<color>';
    initial-value: rgba(250, 169, 165, 1);
    inherits: false;
}

@property --bph-button-sec {
    syntax: '<color>';
    initial-value: rgba(121, 24, 238, 1);
    inherits: false;
}

.wgl-physics {
    &_matter {
        background-color: #fff;
        border-radius: var(--wgl-border-radius, 20px);
        position: relative;
        width: 100%;
        height: 800px;
        clip-path: inset(0 0 0 0 round var(--wgl-border-radius, 20px));
    }

    &_canvas {
        position: absolute;
        width: 100%;
        height: 100%;
        top: 0;
        left: 0;
    }

    &_elements {
        pointer-events: none;
        .wgl-physics_item {
            position: absolute;
            width: var(--size-circle);
            height: var(--size-circle);
            border-radius: 100%;
            transform-origin: center;
            opacity: 0;
            visibility: hidden;
            margin-top: calc(-0.5px * var(--size-circle) - 250px);
            transition: margin 0.6s ease-in-out, background 0.4s ease-in-out, color 0.4s ease-in-out, width 0.15s ease-in-out, opacity 0.15s ease-in-out, visibility 0.15s ease-in-out, height 0.15s ease-in-out;
            &__inner{
                --bph-button-first: transparent;
                --bph-button-sec: transparent;
                background-color: transparent;
                background-repeat: no-repeat;
                background-origin: border-box !important;
                position: absolute;
                top: var(--wgl-items-gap, 0px);
                right: var(--wgl-items-gap, 0px);
                bottom: var(--wgl-items-gap, 0px);
                left: var(--wgl-items-gap, 0px);
                overflow: hidden;
                padding: 20px 25px;
                font-family: var(--burido-header-font-family);
                font-size: 18px;
                font-weight: 600;
                line-height: 1.333em;
                border-radius: 100%;
                letter-spacing: var(--burido-h3-letter-spacing);
                text-align: center;
                color: var(--burido-content-color);
                display: flex;
                align-items: center;
                justify-content: center;
                border: 1px solid rgba(var(--burido-secondary-rgb), 1);
                transition: color .4s, background-color .4s, --bph-button-first .7s, --bph-button-sec .7s;
            }
            &.visible{
                margin-top: 0;
                opacity: 1;
                visibility: visible;
            }
            &.active{
                .wgl-physics_item__inner{
                    background: var(--burido-primary-color);
                    --bph-button-first: rgba(250, 169, 165, 1);
                    --bph-button-sec: var(--burido-primary-color);
                }
            }
        }
    }

    &_title__wrapper{
        display: flex;
        position: fixed;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        margin: auto;
        pointer-events: none;
    }
}