/* ==================== ##Pie Chart ==================== */

.wgl-pie_chart {
    .chart__wrapper {
        position: relative;
        line-height: 0;
    }
    .chart {
        --value-margin: 18px;
        --track-offset: 1px;
        --track-width: 1px;
		position: relative;
        display: inline-block;
        box-sizing: content-box;
        &::before{
            content: '';
            display: block;
            position: absolute;
            top: var(--track-offset);
            right: var(--track-offset);
            bottom: var(--track-offset);
            left: var(--track-offset);
            border-radius: 50%;
            border: var(--track-width) solid transparent;
        }
        canvas {
            display: block;
            position: relative;
            z-index: 1;
        }
        &__percent {
            --value-margin: 1px;
            font-family: var(--burido-header-font-family);
            font-size: 64px;
            line-height: 1;
            font-weight: 600;
            letter-spacing: 0;
            padding-left: 0;
            z-index: 1;
            text-align: center;
            position: absolute;
            top: var(--value-margin);
            left: var(--value-margin);
            width: calc(100% - var(--value-margin) * 2);
            height: calc(100% - var(--value-margin) * 2);
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
            color: var(--burido-header-font-color);
        }
        &__sub_title {
            display: block;
            font-size: 16px;
            font-weight: 400;
            line-height: 1.5em;
            margin-top: 15px;
            color: var(--burido-primary-color);
            font-family: var(--burido-content-font-family);
            + .chart__title{
                margin-top: 0;
            }
            + .chart__description{
                margin-top: 3px;
            }
        }
        &__title {
            display: block;
            font-size: 18px;
            font-weight: 500;
            letter-spacing: 0;
            z-index: 2;
            transition: inherit;
            line-height: 1.25em;
            color: var(--burido-header-font-color);
            margin-top: 22px;
            + .chart__description{
                margin-top: 3px;
            }
        }
        &__description {
            display: block;
            font-size: 16px;
            line-height: 1.875em;
            color: var(--burido-content-color);
            margin-top: 15px;
        }
    }
}

body:is(
    [data-elementor-device-mode='tablet_extra'],
    [data-elementor-device-mode='tablet'],
    [data-elementor-device-mode='mobile_extra'],
    [data-elementor-device-mode='mobile']) {
    .wgl-pie_chart {
        .wgl-layout-left,
        .wgl-layout-right{
            display: block;
        }
    }
}
