/* ==================== ##Elementor ==================== */
body.elementor-page{
    main .wgl-container.wgl-content-sidebar,
    &.single main .wgl-container:not(.wgl-content-sidebar){
        padding-right: 15px;
        padding-left: 15px;
        .elementor{
            margin-left: -15px;
            margin-right: -15px;
        }
    }
}

body.elementor-page,
body.elementor-editor-active,
body.elementor-editor-preview {
    main,
    .footer_top-area:not(.widgets_area) {
        .wgl-container {
            width: auto;
            max-width: none;
            margin-left: auto;
            margin-right: auto;
            &.full-width {
                width: 100%;
                max-width: 100%;
                margin-left: 0;
                margin-right: 0;
            }
        }
    }
    &.single-footer {
        main,
        .footer_top-area {
            &:not(:empty) {
                .wgl-container {
                    max-width: none;
                    margin-left: auto;
                    margin-right: auto;
                }
            }
        }
    }
}
body.elementor-default {
    .footer_top-area:not(.widgets_area) {
        .wgl-container {
            width: auto;
            max-width: none;
            margin-left: auto;
            margin-right: auto;
            &.full-width {
                width: 100%;
                max-width: 100%;
                margin-left: 0;
                margin-right: 0;
            }
        }
    }
}

.elementor-element.elementor-widget.elementor-widget-spacer {
    margin-bottom: 0;
}
.elementor-image-gallery {
    .gallery-item {
        margin-top: 0 !important;
    }
    img {
        border: 0 !important;
    }
}

.elementor-section,
.elementor-element {
    &.wgl-add-background-text {
        &::before {
            margin-left: calc(8.9vw / 2);
        }
        &::before,
        .wgl-background-text {
            position: absolute;
            font-size: 9.375vw;
            line-height: .9em;
            font-family: var(--burido-additional-font-family);
            font-weight: normal;
            letter-spacing: 0;
            z-index: 0;
            width: 100%;
            text-align: center;
            white-space: nowrap;
            display: block;
            user-select: none;
            color: var(--burido-primary-color);
            pointer-events: none;
            -webkit-text-stroke-color: var(--burido-primary-color);
        }
        &::before{
            letter-spacing: .18em;
        }
        &.wgl-animation-background-text {
            &::before {
                display: none;
            }
        }
        .wgl-background-text {
            .letter {
                display: inline-block;
                text-indent: 0;
                opacity: 0;
            }
        }
    }
}

body.elementor-editor-active {
    .elementor-section {
        &.wgl-add-background-text {
            &.wgl-animation-background-text {
                &::before {
                    display: block;
                }
            }
        }
    }
    .elementor-section,
    .elementor-column{
        pointer-events: auto !important;
    }
    .wgl-products.appear-animation .product{
        opacity: 1;
        transform: unset;
    }
}
body .elementor-element-overlay ul li::before,
body .elementor-select-preset ul li::before {
    background: transparent;
}

.elementor-widget-container .elementor-counter .elementor-counter-title {
    line-height: 1.3;
    margin-top: 12px;
    font-weight: 500;
}

.elementor-widget-container {
    .elementor-divider{
        &,
        &-separator{
            border-radius: inherit;
        }
    }
}

.elementor-icon{
    display: inline-block;
    line-height: 1;
    text-align: center;
    transition: all .3s;
    i, svg{
        transition: none;
    }
}