/* ==================== ##Header List Info ==================== */
.elementor-widget.elementor-align-center {
    .wgl-header-list-info {
        .elementor-icon-list-item::after {
            margin: 0;
        }
    }
}

.elementor-widget-wgl-header-list-info {
    .elementor-icon-list-item {
        list-style-type: none;
        margin: 0;
        padding: 0;
        &,
        a{
            display: flex;
            align-items: flex-start;
        }
        &::before {
            display: none;
        }
        span,
        i {
            transition: 0.4s;
        }
        i, svg{
            color: var(--burido-primary-color);
            fill: var(--burido-primary-color);
        }
        &:hover{
            .elementor-icon-list-icon{
                i, svg{
                    color: var(--burido-primary-color);
                    fill: var(--burido-primary-color);
                }
            }
        }
    }
    .elementor-icon-list-items.elementor-inline-items {
        display: flex;
        flex-wrap: wrap;
    }
    .wgl-header-list-icon {
        i {
            -moz-osx-font-smoothing: grayscale;
            -webkit-font-smoothing: antialiased;
            display: inline-block;
            font-style: normal;
            font-variant: normal;
            text-rendering: auto;
            line-height: 1;
        }
    }
    a {
        color: inherit;
    }
    svg{
        transition: inherit;
    }
    .elementor-icon-list-items.elementor-inline-items {
        margin-right: -8px;
        margin-left: -8px;
        .elementor-icon-list-item {
            margin-right: 8px;
            margin-left: 8px;
        }
    }
    .elementor-icon-list-icon+.elementor-icon-list-text {
        align-self: center;
        padding-left: 5px;
    }
}

