/* ==================== ##Double Heading ==================== */

.elementor-widget-wgl-double-heading {
    .wgl-double-heading {
        position: relative;
        z-index: 0;
        .dblh__subtitle {
            display: inline-block;
            color: var(--burido-header-font-color);
            position: relative;
            padding: 6px 7px;
            letter-spacing: -0.03em;
            box-shadow: 0px 0px 0px 1px var(--burido-primary-color);
            border-radius: 10px;
        }
        .dblh__title-wrapper {
            position: relative;
            z-index: 1;
        }
        .dblh__title {
            font: inherit;
            line-height: inherit;
            color: inherit;
            letter-spacing: inherit;
            text-decoration: inherit;
            text-transform: inherit;
            transition: 0.4s, font 0s, letter-spacing 0s;
            text-decoration-thickness: 0.03em !important;
            text-underline-offset: 0.1em;
        }
        .dblh__title-1{
            color: var(--burido-header-font-color);
        }
        .dblh__title-2{
            color: var(--burido-primary-color);
        }
        .dblh__title-3{
            color: var(--burido-header-font-color);
        }
    }
}

body{
    @mixin wgl-dblh-responsive($media) {
        .elementor-widget-wgl-double-heading{
            &.a#{$media} {
                &left .dblh__subtitle {
                    &::after { display: none; }
                    &::before { display: inline-block; }
                }
                &right .dblh__subtitle {
                    &::before { display: none; }
                    &::after { display: inline-block; }
                }
                &center .dblh__subtitle {
                    &::before,
                    &::after {
                        display: inline-block;
                    }
                }
            }
        }
    }

    @include wgl-dblh-responsive('');
    &:is(
        [data-elementor-device-mode='tablet_extra'],
        [data-elementor-device-mode='tablet'],
        [data-elementor-device-mode='mobile_extra'],
        [data-elementor-device-mode='mobile']) {
        @include wgl-dblh-responsive('-tablet');
    }
    &:is(
        [data-elementor-device-mode='mobile_extra'],
        [data-elementor-device-mode='mobile']) {
        @include wgl-dblh-responsive('-mobile');
    }
}
