/* ==================== ##Striped Services ==================== */

.wgl-striped-services {
    display: flex;
    flex-direction: row;
    .service-item {
        flex: 1;
        height: 100%;
        transition: 0.5s;
        position: relative;
        &.active {
            flex: 3;
        }
        .wgl-striped__link{
            position: absolute;
            z-index: 2;
            width: 100%;
            height: 100%;
            left: 0;
            top: 0;
        }
        .service-image {
            height: 100%;
            width: 100%;
            background-repeat: no-repeat;
            transition: 0.5s;
            z-index: 0;
            position: relative;
            &::before,
            &::after{
                content: '';
                position: absolute;
                top: 0;
                right: 0;
                bottom: 0;
                left: 0;
                transition: all .4s linear;
            }
        }
        &_title {
            color: var(--burido-tertiary-color);
			position: relative;
			z-index: 1;
            font-size: 32px;
            line-height: 1.25em;
            transition: all 0.5s ease;
            opacity: 0;
            a {
                display: inline-block;
                font-size: 1em;
                line-height: inherit;
                color: inherit;
            }
        }
        &_subtitle {
            font-size: 24px;
            color: var(--burido-tertiary-color);
            font-weight: 700;
            line-height: 1.5em;
            font-family: var(--burido-content-font-family);
            text-transform: uppercase;
            letter-spacing: 0;
            margin-top: 14px;
            transition: all 0.5s ease;
            opacity: 0;
        }
        &_content {
            font-family: var(--burido-content-font-family);
            font-size: 18px;
            color: var(--burido-tertiary-color);
            line-height: 1.889em;
            transition: all 0.5s ease;
            opacity: 0;
        }
        &_bg_text {
            font-family: var(--burido-h3-font-family);
            font-weight: var(--burido-h3-font-weight);
            font-size: 110px;
            color: var(--burido-tertiary-color);
            line-height: 1.25em;
            transition: all 0.5s ease;
            letter-spacing: -0.04em;
            span{
                display: inline-block;
            }
            .bg_text_position-absolute & {
                display: flex;
                position: absolute;
                top: 0;
                right: 0;
                bottom: 0;
                left: 0;
            }
        }
        &_wrapper {
            display: flex;
            position: absolute;
            top: 0;
            left: 0;
            justify-content: flex-end;
            align-items: flex-start;
            text-align: left;
            flex-direction: column;
            width: 100%;
            height: 100%;
            overflow: hidden;
        }
        .service-item_button_wrapper{
            transition: all 0.5s ease;
            opacity: 0;
        }
        .wgl-striped_button{
            span{
                white-space: nowrap;
            }
        }
        &.active{
            .service-item_title,
            .service-item_subtitle,
            .service-item_content,
            .service-item_button_wrapper{
                opacity: 1;
            }
        }
    }
}

@mixin wgl-striped-responsive($media) {
    body[data-elementor-device-mode='#{$media}'] .wgl-striped-services.breakpoint_on-#{$media} {
        flex-direction: column;
        margin-right: 0 !important;
        .service-item {
            display: flex;
            width: 100%;
        }
        .service-item_title,
        .service-item_subtitle,
        .service-item_content{
            max-width: fit-content;
        }
    }
}

@include wgl-striped-responsive('widescreen');
@include wgl-striped-responsive('desktop');
@include wgl-striped-responsive('tablet_extra');
@include wgl-striped-responsive('tablet');
@include wgl-striped-responsive('mobile_extra');
@include wgl-striped-responsive('mobile');
