/* ==================== ## WGL Tabs ==================== */

.wgl-tabs-horizontal {
	display: flex;
	&_headings {
		display: flex;
		flex-direction: column;
		align-items: stretch;
		position: relative;
		z-index: 1;
	}
	&_header {
		width: 100%;
		display: flex;
		align-items: center;
		position: relative;
		text-align: center;
		font-size: 32px;
		line-height: 1.25em;
		transition: .4s;
		&_wrap{
			flex: 1;
			display: flex;
			justify-content: center;
			transition: background-color .4s;
			cursor: pointer;
		}
	}
	&_content {
		width: 100%;
		display: block;
		&-wrap{
			display: flex;
			flex-direction: column;
			align-items: center;
			justify-content: center;
			flex: 1 1 auto;
		}
	}
	&_icon {
		line-height: 1;
		color: inherit;
		transition: .4s;
		font-weight: normal;
	}
	&_title,
	&_prefix {
		font: inherit;
		color: inherit;
		line-height: inherit;
		letter-spacing: inherit;
		text-transform: inherit;
	}
	&_prefix {
		transition: color .4s;
	}
	.lavalamp {
		position: relative;
	}
	.lavalamp-object{
		position: absolute;
		z-index: 5;
		top: 0;
		right: 0;
		bottom: 0;
		left: auto;
		margin: 0px -2px auto auto;
		opacity: 0;
		font-size: 0;
		line-height: 0;
		&::after {
			content: "";
			position: absolute;
			width: 3px;
			height: 100%;
			background-color: currentColor;
			border-radius: 0;
			display: inline-block;
			margin: auto;
			top: 0;
			bottom: 0;
			left: 0;
		}
	}
	.lavalamp_animate .lavalamp-object {
		opacity: 1;
	}
}