/* ==================== #Calendar ==================== */

body .widget_calendar {
    .calendar_wrap {
        width: 100%;
        table {
            td {
                position: relative;
                z-index: 1;
                padding: 4px 0;
                text-align: center;
                font-size: 14px;
                border-color: #a5a5a5;
                > a {
                    display: inline-block;
                    width: 100%;
                    height: 100%;
                }
            }
            tr {
                border: 0;
            }
            th {
                padding: 5px 0;
                text-align: center;
                border-color: #a5a5a5;
            }
            caption {
                padding: 7px;
                font-size: 16px;
                font-weight: 600;
                text-transform: none;
            }
            tfoot {
                display: none;
            }
        }
        table td#today::before,
        tbody td > a::before {
            content: '';
            position: absolute;
            z-index: -1;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
            transition: 0.3s;
        }
        .wp-calendar-nav {
            margin-bottom: -7px;
        }
    }
}
.footer .calendar_wrap {
    .wp-calendar-nav span a,
    tbody {
        color: #ffffff;
    }
}
.wp-block-calendar {
    tbody td,
    table th {
        position: relative;
        z-index: 1;
        text-align: center;
        padding: 4px 0;
        font-size: 14px;
        border-color: #a5a5a5;
        &#today,
        a{
            color: var(--burido-secondary-color);
            &::before {
                content: '';
                position: absolute;
                z-index: -1;
                width: 100%;
                height: 100%;
                top: 0;
                left: 0;
                transition: 0.3s;
            }
        }
    }
    tfoot #next {
        text-align: right;
    }
    table {
        tbody,
        caption {
            color : inherit;
        }
        caption {
            padding: 7px;
            font-size: 16px;
            font-weight: 600;
        }
        caption,
        #today > a {
            color: var(--burido-secondary-color);
        }
        th{
            padding: 5px 0;
            text-align: center;
            background-color: transparent;
            border-color: #a5a5a5;
        }
    }
    a {
        text-decoration: none;
    }
}
.widget_calendar,
.wp-block-calendar {
    table {
        th {
            font-weight: 700;
            font-size: 16px;
        }
        &:where(:not(.has-text-color)) {
            color: inherit;
        }
    }
    .wp-calendar-nav {
        display: flex;
        justify-content: space-between;
        font-size: 14px;
        line-height: 0;
        span a {
            display: inline-block;
            margin-top: -1em;
            margin-bottom: 21px;
            line-height: 1;
        }
    }
}
