@use "variables";

/* ==================== ## Social Icons ==================== */
.elementor-shape-rounded .elementor-icon.elementor-social-icon {
    -webkit-border-radius: 10%;
    border-radius: 10%
}
.elementor-shape-circle .elementor-icon.elementor-social-icon {
    -webkit-border-radius: 50%;
    border-radius: 50%
}
div.elementor-widget-wgl-social-icons {
    &.elementor-grid{
        &-0,
        &-mobile-0,
        &-tablet-0 {
            .elementor-widget-container {
                line-height: 1;
                font-size: 0
            }
        }
    }
    &:not(.elementor-grid-0):not(.elementor-grid-tablet-0):not(.elementor-grid-mobile-0) .elementor-grid {
        display: inline-grid
    }
    .elementor-grid {
        grid-column-gap: var(--grid-column-gap,5px);
        grid-row-gap: var(--grid-row-gap,5px);
        grid-template-columns: var(--grid-template-columns);
        justify-content: var(--justify-content,center);
        justify-items: var(--justify-content,center)
    }
    .elementor-social-icon {
        --e-social-icon-icon-color: var(--burido-content-color);
        display: inline-flex;
        background-color: #818a91;
        align-items: center;
        justify-content: center;
        text-align: center;
        cursor: pointer;
        i {
            color: var(--e-social-icon-icon-color)
        }
        svg {
            fill: var(--e-social-icon-icon-color);
            transition: 0.4s;
        }
        &:last-child {
            margin: 0
        }
        &:hover {
            opacity: .9;
            color: var(--burido-content-color);
        }
    }
    .wgl-social-icons {
        .elementor-social-icon {
            font-size: var(--icon-size, 25px);
            line-height: var(--icon-size, 25px);
            width: calc(var(--icon-size, 25px) + (2 * var(--icon-padding, .5em)));
            height: calc(var(--icon-size, 25px) + (2 * var(--icon-padding, .5em)));
        }
        .icon__wrapper {
            display: inline-block;
        }

        .elementor-animation-float {
            &:active,
            &:focus,
            &:hover {
                transform: none;
                .wgl-icon {
                    transform: translateY(-8px);
                }
            }
        }
    }

    &.elementor-shape {
        &-circle,
        &-rounded,
        &-square {
            .elementor-social-icon {
                &-x-twitter,
                &-twitter,
                &-twitter-square{
                    background-color: variables.$twitter;
                }
                &-instagram{
                    background-color: variables.$instagram;
                }
                &-telegram,
                &-telegram-plane {
                    background-color: variables.$telegram;
                }
                &-pinterest-p,
                &-pinterest-square{
                    background-color: variables.$pinterest;
                }
                &-facebook,
                &-facebook-f,
                &-facebook-square,
                &-facebook-messenger{
                    background-color: variables.$facebook;
                }
                &-reddit,
                &-reddit-alien,
                &-reddit-square {
                    background-color: variables.$reddit;
                }
                &-whatsapp-square {
                    background-color: variables.$whatsapp;
                }
                &-youtube,
                &-youtube-square {
                    background-color: variables.$youtube;
                }
                &-dribbble-square {
                    background-color: variables.$dribbble;
                }
            }
        }

        &-fill {
            .icon__wrapper {
                &:hover {
                    i {
                        color: var(--burido-tertiary-color);
                    }
                }
            }
            .elementor-social-icon {
                background-color: transparent;
                i {
                    color: var(--burido-primary-color);
                }
            }

            .elementor-social-icon {
                &-x-twitter,
                &-twitter,
                &-twitter-square{
                    i {
                        color: variables.$twitter;
                    }
                }
                &-instagram{
                    i {
                        color: variables.$instagram;
                    }
                }
                &-telegram,
                &-telegram-plane {
                    i {
                        color: variables.$telegram;
                    }
                }
                &-pinterest-p,
                &-pinterest-square{
                    i {
                        color: variables.$pinterest;
                    }
                }
                &-facebook,
                &-facebook-f,
                &-facebook-square,
                &-facebook-messenger{
                    i {
                        color: variables.$facebook;
                    }
                }
                &-reddit,
                &-reddit-alien,
                &-reddit-square {
                    i {
                        color: variables.$reddit;
                    }
                }
                &-whatsapp,
                &-whatsapp-square {
                    i {
                        color: variables.$whatsapp;
                    }
                }
                &-youtube,
                &-youtube-square {
                    i {
                        color: variables.$youtube;
                    }
                }
                &-dribbble-square {
                    i {
                        color: variables.$dribbble;
                    }
                }
            }
        }
    }
}

