            &[class*='twitter'] { background-color: variables.$twitter; }
            &[class*='x-twitter'] { background-color: variables.$twitter; }
            &[class*='youtube'] { background-color: variables.$youtube; }
            &[class*='facebook'] { background-color: variables.$facebook; }
            &[class*='linkedin'] { background-color: variables.$linkedin; }
            &[class*='telegram'] { background-color: variables.$telegram; }
            &[class*='whatsapp'] { background-color: variables.$whatsapp; }
