/*==================== ##Team ==================== */

@use '../../variables';

.wgl_module_team {
    position: relative;
    z-index: 1;
    .team__member {
        transition: 0.3s;
    }
    .member__wrapper {
        position: relative;
        z-index: 1;
        transition: 0.3s;
        &:hover {
            .member__thumbnail {
                --wgl-team-image-scale-size: 1;
                &::after {
                    opacity: 1;
                }
                img {
                    transform: scale(var(--wgl-team-image-scale-size));
                }
            }
        }
    }
    .member__media {
        position: relative;
        z-index: 1;
        overflow: hidden;
    }
    .member__thumbnail {
        display: block;
        position: relative;
        border-radius: 0;
        overflow: hidden;
        --wgl-team-image-scale-size: 1;
        --wgl-team-image-transition: 0.6s;
        img {
            transition: var(--wgl-team-image-transition) ease-in-out;
            border-radius: inherit;
        }
        &::before,
        &::after {
            content: '';
            position: absolute;
            width: 100%;
            height: 100%;
            top: 0;
            right: 0;
            border-radius: inherit;
            transition: 0.5s ease-in-out;
            pointer-events: none;
        }
        &::after {
            opacity: 0;
        }
    }
    .member__info-wrapper {
        margin-top: 27px;
        margin-bottom: 19px;
        position: relative;
        z-index: 1;
        transition: 0.4s;
    }
    .member__info {
        position: relative;
        z-index: 1;
    }
    .member__name {
        font-size: 30px;
        line-height: 1.2;
        margin-bottom: 0;
        font-weight: 600;
        letter-spacing: -0.02em;
        a,
        span {
            font: inherit;
            line-height: inherit;
            color: inherit;
            letter-spacing: inherit;
            transition: 0.5s ease-in-out;
        }
        span {
            cursor: default;
        }
        a:hover {
            color: var(--burido-header-font-color);
        }
    }
    .member__highlighted {
        font-size: 14px;
        font-weight: 600;
        line-height: 1;
        transition: 0.4s;
        color: var(--burido-header-font-color);
        margin-top: 9px;
        position: relative;
        z-index: 1;
        padding: 4px 0;
        background: var(--burido-primary-color);
        display: inline-block;
    }
    .member__excerpt {
        margin-top: 15px;
        line-height: 1.7;
        transition: 0.4s;
        scrollbar-width: none;
        -ms-overflow-style: none;
        &::-webkit-scrollbar {
            display: none;
        }
    }
}

// ↓ Social Icons
.team__member {
    .member__socials {
        z-index: 1;
        line-height: 1;
    }
    > .member__wrapper {
        position: relative;
        z-index: 1;
        overflow: hidden;
        .member__socials {
            position: absolute;
            z-index: 1;
            bottom: 0;
            left: 0;
            margin: auto;
            width: fit-content;
            height: fit-content;
            text-align: center;
        }
        .social__icon {
            display: inline-block;
            position: relative;
            z-index: 1;
            width: 45px;
            height: 45px;
            line-height: 45px;
            margin: 0;
            text-align: center;
            transition: transform .3s ease-in, opacity .3s ease-in;
            opacity: 0;
            transform: translateY(100%);
            border-radius: 0;
        }
        &:hover {
            .social__icon {
                opacity: 1;
                transform: translateY(0);
                transition: transform .5s ease-in-out, opacity .5s ease-in-out;
                $delay: 0;
                @for $i from 1 through 10 {
                    &:nth-child(#{$i}) {
                        transition-delay: #{$delay}s;
                    }
                    $delay: $delay + 0.15;
                }
            }
        }
        @media (max-width: 767px) {
            .social__icon {
                opacity: 1;
                transform: scale(1);
            }
        }
    }
    .social__icon {
        display: inline-block;
        position: relative;
        z-index: 1;
        font-size: 16px;
        text-align: center;
        width: 50px;
        height: 50px;
        line-height: 50px;
        transition: 0.5s ease-in-out;
        border-radius: 50%;
        &:last-child {
            margin-right: 0;
        }
        &::before {
            display: inline-block;
            width: 100%;
            height: 100%;
            border-radius: inherit;
            background: var(--burido-secondary-color);
            color: var(--burido-tertiary-color);
            transition: 0.5s ease-in-out;
        }
        &:hover {
            &::before {
                color: var(--burido-secondary-color);
                background: var(--burido-primary-color);
            }
        }
    }
}

// ↓ Grid
.wgl_module_team {
    --burido-team-grid-gap: 37px;
    .team__members {
        &:not(.carousel) {
            display: flex;
            flex-wrap: wrap;
            .team__member {
                margin-bottom: var(--burido-team-grid-gap);
            }
            @media (min-width: 768px) {
                margin-right: calc((var(--burido-team-grid-gap) / 2) * -1);
                margin-left: calc((var(--burido-team-grid-gap) / 2) * -1);
                .team__member {
                    margin-right: calc(var(--burido-team-grid-gap) / 2);
                    margin-left: calc(var(--burido-team-grid-gap) / 2);
                }
            }
        }
        &.carousel {
            .wgl-carousel_wrapper {
                margin-right: calc((var(--burido-team-grid-gap) / 2) * -1);
                margin-left: calc((var(--burido-team-grid-gap) / 2) * -1);
            }
            .member__wrapper {
                margin-right: calc((var(--burido-team-grid-gap) / 2));
                margin-left: calc((var(--burido-team-grid-gap) / 2));
            }
        }
    }
    .grid-col- {
        &-1 .team__member {
            width: 100%;
        }
        &-2 .team__member {
            width: calc(50% - var(--burido-team-grid-gap));
        }
        &-3 .team__member {
            width: calc(33.333333% - var(--burido-team-grid-gap));
        }
        &-4 .team__member {
            width: calc(25% - var(--burido-team-grid-gap));
        }
        &-5 .team__member {
            width: calc(20% - var(--burido-team-grid-gap));
        }
        &-6 .team__member {
            width: calc(16.6666% - var(--burido-team-grid-gap));
        }
        @media (max-width: 1500px) {
            &-5,
            &-6 {
                .team__member {
                    width: calc(25% - var(--burido-team-grid-gap));
                }
            }
        }
        @media (max-width: 1370px) {
            &-4,
            &-5,
            &-6 {
                .team__member {
                    width: calc(33.333333% - var(--burido-team-grid-gap));
                }
            }
        }
        @media (max-width: 1025px) {
            &-3,
            &-4,
            &-5,
            &-6 {
                .team__member {
                    width: calc(50% - var(--burido-team-grid-gap));
                }
            }
        }
        @media (max-width: 767px) {
            &-2,
            &-3,
            &-4,
            &-5,
            &-6 {
                .team__member {
                    width: 100%;
                }
            }
        }
    }
}