@use "mixins";

/* ==================== ##General Styles ==================== */

//* ↓ Inputs
.wc-block-components-form div.wc-block-components-text-input input:is([type=email],[type=number],[type=tel],[type=text],[type=url]),
div.wc-block-components-text-input input:is([type=email],[type=number],[type=tel],[type=text],[type=url]),
input[type='text'],
input[type='url'],
input[type='search'],
input[type='email'],
input[type='password'],
input[type='tel'],
input[type='time'],
input[type='number'],
input[type='date'],
select,
textarea.wc-block-components-textarea,
textarea {
    display: block;
    height: 40px;
    max-width: 100%;
    margin:     0 0 28px 0;
    padding: 0;
    border: 1px solid var(--burido-header-font-color);
    border-width: 0 0 1px 0;
    border-radius: unset;
    font-family: var(--burido-content-font-family);
    font-size: 16px;
    line-height: 1.7;
    font-weight: 400;
    text-transform: none;
    color: var(--burido-header-font-color);
    background-color: transparent;
    transition: all 0.3s, height 0s;
    @include mixins.placeholder;
}
input {
    &:-webkit-autofill,
    &:-webkit-autofill:hover,
    &:-webkit-autofill:focus {
        -webkit-text-fill-color: var(--burido-header-font-color);
        background: unset;
        transition: background-color 0s ease-in-out 9999s;
    }
}
input[type='checkbox'],
input[type='radio']{
    cursor: pointer;
    margin: 0 15px 0 0;
    vertical-align: middle;
    & + label,
    & + span {
        display: inline;
        vertical-align: middle;
        user-select: none;
        cursor: pointer;
    }
    & + span{
        font-family: var(--burido-header-font-family);
        font-weight: 400;
        font-size: 16px;
        color: var(--burido-content-color);
    }
}

.wgl-style-input {
    label{
        color: var(--burido-header-font-color);
    }
    .bapf_sfilter.bapf_ckbox{
        input[type='checkbox'],
        input[type='radio']{
            visibility: hidden;
            opacity: 0;
            margin: 0;
            font-size: 0;
        }
        label{
            font-size: 16px;
            font-weight: 500;
            line-height: 24px;
        }
    }
    div.wc-block-components-checkbox .wc-block-components-checkbox__input[type='checkbox'],
    div.wc-block-components-radio-control .wc-block-components-radio-control__input,
    input[type='checkbox'],
    input[type='radio']{
        --input-color: var(--burido-header-font-color);
        --input-disabled: var(--burido-content-color);
        appearance: none;
        margin: 0 15px 0 0;
        font-size: 20px;
        color: currentColor;
        width: 1em;
        height: 1em;
        min-width: unset;
        min-height: unset;
        border: 1px solid rgba(var(--burido-header-rgb), 1) !important;
        background: unset !important;
        border-radius: 50%;
        vertical-align: middle;
        left: 0;

        display: inline-grid !important;
        place-content: center;
        &::before {
            content: "";
            width: min(calc(1em - 6px), 8px);
            height: min(calc(1em - 6px), 8px);
            min-height: unset;
            min-width: unset;
            position: static;
            border-radius: inherit;
            transform: scale(0);
            transition: 120ms transform ease-in-out;
            box-shadow: inset 1em 1em var(--input-color);
            /* Windows High Contrast Mode */
            background-color: CanvasText;
        }
        &::after{
            display: none;
        }
        &:checked::before {
            transform: scale(1);
        }
        &:focus {
            outline: max(1px, 0.15em) solid currentColor;
            outline-offset: max(1px, 0.15em);
        }
        &:disabled {
            --input-color: var(--input-disabled);
            color: var(--input-disabled);
            cursor: not-allowed;
        }
    }
    div.wc-block-components-checkbox .wc-block-components-checkbox__input[type='checkbox'],
    input[type='checkbox']{
        border-radius: 3px;
        &::before{
            background: var(--burido-button-success-h) no-repeat center;
            box-shadow: unset;
            width: 1em;
            height: 1em;
            background-size: calc(1em - 6px);
        }
    }
}

input[type='submit'],
button {
    display: inline-block;
    height: 60px;
    max-width: 100%;
    margin-bottom: 0;
    border-radius: 15px;
    outline: none;
    padding: 9px 34px;
    font-size: 14px;
    line-height: 30px;
    font-weight: 600;
    font-family: var(--burido-header-font-family);
    letter-spacing: 0.05em;
    cursor: pointer;
    -webkit-appearance: none;
    transition: 0.4s;
}
input[type='submit'],
button,
.wp-block-search .wp-block-search__button,
#comments input.submit,
form.post-password-form input[type='submit']{
    color: var(--burido-button-color-idle);
    background: var(--burido-button-bg-idle);
    border: 1px solid var(--burido-button-border-idle);
    &:hover,
    &:focus,
    &:active {
        color: var(--burido-button-color-hover);
        background: var(--burido-button-bg-hover);
        border-color: var(--burido-button-border-hover);
    }
}
textarea.wc-block-components-textarea,
textarea {
    height: 114px;
    padding: 5px 0;
}
input[type=number] {
    &::-webkit-inner-spin-button,
    &::-webkit-outer-spin-button {
        opacity: 1;
    }
}
.input-bg-white {
    input,
    textarea {
        background-color: #ffffff;
    }
}
select {
    width: 100%;
    overflow: hidden;
    outline: none;
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    background-image: var(--burido-bg-caret2-h);
    background-size: 10px;
    background-repeat: no-repeat;
    background-position: 100% center;
    padding-left: 0;
    option {
        background: var(--body-background-color);
    }
}
label{
    transition: 0.4s;
}
//* ↑ inputs

body{
    --admin-bar-height: 0.01px;
}
.admin-bar {
    --admin-bar-height: 32px;
    @media all and (max-width: 782px) {
        --admin-bar-height: 46px;
    }
    @media all and (max-width: 600px) {
        --admin-bar-height: 0.01px;
    }
    .wgl-sticky-header {
        top: var(--admin-bar-height);
    }
    .wgl-theme-header .woo_mini_cart {
        margin-top: 0;
    }
}

.post-password-form {
    margin-bottom: 20px;
    p:first-child {
        margin-bottom: 24px;
    }
    label {
        display: inline-block;
        width: 100%;
        margin-bottom: 10px;
        margin-right: 8px;
        @media (min-width: 600px) {
            width: calc(100% - 130px);
            max-width: 270px;
        }
        input[type='password'] {
            width: 100%;
            margin-top: 5px;
            margin-bottom: 0;
        }
    }
    input[type='submit'] {
        min-width: 100px;
        margin-bottom: 10px;
        color: var(--burido-button-color-idle);
        background-color: var(--burido-button-bg-idle);
        transform: translateY(2px);
        height: 42px;
        padding: 5px 28px 4px;
        &:hover,
        &:focus {
            color: var(--burido-button-color-hover);
            background: var(--burido-button-bg-hover);
        }
    }
}

//* ↓ Container
.wgl-container {
    margin-right: auto;
    margin-left: auto;
    width: 1170px;
    &.full-width {
        width: 100%;
        max-width: 100%;
        margin-left: 0;
        margin-right: 0;
    }
    .wgl-container {
        width: 100%;
    }
    .elementor-section-boxed {
        .elementor-section-boxed .elementor-container {
            width: 100%;
        }
    }
    &.wgl-content-sidebar {
        .elementor {
            margin-left: -15px;
            margin-right: -15px;
        }
    }
}

#main .wgl-container .wgl_wrapper {
    left: 0 !important;
}

.row,
.wgl-container,
.clearfix {
    &::after,
    &::before {
        content: '';
        display: table;
        line-height: 0;
    }
}

.wgl-container::after,
.row::after,
.clear,
.clearfix::after {
    clear: both;
}

[class*='wgl_col-'] {
    float: left;
    min-height: 1px;
}

.row {
    margin-left: -15px;
    margin-right: -15px;
    [class*='wgl_col-'] {
        display: block;
        width: 100%;
        padding-right: 15px;
        padding-left: 15px;
    }
}

//* ↓ Carousel
.wgl-carousel {
    position: relative;
    z-index: 1;
}
.wgl-carousel_swiper a {
    &,
    &:hover,
    &:focus {
        transition: 0.4s;
    }
}
//* ↑ carousel

a:hover {
    color: inherit;
}

.wgl-icon {
    display: inline-block;
    line-height: 0;
    fill: currentColor;
    transition: 0.4s;
    svg{
        height: 1em;
        width: 1em;
        color: inherit;
        font-size: inherit;
        transition: none;
    }
    .elementor-icon{
        color: inherit !important;
        fill: currentColor !important;
        transition: unset !important;
        font-size: inherit !important;
    }
}
.wgl-svg-icon{
    line-height: inherit;
}
.wgl-number {
    display: inline-block;
    transition: 0.4s;
    .number {
        min-width: 1em;
        position: relative;
        display: block;
    }
}

//* ↓ Hover Links
body .hover_links {
    a {
        color: inherit;
        text-decoration: underline transparent;
        transition: color 0.3s, text-decoration-color 0.3s;
        text-underline-offset: 0.2em;
        &:hover {
            color: currentColor;
            text-decoration-color: currentColor;
        }
    }
    &.white {
        a {
            &:hover {
                color: #ffffff;
                text-decoration-color: #ffffff;
            }
        }
    }
    &.primary {
        a {
            &:hover {
                color: #ffffff;
                text-decoration-color: #ffffff;
            }
        }
    }
}

//* ↓ Widgets Media/Content Alignment
.wgl-layout {
    &-left,
    &-right {
        display: flex;
    }
}
.a {
    // prettier-ignore
    &left .wgl-layout {
        &-left { justify-content: flex-start; }
        &-right { justify-content: flex-end; }
    }
    &center .wgl-layout {
        &-left,
        &-right {
            justify-content: center;
        }
    }
    // prettier-ignore
    &right .wgl-layout {
        &-left { justify-content: flex-end; }
        &-right { justify-content: flex-start; }
    }
}

//* ↓ Extra Classes
.fullwidth-wrapper {
    width: 100%;
}
.z-index-1 {
    z-index: 1;
}
.relative {
    position: relative;
}
.text-uppercase {
    text-transform: uppercase;
}
.bypostauthor {
    opacity: 1;
}
.ohidden {
    overflow: hidden;
}
.ovisible {
    overflow: visible;
}
.d-block {
    display: block;
}
.d-none {
    display: none;
}
body {
    &[data-elementor-device-mode='desktop'] {
        .d-xl-none {
            display: none;
        }
    }
    &:not([data-elementor-device-mode='desktop']) {
        .d-xl-block {
            display: none;
        }
    }
}
//* ↑ extra classes

.wp-caption-text,
.wp-caption .wp-caption-text {
    margin: 0.5em 0;
    font-size: 13px;
    text-align: center;
}
.wp-caption,
.gallery-caption {
    max-width: 100%;
    margin-bottom: 1em;
    font-style: italic;
    img {
        border-radius: unset;
    }
}

#main {
    padding: 40px 0;
    position: relative;
    overflow: hidden;
    min-height: calc(100vh - var(--header-height, 0px) - var(--footer-height, 0px) - var(--pt-height, 0px) - var(--wp-admin--admin-bar--height, 0px));
}
.wgl-theme-header.header_overlap ~ #main {
    min-height: calc(100vh - var(--footer-height, 0px) - var(--pt-height, 0px) - var(--wp-admin--admin-bar--height, 0px));
}
.archive:not(.woocommerce) {
    #main {
        padding-bottom: 100px;
    }
}
body > #main .row.sidebar_left #main-content {
    float: right;
}
.gm-control-active {
    border-radius: unset;
    box-shadow: none;
}

hr {
    margin: 20px 0 20px;
    border: none;
    border-bottom: 1px solid #1d1f21;
    &.wp-block-separator {
        max-width: 100px;
        &.is-style-wide,
        &.is-style-dots {
            max-width: 100%;
        }
    }
}

table {
    td,
    th {
        padding: 5px 10px;
        border: 1px solid rgba(var(--burido-header-rgb), 0.2);
        text-align: left;
    }
    &:not(:last-child) {
        margin-bottom: 22px;
    }
}

//* https://make.wordpress.org/accessibility/handbook/markup/the-css-class-screen-reader-text/
//* Text meant only for screen readers.
.screen-reader-text {
    position: absolute !important;
    height: 1px;
    width: 1px;
    margin: -1px;
    border: 0;
    padding: 0;
    clip: rect(1px, 1px, 1px, 1px);
    clip-path: inset(50%);
    word-wrap: normal !important;
    overflow: hidden;
    &:focus {
        display: block;
        z-index: 100000; //* Above WP toolbar
        top: 5px;
        left: 5px;
        width: auto;
        height: auto;
        padding: 15px 23px 14px;
        font-size: 1em;
        line-height: normal;
        color: #444444;
        text-decoration: none;
        background-color: #eee;
        clip: auto !important;
        clip-path: none;
    }
}

//* Audio def spacer
.mejs-container {
    margin-bottom: 20px;
}

.wgl-row-animation {
    > .elementor-container {
        z-index: 1;
    }
}

.particles-js {
    position: absolute;
    z-index: 0;
    width: 100%;
    height: 100%;
    background-repeat: no-repeat;
    background-size: cover;
    background-position: 50% 50%;
}
.page-header .particles-js {
    left: 0;
    top: 0;
}

.extended-parallax {
    position: absolute;
    z-index: -1;
    width: 100%;
    height: 100%;
    pointer-events: none;
    .wgl-parallax-layer {
        position: relative !important;
    }
}
.wgl-background-image_parallax {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    div {
        height: 100%;
    }
}

.wgl-elementor-shape {
    overflow: hidden;
    position: absolute;
    left: 0;
    width: 100%;
    line-height: 0;
    direction: ltr;
    pointer-events: none;
    &-top {
        top: -1px;
    }
    &-bottom {
        bottom: -1px;
    }
    svg {
        display: block;
        width: calc(100% + 1.3px);
        position: relative;
        left: 50%;
        transform: translateX(-50%);
    }
}

#burido-footer-inline-css {
    display: none;
}

.wgl-body-bg {
    position: absolute;
    z-index: -1;
    pointer-events: none;
    width: 100%;
    height: 100%;
    left: 0;
    top: 0;
}
.aligncenter {
    display: block;
    margin-left: auto;
    margin-right: auto;
}
.wgl-body-lines {
    position: absolute;
    z-index: -1;
    top: 0;
    left: 0;
    bottom: 0;
    right: 0;
    pointer-events: none;
    > span,
    &::before,
    &::after {
        content: '';
        position: absolute;
        z-index: -100;
        height: 100%;
        width: 1px;
        background: var(--burido-body-lines-color);
        top: 0;
    }
    &::before {
        left: 89px;
        @media (max-width: 767px) {
            left: 29px;
        }
    }
    > span {
        left: 50%;
    }
    &::after {
        right: 89px;
        @media (max-width: 767px) {
            right: 29px;
        }
    }
}