/* ==================== ##Likes ==================== */

.wgl-likes {
    display: inline-block;
    flex-shrink: 0;
    .sl-button {
        color: inherit;
        cursor: pointer;
        transition: 0.4s;
        display: inline-block;
        font-family: var(--burido-header-font-family);
        font-weight: 500;
        .sl-icon {
            display: inline-block;
            position: relative;
            z-index: 1;
            text-align: center;
            font-size: 16px;
            font-weight: normal;
            line-height: 0;
            opacity: 0.5;
            &::before {
                color: inherit;
                transition: 0s;
                display: inline-block;
                vertical-align: middle;
                line-height: 0;
            }
            &.liked {
                opacity: 1;
            }
        }
        .post_featured_bg & {
            display: flex;
            font-size: 14px;
            letter-spacing: 0;
            text-decoration: unset;
            justify-content: center;
            align-items: center;
            .sl-icon {
                font-size: 24px;
                margin-top: -8px;
                &:before {
                    line-height: initial;
                }
            }
            .sl-count {
                line-height: 19px;
                margin-left: 5px;
                &-text {
                    font-size: 12px;
                    font-weight: 700;
                }
            }
        }
    }
    .sl-count {
        display: inline-block;
        margin-left: 6px;
    }
    .sl-count-text,
    .sl-loader {
        display: none !important;
    }
}
