/* ==================== ##Clients ==================== */

.wgl-clients {
    --wgl-gap: 30px;
    display: flex;
    flex-wrap: wrap;
    .wgl-carousel_wrapper {
        width: 100%;
        overflow: visible;
    }
    .clients_item {
        height: auto;
        padding: calc(0.5 * var(--wgl-gap));
    }
    .clients_image {
        display: flex;
        height: 100%;
        overflow: hidden;
        transition: 0.4s;
        position: relative;
        z-index: 1;
        .image_wrapper {
            display: flex;
            position: relative;
            z-index: 1;
            align-items: center;
            height: max-content;
            width: auto;
            justify-content: center;

            .link_on-wrapper & {
                height: auto;
                width: 100%;
            }
        }
        .link_on-wrapper & {
            align-items: stretch;
        }
        &.swiper-slide {
            display: flex;
            height: auto;
        }
        &::before,
        &::after {
            content: '';
            position: absolute;
            z-index: -1;
            width: 100%;
            height: 100%;
            background-repeat: no-repeat;
            background-position: center;
            transition: inherit;
        }
        &::after {
            opacity: 0;
        }
        &:hover {
            &::before {
                opacity: 0;
            }
            &::after {
                opacity: 1;
            }
        }
        .link_on-image & {
            align-items: stretch;
            align-content: stretch;
        }
    }
    .hover_image {
        display: none;
        position: absolute;
        z-index: 1;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        margin: auto;
        visibility: hidden;
    }
    &.items-1 > .clients_item {
        width: 100%;
        &:nth-child(2),
        &:nth-child(n + 3) {
            clear: left;
        }
    }
    &.items-2 > .clients_item {
        width: 50%;
        &:nth-child(3),
        &:nth-child(2n + 5) {
            clear: left;
        }
    }
    &.items-3 > .clients_item {
        width: 33.333333%;
        &:nth-child(4),
        &:nth-child(3n + 7) {
            clear: left;
        }
    }
    &.items-4 > .clients_item {
        width: 25%;
        &:nth-child(5),
        &:nth-child(4n + 9) {
            clear: left;
        }
    }
    &.items-5 > .clients_item {
        width: 20%;
        &:nth-child(6),
        &:nth-child(5n + 11) {
            clear: left;
        }
    }
    &.items-6 > .clients_item {
        width: 16.666666%;
        &:nth-child(7),
        &:nth-child(6n + 13) {
            clear: left;
        }
    }
    &.items-7 > .clients_item {
        width: 14.2857%;
        &:nth-child(8),
        &:nth-child(7n + 15) {
            clear: left;
        }
    }
    img {
        transition: inherit;
    }
    &.anim-zoom {
        .link_on-wrapper & .clients_image,
        .link_on-image & .image_wrapper {
            img {
                transform: scale(0.95);
            }
            &:hover img {
                transform: scale(1);
            }
        }
    }
    &.anim-opacity {
        .link_on-wrapper & .clients_image,
        .link_on-image & .image_wrapper{
            img {
                opacity: 0.5;
            }
            &:hover img {
                opacity: 1;
            }
        }
    }
    &.anim-grayscale {
        .link_on-wrapper & .clients_image,
        .link_on-image & .image_wrapper{
            img {
                filter: grayscale(100%);
                opacity: 0.6;
            }
            &:hover img {
                filter: grayscale(0);
                opacity: 1;
            }
        }
    }
    &.anim-contrast {
        .link_on-wrapper & .clients_image,
        .link_on-image & .image_wrapper{
            &:hover img {
                filter: contrast(300%);
            }
        }
    }
    &.anim-blur-1 {
        .link_on-wrapper & .clients_image,
        .link_on-image & .image_wrapper {
            &:hover img {
                filter: blur(1px);
            }
        }
    }
    &.anim-blur-2 {
        .link_on-wrapper & .clients_image,
        .link_on-image & .image_wrapper{
            img {
                filter: blur(1px);
            }
            &:hover img {
                filter: blur(0);
            }
        }
    }
    &.anim-invert {
        .link_on-wrapper & .clients_image,
        .link_on-image & .image_wrapper {
            img {
                filter: invert(100%);
            }
        }
    }
    &.anim-ex_images {
        .link_on-wrapper & .clients_image,
        .link_on-image & .image_wrapper{
            .hover_image {
                display: block;
                opacity: 0;
            }
            &:hover .hover_image {
                opacity: 1;
                visibility: visible;
                & + .main_image {
                    opacity: 0;
                }
            }
        }
    }
    &.anim-ex_images_ver {
        .link_on-wrapper & .clients_image,
        .link_on-image & .image_wrapper {
            overflow: hidden;
            .hover_image {
                opacity: 0;
                display: block;
                transform: translateY(-100%);
            }
            &:hover .hover_image {
                opacity: 1;
                visibility: visible;
                transform: translateY(0%);
                & + .main_image {
                    opacity: 0;
                    transform: translateY(100%);
                }
            }
        }
    }
    &.anim-mask_image {
        .clients_image{
            justify-content: center;
        }
        .image_wrapper {
            height: auto !important;
            -webkit-mask-size: contain;
            -webkit-mask-position: center center;
            -webkit-mask-repeat: no-repeat;
            overflow: hidden;
            transition: inherit;
        }
    }
}
.elementor-section-full_width {
    .elementor-column-gap-no {
        .elementor-widget-wgl-clients {
            .wgl-carousel {
                .swiper-container{
                    overflow: visible;
                }
            }
        }
    }
}
