/* ==================== ##Typography ==================== */

//* Highlighter
span.highlighter {
    padding: 3px 0.2em;
    border-radius: 5px;
    &.primary {
        background: var(--burido-primary-color);
    }
    &.secondary {
        color: var(--burido-tertiary-color);
        background: var(--burido-secondary-color);
    }
    &.tertiary {
        color: var(--burido-header-font-color);
        background: var(--burido-tertiary-color);
    }
    &.quaternary {
        color: var(--burido-tertiary-color);
        background: var(--burido-header-font-color);
    }
    &.header {
        color: var(--burido-tertiary-color);
        background: var(--burido-header-font-color);
    }
}

//* Underline
span.underline {
    background-repeat: no-repeat;
    background-size: 100% 0.25em;
    background-position: 0% 80%;
    transition: background-size 0.8s 0s;
    &.primary {
        background-image: linear-gradient(to top, var(--burido-primary-color), var(--burido-primary-color));
    }
    &.secondary {
        background-image: linear-gradient(to top, var(--burido-secondary-color), var(--burido-secondary-color));
    }
    &.tertiary {
        background-image: linear-gradient(to top, var(--burido-tertiary-color), var(--burido-tertiary-color));
    }
    &.quaternary {
        background-image: linear-gradient(to top, var(--burido-quaternary-color), var(--burido-quaternary-color));
    }
    &.header {
        background-image: linear-gradient(to top, var(--burido-header-font-color), var(--burido-header-font-color));
    }
}

//* ↓ Blockquote
blockquote {
    position: relative;
    z-index: 1;
    margin: 20px 0;
    padding-left: 70px;
    font-size: 24px;
    line-height: 1.5;
    font-weight: 500;
    min-height: 70px;
    color: var(--burido-header-font-color);
    letter-spacing: -0.03em;
    &::before {
        display: block;
        content: "";
        mask-image: var(--burido-quote-h);
        mask-position: center center;
        mask-size: 1em;
        mask-repeat: no-repeat;
        width: 0.6em;
        height: 0.5em;
        padding: 0;
        box-shadow: none;
        background-color: currentColor;
        font-style: normal;
        font-variant: normal;
        text-transform: none;
        line-height: 0;
        font-size: 80px;
        transition: transform .4s;
        color: var(--burido-primary-color);
        position: absolute;
        z-index: 1;
        left: 0;
        top: 0;
    }
    cite {
        display: block;
        position: relative;
        margin-top: 14px;
        font-size: 18px;
        font-family: var(--burido-header-font-family);
        line-height: 1.3;
        font-style: normal;
        font-weight: 500;
        letter-spacing: 0;
        a {
            color: inherit;
        }
    }
    p {
        &:last-of-type {
            margin-bottom: 0;
        }
        &[style*='text-align: left'] + footer {
            text-align: left;
        }
        &[style*='text-align: center'] + footer {
            text-align: center;
        }
        &[style*='text-align: right'] + footer {
            text-align: right;
        }
    }
}

//* ↓ Dropcaps
.dropcap {
    position: relative;
    z-index: 1;
    float: left;
    width: 1.5em;
    height: 1.5em;
    margin-top: 0.3em;
    margin-right: 0.5em;
    font-size: 1.75em;
    line-height: 1.55em;
    color: var(--burido-header-font-color);
    font-family: var(--burido-header-font-family);
    font-weight: 600;
    text-align: center;
    overflow: hidden;
    border-radius: 10px;
    &:not(.alt) {
        border: 1px solid;
        line-height: calc(1.55em - 2px);
    }
    &.simple {
        border: unset;
        background: unset;
        width: auto;
        height: auto;
        min-width: 1em;
        font-size: 2.5em;
        line-height: 1.2;
        margin-top: 0.1em;
        margin-right: 0.2em;
    }
    &.primary {
        color: var(--burido-primary-color);
        border-color: var(--burido-primary-color);
        &.alt {
            color: var(--burido-header-font-color);
            background: var(--burido-primary-color);
        }
    }
    &.secondary {
        border-color: var(--burido-secondary-color);
        color: var(--burido-secondary-color);
        &.alt {
            color: var(--burido-tertiary-color);
            background: var(--burido-secondary-color);
        }
    }
    &.heading {
        border-color: var(--burido-header-font-color);
        color: var(--burido-header-font-color);
    }
    &.rounded {
        border-radius: 50%;
    }
    &.simple {
        font-size: 2.5em;
        text-align: left;
        border: unset;
        background: unset;
        width: unset;
        height: unset;
        line-height: 1;
    }
}
.elementor-drop-cap {
    margin-top: 0.11em;
    font-weight: 700;
}
p.has-drop-cap:not(:focus):first-letter {
    font-size: 3em;
    line-height: 1.2;
    font-weight: 600;
}
//* ↑ dropcaps

small {
    font-size: 0.8em;
}
code,
tt,
kbd {
    font-size: 87.5%;
    word-break: break-word;
}
i,
cite,
em,
var,
address,
dfn,
q {
    font-style: italic;
}
kbd {
    font-family: monospace;
}
sub {
    vertical-align: sub;
    font-size: smaller;
}
sup {
    vertical-align: super;
    font-size: smaller;
}
