/* ==================== ##Steps ==================== */
@use '../../mixins';

.wgl-steps {
	&-wrap{
		.steps-single-wrap{
			display: grid;
			width: 100%;
			height: auto;
			position: relative;
			justify-items: center;
			grid-template-rows: 1fr 1fr;
			grid-gap: 30px;
			.steps-content_wrap{
				font-size: initial;
				.steps-date{
					font-family: var(--burido-additional-font-family);
					font-weight: 400;
					color: var(--burido-primary-color);
					display: block;
					font-size: 48px;
					line-height: 1em;
					letter-spacing: -0.02em;
					transition: .4s;
				}
				.steps-title{
					font-family: var(--burido-header-font-family);
					font-weight: var(--burido-header-font-weight);
					font-size: 24px;
					line-height: 1.333em;
					transition: .4s;
				}
				.steps-text{
					p:last-child{
						margin-bottom: 0;
					}
				}
			}
			.steps-icon{
				i{
					line-height: 1em;
				}
			}
			.steps-image img{
				box-sizing: content-box;
				transition: .4s;
			}
			.steps-same_height{
				display: flex;
				flex-direction: column;
			}
			&.steps-single-invert{
				.steps-image{
					margin-bottom: auto;
				}
			}
			&:not(.steps-single-invert){
				.steps-image{
					margin-top: auto;
				}
			}
			&.steps-single-invert{
				.steps-same_height.steps-media{
					order: 1;
				}
				.steps-same_height.steps-content_wrap{
					justify-content: flex-end;
				}
				.steps-dot .dot::after{
					top: 100%;
					bottom: auto;
					margin: 10px auto 0;
				}
			}
			.steps-dot{
				position: absolute;
				z-index: 2;
				width: 100%;
				left: 0;
				bottom: 0;
				top: 0;
				right: 0;
				height: fit-content;
				margin: auto !important;
				.steps-dot-line{
					--color-1: var(--burido-primary-color);
					position: absolute;
					left: 0;right: 0;top: 0;bottom: 0;
					&::before,
					&::after{
						content: '';
						width: 50%;
						height: 1px;
						display: block;
						position: absolute;
						top: 0; bottom: 0;
						margin: auto;
						background-repeat: no-repeat;
						background-color: var(--color-1);
					}
					&::before{
						right: 50%;
					}
					&::after{
						left: 50%;
					}
				}
				.dot{
					--dot-size: 9px;
					display: block;
					line-height: var(--dot-size);
					padding-top: 1px;
					font-size: 14px;
					margin: auto;
					background-size: var(--dot-size);
					background-repeat: no-repeat;
					width: var(--dot-size);
					height: var(--dot-size);
					border-radius: var(--dot-size);
					z-index: 2;
					position: relative;

					&::after{
						content: '';
						position: absolute;
						left: 0;
						right: 0;
						bottom: 100%;
						width: 2px;
						height: 19px;
						margin: 0 auto 10px;
					}
				}
			}

			&:first-child{
				.steps-dot-line {
					&::before {
						width: 100vw;
					}
				}
			}
			&:last-child{
				.steps-dot-line {
					&::after {
						width: 100vw;
					}
				}
			}
		}
	}

	&.wgl-steps-col-1{
		.steps-single-wrap{
			&.steps-single-invert {
				flex-direction: column;
				.steps-same_height.steps-content_wrap {
					justify-content: flex-start;
				}
				.steps-same_height.steps-media{
					order: 0;
				}
			}
		}
	}

	&.appear_anim{
		.steps-dot,
		.steps-content_wrap,
		.steps-media{
			opacity: 0;
		}
		.steps-dot{
			transition: all .4s, opacity .4s .3s, transform .4s .3s;
		}

		.steps-single-wrap {
			&:not(.steps-single-invert) {
				.steps-content_wrap{
					transition: all .4s, opacity .4s .5s, transform .4s .5s;
					transform: translateY(-20px);
				}
				.steps-media{
					transition: all .4s, opacity .4s .9s, transform .4s .9s;
					transform: translateY(20px);
				}
			}
			&.steps-single-invert {
				.steps-content_wrap{
					transition: all .4s, opacity .4s .5s, transform .4s .5s;
					transform: translateY(20px);
				}
				.steps-media{
					transition: all .4s, opacity .4s .9s, transform .4s .9s;
					transform: translateY(-20px);
				}
			}
		}
		.show{
			.steps-dot,
			.steps-media,
			.steps-content_wrap{
				opacity: 1;
				transform: translateY(0) !important;
			}
		}
	}
}
.svg_to_clip{
	width: 50px;
}