/* ==================== ##Portfolio ==================== */

//* Portfolio Container
.row .portfolio__item {
    &.swiper-slide{
        display: inline-block;
    }
}
body[data-elementor-device-mode='desktop'],
body[data-elementor-device-mode='laptop'],
body[data-elementor-device-mode='widescreen'] {
    .item__wrapper.wgl-cursor-text {
        .item__image::before,
        .item__image::after,
        .portfolio_link::before,
        .item__description {
            display: none;
        }
    }
}
.portfolio__item {
    --pf-transition: 0.5s ease-in-out;
    .description__wrapper {
        text-align: left;
        width: 100%;
        transition: var(--pf-transition);
    }
    .item__title {
        .title {
            font-size: 24px;
            line-height: 1.333;
            transition: var(--pf-transition);
            letter-spacing: -0.03em;
            font-weight: 600;
            &:hover {
                color: var(--burido-secondary-color);
            }
            a {
                letter-spacing: inherit;
            }
        }
        span,
        a {
            color: inherit;
            font: inherit;
            line-height: inherit;
            transition: unset;
        }
    }
    .portfolio_link {
        display: block;
        position: absolute;
        z-index: 0;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        font-size: 24px;
        opacity: 0;
        &,
        &-icon {
            transition: var(--pf-transition);
        }
    }
    .gallery_mode {
        position: relative;
        overflow: hidden;
        border-radius: 15px;
        > a {
            display: flex;
            position: absolute;
            z-index: 1;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            opacity: 0;
            transition: var(--pf-transition);
        }
        i {
            color: var(--burido-tertiary-color);
            font-size: 30px;
            height: 70px;
            width: 70px;
            text-align: center;
            line-height: 74px;
            border-radius: 50%;
            margin: auto;
        }
        &.item__wrapper .item__image {
            &::after {
                width: 100%;
                height: 100%;
                top: 0;
                left: 0;
                background: rgba(var(--burido-secondary-rgb),0.5);
            }
        }
        .portfolio_link {
            justify-content: center;
            align-items: center;
        }
        &:hover {
            > a {
                opacity: 1;
            }
        }
        .item__image {
            img {
                display: block;
            }
        }
    }
    .wgl-portfolio-item_icon {
        display: inline-block;
        position: relative;
        z-index: 2;
        border-radius: 50%;
        font-size: 20px;
        line-height: 0;
        background: #ffffff;
        transition: var(--pf-transition);
        &:hover {
            a,
            i {
                color: #ffffff;
            }
            .icon_plus {
                background: #ffffff;
            }
        }
        .icon_plus {
            &::before,
            &::after {
                content: '';
                position: absolute;
                z-index: 1;
                width: 16px;
                height: 2px;
                left: 50%;
                top: 50%;
                margin-left: -8px;
                margin-top: -1px;
                background: currentColor;
                transition: 0s, background-color 0.4s;
            }
            &::after {
                transform: rotate(90deg);
            }
        }
        a {
            display: inline-block;
            transition: 0s;
        }
        > a,
        > i {
            display: inline-flex;
            justify-content: center;
            align-items: center;
            width: 1em;
            height: 1em;
            padding: 20px;
        }
        &:empty {
            display: none;
        }
    }
    .item__image {
        img {
            border-radius: inherit;
        }
    }
    .item__wrapper {
        //* img overlays
        --wgl-portfolio-center-scale-size: 100%;
        position: relative;
        z-index: 1;
        transition: 0.5s ease-in-out;
        width: var(--wgl-portfolio-center-scale-size);
        margin: auto;
        .item__image {
            position: relative;
            overflow: hidden;
            --wgl-portfolio-image-scale-size: 1;
            --wgl-portfolio-image-transition: 0.5s;
            img {
                transition: var(--wgl-portfolio-image-transition) ease-in-out;
            }
            &::before,
            &::after {
                content: '';
                position: absolute;
                z-index: 1;
                top: 0;
                right: 0;
                bottom: 0;
                left: 0;
                border-radius: inherit;
                transition: var(--pf-transition);
                pointer-events: none;
            }
            &::after {
                opacity: 0;
            }
        }
        &:hover {
            .item__image {
                img {
                    transform: scale(var(--wgl-portfolio-image-scale-size));
                }
                &::after {
                    opacity: 1;
                }
                &::before {
                    opacity: 0;
                }
            }
        }
        &.description_under_image {
            .item__image {
                position: relative;
                &::after {
                    width: 100%;
                    height: 100%;
                    top: 0;
                    left: 0;
                }
            }
            &.description_cursor_tooltip {
                .item__image {
                    position: relative;
                }
            }
            &:hover {
                .portfolio_link {
                    opacity: 1;
                }
            }
        }
    }
    .item__description {
        &:empty {
            display: none;
        }
    }
    &.additional-post {
        .item__wrapper {
            display: flex;
            height: 100%;
        }
        .item__button {
            position: absolute;
            z-index: 1;
            border: solid 2px var(--burido-primary-color);
            border-radius: 0;
            padding: 13px 40px;
            font-size: 14px;
            font-weight: bold;
            &:hover {
                color: #ffffff;
                background-color: var(--burido-primary-color);
            }
        }
    }
    &.swiper-slide-active,
    &.swiper-slide-duplicate-active  {
        .item__wrapper {
            width: var(--wgl-portfolio-center-scale-size);
        }
    }
}
.post_cats {
    font-size: 14px;
    font-weight: 600;
    line-height: 1.5;
    margin-bottom: -4px;
    text-transform: uppercase;
    .portfolio-category{
        color: var(--burido-content-color);
        letter-spacing: 0.05em;
        margin-bottom: 5px;
        transition: var(--pf-transition);
        &::after {
            content: ",";
            display: inline-block;
            color: var(--burido-header-font-color);
            margin-right: 5px;
        }
        &:last-child {
            &::after {
                display: none;
            }
        }
        &:hover {
            color: var(--burido-secondary-color);
        }
    }
    + .item__title {
        margin-top: 10px;
    }
}

@mixin reveal-portfolio-elements {
    .item__description,
    .item__description::before,
    .portfolio_link {
        opacity: 1;
    }
}

@mixin hide-portfolio-elements {
    .item__description,
    .item__description::before,
    .description__wrapper,
    .description_content {
        opacity: 0;
        visibility: hidden;
    }
}

.description {
    &_under_image {
        position: relative;
        z-index: 1;
        border-radius: 0;
        .item__image {
            position: relative;
            overflow: hidden;
            border-radius: inherit;
            img {
                transform: translateY(0);
                transition: 0.5s;
            }
        }
        .portfolio_link {
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 2;
        }
        .item__description {
            z-index: 3;
            padding-top: 23px;
            padding-bottom: 10px;
            transition: var(--pf-transition);
        }
    }
    &_inside_image {
        position: relative;
        border-radius: 15px;
        overflow: hidden;
        .item__image {
            &:empty {
                height: 320px;
                background: currentColor;
            }
        }
        .item__title .title,
        .portfolio-category {
            &,
            &::after {
                color: var(--burido-tertiary-color);
            }
            &:hover{
                color: rgba(var(--burido-tertiary-rgb),0.6);
            }
        }
        .portfolio-category {
            &:hover{
                color: var(--burido-primary-color);
            }
        }
        .item__description {
            display: flex;
            position: absolute;
            z-index: 3;
            bottom: 0;
            left: 0;
            right: 0;
            flex-direction: column;
            justify-content: flex-end;
            align-items: flex-start;
            padding: 28px 30px 23px;
            opacity: 0;
            overflow: hidden;
            transition: var(--pf-transition);
        }
        .description__wrapper {
            a {
                position: relative;
                z-index: 2;
            }
        }
        &.animation {
            &_simple {
                overflow: hidden;
                .item__description {
                    background-color: rgba(var(--burido-tertiary-rgb),0.2);
                    backdrop-filter: blur(10px);
                }
                .description__wrapper {
                    pointer-events: none;
                    a {
                        pointer-events: auto;
                    }
                    > div,
                    > span,
                    > a {
                        transition: 0.5s;
                        opacity: 0;
                        &:nth-child(2) { transition: 0.7s; }
                        &:nth-child(3) { transition: 0.9s; }
                        &:nth-child(4) { transition: 1.1s; }
                    }
                }
                > .portfolio_link {
                    z-index: 1;
                }
                &:hover {
                    .description__wrapper {
                        > div,
                        > span,
                        > a {
                            opacity: 1;
                        }
                    }
                }
            }
            &_sub_layer {
                perspective: 300px;
                .item__description {
                    top: initial;
                    right: 40px;
                    left: 0;
                    bottom: 0;
                    height: auto;
                    align-items: flex-start;
                    width: calc(100% - 40px);
                    word-break: break-word;
                    transform: translate(-20px,20px);
                    border-top-right-radius: 15px;
                    transition: var(--pf-transition);
                    transform-origin: left center;
                    background-color: var(--burido-secondary-color);
                }
                .wgl-portfolio-item_icon {
                    margin-top: 28px;
                }
                .portfolio_link {
                    z-index: 1;
                }
                .item__image {
                    &::after {
                        background: transparent;
                    }
                }
                &:hover {
                    .item__description {
                        transform: rotateY(0);
                    }
                }
            }
            &_until_hover {
                .item__description {
                    background-color: rgba(var(--burido-secondary-rgb),0.2);
                    backdrop-filter: blur(10px);
                }
                > .portfolio_link {
                    z-index: 1;
                }
                .description__wrapper {
                    > div,
                    > span,
                    > a {
                        transition: 0.5s;
                        opacity: 1;
                        &:nth-child(2) { transition: opacity 0.7s, transform 0.7s; }
                        &:nth-child(3) { transition: opacity 0.9s, transform 0.9s; }
                        &:nth-child(4) { transition: opacity 1.1s, transform 1.1s; }
                    }
                }
                &:hover {
                    .description__wrapper {
                        > div,
                        > span,
                        > a {
                            opacity: 0;
                        }
                    }
                }
            }
            &_always_visible {
                .item__image {
                    &::after {
                        background: linear-gradient(180deg, rgba(0, 0, 0, 0) 38.79%, var(--burido-secondary-color) 100%);
                    }
                }
                .item__description {
                    opacity: 1;
                    width: max-content;
                }
                .description__wrapper {
                    > div,
                    > span,
                    > a {
                        opacity: 1;
                    }
                }
            }
        }
        &:hover,
        &.animation_until_hover {
            @include reveal-portfolio-elements;
        }
        &.animation_until_hover {
            &:hover {
                @include hide-portfolio-elements;
            }
        }
    }
    &_pf_cursor_tooltip {
        &:hover {
            border-radius: 30px;
        }
    }
}

.elementor-widget-wgl-portfolio {
    &.layout-scale {
        .portfolio__item:nth-child(even) {
            --wgl-portfolio-scale-size: 0.7357;
            .item__wrapper {
                transform: scale(var(--wgl-portfolio-scale-size));
            }
        }
    }
    &.descr-align {
        &-center {
            .flex-list {
                .item__description {
                    margin-left: auto;
                    margin-right: auto;
                }
            }
        }
        &-left {
            .flex-list {
                .item__description {
                    margin-right: auto;
                }
            }
        }
        &-right {
            .flex-list {
                .item__description {
                    margin-left: auto;
                }
            }
        }
    }
}

.wgl-portfolio .load_more_wrapper {
    margin-top: 60px;
}

//* Carousel
.wgl-portfolio_container {
    .wgl-carousel_wrapper {
        .wgl-carousel {
            margin-left: 0;
            margin-right: 0;
        }
    }
    .wgl-carousel {
        &.center-mode {
            .swiper-slide-active {
                .animation {
                    &_simple {
                        @include reveal-portfolio-elements;
                        .description__wrapper {
                            > div,
                            > span,
                            > a {
                                opacity: 1;
                                transform: translateY(0);
                            }
                        }
                    }
                    &_sub_layer {
                        @include reveal-portfolio-elements;
                        .item__description {
                            transform: translateY(0);
                        }
                    }
                    &_until_hover {
                        @include hide-portfolio-elements;
                    }
                }
            }
        }
        .wgl-carousel_swiper {
            padding-bottom: 5px;
            margin-bottom: 30px;
        }
        .portfolio__item {
            width: 1000px;
            @media (max-width: 992px) {
                width: 750px;
            }
            @media (max-width: 767px) {
                width: 600px;
            }
            @media (max-width: 600px) {
                width: 550px;
            }
        }
    }
}

//* Appear Animation
.wgl-portfolio_container.appear-animation {
    .portfolio__item .item__wrapper {
        opacity: 0;
        transition-delay: 0.2s;
    }
    &.anim-fade-in {
        .animate .item__wrapper {
            animation: fade_in 0.9s ease forwards;
        }
    }
    &.anim-flip-x {
        .portfolio__item {
            perspective: 1000px;
        }
        .item__wrapper {
            transform-style: flat;
            transform: rotateX(45deg);
        }
        .animate .item__wrapper {
            animation: flip_x 1.5s ease forwards;

        }
    }
    &.anim-flip-x-r {
        .portfolio__item {
            perspective: 1000px;
        }
        .item__wrapper {
            transform-style: flat;
            transform: rotateX(-45deg);
        }
        .animate .item__wrapper {
            animation: flip_x 1.5s ease forwards;

        }
    }
    &.anim-flip-y {
        .portfolio__item {
            perspective: 1000px;
        }
        .item__wrapper {
            transform-style: flat;
            transform: rotateY(45deg);
        }
        .animate .item__wrapper {
            animation: flip_y 1.5s ease forwards;

        }
    }
    &.anim-flip-y-r {
        .portfolio__item {
            perspective: 1000px;
        }
        .item__wrapper {
            transform-style: flat;
            transform: rotateY(-45deg);
        }
        .animate .item__wrapper {
            animation: flip_y 1.5s ease forwards;

        }
    }
    &.anim-slide-top {
        .animate .item__wrapper {
            animation: slide_top 1.5s ease forwards;
            transform: translateY(70px);

        }
    }
    &.anim-slide-bottom {
        .animate .item__wrapper {
            animation: slide_bottom 1.5s ease forwards;
            transform: translateY(-70px);
        }
    }
    &.anim-slide-left {
        .animate .item__wrapper {
            animation: slide_left 1.5s ease forwards;
            transform: translateX(70px);
        }
    }
    &.anim-slide-right {
        .animate .item__wrapper {
            animation: slide_right 1.5s ease forwards;
            transform: translateX(-70px);
        }
    }
    &.anim-zoom {
        .animate .item__wrapper {
            animation: zoom_in 1.5s ease forwards;
            transform: scale(0.5);
        }
    }
}

//* ↓ Grid
.wgl-portfolio,
.wgl-products{
    &_header {
        display: flex;
        margin-bottom: 50px;
        padding-bottom: 22px;
        gap: 20px;
        border-bottom: 1px solid var(--burido-header-font-color);
    }
}
.wgl-portfolio {
    --portfolio-columns-gap: 30px;
    &_header {
        .item_title {
            min-width: 33.333333%;
        }
        .portfolio_subtitle {
            display: block;
            color: var(--burido-content-color);
            font-family: var(--burido-header-font-family);
            font-size: 16px;
            line-height: 1.25;
            font-weight: 500;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            &::before,
            &::after{
                content: '';
                display: inline-block;
                vertical-align: middle;
                background-color: var(--burido-primary-color);
                margin-bottom: 2px;
                width: 12px;
                height: 8px;
                display: none;
            }
            &::before{
                margin-right: calc(0.12em + 5px);
                border-radius: 0 4px 4px 0;
            }
            &::after{
                margin-left: calc(0.12em + 5px);
                border-radius: 4px 0 0 4px;
            }
        }
        .portfolio_title {
            font-size: 48px;
            line-height: 1.1666em;
            margin-top: 15px;
        }
        .isotope-filter:not(.swiper-container-initialized) {
            margin-bottom: 3px;
        }
        &.filter {
            &-left {
                flex-direction: row-reverse;
                .portfolio_subtitle {
                    &::before { display: none; }
                    &::after { display: inline-block; }
                }
                .item_title {
                    text-align: right;
                }
                .swiper-wrapper {
                    justify-content: flex-start;
                }
                .isotope-filter:not(.swiper-container-initialized) {
                    margin-right: auto;
                    text-align: left;
                }
            }
            &-center {
                flex-direction: column;
                text-align: center;
                .portfolio_subtitle {
                    &::before,
                    &::after {
                        display: inline-block;
                    }
                }
                .item_title {
                    margin-bottom: 30px;
                }
                .swiper-wrapper {
                    justify-content: center;
                }
                .isotope-filter:not(.swiper-container-initialized) {
                    margin-left: auto;
                    margin-right: auto;
                    text-align: center;
                }
            }
            &-right {
                .portfolio_subtitle {
                    &::after { display: none; }
                    &::before { display: inline-block; }
                }
                .swiper-wrapper {
                    justify-content: flex-end;
                }
                .isotope-filter:not(.swiper-container-initialized) {
                    margin-left: auto;
                    text-align: right;
                }
            }
            &-space-between {
                .isotope-filter {
                    width: 100%;
                }
                .swiper-wrapper {
                    justify-content: space-between;
                }
            }
        }
        @media (max-width: 1200px) {
            &[class*='filter'] {
                flex-direction: column;
                text-align: center;
                .swiper-wrapper {
                    justify-content: center;
                }
                .isotope-filter:not(.swiper-container-initialized) {
                    margin: 0 auto;
                    text-align: center;
                }
            }
        }
    }
}

.wgl-portfolio_container {
    margin-right: calc( var(--portfolio-columns-gap) * -0.5 );
    margin-left: calc( var(--portfolio-columns-gap) * -0.5 );
    &:not(.carousel, .flex-list){
        margin-bottom: calc( var(--portfolio-columns-gap) * -1 );
    }
    .portfolio__item {
        padding: 0 calc( var(--portfolio-columns-gap) / 2 ) var(--portfolio-columns-gap);
    }
    &[style*='height: 0px;'] {
        margin-bottom: 0;
    }
    &.grid {
        display: flex;
        flex-wrap: wrap;
    }
    &[class*='masonry'] {
        .portfolio__item {
            float: left;
            min-height: 1px;
        }
    }
    &.masonry {
        &-2 .portfolio__item {
            width: 100%;

            &:nth-of-type(8n+2),
            &:nth-of-type(8n+6) {
                img {
                    max-width: unset;
                    width: calc( 100% + var(--portfolio-columns-gap) / 2 + var(--portfolio-masonry-2-equalizer, 0px) );
                }
            }

            @media (min-width: 993px) {
                width: 25%;
                &:nth-of-type(8n+1),
                &:nth-of-type(8n+7) {
                    width: 50%;
                }
            }
            @media (min-width: 601px) and (max-width: 992px) {
                width: 50%;
                &:nth-of-type(8n+1),
                &:nth-of-type(8n+7) {
                    width: 50%;
                }
            }
        }
        &-3 .portfolio__item {
            width: 100%;
            @media (min-width: 993px) {
                width: 25%;
                &:nth-of-type(8n+1),
                &:nth-of-type(8n+2),
                &:nth-of-type(8n+5),
                &:nth-of-type(8n+6) {
                    width: 50%;
                }
            }
            @media (min-width: 769px) and (max-width: 992px) {
                width: 50%;
            }
            @media (min-width: 601px) and (max-width: 768px) {
                width: 50%;
                &:nth-of-type(8n+1),
                &:nth-of-type(8n+2),
                &:nth-of-type(8n+5),
                &:nth-of-type(8n+6) {
                    width: 100%;
                }
            }
        }
        &-4 .portfolio__item {
            width: 100%;
            @media (min-width: 993px) {
                width: 25%;
                &:nth-of-type(6n+1),
                &:nth-of-type(6n+6) {
                    width: 50%;
                }
            }
            @media (min-width: 601px) and (max-width: 992px) {
                width: 50%;
                &:nth-of-type(6n+1),
                &:nth-of-type(6n+6) {
                    width: 100%;
                }
            }
        }
    }
    &.col-5 .portfolio__item {
        width: 20%;
    }
    &.col-4 .portfolio__item {
        width: 25%;
    }
    &.col-3 .portfolio__item {
        width: 33.333333%;
    }
    &.col-2 .portfolio__item {
        width: 50%;
    }
    &.col-1 .portfolio__item {
        width: 100%;
    }
    @media (max-width: 1545px) {
        &.col-5 .portfolio__item {
            width: 25%;
        }
    }
    @media (max-width: 1370px) {
        &:is(
            .col-4,
            .col-5
        ) .portfolio__item {
            width: 33.333333%;
        }
    }
    @media (max-width: 1024px) {
        &:is(
            .col-3,
            .col-4,
            .col-5
        ) .portfolio__item {
            width: 50%;
        }
    }
    @media (max-width: 767px) {
        &:is(
            .col-2,
            .col-3,
            .col-4,
            .col-5
        ) .portfolio__item {
            width: 100%;
        }
    }
    &.flex-list {
        display: flex;
        .portfolio__item {
            width: calc(3 * calc(1/10 * 100%));
            padding: 0;
            margin: 0 calc(var(--portfolio-columns-gap) / 2);
            transition: width 0.6s ease-in-out;
            position: relative;
            z-index: 1;
            &:hover {
                width: calc(8 * calc(1/10 * 100%));
            }
        }
        .description_inside_image .item__description {
            white-space: nowrap;
        }
        .item__wrapper {
            width: 100%;
            height: 100%;
        }
        .item__image {
            width: 100%;
            height: 100%;
            .item__image-wrap {
                height: 100%;
            }
            img {
                height: 100%;
                width: 100%;
                object-position: center;
                object-fit: cover;
            }
        }
        @media (max-width: 1200px) {
            flex-wrap: wrap;
            .description_inside_image .item__description {
                white-space: unset;
            }
            .portfolio__item {
                width: calc(50% - var(--portfolio-columns-gap));
                margin-bottom: var(--portfolio-columns-gap);
                &:hover {
                    width: calc(50% - var(--portfolio-columns-gap));
                }
            }
        }
        @media (max-width: 520px) {
            flex-wrap: wrap;
            .portfolio__item {
                width: 100%;
                &:hover {
                    width: 100%;
                }
            }
        }
    }
    &.grid-2 {
        margin: 0;
        .item__wrapper {
            display: flex;
            border: 1px solid var(--burido-secondary-color);
            margin-bottom: -1px;
            .item__image,
            .item__description {
                width: calc(50% + 1px);
                margin-left: -1px;
            }
            .item__image {
                align-self: center;
                .item__image-wrap {
                    transform: scale(0.816);
                    transition: 1s ease-in-out;
                }
            }
            .post_cats {
                margin-top: 0;
                margin-bottom: 8px;
            }
            .item__title {
                .title {
                    font-size: 48px;
                    letter-spacing: -0.04em;
                }
            }
            .description_content {
                font-size: 22px;
                font-family: var(--burido-header-font-family);
                font-weight: 500;
                line-height: 1.63;
                color: var(--burido-header-font-color);
                letter-spacing: -0.02em;
                margin-top: 15px;
            }
            .item__date {
                transition: 0.5s ease-in-out;
                opacity: 0;
                font-family: var(--burido-header-font-family);
                color: var(--burido-header-font-color);
                font-size: 20px;
                font-weight: 500;
                .item__date-title {
                    font-weight: 600;
                    display: block;
                    color: var(--burido-primary-color);
                    letter-spacing: 0.05em;
                    line-height: 1.5;
                }
            }
            .item__description {
                padding: 58px 60px 46px;
                position: relative;
                z-index: 1;
                display: flex;
                flex-direction: column;
                justify-content: space-between;
                gap: 40px;
                &::before {
                    content: '';
                    position: absolute;
                    z-index: 1;
                    height: 100%;
                }
            }
            .item__button {
                margin-top: 41px;
                a {
                    color: #ababab;
                    transition: color 0.5s ease-in-out;
                }
            }
            &:hover {
                .item__image-wrap {
                    transform: scale(1);
                    img {
                        transform: scale(1.1);
                    }
                }
                .item__date {
                    opacity: 1;
                }
                .item__button {
                    a {
                        color: var(--burido-primary-color);
                    }
                }
            }
        }
        .portfolio__item {
            padding: 0;
            &:nth-child(odd) {
                .item__wrapper {
                    flex-direction: row-reverse;
                }
                .item__description {
                    border-right: 1px solid var(--burido-secondary-color);
                }
            }
            &:nth-child(even) {
                .item__description {
                    border-left: 1px solid var(--burido-secondary-color);
                }
            }
            &:last-child {
                .item__wrapper {
                    margin-bottom: 0;
                }
            }
        }
        @media (max-width: 1500px) {
            .item__wrapper {
                .item__image {
                    .item__image-wrap {
                        transform: scale(0.85);
                    }
                }
                .item__description {
                    padding: 40px;
                    gap: 30px;
                }
                &:hover {
                    .item__image-wrap {
                        transform: scale(1);
                    }
                }
            }
        }
        @media (max-width: 1200px) {
            .item__wrapper {
                .item__image {
                    .item__image-wrap {
                        transform: scale(1);
                    }
                }
                .item__title {
                    .title {
                        font-size: 32px;
                    }
                }
                .description_content {
                    font-size: 16px;
                    line-height: 1.875;
                }
                .item__date {
                    opacity: 1;
                }
            }
        }
        @media (max-width: 768px) {
            .item__wrapper {
                .item__description {
                    padding: 30px;
                    gap: 20px;
                }
                .item__button {
                    margin-top: 20px;
                    a::before {
                        font-size: 30px;
                    }
                }
                .item__date {
                    font-size: 16px;
                }
            }
        }
        @media (max-width: 600px) {
            .portfolio__item {
                .item__wrapper {
                    border: unset;
                    margin-bottom: 0;
                    .item__image,
                    .item__description {
                        width: 100%;
                        margin-left: 0;
                    }
                    &:nth-child(odd),
                    &:nth-child(even) {
                        flex-direction: column;
                    }
                }
                .item__description {
                    padding-bottom: 40px;
                }
                .description_content {
                    display: none;
                }
                .item__date {
                    opacity: 1;
                    .item__date-title {
                        display: inline-block;
                        margin-right: 10px;
                    }
                }
            }
        }
    }
}
