/* ==================== ##Load More ==================== */

.load_more_wrapper {
    position: relative;
    z-index: 1;
    text-align: center;
    margin-top: 60px;
    .button_wrapper {
        display: inline-block;
        position: relative;
    }
    .load_more_item {
        --wgl-icon-gap: -1px;
        --wgl-icon-wrapper: 60px;
        white-space: nowrap;
        color: var(--burido-button-color-idle);
        background-color: var(--burido-button-bg-idle);
        position: relative;
        z-index: 1;
        padding: 18px 29px 18px 29px;
        height: 60px;
        border: unset;
        .wgl_loading_icon {
            display: inline-block;
            position: absolute;
            z-index: 99;
            top: 50%;
            left: 50%;
            margin: -10px 0 0 -8px;
            font-family: 'Font Awesome 5 Free';
            font-weight: 700;
            line-height: 1;
            font-size: 19px;
            color: inherit;
            text-rendering: auto;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
            opacity: 0;
            transition: all 0.4s, color 0s;
            animation: rotating 2s linear infinite;
        }
        span {
            position: relative;
            z-index: 2;
            transition: opacity .3s .3s;
            letter-spacing: inherit;
        }
        .load_more__icon {
            display: flex;
            align-items: center;
            justify-content: center;
            min-height: var(--wgl-icon-wrapper);
            min-width: var(--wgl-icon-wrapper);
            border-radius: var(--wgl-icon-wrapper);
            color: var(--burido-button-color-idle);
            background-color: var(--burido-button-bg-idle);
            position: absolute;
            top: 0;
            left: calc(100% + var(--wgl-icon-gap));
            bottom: 0;
            margin: auto 0;
            transition: 0.4s;
            font-size: 26px;
            svg {
                fill: currentColor;
                width: 1em;
                height: 1em;
            }
            i {
                font-size: 26px;
                padding: 17px 16.65px;
                border-radius: 60px;
                color: var(--burido-button-color-idle);
                background-color: var(--burido-button-bg-idle);
                display: block;
                transition: 0.4s;
            }
        }
        &:hover,
        &:focus,
        &:active {
            &,
            i,
            .load_more__icon {
                color: var(--burido-button-color-hover);
                background-color: var(--burido-button-border-hover);
            }
        }
        &.loading {
            .wgl_loading_icon {
                color: inherit;
                opacity: 1;
                transition: all 0.4s .2s, color 0s;
            }
            &::before,
            span {
                opacity: 0;
                transition: opacity .3s 0s;
            }
        }
        &.full_width_btn {
            .load_more_item {
                width: 100%;
            }
        }
    }
    &.icon-yes {
        .wgl_loading_icon {
            left: calc(100% + 28px);
        }
        .load_more_item {
            margin-right: calc(var(--wgl-icon-wrapper) + var(--wgl-icon-gap));
        }
        .loading {
            span {
                opacity: 1;
            }
            .load_more__icon i::before {
                opacity: 0;
                transition: opacity .3s 0s;
            }
        }
    }
    @keyframes rotating {
        0% {
            transform: rotate(0turn);
        }
        100% {
            transform: rotate(1turn);
        }
    }
}
