/* ==================== ##Flip Box ==================== */
.wgl-flipbox {
    position: relative;
    perspective: 1000px;
    width: 100%;
    height: 300px;
    &_wrap {
        position: relative;
        z-index: 1;
        transition: 0.7s;
        width: 100%;
        height: 100%;
        transform-style: preserve-3d;
        perspective: inherit;
        .media-wrapper{
            &.number-wrapper{
                .wgl-number{
                    font-size: 18px;
                    font-weight: 500;
                    padding: 19px;
                    width: 1em;
                    height: 1em;
                    background-color: #FF7425;
                    box-sizing: content-box;
                    border-radius: 50%;
                }
            }
        }
    }
    &_title {
        display: inline-block;
        font-family: var(--burido-header-font-family);
        font-weight: 600;
        font-size: 24px;
        line-height: 1.25;
        word-break: break-word;
        color: var(--burido-header-font-color);
        margin-top: 15px;
        transition: 0.4s;
        span {
            font-family: inherit;
            font-size: inherit;
            line-height: inherit;
            font-weight: inherit;
            text-transform: inherit;
            letter-spacing: inherit;
            color: inherit;
        }
    }
    &_subtitle {
        display: inline-block;
        color: var(--burido-header-font-color);
        font-family: var(--burido-header-font-family);
        font-size: 14px;
        line-height: 1.25;
        font-weight: var(--burido-header-font-weight);
        letter-spacing: 0.05em;
        text-transform: uppercase;
        span {
            font-family: inherit;
            font-size: inherit;
            line-height: inherit;
            font-weight: inherit;
            text-transform: inherit;
            letter-spacing: inherit;
            color: inherit;
        }
    }
    &_content {
        p:last-child {
            margin-bottom: 0;
        }
    }
    &_button-wrap {
        line-height: 0;
        font-size: 0;
        .wgl-flipbox_button{
            &.icon-read-more{
                line-height: inherit;
                font-size: inherit;
                display: inline-block;
                transition: 0.4s;
                i, span{
                    z-index: 1;
                    right: 0;
                    bottom: 0;
                    text-align: center;
                    display: inline-block;
                    transition: background-color .4s, color .4s, transform .4s;
                    color: var(--burido-header-font-color);
                    width: 1em;
                    height: 1em;
                    line-height: 1em;
                    font-size: 30px;
                    background: unset;
                    border-radius: 0;
                    transform: translateY(var(--icon-translate-y, -1px)) rotate(var(--icon-rotate, 0));
                    &::before{
                        display: block;
                        transition: transform .4s;
                        line-height: inherit;
                    }
                }
            }
        }
    }
    &_item-link {
        position: absolute;
        z-index: 2;
        width: 100%;
        height: 100%;
        left: 0;
        top: 0;
    }
    &_front,
    &_back {
        display: flex;
        flex-direction: column;
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(var(--burido-header-rgb), 0.15);
        backface-visibility: hidden;
        transform: rotate(0);
        transition: 0.7s;
        perspective: inherit;
        transform-style: preserve-3d;
        border-radius: 0;
        padding: 50px 35px 50px;
    }
    &_front {
        z-index: 2;
        .wgl-icon {
            color: var(--burido-header-font-color);
            fill: var(--burido-header-font-color);
        }
    }
    &_back {
        .wgl-icon {
            color: var(--burido-header-font-color);
            fill: var(--burido-header-font-color);
        }
        .wgl-flipbox_content {
            font-size: 16px;
            margin-bottom: 13px;
        }
    }
    &.type {
        &_flip_right {
            .wgl-flipbox_back {
                transform: rotateY(-180deg);
            }
            .elementor-editor-active .dev_view-active &,
            &:hover {
                .wgl-flipbox_wrap {
                    transform: rotateY(180deg);
                }
            }
        }
        &_flip_left {
            .wgl-flipbox_back {
                transform: rotateY(180deg);
            }
            .elementor-editor-active .dev_view-active &,
            &:hover {
                .wgl-flipbox_wrap {
                    transform: rotateY(-180deg);
                }
            }
        }
        &_flip_top {
            .wgl-flipbox_back {
                transform: rotateX(-180deg);
            }
            .elementor-editor-active .dev_view-active &,
            &:hover {
                .wgl-flipbox_wrap {
                    transform: rotateX(180deg);
                }
            }
        }
        &_flip_bottom {
            .wgl-flipbox_back {
                transform: rotateX(180deg);
            }
            .elementor-editor-active .dev_view-active &,
            &:hover {
                .wgl-flipbox_wrap {
                    transform: rotateX(-180deg);
                }
            }
        }
    }
}

.elementor-widget-wgl-flipbox {
    &.a {
        &left {
            .wgl-flipbox .wgl-image-box_img {
                margin-right: auto;
            }
        }
        &center {
            .wgl-flipbox .wgl-image-box_img {
                margin-left: auto;
                margin-right: auto;
            }
        }
        &right {
            .wgl-flipbox .wgl-image-box_img {
                margin-left: auto;
            }
        }
    }
}
