/* ==================== ##Time Line Vertical ==================== */
@use '../../mixins';

.wgl-timeline-vertical {
	--line-size: 10px;
	--curve-width: 1px;
	--curve-gap: 85px;
	--curve-color: var(--burido-primary-color);
	--curve-h-width: 85px;
	--dot-size: 25px;
	--dot-color: var(--body-background-color);
	display: flex;
	flex-direction: column;
	gap: 60px;
	position: relative;
	padding: 0;
	z-index: 1;
	&::before{
		content: '';
		position: absolute;
		top: 0;
		right: 0;
		left: 0;
		margin: auto;
		width: var(--curve-width);
		min-width: var(--curve-width);
		transition: height 1.3s .5s cubic-bezier(0.65, 0.05, 0.36, 1);
		z-index: 1;
		bottom: 0;
		background-color: #ECECEC;
	}
	.tlv__items-wrapper {
		display: flex;
		flex-direction: row-reverse;
		justify-content: flex-start;
		align-items: center;
		position: relative;
		&::before{
			content: '';
			position: absolute;
			top: 0;
			right: 0;
			bottom: 0;
			left: 0;
			pointer-events: none;
			transition: .4s;
		}
		&::after{
			content: '';
			position: absolute;
			top: 0;
			right: 0;
			bottom: 0;
			left: 0;
			margin: auto;
			pointer-events: none;
			transition: .4s;
			width: var(--curve-width);
			min-width: var(--curve-width);
		}
		.tlv__content-wrapper{
			position: relative;
			display: flex;
			flex-direction: column;
			transition: 0.7s;
		}
		&:nth-child(odd) {
			.tlv__item.image{
				justify-content: flex-end;
				padding-right: var(--curve-gap);
			}
			.tlv__curve-wrapper{
				margin-right: var(--curve-gap);
				span{
					left: -6px;
				}
				.dot {
					border-right: 0;
				}
			}
			.tlv__content-wrapper{
				align-items: flex-end;
			}
		}
		&:nth-child(even) {
			flex-direction: row;
			.tlv__volume-wrapper{
				flex-direction: row-reverse;
			}
			.tlv__item{
				flex-direction: row-reverse;
				text-align: right;
			}
			.tlv__item.image{
				padding-left: var(--curve-gap);
			}
			.tlv__curve-wrapper {
				margin-left: var(--curve-gap);
				&::before {
					right: -60px;
					left: auto;
				}
				.dot {
					right: calc(50% - var(--dot-size) * 0.5);
					left: auto;
				}
			}
			.tlv__bg_date{
				right: -1.0em;
				left: auto;
			}
		}
		&:hover {
			.tlv__thumbnail--hover {
				opacity: 1;
				+ .tlv__thumbnail--idle {
					opacity: 0;
				}
			}
			.tlv__curve-wrapper {
				.dot {
					transform: scale(1);
					.wgl-svg-icon{
						opacity: 1;
					}
				}
				span::before{
					transform: rotate3d(0, 0, 1, 45deg) scale(1);
				}
			}
		}
	}
	.tlv__item {
		display: flex;
		position: relative;
		text-align: left;
		width: calc((100% - var(--curve-width)) * 0.5);
		z-index: 2;

		&.image{
			display: flex;
			order: 2;
			justify-content: flex-end;
		}
		&.empty{
			margin: unset !important;
			padding: unset !important;
		}
		&:nth-child(odd) {
			text-align: left;
			.tlv__date-wrapper {
				right: 0;
			}
			.tlv__volume-wrapper{
				&::after{
					left: 0;
				}
			}
		}
	}
	.tlv__volume-wrapper {
		display: flex;
		position: relative;
		width: 100%;
		transition: 0.5s;
		z-index: 1;
	}
	.tlv__curve-wrapper {
		position: relative;
		min-width: 0;
		width: 0;
		&::before{
			content: '';
			top: calc( 50% - var(--curve-width) * 0.5 );
			position: absolute;
			left: -60px;
			right: auto;
			align-self: stretch;
			width: var(--curve-h-width);
			height: var(--curve-width);
			background-color: var(--curve-color);
			order: 1;
			z-index: 1;
			transition: all 0.4s, opacity 0.5s 0.4s;

		}
		.dot{
			width: var(--dot-size);
			height: var(--dot-size);
			border-radius: var(--dot-size);
			line-height: var(--dot-size);
			position: absolute;
			top: calc( 50% - var(--dot-size) * 0.5 );
			left: calc( 50% - var(--dot-size) * 0.5 );
			background-color: var(--dot-color);
			color: var(--dot-icon-color);
			z-index: 2;
			transform: scale(0.2);
			transition: .4s;
			.wgl-svg-icon{
				display: flex;
				align-items: center;
				justify-content: center;
				position: absolute;
				top: 0; right: 0; bottom: 0; left: 0;
				opacity: 0;
				font-size: 26px;
				transition: inherit;
			}
		}
	}
	.tlv__media {
		display: inline-flex;
		align-items: center;
		justify-content: center;
		position: relative;
		max-width: fit-content;
		flex-shrink: 0;
		transition: .4s;
		&::before{
			content: '';
			position: absolute;
			top: 0; right: 0; bottom: 0; left: 0;
			border-radius: inherit;
			z-index: -1;
			pointer-events: none;
			transform: translate(var(--border-offset-x,0), var(--border-offset-y,0));
			transition: inherit;
		}
		[class|=tlv__thumbnail] {
			margin: auto;
			border-radius: inherit;
			transition: 0.6s, border-radius 0s;
		}
	}
	.tlv__thumbnail--hover {
		position: absolute;
		top: 0;
		right: 0;
		bottom: 0;
		left: 0;
		opacity: 0;
	}
	.tlv__content {
		transition: 0.5s;
		p:last-child {
			margin-bottom: 0;
		}
	}
	.tlv__title {
		margin-top: 1px;
		margin-bottom: 19px;
		font-size: 36px;
		line-height: 1.333em;
		position: relative;
		transition: 0.4s;
	}
	.tlv__text {
		position: relative;
		transition: 0.4s;
	}
	.tlv__date-wrapper {
		position: relative;
		width: 100%;
	}
	.tlv__date {
		display: inline-block;
		font-family: var(--burido-header-font-family);
		font-size: 24px;
		font-weight: var(--burido-header-font-weight);
		text-align: left;
		line-height: 1em;
		letter-spacing: 0;
		margin-bottom: 15px;
		transition: 0.4s;
	}
	.tlv__bg_date{
		position: absolute;
		top: -0.6em;
		right: auto;
		bottom: 0;
		left: -1.0em;
		margin: 0;
		max-width: 100%;
		display: inline-block;
		font-family: var(--burido-additional-font-family);
		font-weight: 400;
		letter-spacing: -0.02em;
		font-size: 128px;
		line-height: 1.2em;
		height: min-content;
		color: var(--burido-primary-color);
		z-index: 1;
		pointer-events: none;
		transition: 0.4s;
	}
	.tlv__item{
		&-start,
		&-end{
			--dot-size: 9px;
			position: absolute;
			top: calc(var(--dot-size) * -0.5);
			right: 0;
			left: 0;
			display: inline-block;
			font-size: 0;
			line-height: 0;
			margin: auto;
			width: var(--dot-size);
			height: var(--dot-size);
			border-radius: var(--dot-size);
			background-color: currentColor;
			z-index: 2;
			transition: 0.4s;
		}
		&-end{
			top: auto;
			bottom: calc(var(--dot-size) * -0.5);
		}
	}
	.button-read-more{
		margin: 0;
	}
	&.appear_animation {
		.tlv__items-wrapper{
			&::before{
				opacity: 0;
			}
			&:nth-child(odd) {
				.tlv__date-wrapper {
					transform: translateX(-20%);
				}
				.tlv__volume-wrapper {
					transform: translateX(20%);
				}
			}
			&:nth-child(even) {
				.tlv__date-wrapper {
					transform: translateX(20%);
				}
				.tlv__volume-wrapper {
					transform: translateX(-20%);
				}
			}
		}
		.tlv__item {
			opacity: 0;
			&,
			.tlv__date-wrapper,
			.tlv__volume-wrapper {
				transition: all 0.4s, opacity 0.5s 0.4s, transform 0.5s 0.4s;
			}
		}
		.tlv__items-wrapper.show{
			&::before {
				opacity: 1;
			}
			.tlv__item {
				opacity: 1;
				.tlv__date-wrapper,
				.tlv__volume-wrapper {
					transform: translateX(0);
				}
			}
		}
	}
}
body:is(
	[data-elementor-device-mode='tablet_extra'],
	[data-elementor-device-mode='tablet']) {
	.wgl-timeline-vertical .tlv__items-wrapper{
		.tlv__bg_date{
			left: 0.1em;
		}
		&:nth-child(even) .tlv__bg_date{
		}
	}
}
body:is(
	[data-elementor-device-mode='tablet_extra'],
	[data-elementor-device-mode='tablet'],
	[data-elementor-device-mode='mobile_extra'],
	[data-elementor-device-mode='mobile']) {
	.wgl-timeline-vertical .tlv__items-wrapper{
		&:nth-child(even) .tlv__volume-wrapper{
			flex-direction: column;
			align-items: flex-end;
		}
		&:nth-child(odd) .tlv__volume-wrapper{
			flex-direction: column;
			align-items: flex-start;
		}
	}
}

@mixin wgl-timeline-responsive($media) {
	body[data-elementor-device-mode='#{$media}'] .wgl-timeline-vertical.breakpoint_on-#{$media} {

		--curve-h-width: 0;
		padding: 0;
		&::before{
			right: auto;
		}
		.tlv__item-start,
		.tlv__item-end{
			right: auto;
			left: calc(var(--dot-size) * -0.5);
		}
		.tlv__item{
			width: 100%;
		}
		.tlv__curve-wrapper {
			&::before{
				top: calc(var(--dot-size) * 0.5);
			}
			.dot{
				display: none;
				margin-left: calc(var(--curve-width) * 0.5);
				top: 0;
			}
		}
		.tlv__item.image .tlv__media{
			margin: 0 0 30px 0;
			img{
				width: 300px;
			}
		}
		.tlv__date{
			font-size: 20px;
			margin-bottom: 12px;
		}
		.tlv__items-wrapper{
			--curve-gap: 6%;
			flex-direction: column-reverse;
			&::after{
				right: auto;
				left: calc(var(--curve-width) * -0.5);
			}
			.tlv__item{
				flex-direction: row;
				text-align: left;
				justify-content: flex-start;
			}
			&:first-child .tlv__item{
				padding-top: 0 !important;
			}
			&:last-child .tlv__item{
				padding-bottom: 0 !important;
			}
			.tlv__volume-wrapper{
				flex-direction: column;
				align-items: flex-start;
			}
			.tlv__item.image{
				padding-left: var(--curve-gap);
				padding-right: 0;
			}
			.tlv__curve-wrapper{
				margin-left: 0;
				margin-right: var(--curve-gap);
			}
			.tlv__bg_date{
				right: 0.2em;
				left: auto;
			}
		}
	}

	body[data-elementor-device-mode='#{$media}'] {
		.elementor-widget-wgl-time-line-vertical.media_position-inner{
			.wgl-timeline-vertical.breakpoint_on-#{$media} {
				flex-direction: column;
				.tlv__items-wrapper {
					width: 100%;
					margin: 0;
				}
			}
		}
	}
}

@include wgl-timeline-responsive('widescreen');
@include wgl-timeline-responsive('desktop');
@include wgl-timeline-responsive('tablet_extra');
@include wgl-timeline-responsive('tablet');
@include wgl-timeline-responsive('mobile_extra');
@include wgl-timeline-responsive('mobile');


/* Mini Timeline */
.elementor-widget-wgl-time-line-vertical.media_position-inner{
	.wgl-timeline-vertical{
		flex-direction: row;
		flex-wrap: wrap;
		align-items: flex-start;
		column-gap: 0 !important;
		gap: 95px;
	}
	.tlv__media{
		align-self: flex-start;
		border-radius: 50px;
		img{
			width: 100px;
		}
	}
	.tlv__items-wrapper{
		width: 50%;
		flex-direction: column-reverse;
		&:nth-child(even){
			margin-top: 75px;
			&::after{
				right: auto;
				left: calc(var(--curve-width) * -0.5);
			}
			.tlv__item{
				flex-direction: row;
				text-align: left;
			}
			.tlv__volume-wrapper {
				flex-direction: row;
			}
			.tlv__curve-wrapper {
				margin-right: var(--curve-gap);
				margin-left: 0;
				.dot {
					right: auto;
					left: calc(50% - var(--dot-size) * 0.5);
				}
			}
			.tlv__content-wrapper{
				flex-direction: row;
			}
			.tlv__media{
				margin-right: 22px;
			}
			.tlv__bg_date{
				right: -1.0em;
				left: auto;
			}
		}
		&:nth-child(odd){
			&::after{
				right: calc(var(--curve-width) * -0.5);
				left: auto;
			}
			.tlv__item{
				flex-direction: row-reverse;
				text-align: right;
			}
			.tlv__volume-wrapper {
				flex-direction: row-reverse;
			}
			.tlv__curve-wrapper {
				margin-left: var(--curve-gap);
				margin-right: 0;
				.dot {
					right: calc(50% - var(--dot-size) * 0.5);
					left: auto;
				}
			}
			.tlv__content-wrapper{
				flex-direction: row-reverse;
			}
			.tlv__media{
				margin-left: 22px;
			}
			.tlv__bg_date{
				left: -1.0em;
				right: auto;
			}
		}
	}
	.tlv__item{
		width: calc(100% - var(--curve-width));
	}
}

body:is(
	[data-elementor-device-mode='tablet_extra'],
	[data-elementor-device-mode='tablet'],
	[data-elementor-device-mode='mobile_extra'],
	[data-elementor-device-mode='mobile']) {
	.elementor-widget-wgl-time-line-vertical.media_position-inner {
		.tlv__items-wrapper{
			.tlv__content-wrapper {
				flex-direction: column;
			}
			.tlv__media {
				margin-left: 0;
				margin-bottom: 22px;
			}
			&:nth-child(odd) .tlv__content-wrapper{
				.tlv__media {
					align-self: flex-end;
				}
			}
		}
	}
}