/* ==================== ##Video Popup ==================== */

.wgl-video-popup {
    position: relative;
    line-height: 0;
    z-index: 1;
    .videobox_content {
        display: inline-flex;
        align-items: center;
        cursor: pointer;
        transition: 0.4s;
    }
    .videobox_background img {
        position: relative;
        z-index: 0;
        width: 100%;
        box-shadow: 0 0 0 0 rgba(0, 0, 0, 0.15);
    }
    .title {
        position: relative;
        display: inline-block;
        font-family: var(--burido-header-font-family);
        font-weight: var(--burido-header-font-weight);
        font-size: 20px;
        line-height: 1.25;
        color: var(--burido-header-font-color);
        z-index: 2;
    }
    .videobox_link {
        display: block;
        position: relative;
        flex-shrink: 0;
        cursor: pointer;
        color: var(--burido-header-font-color);
        fill: currentColor;
        stroke: currentColor;
        transition: all 0.4s;
        &::before{
            content: '';
            display: block;
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            background: var(--burido-tertiary-color);
            border: 1px solid var(--burido-header-font-color);
            border-radius: inherit;
            transition: all 0.4s;
            z-index: 2;
        }
    }
    .videobox_content:hover{
        .videobox_link::before{
            transform: scale(1.1);
        }
    }
    .videobox_icon {
        display: block;
        position: absolute;
        z-index: 2;
        top: 50%;
        left: 50%;
        width: 20px;
        height: 24px;
        transform: translate(-40%, -50%);
        stroke-width: 0.05em;
        transition: none;
    }
    &.title_pos {
        &-top {
            .videobox_content {
                flex-direction: column;
            }
            .title {
                order: 0;
                margin-bottom: 32px;
            }
        }
        &-right {
            .videobox_content {
                justify-content: flex-start;
            }
            .title {
                margin-left: 22px;
                order: 1;
            }
        }
        &-bot {
            .videobox_content {
                flex-direction: column;
            }
            .title {
                order: 1;
                margin-top: 32px;
            }
        }
        &-left {
            .title {
                order: 0;
                margin-right: 22px;
            }
        }
    }

    .videobox_animation {
        display: block;
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        border-radius: 50%;
        color: var(--burido-primary-color);
        pointer-events: none;
    }
    &.animation {
        &-disable {
            .videobox_content:hover {
                .videobox_link,
                .videobox_link::before{
                    transform: unset;
                }
            }
        }
        &-circles {
            .videobox_animation {
                z-index: 1;
                border-width: 0.5px;
                border-style: solid;
                opacity: 0;
                animation: circles 3.9s linear 0s infinite;
                animation-play-state: paused;
                &.circle_2 {
                    animation-delay: 1.3s;
                }
                &.circle_3 {
                    animation-delay: 2.6s;
                }
            }
            .videobox_link{
                border-radius: 50%;
                &::before {
                    transform: unset;
                }
            }
            .videobox_content:hover .videobox_animation,
            &.idle-animation .videobox_animation {
                animation-play-state: running;
            }
            &.idle-animation .videobox_content:hover .videobox_animation {
                animation-play-state: paused;
            }
            @keyframes circles {
                0% {
                    transform: scale(1);
                    opacity: 0;
                }
                20% {
                    transform: scale(1.44);
                    opacity: 0.5;
                }
                100% {
                    transform: scale(3.2);
                    opacity: 0;
                }
            }
        }
        &-ring_pulse {
            .videobox_animation {
                z-index: 1;
                background: inherit;
                background-color: var(--burido-primary-color);
                animation: pulse_ring 2.2s cubic-bezier(0.455, 0.03, 0.515, 0.955) 0s infinite;
                animation-play-state: paused;
            }
            .videobox_link{
                border-radius: 50%;
                &::before {
                    transform: unset;
                }
            }
            .videobox_content:hover .videobox_animation,
            &.idle-animation .videobox_animation {
                animation-play-state: running;
            }
            &.idle-animation .videobox_content:hover .videobox_animation {
                animation-play-state: paused;
            }
            @keyframes pulse_ring {
                0% {
                    transform: scale(1);
                }
                50% {
                    transform: scale(1.7);
                }
                100% {
                    transform: scale(1);
                }
            }
        }
        &-ring_static {
            .videobox_link{
                border-radius: 50%;
                &::before {
                    transform: unset;
                }
                .videobox_animation {
                    z-index: -1;
                    border: 1px solid;
                    border-radius: inherit;
                    top: -70%;
                    left: -70%;
                    width: 242%;
                    height: 242%;
                    transition: 0.5s;
                    pointer-events: none;
                }
            }
            .videobox_content:hover {
                .videobox_animation {
                    transform: scale(0.3);
                    opacity: 0;
                }
            }
        }
        &-scale {
            .videobox_content {
                .videobox_link {
                    transition: 0.4s, transform 0.2s;
                }
                &:hover {
                    .videobox_link {
                        transform: scale(1.03);
                    }
                }
                &:active {
                    .videobox_link {
                        transform: scale(0.97);
                    }
                }
            }
        }
    }

    &.with_image {
        // for blog
        .videobox_link_wrapper {
            position: absolute;
            z-index: 1;
        }
        .videobox_link {
            width: 80px;
            height: 80px;
            color: var(--burido-header-font-color);
            fill: currentColor;
            &::before{
                border-radius: 50%;
                color: var(--burido-tertiary-color);
                background-color: var(--burido-secondary-color);
                border-color: var(--burido-secondary-color);
            }
            svg {
                fill: var(--burido-tertiary-color);
                stroke: var(--burido-tertiary-color);
                width: 20px;
                height: 23px;
            }
        }
        .videobox_content:hover {
            .videobox_link::before {
                transform: scale(1.1);
            }
        }
    }
}

body {
    @mixin wgl-popup-responsive($media) {
        .elementor-widget-wgl-video-popup {
            &.button_align#{$media} {
                &-left {
                    text-align: left;
                    .videobox_content {
                        justify-content: flex-start;
                    }
                    .title_pos-bot,
                    .title_pos-top {
                        .videobox_content {
                            justify-content: unset;
                            align-items: flex-start;
                        }
                    }
                    &.elementor-element {
                        display: block;
                        width: 100%;
                    }
                }
                &-center {
                    text-align: center;
                    .videobox_content {
                        justify-content: center;
                        align-items: center;
                    }
                    .title_pos-right {
                        .videobox_content {
                            justify-content: center;
                            align-items: center;
                        }
                    }
                    &.elementor-element {
                        display: block;
                        width: 100%;
                    }
                }
                &-right {
                    text-align: right;
                    .videobox_content {
                        justify-content: flex-end;
                        flex-direction: row;
                    }
                    .title_pos-bot {
                        .videobox_content {
                            justify-content: unset;
                            align-items: flex-end;
                            flex-direction: column;
                        }
                        .title {
                            order: 1;
                        }
                    }
                    .title_pos-top {
                        .videobox_content {
                            justify-content: unset;
                            align-items: flex-end;
                            flex-direction: column;
                        }
                        .title {
                            order: 0;
                        }
                    }
                    &.elementor-element {
                        display: block;
                        width: 100%;
                    }
                }
                &-inline {
                    &.elementor-element {
                        display: inline-block;
                        width: auto;
                    }
                }
            }
        }
    }

    @include wgl-popup-responsive('');
    &:is(:not(
        [data-elementor-device-mode="widescreen"],
        [data-elementor-device-mode="desktop"]
    )) {
        @include wgl-popup-responsive('-tablet');
    }
    &:is(
        [data-elementor-device-mode="mobile_extra"],
        [data-elementor-device-mode="mobile"]
    ) {
        @include wgl-popup-responsive('-mobile');
    }
}
