/* ==================== #Navigation Menu ==================== */

@use '../../mixins';

.widget_nav_menu,
.widget_pages {
    .menu,
    & > ul {
        padding: 0;
        margin: 0;
        li {
            padding-right: 0;
            margin-bottom: 10px;
        }
        &,
        ul {
            list-style: none;
        }
        a {
            display: block;
            position: relative;
            @include mixins.widget_list_dot;
        }
    }
    .current-menu-item > a::before {
        color: inherit;
    }
}
ul.wp-block-page-list {
    padding: 0;
    margin: 0;
    li {
        padding-right: 0;
        margin-bottom: 10px;
    }
    &,
    ul {
        list-style: none;
    }
    a {
        display: block;
        position: relative;
        @include mixins.widget_list_dot;
    }
}