/* ==================== ##Working Hours ==================== */

.wgl-working-hours {
    .working-item {
        display: flex;
        align-items: baseline;
        &_day {
            order: 1;
            margin-right: 13px;
        }
        &_hours {
            order: 3;
            margin-left: 13px;
        }
        &::after {
            content: '';
            width: 100%;
            height: 1px;
            flex: 1;
            order: 2;
            transform: translateY(1px);
        }
    }
    .working-item {
        .working-item_day {
            font-weight: 400;
        }
        .working-item_hours {
            font-weight: 600;
        }
    }
}
