/* ==================== #Tagcloud ==================== */

.tagcloud,
.wp-block-tag-cloud {
    --tag-cloud-gap: 6px;
    font-size: 0;
    a {
        display: inline-block;
        margin-bottom: var(--tag-cloud-gap);
        padding: 0 9px;
        font-size: 14px !important;
        line-height: 34px;
        font-weight: 500;
        font-family: var(--burido-content-font-family);
        color: var(--burido-header-font-color);
        background: var(--burido-form-bg-color);
        transition: 0.4s ease-in-out;
        border-radius: 10px;
        &:not(:last-child) {
            margin-right: var(--tag-cloud-gap);
        }
        &:hover,
        .format-no_featured &:hover {
            color: var(--burido-tertiary-color);
            background-color: var(--burido-secondary-color);
            border-radius: 30px;
        }
    }
}
.widget_tag_cloud,
.widget_product_tag_cloud {
    margin-bottom: 17px;
    .tagcloud {
        margin-bottom: -20px;
    }
    .title-wrapper {
        margin-bottom: 24px;
    }
}