/* ==================== ##Header Modules ==================== */

//* ↓ Default Styles
.elementor-element.elementor-widget {
    &.elementor-widget-wgl {
        &-header-logo,
        &-header-search,
        &-header-delimiter,
        &-header-list-info,
        &-header-cart,
        &-favorite,
        &-header-wishlist,
        &-header-login,
        &-date,
        &-menu {
            margin-bottom: 0;
        }
    }
    &.elementor-widget-wgl-header {
        &-logo,
        &-date,
        &-search,
        &-delimiter,
        &-list-info,
        &-side_panel,
        &-cart,
        &-favorite,
        &-wishlist,
        &-login{
            width: auto;
        }
    }
    &.elementor-widget-wgl-date {
        width: auto;
    }
    &.elementor-widget-wgl-header-delimiter {
        .delimiter {
            background: #e5e5e5;
        }
    }
}
