//* ==================== ##Isotope ==================== */

.wgl-filter_wrapper {
    pointer-events: none;
}
.isotope-filter {
    --wgl-filtet-categories-gap: 10px;
    @media (max-width: 767px) {
        --wgl-filtet-categories-gap: 6px;
    }
    .wgl-filter_swiper_wrapper {
        width: calc(100% + var(--wgl-filtet-categories-gap));
        margin: 0 calc(-0.5 * var(--wgl-filtet-categories-gap));
    }
    .swiper-wrapper {
        min-width: max-content;
        width: auto;
    }
    .swiper-slide {
        display: inline-block;
        width: fit-content;
        pointer-events: all;
    }
    &:not(.swiper-container-initialized) {
        display: flex;
        align-items: flex-end;
        max-width: 100%;
        overflow: hidden;
        margin-bottom: 10px;
        &.filter {
            &-left {
                margin-right: auto;
                text-align: left;
            }
            &-center {
                margin-left: auto;
                margin-right: auto;
                text-align: center;
            }
            &-right {
                margin-left: auto;
                text-align: right;
            }
        }
    }

    &.filter {
        &-left {
            .swiper-wrapper {
                justify-content: flex-start;
            }
        }
        &-center {
            .swiper-wrapper {
                justify-content: center;
            }
        }
        &-right {
            .swiper-wrapper {
                justify-content: flex-end;
            }
        }
        &-space-between {
            .isotope-filter {
                width: 100%;
            }
            .swiper-wrapper {
                justify-content: space-between;
            }
        }
    }
    &.wgl-filter_wrapper a {
        display: inline-block;
        position: relative;
        margin: 0 calc( 0.5 * var(--wgl-filtet-categories-gap));
        padding: 0 2px;
        border-radius: unset;
        font-size: 16px;
        line-height: 1.5;
        font-weight: 500;
        transition: 0.5s ease-in-out;
        color: var(--burido-header-font-color);
        letter-spacing: 0;
        .cat_title{
            position: relative;
            display: inline-block;
        }
        &::before {
            content: '';
            position: absolute;
            z-index: 0;
            bottom: 2px;
            left: 0;
            width: 100%;
            height: 0;
            background: var(--burido-primary-color);
            transition: 0.4s;
        }
        &:hover {
            &::before {
                height: 4px;
            }
        }
        &.active {
            &::before {
                height: calc(100% - 4px);
            }
        }
        &.active {
        }
        .filter_counter,
        &.empty {
            display: none;
        }
    }
    &.has_filter_counter {
        .filter_counter {
            display: inline-block !important;
            z-index: 1;
            text-align: center;
            line-height: 1;
            font-size: 11px;
            font-weight: 700;
            transition: 0.3s;
            letter-spacing: 0;
            vertical-align: text-top;
            margin-left: 2px;
            margin-top: -7px;
            transition: 0s;
        }
    }
    &.max_width_enabled {
        overflow: hidden;
    }
}

// Isotope Filtering
// @see https://isotope.metafizzy.co/v1/docs/introduction.html
.isotope-item {
    z-index: 2;
}
.isotope-hidden.isotope-item {
    pointer-events: none;
    z-index: 1;
}
// Isotope CSS3 transitions
.isotope,
.isotope .isotope-item {
    transition-duration: 0.8s;
}
.isotope {
    transition-property: height, width;
}
.isotope .isotope-item {
    transition-property: transform, opacity;
}
//* disabling Isotope CSS3 transitions
.isotope.no-transition,
.isotope.no-transition .isotope-item,
.isotope .isotope-item.no-transition {
    transition-duration: 0s;
}
