/* ==================== ##Image Layers ==================== */

.wgl-image-layers {
    display: inline-block;
    position: relative;
    line-height: 0;
    max-width: 100%;
    .img-layer_item{
        transform: translate(var(--pos-x, 0%), var(--pos-y, 0%));
    }
    .img-layer_image-wrapper {
        position: relative;
        line-height: 0;
        width: inherit;
        max-width: 100%;
        height: inherit;
        max-height: 100%;

        display: flex;
        &:not(:first-child) {
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
        }
        .img-layer_image {
            opacity: var(--wgl-opacity, 1);
            filter: blur(var(--wgl-blur, 0));
            transform: scale(var(--wgl-scale,1)) rotate(var(--wgl-rotate,0deg)) translate(var(--wgl-h-pos,0), var(--wgl-v-pos,0));
            transform-origin: center;
            transition: all 0.5s;
            img{
                border-radius: inherit;
            }
        }
    }
}

.elementor-widget-wgl-image-layers{
    font-size: 0;
}
