body:not([data-elementor-device-mode='desktop'],[data-elementor-device-mode='laptop'],[data-elementor-device-mode='widescreen']) {
    #wgl-cursor {
        display: none;
    }
}
#wgl-cursor {
    z-index: 1000;
    position: fixed;
    left: 0;
    top: 0;
    transition: 0.05s;
    pointer-events: none;
    &-pointer {
        position: absolute;
        z-index: 1;
        left: 0;
        top: 0;
        width: max-content;
        white-space: nowrap;
        color: var(--burido-cursor-point-color);
        font-weight: 700;
        font-size: 14px;
        &::before {
            content: '';
            position: absolute;
            z-index: 1;
            left: 0;
            top: 0;
            width: 8px;
            height: 8px;
            background-color: currentColor;
            transition: background-color 0.1s;
        }
        > .cursor-content {
            --color: var(--burido-tertiary-color);
            --bg-color: transparent;
            --color-child: var(--burido-primary-color);
            --bg-color-child: transparent;
            --size: 24px;
            --transition: 0.5s;

            color: var(--color);
            background-color: var(--bg-color);
            font-size: var(--size);
            transform-origin: left top;
            transition: var(--transition) ease-in-out;
            letter-spacing: 0;
            display: block;
            overflow: hidden;
            transform: scale(1);
            img {
                transition: var(--transition) ease-in-out;
            }
            &:not([class*='animation']) {
                transform: scale(0);
            }
            &.cursor_center {
                transform: scale(0) translate(-50%, -50%);
                &.animation-fade {
                    transform: scale(1) translate(-50%, -50%);
                }
                &.animation-zoom {
                    transform: scale(0) translate(-50%, -50%);
                }
            }
            &.animation {
                &-fade {
                    opacity: 0;
                    transform: scale(1);
                }
                &-zoom {
                    transform: scale(0);
                }
                &-slide-in-left {
                    img {
                        transform: translateX(-100%);
                    }
                }
                &-slide-in-right {
                    img {
                        transform: translateX(100%);
                    }
                }
                &-slide-in-top {
                    img {
                        transform: translateY(-100%);
                    }
                }
                &-slide-in-bot {
                    img {
                        transform: translateY(100%);
                    }
                }
            }
        }
        > .cursor-content-text {
            position: absolute;
            z-index: 1;
            img {
                color: var(--burido-tertiary-color);
            }
        }
        > .tooltip_bg {
            overflow: visible;
            --tooltip-bg-width: 70px;
            --tooltip-bg-height: 70px;
            --tooltip-bg-radius: 50%;
            &::before,
            &::after {
                content: '';
                position: absolute;
                pointer-events: none;
                left: 50%;
                top: 50%;
                border-radius: var(--tooltip-bg-radius);
                transform: translate(-50%,-50%);
            }
            &::before {
                z-index: -1;
                width: var(--tooltip-bg-width);
                height: var(--tooltip-bg-height);
                background-color: var(--burido-primary-color);
            }
            &::after {
                z-index: -2;
                width: calc(var(--tooltip-bg-width) * 4);
                height: calc(var(--tooltip-bg-height) * 4);
            }
        }
        > .cursor_center {
            transform: translate(-50%, -50%);
        }
        &.visible {
            &::before {
                background-color: transparent;
            }
            > .cursor-content {
                transform: scale(1);
                &.cursor_center {
                    &,
                    &.animation-zoom {
                        transform: scale(1) translate(-50%, -50%);
                    }
                }
                img {
                    display: block;
                }
                &.animation {
                    &-fade {
                        opacity: 1;
                    }
                    &-zoom {
                        transform: scale(1);
                    }
                    &-slide-in-left,
                    &-slide-in-right {
                        img {
                            transform: translateX(0);
                        }
                    }
                    &-slide-in-top,
                    &-slide-in-bot {
                        img {
                            transform: translateY(0);
                        }
                    }
                }
            }
        }
    }

    &.portfolio {
        #wgl-cursor-pointer {
            color: transparent;
            left: 10px;
            top: 10px;
        }
    }
    .cursor-from-js,
    .cursor-global,
    .portfolio-tooltip,
    .product-cat-tooltip {
        color: unset;
        background: unset;
        h6 {
            font-size: 16px;
            font-weight: 600;
            width: fit-content;
            line-height: 1.4;
            padding: 5px 10px;
            color: var(--burido-secondary-color);
            text-align: center;
            .wgl-icon {
                font-size: inherit;
                color: inherit;
            }
        }
        .wgl-icon {
            font-size: 28px;
            color: var(--burido-secondary-color);
            vertical-align: middle;
            line-height: 1;
            .elementor-icon {
                font-size: inherit;
                color: inherit;
                transition: inherit;
            }
        }
        .descr,
        .post_cats,
        .count {
            width: fit-content;
            margin: 0;
            margin-top: 1px;
            color: var(--burido-primary-color);
        }
    }
    .portfolio-tooltip {
        padding: 0;
        overflow: visible;
        margin: 20px;
        &::before {
            content: '';
            position: absolute;
            z-index: -1;
            pointer-events: none;
            width: 350px;
            height: 350px;
            left: 50%;
            top: 50%;
            border-radius: 50%;
            transform: translate(-50%,-50%);
        }
        h6 {
            font-size: 24px;
            color: var(--burido-header-font-color);
            background: var(--burido-tertiary-color);
            padding: 11px 15px;
            border-radius: 15px;
        }
        > .post_cats {
            color: var(--burido-header-font-color);
            background: var(--burido-primary-color);
            border-radius: 10px;
            margin-top: -7px;
            margin-left: 15px;
            margin-right: 15px;
            padding: 6px 9px;
            white-space: normal;
            span {
                margin: 0;
                color: inherit;
                line-height: 1.3;
                &::after {
                    color: var(--burido-header-font-color);
                }
            }
        }
    }
    .carousel-tooltip {
        line-height: 1;
        margin: 0 -2px;
    }
}
.wgl-cursor-text[data-cursor-prop="none"] {
    &,
    a {
        cursor: none;
    }
}
.admin-bar {
    #wgl-cursor-pointer {
        bottom: 0;
    }
}