@use "mixins";

/* ==================== #Search ==================== */
.widget_search,
.widget_product_search {
    margin-bottom: 5px;
    .search-form{
        margin-top: -7px;
    }
}
body {
    .widget_search .search-form,
    .widget_product_search .woocommerce-product-search ,
    .wc-block-product-search__fields {
        position: relative;
        z-index: 1;
        .search-field {
            height: 42px;
            width: 100%;
            margin-bottom: 0;
            padding-left: 27px;
            outline: none;
            overflow: hidden;
            font-size: 16px;
            font-weight: 400;
            @include mixins.placeholder;
        }
        .search__icon,
        .wc-block-product-search__button {
            color: var(--burido-primary-color);
        }
        .search-button:hover .search__icon,
        .wc-block-product-search__button:hover {
            color: var(--burido-secondary-color);
        }
        @include mixins.search_button;
        @include mixins.search_icon;
    }
    .wc-block-product-search__fields {
        .wc-block-product-search__field {
            margin: 0;
        }
        .wc-block-product-search__button {
            display: block;
            margin: 0;
            padding: 0;
            overflow: unset;
            border: unset;
            pointer-events: auto;
            background: unset;
            &::before {
                display: block;
                content: "";
                mask-image: var(--burido-search-h);
                mask-position: center center;
                mask-size: 1em;
                mask-repeat: no-repeat;
                width: 1em;
                height: 1em;
                padding: 0;
                box-shadow: none;
                background-color: currentColor;
                font-style: normal;
                font-variant: normal;
                text-transform: none;
                line-height: 0;
                font-size: 22px;
                transition: .4s;
            }
            svg {
                display: none;
            }
        }
    }
}

.wp-block-search{
    .wp-block-search__inside-wrapper {
        border: 0;
        padding: 0;
        position: relative;
        .wp-block-search__button,
        .wp-block-search__input{
            margin: 0;
        }
        .wp-block-search__input{
            border: 0;
        }
    }
    &.wp-block-search__no-button {
        .wp-block-search__input {
            width: 100%;
        }
    }
    &.wp-block-search__button-inside,
    &.wp-block-search__button-outside,
    &.wp-block-search__no-button {
        .wp-block-search__inside-wrapper {
            .wp-block-search__input {
                border: 0;
                border-bottom: 1px solid var(--burido-header-font-color);
                padding: 0;
                height: 40px;
                &:focus {
                    border-color: var(--burido-header-font-color);
                }
            }
        }
    }
    &.wp-block-search__button-inside {
        .wp-block-search__inside-wrapper {
            border: 0;
            padding: 0;
            position: relative;
            .wp-block-search__input {
                padding-left: 0;
            }
            .wp-block-search__button {
                margin: 0;
                position: absolute;
                right: 0;
                top: 0;
            }
        }
    }
    &.wp-block-search__text-button,
    &.wp-block-search__icon-button {
        &.wp-block-search__button-inside {
            .wp-block-search__button {
                position: absolute;
                z-index: 1;
                right: 0;
                top: 0;
            }
        }
        &.wp-block-search__button-outside {
            .wp-block-search__input {
                display: inline;
            }
            .wp-block-search__button {
                margin-left: 10px;
            }
        }
    }
    &.wp-block-search__text-button {
        &.wp-block-search__button-outside,
        &.wp-block-search__button-inside {
            .wp-block-search__button {
                font-size: 14px;
                padding: 5px 20px;
                line-height: 1;
            }
        }
        &.wp-block-search__button-inside {
            .wp-block-search__input {
                padding-right: 95px;
            }
        }
    }
    &.wp-block-search__icon-button {
        &.wp-block-search__button-outside,
        &.wp-block-search__button-inside {
            .wp-block-search__button {
                padding: 0;
                border-radius: 50%;
                border: unset;
                vertical-align: bottom;
                &::before {
                    display: block;
                    content: "";
                    mask-image: var(--burido-search-h);
                    mask-position: center center;
                    mask-size: 1em;
                    mask-repeat: no-repeat;
                    width: 40px;
                    height: 40px;
                    padding: 0;
                    box-shadow: none;
                    background-color: currentColor;
                    font-style: normal;
                    font-variant: normal;
                    text-transform: none;
                    line-height: 0;
                    font-size: 22px;
                }
                .search-icon {
                    display: none;
                }
            }
        }
        &.wp-block-search__button-outside {
            .wp-block-search__input {
                width: calc(100% - 50px);
            }
        }
        &.wp-block-search__button-inside {
            .wp-block-search__input {
                padding-right: 50px;
                width: 100%;
            }
        }
    }
}
