/* ==================== ##Image Comparison ==================== */

.wgl-image_comparison.cocoen{
    cursor: pointer;
    line-height: 0;
    margin: 0;
    overflow: hidden;
    padding: 0;
    position: relative;
    user-select: none;
    border-radius: 0;
    img.comp-image{
        max-width: none;
        display: block;
        width: 100%;
    }
    & > div{
        height: 100%;
        left: 0;
        overflow: hidden;
        position: absolute;
        top: 0;
        width: 50%;
    }
    .cocoen-drag{
        position: absolute;
        z-index: 1;
        top: 0;
        bottom: 0;
        left: 50%;
        width: 2px;
        margin-left: -1px;
        background: var(--burido-tertiary-color);
        cursor: ew-resize;
        &::before,
        &::after{
            content: "";
            position: absolute;
            top: 50%;
            width: 80px;
            height: 80px;
            cursor: pointer;
            margin-top: -40px;
            border-radius: 0;
            transform: rotate(90deg);

            background-image: var(--burido-bg-caret2-h);
            background-size: 14px;
            background-repeat: no-repeat;
            background-position: 50% 78%;
        }
        &::before{
            z-index: 1;
            left: 50%;
            margin-left: -40px;
            background-color: var(--burido-tertiary-color);
            border-radius: 40px;
            transform: scaleX(-1) rotate(90deg);
            box-shadow: 4px 4px 15px 0 rgba(0, 0, 0, 0.1);
        }
        &::after{
            z-index: 2;
            right: 50%;
            margin-right: -40px;
            background-color: transparent !important;
        }
    }
}