/* ==================== #Author ==================== */
.widget_author {
    margin-bottom: 0;
}
.author-widget {
    &_wrapper {
        position: relative;
        z-index: 1;
        text-align: center;
        max-width: 270px;
        margin-left: auto;
        margin-right: auto;
        background-size: cover;
        overflow: hidden;
        margin-bottom: 9px;
        padding: 30px;
        padding-bottom: 0;
        > h4,
        > p {
            + .author-widget_social {
                margin-top: 19px;
            }
        }
    }
    &_content {
        color: var(--burido-header-font-color);
        margin-top: 20px;
    }
    &_img{
        width: 210px;
        border-radius: 50%;
        margin: 0 auto;
    }
    &_title {
        font-size: 32px;
        line-height: 1.25em;
        color: inherit;
        span {
            font: inherit;
            line-height: inherit;
            letter-spacing: inherit;
            color: inherit;
        }
    }
    &_text {
        font-size: 16px;
        font-weight: 500;
        color: inherit;
        margin: 0;
        margin-top: 2px;
    }
    &_social {
        position: relative;
        z-index: 1;
        margin: 20px auto 0;
        max-width: fit-content;
        background: var(--burido-secondary-color);
        a {
            display: inline-block;
            position: relative;
            height: 46px;
            width: 46px;
            border-radius: 50%;
            font-size: 15px;
            line-height: 46px;
            font-weight: 400;
            color: var(--burido-tertiary-color);
            background: transparent;
            transition: .4s;
            text-align: center;
            &::before {
                display: inline-block;
                transition: unset;
            }
            &:hover {
                color: var(--burido-tertiary-color);
                opacity: 0.8;
            }
        }
    }
    &_social-link:not(:last-child) {
        margin-right: 0;
    }
    &_img_sign-wrapper {
        margin: 0;
        line-height: 0;
        font-size: 0;
        margin: -67px -20px -109px 0;
        z-index: -1;
        position: relative;
    }
}
