/* ==================== ##Countdown ==================== */

.wgl-countdown {
    .countdown-row {
        display: flex;
        align-items: center;
    }
    .countdown-section {
        position: relative;
        color: inherit;
        .countdown-amount {
            --dots-size: 10px;
            --dots-interval: 20px;
            --dots-v-pos: 20%;
            --dots-h-pos: 0;

            display: flex;
            flex-direction: row;
            align-items: center;
            justify-content: center;
            z-index: 1;
            margin: 0 auto;
            font-size: 1em;
            line-height: 1;
            font-family: var(--burido-additional-font-family);
            font-weight: normal;
            letter-spacing: 0;
            box-sizing: border-box;
            color: var(--burido-primary-color);
            span{
                display: inline-block;
            }
        }
        .countdown-period {
            display: block;
            letter-spacing: 0;
            font-family: var(--burido-header-font-family);
            font-size: 20px;
            font-weight: 600;
            line-height: 1;
            color: var(--burido-header-font-color);
            min-width: 100%;
            margin: auto;
            padding-top: 0;
            white-space: nowrap;
        }
    }
}

.elementor-widget-wgl-countdown {
    &.a {
        &left {
            .countdown-row {
                justify-content: flex-start;
            }
        }
        &center {
            .countdown-row {
                justify-content: center;
            }
        }
        &right {
            .countdown-row {
                justify-content: flex-end;
            }
        }
        &justify {
            .countdown-section {
                flex: 1;
            }
        }
    }
    &:not(.show_title_yes){
        .countdown-period{
            display: none !important;
        }
    }

    &.dots_style-circle,
    &.dots_style-rhombus,
    &.dots_style-square {
        .countdown-section:not(:last-child) .countdown-amount {
            &::before,
            &::after {
                content: '';
                visibility: hidden;
                position: absolute;
                z-index: 1;
                top: var(--dots-v-pos);
                right: var(--dots-h-pos);
                width: var(--dots-size);
                height: var(--dots-size);
                background: currentColor;
                color: var(--burido-primary-color);
            }
            &::before {
                margin-top: 0;
                transform: translateX(50%) translateY(-50%) rotate(45deg);
            }
            &::after {
                margin-top: calc(var(--dots-interval) + var(--dots-size));
                transform: translateX(50%) translateY(50%) rotate(45deg);
            }
        }
    }

    &.dots_style-square .countdown-section:not(:last-child) .countdown-amount {
        &::before, &::after {
            border-radius: 0;
            transform: translateX(50%) translateY(-50%) rotate(0deg);
        }
    }


    &.dots_style-circle .countdown-section:not(:last-child) .countdown-amount {
        &::before, &::after {
            border-radius: 50%;
            transform: translateX(50%);
        }
    }

    &.dots_style-font .countdown-section:not(:last-child) .countdown-amount {
        &::after {
            content: ':';
            position: absolute;
            z-index: 1;
            top: 0;
            right: 0;
            margin-top: 0;
            transform: translateX(50%);
        }
    }
}

body:not([data-elementor-device-mode='widescreen'], [data-elementor-device-mode='desktop']){
    .elementor-widget-wgl-countdown {
        &.a-{
            &tabletleft {
                .countdown-row {
                    justify-content: flex-start;
                }
            }
            &tabletcenter {
                .countdown-row {
                    justify-content: center;
                }
            }
            &tabletright {
                .countdown-row {
                    justify-content: flex-end;
                }
            }
            &tabletjustify {
                .countdown-section {
                    flex: 1;
                }
            }
        }
    }
}

body:is(
    [data-elementor-device-mode='mobile_extra'],
    [data-elementor-device-mode='mobile']){
    .elementor-widget-wgl-countdown {
        .countdown-section .countdown-period{
            font-size: 14px;
        }
        &.a- {
            &mobileleft {
                .countdown-row {
                    justify-content: flex-start;
                }
            }
            &mobilecenter {
                .countdown-row {
                    justify-content: center;
                }
            }
            &mobileright {
                .countdown-row {
                    justify-content: flex-end;
                }
            }
            &mobilejustify {
                .countdown-section {
                    flex: 1;
                }
            }
        }
    }
}