/* ==================== ##Pagination ==================== */

.wgl-pagination {
    --pagination-gap: 0;
    margin: calc(var(--pagination-gap) / 2 * -1);
    padding: 0 0 35px;
    list-style: none;
    clear: both;
    .page,
    .post-page-numbers {
        display: inline-block;
        margin: calc(var(--pagination-gap) / 2);
        line-height: 1;
        .page-numbers,
        .post-page-link {
            display: inline-block;
            position: relative;
            z-index: 1;
            height: 50px;
            min-width: 50px;
            padding: 0 5px;
            font-size: 16px;
            line-height: 50px;
            font-weight: 600;
            text-align: center;
            vertical-align: middle;
            transition: 0.4s ease-in-out;
            color: var(--burido-secondary-color);
            background-color: var(--burido-primary-color);
            border-radius: 50px;
            i {
                font-style: normal;
                display: inline-block;
                vertical-align: middle;
                transition: all 0.4s, color 0s;
                &::before,
                &::after {
                    display: inline-block;
                    transition: all 0.4s ease-in-out, color 0s;
                }
            }
            &:hover,
            &.current {
                color: var(--burido-tertiary-color);
                background-color: var(--burido-secondary-color);
            }
            &.prev,
            &.next {
                padding: 0;
                font-size: 22px;
                font-weight: normal;
                &::before {
                    display: none;
                }
            }
            &.prev {
                i {
                    transform: scale(-1) translate(0px, 5px);
                }
            }
            &.next {
                i {
                    transform: translate(0px,1px);
                }
            }
            &.current {
                pointer-events: none;
            }
            &.dots {
                pointer-events: none;
                min-width: unset;
                border: unset;
                background: unset;
                margin: 0 5px;
            }
        }
        &.current {
            span.page-link {
                color: var(--burido-tertiary-color);
                background-color: var(--burido-secondary-color);
            }
        }
        &.current,
        span.current {
            user-select: none;
            cursor: default;
        }
    }
    .page-numbers,
    .post-page-numbers {
        &.dots {
            user-select: none;
            cursor: default;
        }
        &.dots,
        &.next,
        &.prev {
            &::after {
                display: none;
            }
        }
    }
}

.blog-post_content {
    .wgl-pagination {
        padding-bottom: 0;
        margin-bottom: 10px;
        font-size: 0;
        .page:not(:last-child),
        .post-page-numbers:not(:last-child){
            margin-right: 7px;
        }
        .post-page-link {
            min-width: 25px;
            height: 30px;
            min-width: 30px;
            font-size: 14px;
            line-height: 30px;
            padding: 0 5px;
            margin: 25px 0 0 0;
        }
    }
}