//* ==================== ##Testimonials ==================== */

.wgl-testimonials {
    position: relative;
    --wgl-gap: 30px;
    > .row{
        display: flex;
        flex-wrap: wrap;
        margin: calc(-0.5 * var(--wgl-gap));
    }
    .wgl-carousel_wrapper{
        --wgl-gap: inherit;
        margin: 0 calc(-0.5 * var(--wgl-gap));
        .testimonials__wrapper {
            padding: 0 calc(0.5 * var(--wgl-gap));
        }
    }
    .testimonials__wrapper {
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        transition: 0s, opacity 0.4s, filter 0.4s;
        padding: calc(0.5 * var(--wgl-gap));
    }
    .testimonial__item {
        display: flex;
        width: 100%;
        position: relative;
        z-index: 1;
        transform: translate(0);
        transition: inherit;
    }
    &.hover_animation {
        .testimonials__wrapper {
            padding-top: 20px;
            &:hover .testimonial__item {
                transform: translateY(-20px);
            }
        }
    }
    .item__author {
        display: flex;
        align-items: center;
        justify-content: center;
        line-height: 1;
    }
    .author__meta {
        display: flex;
        flex-direction: column;
    }
    .item__rating {
        display: inline-block;
        position: relative;
        width: calc(5.8em + 4 * 0.2em);
        font-size: 14px;
        letter-spacing: 0.2em;
        line-height: 1;
        color: var(--burido-header-font-color);
        &::before,
        ::before {
            content: '\f005\f005\f005\f005\f005';
            font-family: "Font Awesome 5 Free";
            font-weight: 700;
        }
        &::before {
            color: rgba(var(--burido-header-rgb),0.3);
        }
        span {
            position: absolute;
            top: 0;
            left: 0;
            padding-top: 1em;
            overflow: hidden;
            &::before {
                position: absolute;
                top: 0;
                left: 0;
                color: var(--burido-header-font-color);
            }
        }
    }
    .author__name {
        font-family: var(--burido-header-font-family);
        font-weight: var(--burido-header-font-weight);
        letter-spacing: -0.03em;
        font-size: 24px;
        line-height: 1.5em;
        color: var(--burido-header-font-color);
        transition: 0.4s;
        a {
            font: inherit;
            color: inherit;
            line-height: inherit;
            letter-spacing: inherit;
        }
    }
    .author__position {
        display: inline-block;
        font-size: 14px;
        line-height: 1.5;
        letter-spacing: 0;
        margin-top: 1px;
        margin-bottom: 22px;
    }
    .item__icon{
        display: none;
        width: fit-content;
        position: relative;
        color: var(--burido-primary-color);
        font-size: 80px;
        line-height: 0.2em;
        font-weight: normal;
        vertical-align: text-bottom;
        margin: 0 20px 10px 0;
        &::before{
            display: block;
            content: "";
            mask-image: var(--burido-quote-h);
            mask-position: center center;
            mask-size: 1em;
            mask-repeat: no-repeat;
            width: 0.6em;
            height: 0.5em;
            padding: 0;
            box-shadow: none;
            background-color: currentColor;
            font-style: normal;
            font-variant: normal;
            text-transform: none;
            line-height: 0;
            transition: transform 0.4s;
        }
    }
    .item__title{
        font-size: 40px;
        color: var(--burido-header-font-color);
        line-height: 1.4em;
    }
    .item__quote {
        position: relative;
        color: var(--burido-header-font-color);
        margin-left: 52px;
        border: 1px solid #DEDEDE;
        line-height: 1.8;
        .item__icon{
            position: absolute;
            right: 0;
            bottom: 0;
            margin: 0 0.5em -0.38em 0;
        }
        p:last-child {
            margin-bottom: 0;
        }
    }
    .author__thumbnail {
        position: relative;
        display: inline-block;
        --image-width: 120;
        --image-not-active-width: var(--image-width);
        margin-right: 27px;
        transition: .7s;
        img {
            display: inline-block;
            width: calc(var(--image-width) * 1px);
            min-width: calc(var(--image-width) * 1px);
            transform: scale(1);
            transition: transform .7s;
        }
    }
    .testimonials__wrapper:hover{
        .author__thumbnail img{
            transform: scale(1) !important;
        }
    }
    .swiper-slide:not(.swiper-slide-active){
        .author__thumbnail img{
            transform: scale( calc( var(--image-not-active-width) / var(--image-width) ) );
        }
    }
    &.type {
        &-top_block {
            .author__name{
                margin-top: 25px;
            }
            .author__position{
                margin-bottom: 0;
            }
            .author__thumbnail {
                margin-bottom: -34px;
                margin-right: 0;
                margin-left: 0
            }
            .item__icon + .author__thumbnail {
                margin-top: 20px;
            }
        }
        &-bottom_block {
            .author__name{
                margin-top: 25px;
            }
            .author__position{
                margin-bottom: 0;
            }
            .author__thumbnail {
                margin: 15px 0 0;
            }
            .item__quote{
                margin: 0;
            }
            .item__author {
                flex-direction: column;
            }
        }
        &-top_inline {
            .author__thumbnail{
                margin-bottom: -38px;
            }
            .item__quote{
                margin-bottom: 26px;
            }
        }
        &-bottom_inline {
            .item__quote {
                margin-bottom: 26px;
                margin-left: 0;
            }
            .author__position{
                margin-bottom: 2px;
            }
        }
        &-left_block {
            .author__name{
                margin-top: 25px;
            }
            .author__position{
                margin-bottom: 0;
            }
            .author__thumbnail{
                margin-right: 40px;
            }
            .item__quote{
                margin-left: 0;
            }
            body:is( [data-elementor-device-mode='mobile_extra'], [data-elementor-device-mode='mobile']) & .testimonials__wrapper{
                display: block;
                .author__thumbnail{
                    margin-right: 0;
                    margin-bottom: 20px;
                }
            }
        }
    }
    @media (max-width: 600px) {
        &.type-inline_top {
            .author__thumbnail {
                position: relative;
                margin-left: 0;
                margin-top: 0;
            }
        }
        &.type-inline_top {
            .wgl-carousel_wrapper .testimonials__wrapper {
                padding-left: 15px;
            }
        }
    }
}

.elementor-widget-wgl-testimonials {
    max-width: 100% !important;
    // Alignment
    @mixin wgl-testimonial-a-responsive($media) {
        &.a#{$media}left {
            .type-bottom_block {
                .item__author {
                    align-items: flex-start;
                    flex-direction: column;
                    justify-content: center;
                }
            }
            .type-top_block,
            .type-left_block {
                .item__author {
                    align-items: flex-start;
                    flex-direction: column;
                    justify-content: flex-start;
                }
            }
            .type-top_inline,
            .type-bottom_inline {
                .item__author {
                    align-items: center;
                    flex-direction: row;
                    justify-content: flex-start;
                }
            }
        }
        &.a#{$media}center {
            .type-bottom_block {
                .item__author {
                    align-items: center;
                    flex-direction: column;
                    justify-content: center;
                }
            }
            .type-top_block,
            .type-left_block {
                .item__author {
                    align-items: center;
                    flex-direction: column;
                    justify-content: center;
                }
            }
            .type-top_inline,
            .type-bottom_inline {
                .item__author {
                    align-items: center;
                    flex-direction: row;
                    justify-content: center;
                }
            }
        }
        &.a#{$media}right {
            .type-bottom_block {
                .item__author {
                    align-items: flex-end;
                    flex-direction: column;
                    justify-content: center;
                }
            }
            .type-top_block,
            .type-left_block {
                .item__author {
                    justify-content: flex-end;
                    flex-direction: column;
                    align-items: flex-end;
                }
            }
            .type-top_inline,
            .type-bottom_inline {
                .item__author {
                    align-items: center;
                    flex-direction: row;
                    justify-content: flex-end;
                }
            }
        }
    }

    .testimonials__wrapper.no_image{
        .testimonial__item{
            margin: 0;
            padding: 0;
        }
        .author__thumbnail{
            position: static;
            top: unset;
            left: unset;
            right: unset;
            transform: unset;
        }
    }
    @include wgl-testimonial-a-responsive('');
    body:is(
            [data-elementor-device-mode='tablet_extra'],
            [data-elementor-device-mode='tablet'],
            [data-elementor-device-mode='mobile'],
            [data-elementor-device-mode='mobile_extra']) & {
        @include wgl-testimonial-a-responsive('-tablet');
    }
    body:is(
            [data-elementor-device-mode='mobile'],
            [data-elementor-device-mode='mobile_extra']) & {
        @include wgl-testimonial-a-responsive('-mobile');
    }
}
