/* ==================== ##Revolution Slider ==================== */

.wgl-container {
    rs-module,
    .rb-modal-wrapper,
    #rs_overview,
    #objectlibrary,
    #waitaminute,
    #rs_overview_menu,
    #builderView {
        [class*="fab fa-"]{
            font-weight: 400;
            font-family: "Font Awesome 5 Brands";
            &::before{
                font-family: "Font Awesome 5 Brands";
                font-weight: inherit;
            }
        }

        [class*="far fa-"],
        [class*="fal fa-"],
        [class*="fas fa-"]{
            font-family: "Font Awesome 5 Free";
            font-weight: 400;
            &::before{
                font-family: "Font Awesome 5 Free";
                font-weight: 900;
            }
        }

        [class*="far fa-"]{
            font-weight: 900;
            &::before{
                font-weight: 900;
            }
        }
    }
    .rs-layer.wgl-button,
    .rev_slider_button{
        transition: all .4s;
    }
}
