/* ==================== ##Contact Form ==================== */

.wpcf7 {
    &-form-control-wrap {
        display: block;
    }
    form .wpcf7-response-output {
        margin: 20px 0 5px 0;
    }

    input[type='text'],
    input[type='url'],
    input[type='search'],
    input[type='email'],
    input[type='password'],
    input[type='tel'],
    input[type='time'],
    input[type='number'],
    input[type='date'],
    input[type='range'],
    select,
    textarea{
        width: 100%;
    }
    .ajax-loader {
        display: none !important;
    }
    &-not-valid {
        border-color: #ff0000;
    }
    input, textarea, select {
        + .wpcf7-not-valid-tip {
            margin-top: 0;
            margin-bottom: -13px;
            font-size: 13px;
        }
    }
    .form-icon {
        position: absolute;
        z-index: 1;
        top: 9px;
        right: 35px;
        font-size: 14px;
        color: #bababa;
    }
    .wpcf7-spinner {
        display: none;
    }
    //* ↓ Submit Button
    .wpcf7-submit {
        padding: 8px 40px;
        position: relative;
        z-index: 1;
    }
    //* ↑ submit button
    &-form-control-wrap {
        .wpcf7-acceptance,
        .wpcf7-radio,
        .wpcf7-checkbox {
            .wpcf7-list-item {
                display: flex;
                align-items: center;
                input {
                    width: auto;
                    height: auto;
                    + .wpcf7-list-item-label {
                        padding-left: 0.5em;
                        display: inline-block;
                    }
                }
                label {
                    display: flex;
                    align-items: center;
                }
            }
        }
        .wpcf7-radio .wpcf7-list-item {
            input[type='radio'] {
                appearance: radio;
            }
        }
    }
    .row {
        margin-left: -15px;
        margin-right: -15px;
        [class*='wgl_col-'] {
            padding-right: 15px;
            padding-left: 15px;
        }

        //* ↓ Coming Soon
        &.coming-soon {
            .wpcf7-form-control-wrap {
                display: inline-block;
                vertical-align: top;
                @media (min-width: 600px) {
                    margin-right: 20px;
                }
                + br {
                    display: none;
                }
            }

            input[type='submit'] {
                padding: 6px 32px;
                min-width: 135px;
            }
            + .wpcf7-mail-sent-ok {
                margin-top: -15px;
            }
        }
        &.home-4,
        &.services{
            input[type='submit'] {
                min-width: 150px;
            }
        }
        &.home-1,
        &.home-4,
        &.coming-soon,
        &.services,
        &.faq{
            input[type='text'],
            input[type='url'],
            input[type='search'],
            input[type='email'],
            input[type='password'],
            input[type='tel'],
            input[type='time'],
            select{
                border: unset;
                height: 56px;
                box-shadow: 0 15px 38px 0 rgba(46, 63, 38, .15);
            }
            textarea{
                border: unset;
            }
            .label- {
                &mail,
                &name,
                &url,
                &textarea {
                    &::before {
                        height: 56px;
                        line-height: 56px;
                    }
                }
            }
            input[type='submit'] {
                height: 56px;
            }
        }
    }
    .wpcf7-list-item {
        margin: 0;
    }
    .wgl-button-cf7 {
        position: relative;
        z-index: 1;
        display: inline-block;
    }
}
.wpb_text_column .wpcf7 .wpcf7-form-control-wrap {
    display: block;
    margin-bottom: 20px;
}
.sign_up {
    display: flex;
    justify-content: center;
    margin-right: -20px;
    input[type='submit'] {
        margin-left: 20px;
        height: 56px;
    }
    input[type='email'] {
        width: 350px;
    }
    .ajax-loader {
        display: none;
    }
}