/* ==================== ##Header Date ==================== */

.wgl-header-date {
    font-size: 11px;
    line-height: 1.3em;
    font-weight: 400;
    text-transform: uppercase;
    display: flex;
    &.wgl-default-format {
        align-items: center;
        > span {
            &:first-child {
                font-size: 28px;
                margin-right: 8px;
            }
            &:last-child {
                font-weight: 400;
                span {
                    display: block;
                }
            }
        }
    }
    > span{
        &:first-child {
            color: var(--burido-primary-color);
        }
    }
    > span{
        &:last-child {
            color: var(--burido-header-font-color);
        }
    }
}
