/* ==================== ##Showcase ==================== */

.wgl-showcase-2 {
    position: relative;
    display: flex;
    flex-direction: column;
    pointer-events: none;
    --separator-color: rgba(var(--burido-header-rgb), 0.5);
    .showcase-2__wrapper{
        position: relative;
    }
    .showcase-2__title,
    .showcase-2__button_wrapper{
        position: relative;
        z-index: 2;
        transition: z-index 0s .1s;
    }
    .showcase-2__item{
        display: flex;
        position: relative;
        padding: 20px 3.125% 20px 3.125%;
        min-height: 150px;
        justify-content: space-between;
        align-items: center;
        margin: -1px 0 0 0;
        width: 100%;
        pointer-events: auto;
        flex-wrap: nowrap;
        &::after{
            opacity: var(--separator-opacity, 0);
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            border-bottom: var(--separator-width, 1px) solid var(--separator-color);
            z-index: -2;
        }
        &:first-child::after{
            border-top: var(--separator-width, 1px) solid var(--separator-color);
        }
    }
    .showcase-2__item_inner{
        display: flex;
        justify-content: center;
        align-items: center;
        width: 100%;
        flex-wrap: nowrap;
    }
    .showcase-2__subtitle{
        font-family: var(--burido-header-font-family);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.5em;
        display: inline-block;
        position: relative;
        letter-spacing: 0;
        color: var(--burido-header-font-color);
        transition: all .4s;
        white-space: normal;
    }
    .showcase-2__title{
        display: inline-flex;
        flex-shrink: 0;
        align-items: center;
        white-space: normal;
        max-width: 100%;
        transition: all .4s;
        .title{
            position: relative;
            z-index: 1;
            font-size: 64px;
            font-family: var(--burido-header-font-family);
            font-weight: var(--burido-header-font-weight);
            line-height: 1.3em;
            color: var(--burido-header-font-color);
            letter-spacing: var(--burido-h3-letter-spacing);
            text-transform: inherit;
            white-space: normal;
        }
    }
    .showcase-2__bg_text{
        display: flex;
        align-items: center;
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        padding-top: 0.02em;
        font-family: var(--burido-additional-font-family);
        font-weight: 400;
        font-size: clamp(96px, 12vw, 170px);
        line-height: 1.2em;
        color: var(--burido-tertiary-color);
        z-index: -1;
    }
    .showcase-2__content_wrapper {
        font-size: 16px;
        line-height: 1.778em;
        color: var(--burido-header-font-color);
        width: min( var(--sc2-content-width, 490px), calc(var(--sc2-inner-width, 100%) - var(--sc2-title-width, 700px)) );
    }
    .showcase-2__content{
        width: min( var(--sc2-content-width, 490px), calc(var(--sc2-inner-width, 100%) - var(--sc2-title-width, 700px)) );
        min-width: 100%;
        display: inline-block;
        p:last-child{
            margin: 0;
        }
    }
    .showcase-2__image{
        position: absolute;
        top: 50%;
        height: auto;
        left: var(--wgl-image-position, 20%);
        z-index: 4;
        opacity: 0;
        transform: translateY(-50%) rotate(var(--wgl-image-rotate, 0deg));
        transform-origin: top center;
        pointer-events: none;
        overflow: hidden;
        transition: all .45s, opacity .3s .15s;
        img{
            border-radius: inherit;
            max-width: unset;
            transform: translateX(-100%);
            transition: transform 0.45s;
        }
    }
    .showcase-2__background{
        &,
        &::before,
        &::after{
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            pointer-events: none;
            z-index: -1;
            transition: .4s;
        }
        &::before{
            content: '';
            opacity: 1;
        }
        &::after{
            content: '';
            opacity: 0;
        }
    }
    .showcase-2__item.active,
    .showcase-2__item:hover{
        .showcase-2__background{
            &::after{
                opacity: 1;
            }
        }

        .showcase-2__image{
            opacity: 1;
            transition: all .45s, opacity .3s .15s;
            img{
                transform: translateX(0);
            }
        }
    }
    &:not(:hover) .active,
    .showcase-2__item:hover{
        .showcase-2__title,
        .showcase-2__button_wrapper{
            position: relative;
            z-index: 5;
            transition: z-index 0s 0s;
        }
    }
    .showcase-2__link{
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 0;
        z-index: 6;
        transition: 0s .5s;
    }
    .showcase-2__item.active{
        .showcase-2__link{
            height: 100%;
        }
    }
    .showcase-2__button_wrapper{
        position: relative;
        .showcase-2__button{
            &.icon-read-more{
                display: flex;
                align-items: center;
                justify-content: center;
                transition: all .4s;
                will-change: transform;
                background-color: transparent;
                color: var(--burido-header-font-color);
                border-radius: 50%;
                svg, i, span{
                    height: 1em;
                    width: 1em;
                    min-width: 1em;
                    line-height: 1em;
                    text-align: center;
                    display: inline-block;
                    box-sizing: content-box;
                    transition: transform .4s;
                    &::before{
                        display: block;
                        transition: transform .4s;
                        will-change: transform;
                        line-height: inherit;
                    }
                }
            }
        }
    }
    &:not(.mobile_view_disable, .mobile_view_enable) {
        .showcase-2__content_wrapper{
            opacity: 0 !important;
            width: 0 !important;
            height: 0 !important;
        }
    }
    &.content_animation-yes.mobile_view_disable .showcase-2__item:not(.active){
        .showcase-2__content_wrapper{
            width: 0 !important;
            opacity: 0 !important;
        }
        .showcase-2__image img{
            transform: unset;
        }
    }
    &.content_animation-yes.mobile_view_enable{
        .showcase-2__item{
            &_inner{
                align-content: flex-start;
                flex-wrap: wrap;
            }
            .showcase-2__content_wrapper{
                display: none;
                opacity: 0;
                width: 100% !important;
                max-width: 100%;
                order: 1;
                transition-property: opacity !important;
            }
            .showcase-2__content{
                width: min( var(--sc2-content-width, 100%), 100%);
                min-width: unset;
            }
            &.active {
                .showcase-2__content_wrapper{
                    opacity: 1;
                }
            }
        }
    }
    &:not(.content_animation-yes).mobile_view_enable{
        .showcase-2__item {
            &_inner {
                align-content: flex-start;
                flex-wrap: wrap;
            }
            .showcase-2__content_wrapper{
                width: 100% !important;
                max-width: 100%;
                order: 1;
                display: block !important;
            }
            .showcase-2__content{
                width: min( var(--sc2-content-width, 100%), 100%);
                min-width: unset;
            }
        }
    }
}


@mixin wgl-showcase2-responsive($media) {
    body[data-elementor-device-mode='#{$media}'] .wgl-showcase-2.breakpoint_on-#{$media}:not(.content_animation-yes) {
        .showcase-2__background::after {
            opacity: 1;
        }
    }
}

@include wgl-showcase2-responsive('widescreen');
@include wgl-showcase2-responsive('desktop');
@include wgl-showcase2-responsive('tablet_extra');
@include wgl-showcase2-responsive('tablet');
@include wgl-showcase2-responsive('mobile_extra');
@include wgl-showcase2-responsive('mobile');