/* ==================== ##Header Styles ==================== */

.wgl-theme-header {
    position: relative;
    z-index: 3001;
    color: var(--burido-header-font-color);
    .wrapper {
        a {
            color: inherit;
        }
        .burido_module_button {
            a {
                margin-bottom: 0;
                box-shadow: none;
                color: #ffffff;
            }
        }
    }
    .wgl-sticky-header .wgl-logotype-container > a {
        &,
        > img {
            max-height: none !important;
        }
    }
    &.header_overlap {
        position: absolute;
        z-index: 99;
        width: 100%;
        left: 0;
        top: 0;
    }
    &.header_shadow {
        box-shadow: 1px 0 10px rgba(0, 0, 0, 0.1);
    }
}
.mobile-hamburger-module{
    .hamburger-box{
        display: inline-flex;
        justify-content: center;
        align-items: center;
    }
}
.wgl-elementor-builder.wgl-mobile-header{
    border: 0;
    display: block;
    .hamburger-box{
        display: inline-flex;
    }
    .wgl-menu-outer_content{
        .hamburger-box{
            display: none;
        }
    }
}
.wgl-mobile-header,
.mobile_nav_wrapper .primary-nav .menu{
    display: none;
}
.wgl-mobile-header .menu-item__plus,
.menu_vertical .menu-item__plus,
.mobile_nav_wrapper .primary-nav > ul > li ul::before,
.mobile_nav_wrapper .primary-nav > ul > li > div.mega-menu-container::before{
    display: none !important;
}

body:not(.elementor-editor-active) {
    .wgl-theme-header {
        .elementor-column,
        .elementor-column-wrap,
        .elementor-widget-wrap,
        .elementor-widget[data-widget_type="wgl-menu.default"] {
            position: static;
        }
    }
}
.wgl-header-row {
    .wgl-header-row_wrapper {
        display: flex;
        position: relative;
        flex-flow: row nowrap;
        align-items: center;
        justify-content: space-between;
    }
    .header_side {
        &.display_normal {
            flex: 0 auto;
        }
        &.display_grow {
            flex: 1;
            .primary-nav > .menu {
                white-space: nowrap;
            }
        }
        &.v_align_middle {
            align-self: center;
        }
        &.v_align_bottom {
            align-self: flex-end;
            .primary-nav > ul > li > a {
                align-self: flex-end;
                align-items: flex-end;
            }
            .header_area_container > *,
            .header_search-button {
                vertical-align: bottom;
            }
        }
        &.v_align_top {
            align-self: flex-start;
            .primary-nav .lavalamp-object {
                top: 0;
                bottom: auto;
                &::before {
                    transform: rotate(0.5turn);
                }
            }
            .primary-nav > ul > li > a {
                align-self: flex-start;
                align-items: flex-start;
            }
            .header_area_container > *,
            .header_search-button {
                vertical-align: top;
            }
        }

        &.h_align_left {
            text-align: left;
        }
        &.h_align_center {
            text-align: center;
        }
        &.h_align_right {
            text-align: right;
        }

        &.display_grow.h_align_right {
            margin-left: auto;
        }
        &.display_grow.h_align_center {
            margin-right: auto;
            margin-left: auto;
        }
        &.display_grow.h_align_left {
            margin-right: auto;
        }

        &.display_grow.h_align_left .header_area_container {
            justify-content: flex-start;
        }
        &.display_grow.h_align_center .header_area_container {
            justify-content: center;
        }
        &.display_grow.h_align_right .header_area_container {
            justify-content: flex-end;
        }

        &[class^="position_center"] {
            .header_area_container > div.mini-cart {
                padding: 0;
            }
            .primary-nav > ul li.mega-menu > ul.mega-menu {
                left: 0;
                right: 0;
                margin: 0 auto;
            }
        }
        &[class^="position_left"] .header_area_container > *:last-child {
            padding-right: 0;
        }
        &[class^="position_right"] .header_area_container > *:first-child {
            padding-left: 0;
        }
        &[class^="position_left"] .primary-nav ul li ul {
            left: 0;
            right: auto;
        }
        &[class^="position_left"] .primary-nav > ul > li {
            ul .sub-menu {
                left: 100%;
                right: auto;
            }
            &:not(:first-child):last-child {
                > .sub-menu {
                    left: 0;
                    right: auto;
                    .sub-menu {
                        left: 100%;
                        right: auto;
                    }
                }
            }
        }
    }
}
.wgl-header-row {
    .header_side,
    .header_render_editor,
    .wrapper,
    .header_area_container {
        max-width: 100%;
        box-sizing: border-box;
    }
}

.header_area_container {
    display: inline-block;
    height: 100%;
    max-height: 100%;
    > * {
        display: inline-block;
        vertical-align: middle;
    }
}

.delimiter {
    position: relative;
}

//* Logo
.wgl-logotype-container {
    img {
        vertical-align: middle;
        max-height: 100%;
        max-width: initial;
        width: auto;
    }
    a,
    a:hover,
    h1 {
        color: inherit;
    }
    .logo-name {
        font-size: 34px;
        line-height: 1;
        @media (max-width: 1200px) {
            font-size: 24px;
        }
    }
}
header:not(.wgl-menu-outer_content) > .wgl-logotype-container {
    .logo-name {
        width: 200px;
        width: min-content;
        font-size: 30px;
        white-space: pre-line;
    }
}

//* Menu
.wgl-site-header,
.wgl-sticky-header{
    .primary-nav {
        ul:hover {
            li:not(:hover) {
                > div, > ul.wgl-mega-menu {
                    clip: rect(auto, auto, 0, auto);
                }
            }
        }
    }
}
.primary-nav {
    position: relative;
    z-index: 1;
    a {
        cursor: pointer;
        transition: 0.3s;
    }
    &.align-left{
        text-align: left;
        > ul.menu  > li.mega-menu-links > ul.mega-menu.sub-menu,
        > ul.menu  > li.mega-cat > div.mega-menu-container {
            left: 0;
            right: auto;
        }
    }
    &.align-center {
        text-align: center;
        > ul.menu  > li.mega-menu-links > ul.mega-menu.sub-menu,
        > ul.menu  > li.mega-cat > div.mega-menu-container {
            left: 0;
            right: 0;
            margin-left: auto;
            margin-right: auto;
        }
    }
    &.align-right{
        text-align: right;
        > ul.menu  > li.mega-menu-links > ul.mega-menu.sub-menu,
        > ul.menu  > li.mega-cat > div.mega-menu-container {
            left: auto;
            right: 0;
        }
    }
    .content__media{
        font-weight: 400;
        transition: 0.4s;
        position: relative;
    }
    //* Lavalamp settings
    &.menu_line_enable {
        .menu {
            position: relative;
            .lavalamp-object {
                opacity: 0;
                position: absolute;
                z-index: 1;
                left: 0;
                top: 0;
                height: 1px;
                line-height: 1;
                display: flex;
                justify-content: space-between;
                color: var(--burido-secondary-color);
                pointer-events: none;
                background: currentColor;
            }
            &.lavalamp_animate {
                .lavalamp-object {
                    opacity: 1;
                }
            }
        }
    }
    > ul.lavalamp > li > a .item_wrapper_text::after,
    &.menu_line_enable > ul > li > a .item_wrapper_text .menu-item_dots {
        display: none !important;
    }
    ul li {
        display: inline-block;
        vertical-align: middle;
        line-height: inherit;
        margin-bottom: 0;
    }
    ul > li {
        height: 100%;
        > a {
            .item_wrapper_text {
                line-height: initial;
                position: relative;
                .menu-item_dots {
                    position: absolute;
                    z-index: -1;
                    width: 100%;
                    height: 1px;
                    left: 0;
                    bottom: 0;
                    opacity: 0;
                    margin: auto;
                    transition: 0.5s ease-in-out, color 0s;
                    pointer-events: none;
                    border-radius: inherit;
                    background: var(--burido-secondary-color);
                }
            }
        }
    }
    > ul li {
        position: relative;
        padding-left: 0;
    }
    > ul li.mega-menu {
        position: static !important;
        > ul.mega-menu {
            left: 0;
            right: 0;
            margin-left: auto;
            margin-right: auto;
            .menu-item__plus{
                display: none;
            }
        }
        &.mega-menu-e{
            position: relative !important;
            &.position-center,
            &.position-left-side{
                position: static !important;
            }
        }
    }
    > ul {
        height: 100%;
        margin-left: 0;
        padding: 0;
        & > li{
            & > a::before{ // easy transition (important block style if .sub-menu top > 100%)
                content: "";
                position: absolute;
                top: 100%;
                height: 11px;
                left: 0;
                right: 0;
            }
        }
    }
    ul > li.menu-item-has-children,
    ul > li.mega-menu.mega-cat {
        > a {
            > .menu-item__plus {
                position: relative;
                z-index: 1;
                font-size: 13px;
                font-style: normal;
                font-weight: normal;
                margin: 0 0 0 4px;
                transform-origin: center;
                perspective-origin: center;
                transform: unset;
                max-width: 14px;
                &::before {
                    display: inline-block;
                    vertical-align: middle;
                    content: "";
                    mask-image: var(--burido-arrow-down-right-h);
                    mask-position: center center;
                    mask-size: 1em;
                    mask-repeat: no-repeat;
                    width: 1em;
                    height: 1em;
                    padding: 0;
                    box-shadow: none;
                    background-color: currentColor;
                    font-style: normal;
                    font-variant: normal;
                    text-transform: none;
                    line-height: 0;
                    font-size: 18px;
                    transition: transform .4s;
                }
            }
            .menu-item_dots {
                width: calc(100% + 18px);
            }
        }
    }
    > ul > li {
        height: 100%;
        > a {
            &.__mPS2id {
                &.active {
                    .item_wrapper_text {
                        .menu-item_dots {
                            opacity: 1;
                        }
                    }
                }
            }
        }
        &[class*='current'] > a {
            .item_wrapper_text {
                line-height: initial;
            }
        }
        &[class*='current'] > a,
        &:hover > a {
            color: var(--burido-header-font-color);
            .item_wrapper_text {
                .menu-item_dots {
                    opacity: 1;
                }
            }
        }
        &.mega-menu-links > ul.mega-menu {
            padding-left: 20px;
            padding-right: 20px;
            & > li > a .item_wrapper_text::before{
                display: none;
            }
        }
        > a {
            display: flex;
            position: relative;
            z-index: 1;
            height: 100%;
            align-items: center;
            padding: 0;
            transition: 0.5s ease-in-out;
            color: var(--burido-header-font-color);
            border-radius: unset;
            margin: 0 20px;
        }
    }
    &.marker-disable {
        > ul > li > a {
            .menu-item_dots,
            &::after {
                display: none !important;
            }
        }
    }
    ul li > ul,
    ul li > ul ul,
    ul li .mega-menu-container {
        display: block;
        position: absolute;
        z-index: 555;
        top: calc(100% + 20px);
        left: -20px;
        min-width: 260px;
        white-space: nowrap;
        margin: 0;
        padding: 28px 0 24px;
        text-align: left;
        opacity: 0;
        visibility: hidden;
        transition: 0.5s ease-in-out;
        border-radius: 15px;
        &.wgl-e-container{
            white-space: normal;
            padding: 0;
            .elementor-column,
            .elementor-column-wrap,
            .elementor-widget-wrap{
                position: relative;
            }
        }
        .primary-nav{
            height: auto !important;
            ul{
                margin: 0;
                padding: 0;
                li{
                    margin-bottom: 0;
                }
            }

        }
    }
    ul li .mega-menu-container {
        transform: translateY(-200%);
        transition: 0.3s ease-out, transform 0s 0.3s;
        overflow: hidden;
    }
    ul li > ul {
        ul {
            top: -8px;
            left: 100%;
            margin: 0 2px;
            &::before {
                content: '';
                position: absolute;
                z-index: -1;
                height: 100%;
                width: calc(100% + 10px);
                top: 0;
                left: -10px;
            }
        }
        li {
            display: block;
            > a {
                .item_wrapper_text,
                > i {
                    transition: 0.5s ease-in-out;
                    margin-right: 14px;
                }
                .item_wrapper_text {
                    .menu-item_dots {
                        display: none;
                    }
                }
            }
            &:hover {
                ul {
                    top: -28px;
                }
            }
            &:hover,
            &[class*='current'] {
                > a {
                    &,
                    > .menu-item__plus {
                        color: var(--burido-primary-color);
                    }
                    .item_wrapper_text {
                        .menu-item_dots {
                            opacity: 1;
                        }
                    }
                }
            }
        }
        .menu-item {
            line-height: inherit;
            a {
                display: flex;
                align-items: center;
                justify-content: space-between;
                color: inherit;
                transition: all 0s, text-decoration 0.3s ease-in-out;
                padding: 9px 42px;
                overflow: hidden;
            }
        }
    }
    ul li:hover > ul,
    ul li:hover > div.mega-menu-container {
        z-index: 556;
        top: 100%;
        opacity: 1;
        visibility: visible;
        &.mega-menu > ul.mega-menu,
        &.mega-menu > li > ul.mega-menu,
        > ul.mega-menu,
        > li > ul.mega-menu {
            opacity: 1;
            visibility: visible;
        }
    }
    ul li:hover > div.mega-menu-container {
        transform: translateY(0);
        transition: 0.3s ease-out, transform 0s;
    }
    ul li ul:not(.mega-menu){
        li.menu-item-has-children {
            > a > .menu-item__plus {
                padding-left: 1px;
                line-height: 1;
                font-style: normal;
                margin: 0;
                font-size: 18px;
                color: inherit;
            }
            &[class*='current'] > a,
            &:hover > a {
                .item_wrapper_text {
                    .menu-item_dots {
                        opacity: 1;
                    }
                }
            }
        }
    }

    > .menu > .menu-item {
        &:not(:first-child):last-child {
            > .sub-menu {
                right: 0;
                &,
                .sub-menu {
                    left: auto;
                }
                .sub-menu {
                    right: 100%;
                }
                &.wgl-mega-menu-position-center{
                    left: -50vw;
                    right: -50vw;
                    margin-left: auto;
                    margin-right: auto;
                }
                &.wgl-mega-menu-position-left-side{
                    left: 0;
                    right: auto;
                    margin-left: -16px;
                    margin-right: auto;
                }
            }
        }
        > .sub-menu {
            &.wgl-submenu-position-left,&.wgl-mega-menu-position-left{
                left: auto !important;
                right: -16px !important;
            }
            &.wgl-submenu-position-right,&.wgl-mega-menu-position-right{
                right: auto !important;
                left: -16px !important;
            }
            &.wgl-mega-menu.wgl-mega-menu-position-center{
                left: -50vw;
                right: -50vw;
                margin-left: auto;
                margin-right: auto;
                max-width: 98vw;
            }
            &.wgl-mega-menu.wgl-mega-menu-position-left-side{
                left: 0;
                right: auto;
                margin-left: 0;
                margin-right: auto;
            }
        }
    }

    ul.sub-menu {
        &.wgl-submenu-position-left{
            left: auto !important;
            right: 100% !important;
        }
        &.wgl-submenu-position-right{
            right: auto !important;
            left: 100% !important;
        }
    }
    ul li.mega-menu-e ul.sub-menu{
        display: none;
    }
    .submenu-label{
        background: linear-gradient(90deg, #f44e6b, #dc1a72);
        color: #ffffff;
        border-radius: 4px;
        font-family: var(--burido-content-font-family);
        font-size: 14px;
        line-height: 18px;
        margin-left: 5px;
        min-width: 44px;
        display: inline-block;
        text-align: center;
        padding: 1px 6px 1px;
    }
}

.admin-bar {
    .wgl-sticky-header {
        top: 32px;
        @media (max-width: 782px) {
            top: 46px;
        }
    }
    .wgl-theme-header .woo_mini_cart {
        max-height: calc(100% - 32px - 30px);
    }
}

//* ↓ Vertical Menu
.elementor-widget-wgl-menu{
	&.menu_vertical{
		.primary-nav{
            & > ul{
                position: relative;
                left: 0;
                width: 100%;
                height: auto;
                box-sizing: border-box;
                margin: 0;
                padding: 0;
                text-align: left;
                display: block !important;
                background: transparent;
                border: unset;
                & > li {
                    margin-bottom: 10px;
                }
            }
			ul li{
				display: block;
				float: none;
				height: auto;
				padding: 0;
                margin: 0;
                > a {
                    transition: all 0s, background-color 0.3s ease-in-out, text-decoration 0.3s ease-in-out, -webkit-text-decoration 0.3s ease-in-out;
                    .item_wrapper_text,
                    > i {
                        position: initial;
                        transition: 0.5s ease-in-out;
                    }
                    .menu-item_dots {
                        background: transparent;
                        border-radius: 10px;
                    }
                }
                &:hover {
                    > a {
                        &,
                        > .menu-item__plus {
                            color: var(--burido-header-font-color);
                        }
                    }
                }
                a {
                    display: block;
					margin: 0;
					position: relative;
                    overflow: visible;
                    line-height: 1;
                    padding: 5px 0;
				}
				&.mega-menu-links > ul > li{
					width: 100%;
				}
                .mega-menu-container{
                    display: none !important;
                }
			}
			ul li ul{
				position: relative;
				top: 0 !important;
				left: 0;
				right: 0 !important;
				width: 100%;
				box-sizing: border-box;
				padding: 0 0 0 15px;
				opacity: 1;
				visibility: visible;
				transition: 0s;
				white-space: initial;
				overflow: hidden;
				transform: none !important;
				min-width: initial;
				background-color: inherit;
                .elementor-invisible &{
                    visibility: hidden;
                }
			}
			ul li ul.sub-menu,
			ul li.mega-menu-links > ul.mega-menu > li > ul > li ul,
			ul li.mega-menu-links > ul.mega-menu > li > ul{
				box-shadow: none;
				border: none;
				width: 100%;
				transition: 0s;
				display: none;
                color: var(--burido-header-font-color);
				&::after{
					display: none;
				}
			}
            ul li.mega-menu-links > ul.mega-menu .item_text > img{
                display: none;
            }

            ul li {
                & > a > span{
                    position: relative;
                    display: inline-block;
                }
            }
		}
	}
}

//* ↓ Mega Menu
.primary-nav ul li.mega-menu-links {
    > ul {
        padding: 0;
        box-sizing: border-box;
        width: 1170px;
        display: flex;
        flex-wrap: wrap;
        > li {
            float: left;
            box-sizing: border-box;
            margin-top: 34px;
            margin-bottom: 30px;
            margin-left: 0;
            margin-right: 0;
            padding: 0;
            font-size: 16px !important;
            font-weight: 600 !important;
            text-transform: capitalize;
            &::after {
                content: unset;
                display: none;
                position: absolute;
                top: 30px;
                right: 0;
                width: 1px;
                height: calc(100% - 60px);
                background: unset;
            }
            &:hover ~ li {
                z-index: 0;
            }
            &.hide-mega-headings {
                > a {
                    display: none;
                }
            }
            &:hover {
                > a .item_wrapper_text {
                    background: none !important;
                }
            }
            > a {
                position: relative;
                padding: 4px 15px 0;
                .item_wrapper_text {
                    padding-left: 0 !important;
                    pointer-events: none;
                }
                .item_wrapper_text::before,
                &::after {
                    display: none;
                }
            }
        }
    }
    &.mega-columns-1col > ul > li {
        width: 100%;
        &::after {
            display: none;
        }
    }
    &.mega-columns-2col > ul > li {
        width: 50%;
        &:nth-child(2n)::after {
            display: none;
        }
    }
    &.mega-columns-3col > ul > li {
        width: 33.333333%;
        &:nth-child(3n)::after {
            display: none;
        }
    }
    &.mega-columns-4col > ul > li {
        width: 25%;
        &:nth-child(4n)::after {
            display: none;
        }
    }
    &.mega-columns-5col > ul > li {
        width: 20%;
        &:nth-child(5n)::after {
            display: none;
        }
    }
    > ul.mega-menu {
        > li > ul {
            position: relative;
            left: 0 !important;
            right: auto !important;
            padding-top: 6px;
            padding-bottom: 25px;
            top: 0;
            opacity: 0;
            min-width: auto;
            visibility: hidden;
            margin-top: 0;
            background: transparent;
            border: 0;
            box-shadow: none;
            > li {
                padding-left: 0;
                padding-right: 0;
                text-transform: none;
                ul {
                    left: 100% !important;
                    right: auto !important;
                }
            }
        }
        .item_text{
            display: flex;
            flex-direction: column;
            text-align: center;
            > img {
                box-shadow: 0px 5px 15px 0px rgba(0, 0, 0, 0.08);
                border-radius: 0;
                margin-bottom: 10px;
                transition: 0.4s;
            }
        }
        > .menu-item {
            > a{
                font-size: 18px;
                &:hover{
                    .item_text > img{
                        transform: translateY(-10px);
                    }
                }
            }
        }
    }
}
//* Foresee a divider, if there is no Page Title
body {
    &.home.blog {
        > header:not(.header_overlap) {
            + #main {
                border-top: 1px solid rgba(var(--burido-header-rgb), 0.1);
            }
        }
    }
}
//* ↓ Sticky Menu
.wgl-sticky-header {
    position: fixed;
    z-index: 99999;
    top: 0;
    left: 0;
    pointer-events: none;
    width: 100%;
    transform: translateY(-100%);
    opacity: 0;
    transition: 0.3s;
    &.sticky_active {
        pointer-events: auto;
        transform: translateY(0);
        opacity: 1;
    }
    &.header_sticky_shadow {
        box-shadow: 1px 0 10px rgba(0, 0, 0, 0.1);
    }
}

//* ↓ Mobile Menu
.wgl-mobile-header {
    .wgl-header-row {
        display: flex;
        align-items: center;
    }
    .wgl-logotype-container a,
    .wgl-logotype-container a:hover,
    .wgl-logotype-container h1 {
        color: var(--burido-tertiary-color);
    }
    .wgl-header-row_wrapper {
        height: var(--burido-header-mobile-height);
    }
    .header_search {
        .wgl-search .header_search-close {
            transform: scale(0);
        }
        &.header_search-open {
            .wgl-search .header_search-close {
                transform: scale(1);
            }
        }
    }
    .primary-nav ul li.mega-menu > .sub-menu,
    .primary-nav ul li.mega-menu-links > ul.mega-menu{
        .item_text > img{
            display: none;
        }
        > .menu-item > a{
            font-size: inherit;
            font-weight: inherit;
        }
    }
}

//* ↓ Elementor Widget
main,
header {
    .elementor-widget-wrap {
        align-items: center;
    }
    nav {
        &.submenu-disable {
            .menu-item__plus,
            .sub-menu,
            .wgl-mega-menu {
                display: none;
            }
        }
    }
}

//* Header is always visible during its editing
body.single-header.elementor-editor-active {
    .wgl-site-header {
        &,
        .primary-nav {
            display: block;
        }
    }
}

.menu-item.dnone > {
    a > .menu-item__plus,
    a > .button_switcher,
    .wgl-mega-menu,
    ul {
        display: none !important;
    }
}

// Wgl header favorite
@mixin icon {
	content: "\e90d";
	font-family: 'woosw';
	font-style: normal;
	font-weight: normal;
	font-variant: normal;
	text-transform: none;
	position: relative;
	color: var(--burido-header-font-color);
	display: inline-flex;
	align-items: center;
	justify-content: center;
	line-height: 1em;
	letter-spacing: unset;
	background-color: var(--burido-secondary-color);
	border-radius: 100px;
	font-size: 24px;
	width: 50px;
	height: 50px;
}
@mixin count {
	display: inline-block;
    border-radius: 0;
	font-family: var(--burido-content-font-family);
    font-weight: var(--burido-header-font-weight);
    font-size: 12px;
	line-height: 18px;
	min-width: 18px;
	text-align: center;
	padding: 0 3px;
	z-index: 2;
	position: absolute;
    top: 0;
	right: 0;
    bottom: 0;
    left: 0;
    color: var(--burido-tertiary-color);
    background-color: var(--burido-primary-color);
    width: -moz-fit-content;
    width: fit-content;
    height: -moz-fit-content;
    height: fit-content;
	margin: auto;
    transform: translate(8px, 10px);
}
.elementor-widget-wgl-header-favorite .wgl-favorite_wrapper {
	line-height: 30px;
	height: 100%;
	letter-spacing: 0;
	color: var(--burido-header-font-color);
	cursor: pointer;
	position: relative;
	z-index: 1;
	.wgl-favorite {
		font-size: 0;
		list-style: none;
		.favorite-count {
			display: flex;
			align-items: center;
			flex-direction: row-reverse;
			&::before{ @include icon; }
			span{ @include count; }
			&[data-count="0"],
			&[data-count=""] {
				&::after{
					display: none;
				}
			}
		}
	}
}

