/* ==================== #Mobile Navigation ==================== */

.wgl-mobile-header {
    background-color: var(--mobile-header-bg-color, #ffffff);
    color: var(--mobile-header-color, #000000);
    border-bottom: 1px solid var(--mobile-header-border-color, rgba(131,131,131,0.2));
}
.mobile-hamburger-toggle{
    line-height: 0;
}
.hamburger-box {
    display: none;
    cursor: pointer;
    .mobile-hamburger-module &{
        display: inline-flex;
    }
    .hamburger-inner {
        width: 20px;
        line-height: 0;
        span {
            display: inline-block;
            position: relative;
            width: 20px;
            height: 2px;
            vertical-align: top;
            background: currentColor;
            + span {
                margin-top: 5px;
            }
        }
    }
}
.header_area_container {
    .hamburger-box {
        padding: 20px !important;
        margin: -20px;
    }
}

body.mobile_switch {
    &_on {
        .hamburger-inner {
            span:nth-child(1) { animation: ease .7s .4s burger_top-1-45 forwards }
            span:nth-child(2) { animation: ease .7s .4s burger_scaled-1 forwards }
            span:nth-child(3) { animation: ease .7s .4s burger_bottom-1-135 forwards }
        }
    }
    &_off {
        .hamburger-inner {
            span:nth-child(1) { animation: ease .7s .4s burger_top-2-45 backwards }
            span:nth-child(2) { animation: ease .7s .4s burger_scaled-2 backwards }
            span:nth-child(3) { animation: ease .7s .4s burger_bottom-2-135 backwards }
        }
    }
}

body.mobile_switch_on .mobile_nav_wrapper {
    .wgl-menu_overlay {
        opacity: 1;
        visibility: visible;
    }
}

.mobile_nav_wrapper {
    position: relative;
    z-index: 2;
    .wgl-menu_overlay {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.3);
        visibility: hidden;
        opacity: 0;
        transition: 0.45s ease-in-out;
        z-index: 2;
    }
}

.mobile_nav_wrapper {
    .primary-nav {
        width: calc(100% + 13px);

        ul li ul li > a .item_wrapper_text::before,
        ul li ul li.menu-item-has-children::after,
        ul li ul li.menu-item-has-children > a::after,
        > ul > li.menu-item-has-children > a::after,
        ul li ul li > a::before,
        > ul > li > a::after,
        > ul > li.menu-item-has-children > a::after,
        > ul > li.mega-menu.mega-cat > a::after{
            display: none;
        }
        > ul > li {
            margin-bottom: 10px;
        }
        > ul > li,
        ul > li {
            &[class*='current'] {
                > a {
                    .menu-item_dots {
                        display: none;
                    }
                }
            }
        }
        > ul > li > a {
            .item_wrapper_text {
                padding-right: 0 !important;
                margin-left: 0 !important;
                padding: 0;
            }
        }
        > ul li {
            position: static;
        }
        > ul.mobile_switch_on li {
            &[class*='current'] {
                > a {
                    color: var(--burido-submenu-mobile-color-active, var(--burido-tertiary-color));
                    .button_switcher {
                        &::before {
                            opacity: 1;
                        }
                    }
                }
            }
        }
        ul li {
            a {
                position: relative;
                text-transform: capitalize;
            }
            ul li.current-menu-ancestor.current-menu-parent > a .item_wrapper_text,
            ul li.current-menu-item > a .item_wrapper_text,
            ul li.current_page_item > a .item_wrapper_text,
            ul li:hover > a .item_wrapper_text {
                color: inherit;
            }
        }
        > ul > li.menu-item-has-children > a .item_text::before{
            display: none;
        }
    }
}

.mobile_nav_wrapper .primary-nav ul li ul.sub-menu,
.mobile_nav_wrapper .primary-nav ul li div.wgl-e-container {
    position: relative;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    width: 100%;
    box-sizing: border-box;
    padding: 0 0 0 15px;
    margin: 0;
    min-width: auto;
    font-weight: inherit;
    font-size: inherit;
    color: inherit;
    opacity: 1;
    visibility: visible;
    transition: 0s;
    white-space: initial;
    overflow: hidden;
    transform: none !important;
    .elementor-container{
        width: 100%;
    }
    &.mega-menu-container{
        padding: 0;
        width: 100% !important;
    }
}

body.admin-bar {
    .wgl-menu_outer {
        top: 32px;
        height: calc(100vh - 32px);
        &.menu-animation_fade_down{
            height: 0;
        }
        @media (max-width: 782px) {
            top: 46px;
            height: calc(100vh - 46px);
            &.menu-animation_fade_down{
                height: 0;
            }
        }
    }
}

.wgl-menu_outer {
    position: fixed;
    z-index: 999;
    background-color: #113039;
    overflow: hidden;
    width: 400px;
    height: 100%;
    top: 0;
    transform: translateX(-100%);
    transition: transform 0.45s ease-in-out;
    user-select: none;
    &.menu-position_right {
        right: 0;
        transform: translateX(100%);
        .wgl-menu-outer_header {
            right: auto;
            left: -35px;
        }
    }
    &.menu-animation_fade_down{
        transform: translateX(0%);
        height: 0;
        will-change: height;
        transition: height 0.45s cubic-bezier(0.5, 1, 0.89, 1);
    }
    .mobile-hamburger-close {
        position: relative;
        z-index: 999;
        border-radius: 5px;
        line-height: 0;
        background: var(--burido-primary-color);
        color: var(--burido-header-font-color);
    }
    .wgl-menu-outer_header {
        position: absolute;
        top: 10px;
        right: -45px;
        .hamburger-box {
            padding: 12px 10px;
        }
    }
    .wgl-menu_content {
        position: relative;
        width: 100%;
        height: 100%;
    }
    .wgl-menu-outer_content {
        position: absolute;
        padding: 30px;
        width: 100%;
        bottom: 17px;
        top: 0;
        right: 0;
        left: 0;
        overflow-y: scroll;
        scrollbar-width: none;
        -webkit-overflow-scrolling: touch;
        &::-webkit-scrollbar {
            display: none;
        }
    }
}

//* Mobile Switcher
body.mobile_switch_on {
    position: fixed;
    overflow: hidden;
    width: 100%;
    height: 100%;
    .wgl-menu_outer {
        transform: translateX(0%);
        overflow: visible;
        &.menu-animation_fade_down{
            height: 100%;
        }
    }
    &.admin-bar {
        .wgl-menu_outer {
            &.menu-animation_fade_down{
                top: 32px;
                height: calc(100vh - 32px);
            }
            @media (max-width: 782px) {
                &.menu-animation_fade_down{
                    top: 46px;
                    height: calc(100vh - 46px);
                }
            }
        }
    }
}
.mobile_nav_wrapper .wgl-menu-outer_content > * {
    height: auto;
    margin-top: 20px;
    &:first-child {
        margin-top: 0;
    }
}
.mobile_nav_wrapper .primary-nav > ul.mobile_switch_on {
    position: relative;
    left: 0;
    width: 100%;
    height: auto;
    box-sizing: border-box;
    margin: 30px 0 0;
    padding: 0;
    text-align: left;
    display: block !important;
    > li > ul {
        margin-bottom: 0;
    }
}
.mobile_nav_wrapper .primary-nav ul.mobile_switch_on li {
    display: block;
    float: none;
    height: auto;
    padding: 0;
    margin: 0;
    div.mega-menu-container {
        display: none !important;
    }
    &::before {
        display: none;
    }
    //* Mobile Mega Menu Column
    &.mega-menu-links {
        > .mega-menu.sub-menu {
            min-height: inherit !important;
            padding-right: 0 !important;
            padding-left: 15px !important;
            max-width: none !important;
            background-image: none !important;
            li {
                width: 100%;
                margin-top: 0;
                font-weight: inherit !important;
                &.hide-mega-headings {
                    a {
                        display: block;
                    }
                }
                ul {
                    &.show_sub_menu {
                        visibility: visible;
                        opacity: 1;
                    }
                    li {
                        &::after {
                            display: none;
                        }
                    }
                }
                &::after {
                    display: none;
                }
            }
        }
    }
}
.mobile_nav_wrapper .primary-nav ul.mobile_switch_on li {
    a {
        padding: 5px 0;
        margin: 0;
        background: transparent;
        color: inherit;
        flex-direction: row !important;
        opacity: 1 !important;
        text-decoration: unset;
        overflow: visible;
        &::before{
            display: none;
        }
        .item_wrapper_text {
            display: inline;
            border: unset;
            &::before,
            &.menu-item_plus {
                display: none;
            }
        }
    }
}

.mobile_nav_wrapper .primary-nav ul li ul li {
    border-bottom: 0 !important;
    margin: 0;
    &:hover > a {
        background: transparent;
        color: inherit;
    }
    > a {
        &::after {
            display: none;
        }
        .item_wrapper_text {
            padding: 0;
            background: none !important;
        }
    }
}

.mobile_nav_wrapper .primary-nav ul li.mega-menu-links > ul > li > a::before {
    display: none;
}

.mobile_nav_wrapper .primary-nav ul li.mega-menu-links > ul > li:hover > a .item_wrapper_text {
    color: inherit;
}

.mobile_nav_wrapper .primary-nav ul li ul.sub-menu,
.mobile_nav_wrapper .primary-nav ul li div.sub-menu,
.mobile_nav_wrapper .primary-nav ul li.mega-menu-links > ul.mega-menu > li > ul > li ul,
.mobile_nav_wrapper .primary-nav ul li.mega-menu-links > ul.mega-menu > li > ul {
    box-shadow: none;
    margin-top: 0;
    font-weight: inherit;
    border: none;
    width: 100%;
    transition: 0s;
    background-color: rgba(34, 35, 40, 1);
    display: none;
    &::after {
        display: none;
    }
}

.mobile_nav_wrapper .primary-nav ul li.mega-menu-links > ul.mega-menu > li > ul {
    padding-top: 0;
    padding-bottom: 0;
}

.mobile_nav_wrapper .primary-nav ul li ul.sub-menu li {
    &:hover,
    &:focus {
        padding-left: 0;
    }
}

//* Button Switcher
.mobile_nav_wrapper .primary-nav .menu-item{
    .button_switcher {
        width: 100%;
        height: 100%;
        z-index: 1;
        cursor: pointer;
        position: absolute;
        top: 50%;
        transform: translateY(-50%);
        right: 0;
        margin-right: 0;
        background: transparent;
        &::before {
            display: inline-block;
            vertical-align: middle;
            content: "";
            mask-image: var(--burido-arrow-down-right-h);
            mask-position: center center;
            mask-size: 1em;
            mask-repeat: no-repeat;
            width: 1em;
            height: 1em;
            padding: 0;
            box-shadow: none;
            background-color: currentColor;
            font-style: normal;
            font-variant: normal;
            text-transform: none;
            line-height: 0;
            font-size: 18px;
            transition: transform .4s;
            margin-left: 0 !important;
            position: absolute;
            top: 0;
            bottom: 0;
            right: 10px;
            left: unset;
            margin: auto;
        }
        &::after {
            content: '';
            display: block;
            position: absolute;
            top: 15%;
            left: 15%;
            width: 70%;
            height: 70%;
            opacity: 0.05;
            background-color: transparent;
            transition: 0.2s;
        }
        &:hover,
        &:focus {
            &::after {
                opacity: 0.02;
            }
        }
        &.is-active {
            &::before {
                transform: rotate(45deg);
            }
        }
    }
}
.menu_vertical.elementor-widget-wgl-menu {
	&.menu_expand{
		.primary-nav{
            .button_switcher_vertical {
                width: 100%;
                height: 100%;
                z-index: 1;
                cursor: pointer;
                position: absolute;
                top: calc(50% - 5px);
                transform: translateY(-50%);
                right: 0;
                margin-right: 0;
                background: transparent;
                &::before{
                    background: none !important;
                    position: absolute;
                    top: 0;
                    right: 0;
                    left: 0;
                    bottom: 0;
                    margin: auto;
                    content: "\f106";
                    font-family: "Font Awesome 5 Free";
                    font-weight: 600;
                    display: inline-block;
                    vertical-align: middle;
                    transform: rotate(90deg);
                    z-index: 1;
                    font-size: 13px;
                    width: 1em;
                    height: 1em;
                    line-height: 1em;
                    font-style: normal;
                    font-weight: normal;
                    color: rgba(var(--burido-tertiary-rgb), 0.2);
                    transform-origin: center;
                    perspective-origin: center;
                    transition: 0.4s;
                }
                &::after {
                    content: '';
                    display: block;
                    position: absolute;
                    top: 15%;
                    left: 15%;
                    width: 70%;
                    height: 70%;
                    opacity: 0.05;
                    background-color: transparent;
                    transition: 0.2s;
                }
                &:hover,
                &:focus {
                    &::after {
                        opacity: 0.02;
                    }
                }
                &.is-active::before{
                    transform: rotate(180deg);
                    color: var(--burido-primary-color);
                }
            }

            li:hover > a .button_switcher_vertical::before{
                color: var(--burido-primary-color);
            }
		}
	}
	.primary-nav{
		.button_switcher_vertical{
			width: 50px;
			height: 50px;
			z-index: 1;
			cursor: pointer;
			position: absolute;
			top: 50%;
			transform: translateY(-50%);
			right: 0;
			margin-right: 0;
			&::before {
                display: inline-block;
                vertical-align: middle;
                content: "";
                mask-image: var(--burido-arrow-down-right-h);
                mask-position: center center;
                mask-size: 1em;
                mask-repeat: no-repeat;
                width: 1em;
                height: 1em;
                padding: 0;
                box-shadow: none;
                background-color: currentColor;
                font-style: normal;
                font-variant: normal;
                text-transform: none;
                line-height: 1em;
                font-size: 18px;
                transition: .4s;
                position: absolute;
                top: 0;
                right: 0;
                left: 0;
                bottom: 0;
                margin: auto;
			}
			&.is-active::before{
                transform: rotate(45deg);
			}
		}
        li:hover > a .button_switcher_vertical::before{
            color: var(--burido-header-font-color);
        }
	}
}

.mobile_nav_wrapper .search_mobile_menu {
    .header_search-field {
        background: unset;
        color: inherit;
    }
}

.wgl-mobile-header .mini-cart {
    position: static;
}

.wgl-mobile-header .socials-wrapper {
    display: flex;
    .wgl-social{
        i{
            width: 1em;
            height: 1em;
            position: relative;
            display: block;
        }
    }
}

.wgl-mobile-header .wgl-header-row .header_side[class^='position_right'] .header_area_container {
    > * {
        margin-left: 15px;
        &:first-child {
            margin-left: 0;
        }
    }
}
.wgl-mobile-header .wgl-header-row .header_side[class^='position_left'] .header_area_container {
    > * {
        margin-right: 15px;
        &:last-child {
            margin-right: 0;
        }
    }
}
.wgl-mobile-header .wgl-header-row .header_side[class^='position_center'] .header_area_container {
    > * {
        margin-left: 15px;
        margin-right: 15px;
        &:last-child,
        &:first-child {
            margin-right: 0;
            margin-left: 0;
        }
    }
}

@media (max-width: 1200px) {
    .wgl-theme-header .wgl-sticky-header {
        display: none;
    }
}
@media (max-width: 782px) {
    body.admin-bar {
        .wgl-menu_outer {
            top: 46px;
            height: calc(100vh - 46px);
        }
    }
}
@media (max-width: 450px) {
    .wgl-menu_outer {
        width: calc(100% - 50px);
    }
}
@media (max-width: 360px) {
    .wgl-mobile-header .woo_mini_cart {
        width: calc(100vw - 40px);
    }
}


//* ↓ Keyframes ↓
$burger_offset: 7px;
@keyframes burger_top-1-45 {
    0% { top: 0; transform: rotate(0) }
   50% { top: $burger_offset; transform: rotate(0) }
  100% { top: $burger_offset; transform: rotate(45deg) }
}
@keyframes burger_top-2-45 {
    0% { top: $burger_offset; transform: rotate(45deg) }
   50% { top: $burger_offset; transform: rotate(0) }
  100% { top: 0; transform: rotate(0) }
}
@keyframes burger_bottom-1-135 {
    0% { bottom: 0; transform: rotate(0) }
   50% { bottom: $burger_offset; transform: rotate(0) }
  100% { bottom: $burger_offset; transform: rotate(135deg) }
}
@keyframes burger_bottom-2-135 {
    0% { bottom: $burger_offset; transform: rotate(135deg) }
   50% { bottom: $burger_offset; transform: rotate(0) }
  100% { bottom: 0; transform: rotate(0) }
}
@keyframes burger_scaled-1 {
   50% { transform: scale(0) }
  100% { transform: scale(0) }
}
@keyframes burger_scaled-2 {
      0% { transform: scale(0) }
     50% { transform: scale(0) }
    100% { transform: scale(1) }
}
//* ↑ keyframes ↑
