/* ==================== ##Browser Reset ==================== */

* {
    box-sizing: border-box;
    &:focus {
        outline: none !important;
    }
}

html,
body,
div,
span,
applet,
object,
iframe,
table,
caption,
tbody,
tfoot,
thead,
tr,
th,
td,
del,
dfn,
em,
font,
img,
ins,
kbd,
q,
s,
samp,
small,
strike,
strong,
sub,
sup,
tt,
var,
h1,
h2,
h3,
h4,
h5,
h6,
p,
blockquote,
pre,
a,
abbr,
acronym,
address,
big,
cite,
code,
dl,
dt,
dd,
ol,
ul,
li,
fieldset,
form,
label,
legend {
    margin: 0;
    border: 0;
    outline: 0;
    padding: 0;
    font-size: 100%;
    font-family: inherit;
    font-weight: inherit;
    font-style: inherit;
    vertical-align: baseline;
}
body {
    position: relative;
    overflow-x: hidden;
}
body,
html {
    max-width: 100%;
    -moz-osx-font-smoothing: grayscale;
    -webkit-font-smoothing: antialiased;
}
mark {
    padding: 0 5px;
    color: var(--burido-header-font-color);
}
strong {
    font-weight: 700;
}
pre {
    max-width: 100%;
    margin-top: 18px;
    margin-bottom: 20px;
    padding: 20px;
    word-wrap: break-word;
    border: 1px solid #e4e4e4;
    border-radius: 0;
    overflow: auto;
}
code,
kbd,
tt,
var,
pre {
    font-family: monospace;
}
ul,
ol {
    padding: 0 0 20px 0;
}
li ul {
    padding-bottom: 0;
}
textarea {
    min-height: 50px;
    height: 122px;
}
img {
    vertical-align: top;
    max-width: 100%;
    height: auto;
    user-select: none;
}
label,
legend {
    display: block;
    margin-bottom: 5px;
}
label{
    font-family: var(--burido-header-font-family);
    font-size: 16px;
    margin-left: 0;
}
legend{
    font-weight: 500;
    font-family: var(--burido-h4-font-family);
    font-size: var(--burido-h4-font-size);
}
iframe {
    width: 100%;
    display: block;
}
table {
    width: 100%;
    border-collapse: collapse;
}

dl {
    margin-bottom: 1.75em;
}
dt {
    font-weight: 700;
}
dd {
    margin: 0 0 1.75em;
}

p {
    margin: 0 0 16px 0;
    &:empty {
        display: none;
        padding: 0;
        margin: 0;
    }
}
a {
    transition: all 0.4s;
    &,
    &:active,
    &:focus,
    &:hover {
        text-decoration: none;
    }
}
p a {
    transition: color 0.3s;
}
