/* ==================== ##Progress Bar ==================== */

.wgl-progress-bar {
    display: block;
    border-radius: unset;
    transition: 1.5s; //* affects js logic
    .progress__content,
    .progress__value {
        display: flex;
        justify-content: space-between;
        align-items: center;
        position: relative;
        font-family: var(--burido-header-font-family);
        font-weight: var(--burido-header-font-weight);
        font-size: 14px;
        line-height: 1;
        letter-spacing: 0.05em;
        text-transform: uppercase;
        z-index: 2;
        transition: inherit;
    }
    .progress__value{
        justify-content: flex-end;
        letter-spacing: 0;
    }
    .content__value {
        position: relative;
        margin-left: 8px;
        display: flex;
    }
    .progress__bar {
        position: relative;
        z-index: 0;
        width: auto;
        box-sizing: content-box;
        transition: inherit;
    }
    .bar__empty {
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
    }
    .bar__filled {
        position: relative;
        z-index: 1;
        top: 50%;
        width: 0;
        height: inherit;
        border-radius: inherit;
        transform: translateY(-50%);
        transition: inherit;
        max-width: 100%;
    }
    &.layout {
        &-dynamic {
            .progress__content {
                width: 0;
                white-space: nowrap;
            }
        }
        &-dynamic_middle {
            .progress__value{
                height: 0;
                position: absolute;
                left: 100%;
                top: 0;
                bottom: 0;
                margin: auto 0;
            }
            .content__value{
                justify-content: flex-end;
                margin: 0;
                min-width: 0;
                transition: 1.2s;
            }
            .bar__empty{
                background: unset !important;
            }
        }
        &-aside {
            display: flex;
            align-items: flex-end;
            margin-top: 7px;
            font-size: 15px;
            line-height: 1;
            font-weight: 700;
            .progress__bar {
                margin-top: 0;
            }
            .aside__wrapper {
                flex-grow: 1;
                transition: inherit;
            }
            .content__value {
                position: relative;
                margin-left: 15px;
                &,
                .value__wrapper {
                    text-align: right;
                }
                .value__wrapper {
                    position: absolute;
                    z-index: 1;
                    top: 0;
                    right: 0;
                    bottom: 0;
                    left: 0;
                    display: flex;
                }
                .placeholder {
                    &__digit,
                    &__unit {
                        visibility: hidden;
                    }
                }
            }
        }
    }
}
