/* ==================== ##Demo Item ==================== */

.wgl-demo-item {
    text-align: center;
    .demo-item {
        transition: 0.4s;
        display: block;
        &_title {
            display: flex;
            font-family: var(--burido-header-font-family);
            font-weight: var(--burido-header-font-weight);
            font-size: 20px;
            line-height: 1.5em;
            color: var(--burido-header-font-color);
            transition: 0.4s;
            position: relative;
            z-index: 1;
            .icon-wrapper{
                margin: -1em 0;
                font-size: 0;
                line-height: 0;
            }
            svg {
                fill: currentColor;
            }
            .wgl-icon{
                font-size: 31px;
            }
        }
        &_image-wrap {
            position: relative;
            z-index: 1;
        }
    }
    &:hover {
        .demo-item {
            &_title {
                color: var(--burido-header-font-color);
            }
        }
    }
    &.lift_on_hover:hover {
        .demo-item {
            transform: translateY(-15px);
        }
    }
}
