/* ==================== ##Views ==================== */

.wgl-views {
    display: inline-block;
    .post_views_inner{
        color: inherit;
        transition: 0.45s;
        font-family: var(--burido-header-font-family);
    }
    .sl-icon{
        display: inline-block;
        position: relative;
        z-index: 1;
        text-align: center;
        font-size: 16px;
        font-weight: normal;
        line-height: 0;
        transform: translateY(2px);
        &:before {
            line-height: 0;
        }
    }
    .post_featured_bg & {
        .post_views_inner {
            display: flex !important;
            font-size: 14px;
            font-weight: 500;
            letter-spacing: 0;
            text-decoration: unset;
            justify-content: center;
            align-items: center;

        }
        .sl-icon {
            transform: translateY(0);
            font-size: 18px;
            &:before {
                line-height: initial;
            }
        }
        .sl-count {
            line-height: 19px;
            margin-left: 7px;
            &-text {
                font-size: 12px;
                font-weight: 700;
            }
        }
    }
    .sl-count {
        display: inline-block;
        margin-left: 8px;
        transition: inherit;
    }
    .sl-count-text {
        display: none !important;
    }
}
