/* ==================== ##Time Line Horizontal ==================== */

.wgl-timeline-horizontal {
    .time_line_h-date_wrap{
        justify-content: flex-start;
        align-items: flex-end;
        --wgl-size: 11px;
        --wgl-size-active: var(--wgl-size);
        --wgl-gap: 10px;
        .swiper-slide {
            display: flex;
            align-items: center;
            pointer-events: none;
            font-size: 0;
            margin: 0;
            position: relative;

            &::before,
            &::after{
                content: '';
                width: calc( 50% - var(--wgl-gap) - (var(--wgl-size) / 2) );
                height: 1px;
                display: block;
                background-color: rgba(var(--burido-secondary-rgb), 0.2);
                position: absolute;
                bottom: calc(var(--wgl-size-active) / 2 - 0.5px);
            }
            &::before{
                left: 0;
            }
            &::after{
                right: 0;
            }
            &:first-child{
                &::before{
                    left: auto;
                    right: calc( 50% + var(--wgl-gap) + (var(--wgl-size) / 2) );
                    width: 100vw;
                }
            }

            &:last-child {
                &::after{
                    left: calc( 50% + var(--wgl-gap) + (var(--wgl-size) / 2) );
                    right: auto;
                    width: 100vw;
                }
            }
            &:only-child {
                width: 100% !important;
                text-align: center;
                .wgl-time_line-date{
                    transform: unset !important;
                    margin: auto;
                }
            }
        }
        &::after, &::before{
            display: none;
        }
    }
    .time_line_h-date_inner{
        display: inline-block;
        cursor: pointer;
        pointer-events: auto;
        padding: 0;
        width: 100%;
        text-align: center;
    }
    .time_line_h-title{
        font-size: 36px;
        font-family: var(--burido-h3-font-family);
        font-weight: var(--burido-h3-font-weight);
        color: var(--burido-header-font-color);
        line-height: 1.25em;
        margin-bottom: 19px;
    }
    .wgl-time_line-date{
        font-family: var(--burido-additional-font-family);
        font-weight: 400;
        color: var(--burido-primary-color);
        display: block;
        font-size: 48px;
        line-height: 1.25;
        letter-spacing: -0.02em;
        transition: .4s;
        position: relative;
        padding: 14px 5px 0 5px;
        text-align: center;

        body:is( [data-elementor-device-mode='mobile_extra'], [data-elementor-device-mode='mobile']) & {
            font-size: 32px;
        }
    }
    .wgl-time_line-dot{
        display: inline-block;
        width: var(--wgl-size-active);
        height: var(--wgl-size-active);
        border-radius: var(--wgl-size-active);
        position: relative;
        z-index: 2;
        &::after {
            display: block;
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            margin: auto;
            width: var(--wgl-size);
            height: var(--wgl-size);
            border-radius: var(--wgl-size);
            border-color: var(--burido-secondary-color);
            transition: all .2s linear;
        }
    }

    .time_line_h-date_container{
        position: relative;
        z-index: 10;
    }
    .time_line_h-content_container{
        --content_gap: 30px;
        margin: 0 calc( var(--content_gap) * -1 );
    }
    .time_line_h-content_wrap{
        padding: 0 var(--content_gap);
    }
    .time_line_h-content{
        .time_line_h-title{
            transition: .4s;
        }
        .time_line_h-text{
            transition: .4s;
        }
    }
    .time_line_h-date{
        &.slide-active{
            --wgl-size: var(--wgl-size-active) !important;
        }
        &:hover,
        &.slide-active{
            .wgl-time_line-dot {
                &::after {
                    background-color: var(--burido-secondary-color);
                }
            }
        }
    }

    .elementor-swiper-button{
        --vertical-position: -7px;
        --horizontal-position: 0%;
        --center-horizontal-position: 0%;
        --wgl-swiper-button-diameter: 50px;
        display: block;
        position: absolute;
        z-index: 100;
        top: var(--vertical-position);
        margin: 0 var(--center-horizontal-position) 0 calc(-1 * var(--center-horizontal-position));
        width: var(--wgl-swiper-button-diameter);
        height: var(--wgl-swiper-button-diameter);
        padding: 0;
        font-size: 19px;
        font-weight: normal;
        line-height: 0;
        letter-spacing: unset;
        text-align: center;
        text-indent: unset;
        cursor: pointer;
        transition: all 0s, opacity 0.4s;
        color: var(--burido-secondary-color);
        border: 1px solid var(--burido-secondary-color);
        background-color: var(--burido-content-color);

        body:is( [data-elementor-device-mode='mobile_extra'], [data-elementor-device-mode='mobile']) & {
            --wgl-swiper-button-diameter: 30px;
            font-size: 15px;
        }
        i{
            display: inline-block;
        }
        &-prev{
            transform: translate3d(calc( -1 * var(--horizontal-position) ), 0, 0px);
            left: var(--horizontal-position);
            i{ transform: scale(-1) }
        }
        &-next{
            transform: translate3d(var(--horizontal-position), 0, 0px);
            right: var(--horizontal-position);
        }
        &.swiper-button-disabled{
            opacity: 1;
            i{
                opacity: 0.3;
                transition: .2s;
            }
        }
    }
    .swiper-pagination {
        --dots-vertical-position: 20px;
        --dots-horizontal-position: 50%;
        position: relative;
        z-index: 2;
        width: max-content;
        padding: 0;
        margin: var(--dots-vertical-position) 0 0 var(--dots-horizontal-position);
        transform: translateX(calc( -1 * var(--dots-horizontal-position )));
        min-height: 20px;
        line-height: 0;
        font-size: 0;
        bottom: 0;
        transition: none;
        .swiper-pagination-bullet {
            width: auto;
            height: auto;
            border-radius: 0;
            background: initial;
            opacity: 1;
            display: inline-block;
            vertical-align: middle;
            margin: 0 2px;
            padding: 5px;
            font-size: 0;
            line-height: 0;
            list-style: none;
            cursor: pointer;
            transition: 0.4s;
            &.swiper-pagination-bullet-active button {
                background-color: var(--burido-secondary-color);
            }
        }
        button {
            display: inline-block;
            position: relative;
            z-index: 1;
            font-size: 0;
            line-height: 0;
            padding: 0;
            margin: 0;
            border: 0;
            vertical-align: bottom;
            transition: inherit;
            background-color: #AFBCCC;
            width: 6px;
            height: 6px;
            border-radius: 50%;
        }
    }
    &.appear_anim{
        .time_line_h-date {
            &::before,
            &::after {
                opacity: 0;
                transition: all 0.4s 0.2s, width .4s, left .4s, right .4s;
            }
        }
        .wgl-time_line-dot{
            opacity: 0;
            transform: scale(0.4);
            transition: all 0.4s .4s;
        }
        .wgl-time_line-date{
            opacity: 0;
            transform: translateY(-10px);
            transition: all 0.4s .4s;
        }
        .time_line_h-content_wrap{
            opacity: 0;
            transition: all 0.4s .3s;
        }
        .elementor-swiper-button{
            opacity: 0;
            transition: all 0s, opacity 0.4s;
        }
        &.show{
            .time_line_h-date {
                &::before,
                &::after {
                    opacity: 1;
                }
            }
            .wgl-time_line-date{
                opacity: 1;
                transform: translateY(0);
            }
            .wgl-time_line-dot{
                opacity: 1;
                transform: scale(1);
            }
            .time_line_h-content_wrap,
            .elementor-swiper-button{
                opacity: 1;
            }
        }
    }
}
