/* ==================== #Recent Posts ==================== */
.wgl-posts {
    .title-wrapper {
        margin-bottom: 24px;
    }
}
.widget .recent-posts-widget {
    margin: 24px 0 0;
    padding: 0;
    list-style: none;
    li {
        padding: 0;
        line-height: inherit;
        margin-bottom: -2px;
        img {
            min-width: 70px;
            width: 70px;
            border-radius: 0;
            transition: 0.4s;
        }
        &:not(:first-child) {
            margin-top: 26px;
        }
        a{
            margin: 0;
            display: flex;
            &:hover {
                .post__title {
                    background-size: 100% 0.25em;
                }
                img {
                    border-radius: 15px;
                }
            }
        }
    }
    .recent-posts-image_wrapper {
        margin: 0 19px 0 0;
        img {
            border-radius: 0;
        }
    }
    .meta-data {
        font-size: 14px;
        font-weight: 500;
        line-height: 1;
        color: var(--burido-content-color);
        margin-top: 0;
        margin-bottom: 12px;
        span {
            line-height: inherit;
            font: inherit;
            letter-spacing: inherit;
        }
        .wgl-light-posts & {
            color: #DEDEDE;
        }
    }
    .recent-posts-content_wrapper {
        width: calc(100% - 20px);
        align-self: center;
        &:first-child{
            margin-top: -4px;
        }
    }
    .recent-post-content {
        margin-top: 3px;
        font-size: 0.9rem;
        line-height: 1.8;
    }
    .post__title {
        font-size: 16px;
        line-height: 24px;
        transition: 0.4s ease-in-out;
        margin-top: 10px;
        margin-bottom: -7px;
        font-weight: 600;
        color: inherit;
        background-repeat: no-repeat;
        background-size: 0% 0.25em;
        background-position: 0% 80%;
        transition: background-size 0.8s 0s;
        background-image: linear-gradient(to top, var(--burido-primary-color), var(--burido-primary-color));
        display: inline;
    }
    .post__link {
        color: var(--burido-header-font-color);
        .wgl-light-posts & {
            color: var(--burido-tertiary-color);
        }
    }
}
.widget_wgl_posts {
    .recent-posts-widget {
        margin-top: 0;
        margin-bottom: -7px;
    }
}
