/* ==================== ##Satellite Service ==================== */
.elementor-widget-wgl-satellite-service{
    &:hover{
        .wgl-services_title{
            color: var(--burido-header-font-color);
            a{
                color: var(--burido-header-font-color);
            }
        }
    }
}
.wgl-service-sat {
    .wgl-services {
        &_wrap {
            transition: 0.4s;
        }
        &_media-wrap {
            position: relative;
            z-index: 1;
            width: 110px;
            height: 110px;
            line-height: 110px;
            font-size: 45px;
            display: inline-block;
            border: 1px dashed CurrentColor;
            box-sizing: content-box;
            border-radius: 50%;
            text-align: center;
            transition: 0.4s;
            border-color: var(--burido-tertiary-color);
        }
        &_title {
            font-size: 24px;
            line-height: 1.4;
            transition: 0.4s;
            color: var(--burido-header-font-color);
        }
        &_circle-wrapper {
            position: absolute;
            z-index: -1;
            width: 78px;
            height: 78px;
            left: 16px;
            top: 16px;
            &:nth-child(1) {
                transform: rotate(0deg);
                animation: service_hexagon_1 2s infinite linear;
                animation-play-state: paused;
                .wgl-services_circle{
                    background-color: var(--burido-tertiary-color);
                }
            }
            &:nth-child(2) {
                transform: rotate(180deg);
                animation: service_hexagon_2 2s infinite linear;
                animation-play-state: paused;
                .wgl-services_circle{
                    background-color: var(--burido-tertiary-color);
                }
            }
        }
        &_circle {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: red;
            transform: translate3d(-50%, -50%, 0);
        }
        &_readmore {
            display: inline-block;
            color: var(--burido-primary-color);
            &:hover{
                color: var(--burido-tertiary-color);
            }
        }
        &_item-link {
            position: absolute;
            z-index: 2;
            width: 100%;
            height: 100%;
            left: 0;
            top: 0;
        }
    }
    .wgl-icon{
        color: var(--burido-tertiary-color);
        display: block;
        line-height: inherit;
        font-size: inherit;
        i {
            display: inline;
        }
    }
    .wgl-widget_wrapper.elementor-image-box-img {
        height: 100%;
        line-height: 1;
        display: flex;
        align-items: center;
        justify-content: center;
    }
    .wgl-image-box_img {
        & > span {
            display: flex;
        }
    }
    &:hover {
        .wgl-services {
            &_circle-wrapper {
                &:nth-child(1),
                &:nth-child(2) {
                    animation-play-state: running;
                }
            }
        }
    }
}
@keyframes service_hexagon_1 {
    0% {
        transform: rotate(90deg);
    }
    100% {
        transform: rotate(450deg);
    }
}
@keyframes service_hexagon_2 {
    0% {
        transform: rotate(-90deg);
    }
    100% {
        transform: rotate(270deg);
    }
}
