/* ==================== ##Footer Styles ==================== */

.footer_wrapper {
    padding: 24px 0;
}
.footer_top-area {
    p {
        margin-bottom: 0;
    }
    &.widgets_area {
        .row > div {
            padding-top: 50px;
            padding-bottom: 40px;
        }
    }
    input[type='text'],
    input[type='url'],
    input[type='search'],
    input[type='email'],
    input[type='password'],
    input[type='tel'],
    input[type='time'],
    select,
    textarea {
        color: #ffffff;
    }
    strong {
        font-weight: inherit;
    }
    select {
        background-image: var(--burido-bg-caret2-3);
    }
    .widget ul li a:hover {
        color: var(--burido-tertiary-color);
    }
    .textwidget img {
        margin-bottom: 20px;
    }
    .widget.widget_wgl_posts .recent-posts-widget {
        padding-top: 0;
    }
    .footer-link {
        position: relative;
        z-index: 1;
        &::before {
            content: '';
            position: absolute;
            z-index: 1;
            display: block;
            bottom: 0;
            border-bottom: 1px solid;
            width: 0;
            right: auto;
            left: 50%;
            transform: translateX(-50%);
            visibility: visible;
            transition: all 0.3s ease-in-out 0s, color 0s;
        }
        &:hover {
            color: #ffffff !important;
            &::before {
                width: 100%;
                color: #ffffff !important;
            }
        }
    }
    ul.wp-block-archives.wp-block-archives-list li a .post_count,
    ul.wp-block-categories.wp-block-categories-list li a .post_count,
    .widget ul li a .post_count {
        color: var(--burido-secondary-color);
    }
}
.footer {
    position: relative;
    overflow: hidden;
    .widgets_area {
        .row{
            border-top-width: 1px;
            border-top-style: solid;
            border-top-color: transparent;
        }
    }
    .blog-posts {
        .blog-post_title {
            margin-top: -5px;
        }
        .item:last-child {
            .blog-post {
                margin-bottom: 0;
            }
        }
    }
    .gallery-caption {
        display: none;
    }
    .widget_search .search-form .search-field:active,
    .widget_search .search-form .search-field:focus,
    .widget_product_search .woocommerce-product-search .search-field:active,
    .widget_product_search .woocommerce-product-search .search-field:focus,
    .wc-block-product-search__fields .search-field:active,
    .wc-block-product-search__fields .search-field:focus {
        border-color: #fff;
    }
    .wp-block-search .wp-block-search__button {
        background: var(--burido-tertiary-color);
        border-color: var(--burido-tertiary-color);
        color: var(--burido-secondary-color);
        &:hover {
            background: var(--burido-primary-color);
            border-color: var(--burido-primary-color);
            color: var(--burido-secondary-color);
        }
    }
}
.primary-nav.footer-menu .menu-item {
    display: inline-block;
    margin: 0 20px;
}
.copyright {
    font-size: 16px;
    p {
        margin: 0;
    }
}

//* ↓ Single Page Footer in case of deactivated Elementor
body.single.single-footer {
    header {
        &,
        + .page-header {
            display: none;
        }
    }
}
//* ↑ single page footer
