/* ==================== ##Text Editor ==================== */

.elementor-widget-wgl-text-editor {
    .text-editor_outer-clone {
        position: absolute;
        z-index: 1;
        top: 0;
        left: 0;
        transform: translate(var(--start-circle-point-left),var(--start-circle-point-top));
        width: var(--circle-width);
        height: var(--circle-width);
        border-radius: 50%;
        margin-top: calc(var(--circle-width) / 2 * -1);
        margin-left: calc(var(--circle-width) / 2 * -1);
        overflow: hidden;
        transition: all 0.1s ease-out 0s, opacity 0.4s;
        pointer-events: none;
        .text-editor_wrapper-clone {
            background-color: var(--burido-primary-color);
            position: absolute;
            z-index: 1;
            top: 0;
            left: 0;
            transform: translate(calc(var(--start-circle-point-left) * -1),calc(var(--start-circle-point-top) * -1));
            margin-top: calc(var(--circle-width) / 2);
            margin-left: calc(var(--circle-width) / 2);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            transition: all 0.1s ease-out 0s, opacity 0.4s;
        }
    }
    .text-editor_wrapper {
        font-size: 110px;
        line-height: 1.5em;
        font-family: var(--burido-h3-font-family);
        font-weight: var(--burido-h3-font-weight);
        letter-spacing: var(--burido-h3-letter-spacing);
        color: var(--burido-header-font-color);
        letter-spacing: -0.05em;
        span,
        a {
            display: inline-block;
            transition: 0.5s ease-in-out;
        }
        .text-editor__image {
            display: inline-flex !important;
            vertical-align: middle;
            align-items: center;
            pointer-events: none;
            img {
                width: 108px;
                min-width: 108px;
            }
        }
    }
    &.visibility-on_hover {
        .wgl-text-editor {
            &.mask_effect {
                .text-editor_outer-clone {
                    opacity: 0;
                }
                .text-editor_wrapper {
                    &:hover {
                        .text-editor_outer-clone {
                            opacity: 1;
                        }
                    }
                }
            }
        }
    }
    .wgl-text-editor {
        &.mask_effect {
            --circle-width: 212px;
            --start-circle-point-top: 0;
            --start-circle-point-left: 0;
            position: relative;
            z-index: 1;
            display: inline-block;
            .text-editor_wrapper {
                & + .text-editor_wrapper {
                    display: none;
                }
            }
        }
        &.loop_animation {
            display: flex;
            --wgl-loop-animation-gap: 0.4em;
            --wgl-loop-animation-duration: 120s;
            gap: var(--wgl-loop-animation-gap);
            .text-editor_wrapper  {
                display: flex;
                gap: inherit;
                animation: scroll var(--wgl-loop-animation-duration) linear infinite;
                white-space: nowrap;
                &:not(.text-editor_wrapper-clone) {
                    display: none;
                }
            }
            &.reverse {
                .text-editor_wrapper   {
                    animation-direction: reverse;
                }
            }
            &.hover_stop:hover {
                .text-editor_wrapper   {
                    animation-play-state: paused;
                }
            }
            @keyframes scroll {
                from {
                    transform: translateX(0);
                }
                to {
                    transform: translateX(-100%);
                }
            }
        }
        &.text_appear{
            --wgl-text-duration: 400ms;
            --wgl-text-delay: 400ms;
            .word{
                white-space: nowrap;
            }
            .target{
                opacity: 0;
                display: inline-block;
                animation-duration: var(--wgl-text-duration);
                animation-delay: var(--wgl-text-delay);
                animation-play-state: paused;
                animation-fill-mode: both;
            }
            &.appear{
                .target{
                    opacity: 1;
                    animation-play-state: running;
                }
            }
        }
    }
}