/* ==================== ##Header Search ==================== */

@use 'mixins';

.header_search {
    height: 100%;
    &-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        position: relative;
        font-size: 22px;
        transform-origin: center;
        cursor: pointer;
        transition: 0.3s;
        line-height: 0;
        padding: 15px;
        border-radius: 50%;
        background: var(--burido-primary-color);
    }
    &-close {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        position: absolute;
        right: 0;
        left: 0;
        margin: auto;
        line-height: 0;
        cursor: pointer;
        opacity: 0;
        transform-origin: center;
        transition: 0.3s;
        transform: scale(0);
        font-size: 24px;
        padding: 14px;
        min-width: fit-content;
        border-radius: 50%;
        background: var(--burido-primary-color);
    }
    .header_search-button-wrapper {
        display: flex;
        align-items: center;
        height: 100%;
        transition: 0.3s;
        justify-content: center;
        position: relative;
    }
    .search-field {
        &:active,
        &:focus{
            &::placeholder {
                opacity: 1 !important;
            }
        }
    }
    &.search_alt,
    &.search_standard,
    &.search_standard_fw,
    &.search_simple,
    &.search_mobile_menu {
        .header_search-field {
            .search-form {
                position: relative;
                z-index: 1;
                .search-button:hover .search__icon {
                    color: var(--burido-tertiary-color);
                }
            }
            @include mixins.search_button;
            @include mixins.search_icon;
        }
    }
    &.search_simple {
        .header_search-field {
            .search-form {
                position: relative;
                z-index: 1;
                .search-button:hover .search__icon {
                    color: var(--burido-secondary-color);
                }
            }
        }
    }
    &.search_mobile_menu {
        .header_search-field {
            .search-form {
                .search-button:hover .search__icon {
                    color: var(--burido-tertiary-color);
                }
            }
        }
    }
    &.search_alt {
        .header_search-field {
            opacity: 0;
            visibility: hidden;
            transform: scale3d(0.8, 0.8, 0.8);
            transition: 0.3s;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            position: fixed;
            z-index: 100001;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            max-height: 100vh;
            background: rgba(37, 37, 37, 0.85);
            .search-form {
                width: 80%;
                max-width: 1170px;
                .search__icon,
                .search-button {
                    right: 5px;
                    left: auto;
                    color: #fff;
                    &:hover .search__icon {
                        color: var(--burido-primary-color);
                    }
                }
            }
            .search-field {
                width: 100%;
                height: 50px;
                font-weight: 400;
                font-size: 18px;
                padding: 0 50px 0 0;
                color: #fff;
                border-color: rgba(255,255,255,0.85);
            }
            .header_search-wrap {
                display: flex;
                justify-content: space-between;
                align-items: center;
                width: 80%;
                max-width: 1170px;
                margin-bottom: 40px;
                .header_search-heading_description {
                    font-size: 40px;
                    line-height: 1.3;
                    font-weight: 700;
                    color: #ffffff;
                    letter-spacing: 0;
                    font-family: var(--burido-content-font-family);
                    @media (max-width: 480px) {
                        font-size: 30px;
                    }
                }
            }
            .header_search-close {
                position: relative;
                color: #ffffff;
                margin: 0;
                margin-right: 4px;
                padding: unset;
                background: unset;
                &::before{
                    transition: 0.4s;
                    display: block;
                }
                &:hover{
                    &::before{
                        transform: rotate(90deg);
                    }
                }
                @media (max-width: 480px) {
                    display: none;
                }
            }
        }
    }
    &.search_standard {
        position: relative;
        .header_search-field {
            position: absolute;
            z-index: 2;
            top: calc(100% + 20px);
            right: 0;
            padding: 33px 40px 40px;
            opacity: 0;
            visibility: hidden;
            transition: 0.5s ease-in-out;
            border-radius: 15px;
            .search-field {
                width: 270px;
                margin-bottom: 0;
                padding-left: 28px;
                color: inherit;
                border-color: currentColor;
            }
            .search__icon {
                color: var(--burido-primary-color);
            }
            .header_search-close {
                display: none;
            }
            @media (max-width: 499px) {
                padding: 20px;
                right: 0;
            }
        }
    }
    &.search_standard_fw {
        .header_search-field {
            display: flex;
            align-items: center;
            position: absolute;
            z-index: 3;
            top: 0;
            right: 0;
            width: 0;
            height: 100%;
            border-radius: 0;
            padding: 0;
            overflow: hidden;
            transform: scale3d(1, 1, 1);
            opacity: 0;
            visibility: hidden;
            transition: 0.4s;
            .search-form {
                width: 100%;
                max-width: 1170px;
                margin: 0 auto;
            }
            .search-field {
                width: inherit;
                max-width: inherit;
                margin: 0 auto;
                color: inherit;
                padding-left: 26px;
                height: 42px;
                border-color: var(--burido-tertiary-color);
            }
            .search__icon {
                color: var(--burido-primary-color);
            }
            .header_search-close {
                right: 25px;
                width: 50px;
                height: 50px;
                line-height: 52px;
                border-radius: 0;
                color: var(--burido-tertiary-color);
                text-align: center;
                z-index: 2;
                background: transparent;
                display: none;
                &::before {
                    z-index: 2;
                    position: relative;
                }
                &:hover {
                    color: var(--burido-primary-color);
                }
            }
        }
    }
    &.search_simple {
        position: relative;
        .header_search-field {
            background: transparent;
            .search-field {
                width: 270px;
                margin-bottom: 0;
                padding: 0 10px 0 26px;
                height: 42px;
            }
        }
    }
    &.header_search-open {
        &.search_standard,
        &.search_alt {
            .header_search-button {
                opacity: 0;
                transform: scale(0);
            }
            .header_search-close {
                opacity: 1;
                transform: scale(1);
            }
            .header_search-field {
                opacity: 1;
                visibility: visible;
                transform: scale3d(1, 1, 1);
            }
        }
        &.search_standard {
            .header_search-field {
                top: 100%;
            }
        }
        &.search_standard_fw{
            .header_search-button {
                opacity: 0;
                transform: scale(0);
            }
            .header_search-field {
                right: 0;
                width: 100%;
                height: 100%;
                opacity: 1;
                visibility: visible;
                transform: scale3d(1, 1, 1);
                .header_search-close {
                    opacity: 1;
                    transform: scale(1);
                }
            }
        }
    }
    &.search_mobile_menu {
        .header_search-field {
            .search-form .search-field {
                width: 100%;
                border-bottom: 1px solid rgba(255,255,255, 0.5);
                color: inherit;
                padding-left: 26px;
                &:-webkit-autofill,
                &:-webkit-autofill:hover,
                &:-webkit-autofill:focus {
                    -webkit-text-fill-color: var(--mobile-header-color);
                }
            }
            .search__icon {
                color: inherit;
            }
        }
    }
}
.wgl-mobile-header{
    .header_search {
        &-button,
        &-close {
            font-size: 18px;
            height: 40px;
            width: 40px;
            margin: -10px 0;
            background: unset;
        }
        &-close {
            font-size: 16px;
        }
        &.search_standard {
            position: static;
            .header_search-field{
                top: 100%;
                max-width: calc(100vw - 30px);
            }
        }
        &.search_standard_fw {
            .header_search-field {
                background-color: var(--mobile-header-bg-color, #000000);
                .search-field {
                    font-size: 14px;
                    color: var(--mobile-header-color, #ffffff);
                }
                .header_search-close {
                    right: 10px;
                    width: 40px;
                    height: 40px;
                    line-height: 46px;
                }
            }
        }
    }
}
.elementor-widget.elementor-widget-wgl-header-search {
    position: initial;
    .elementor-widget-container{
        height: 100%;
    }
}
// ↓ Vertical Alignment
.v_align {
    &_middle .header_search-button-wrapper {
        align-items: center;
    }
    &_bottom .header_search-button-wrapper {
        align-items: flex-end;
    }
}
.wgl-search {
    align-items: center;
}
// ↑ vertical alignment
@media screen and (max-width: 479px) {
    .header_search-field {
        right: 0;
    }
}
@media only screen and (max-width: 440px) {
    .header_search.search_alt {
        .header_search-wrap .header_search-heading_description {
            font-size: 30px;
        }
    }
}