/* ==================== ##Blog ==================== */

//* ↓ Blog Single
.blog-post-single-item{
    &.blog-post{
        &.format-quote,
        &.format-link{
            &::before{
                display: none !important;
            }
        }
    }
}

//* ↓ Blog Module
.blog-style-standard {
    &.hover-animation {
        .blog-post {
            padding-top: 25px;
            &:hover .blog-post_wrapper {
                transform: translateY(-25px);
            }
        }
    }
    .blog-post_wrapper {
        .blog-post_meta_info {
            position: absolute;
            z-index: 12;
            left: 0;
            bottom: -25px;
            width: 100%;
            padding-top: 0;
            padding-bottom: 0;
            transition: 0.45s;
            .meta-data {
                margin: 0;
                font-size: 14px;
                font-weight: 600;
            }
        }
        > .blog-post_meta_info {
            position: relative;
            bottom: unset;
            &:not(:empty) {
                margin-bottom: 3px;
            }
        }
    }
    .wgl_col {
        &-12 {
            .blog-post {
                margin-bottom: 86px;
            }
            &:not(.swiper-slide):last-child .blog-post {
                margin-bottom: 45px;
            }
            .format {
                &-video.blog-post {
                    .blog-post_media .blog-post_media_part {
                        padding-bottom: 56%;
                        &.video_image:not(.video_parallax) {
                            padding-bottom: 0;
                        }
                    }
                }
            }
        }
        &-6,
        &-4,
        &-3 {
            .blog-post{
                margin-bottom: 66px;
                .post_meta-wrap {
                    margin-top: 31px;
                }
                &.hide_media {
                    .blog-post_content {
                        padding: 30px;
                        padding-top: 22px;
                        .post_categories + .post_meta-wrap {
                            margin-top: 20px;
                        }
                    }
                    .post_categories {
                        left: 30px;
                        width: calc(100% - 60px);
                    }
                }
            }
            .blog-post_media {
                .post_categories {
                    top: -16px;
                    left: 30px;
                }
            }
            > :not(.format-no_featured) {
                .blog-post{
                    .blog-post_content {
                        padding-top: 21px;
                        padding-bottom: 20px;
                    }
                }
            }
            .blog-post_title {
                font-size: 24px;
                line-height: 1.5;
                margin-top: 15px;
                @media (max-width: 767px) {
                    font-size: 20px;
                }
                > a {
                    font: inherit;
                    line-height: inherit;
                }
            }
            .format {
                &-quote {
                    --quote-offset: 50px;
                    .blog-post_media {
                        margin-top: -10px;
                        margin-bottom: 38px;
                        padding-bottom: 24px;
                    }
                    .post_categories {
                        margin-bottom: 0;
                    }
                    .blog-post_quote-text {
                        margin-top: 0;
                        font-size: 20px;
                        &::before {
                            font-size: 60px;
                            top: 3px;
                        }
                    }
                }
                &-link {
                    .blog-post_media {
                        margin-top: -10px;
                        margin-bottom: 38px;
                        padding-bottom: 24px;
                    }
                    .post_categories {
                        margin-bottom: 0;
                    }
                    .blog-post_link {
                        .link_post {
                            padding-left: 44px;
                            font-size: 20px;
                        }
                        &::before {
                            font-size: 38px;
                            top: -6px;
                            left: -2px;
                        }
                    }
                }
                &-video {
                    .blog-post_media_part .videobox_link_wrapper {
                        margin: 30px;
                    }
                }
                &-gallery {
                    .blog-post_media .wgl-navigation_wrapper {
                        margin: 20px;
                        .elementor-swiper-button-next,
                        .elementor-swiper-button-prev {
                            font-size: 20px;
                            --wgl-swiper-button-diameter: 40px;
                        }
                    }
                }
                &-audio {
                    .blog-post_media {
                        margin-bottom: 30px;
                        margin-top: 0;
                    }
                }
            }
            .elementor-swiper-button-prev,
            .elementor-swiper-button-next {
                --wgl-swiper-button-diameter: 38px;
            }
        }

    }
    .blog-post {
        transition: 0.4s;
        border-radius: 0;
        .blog-post_wrapper {
            position: relative;
            z-index: 1;
        }
        .post_meta-wrap {
            margin-top: 32px;
        }
        &.hide_media {
            background: var(--burido-form-bg-color);
            .blog-post_media_part {
                overflow: visible;
                border-radius: unset;
            }
            .post_categories {
                position: relative;
                z-index: 1;
                left: 40px;
                top: -16px;
                width: calc(100% - 80px);
                @media (max-width: 767px) {
                    left: 30px;
                    width: calc(100% - 60px);
                }
            }
            .blog-post_content {
                padding: 33px 40px 53px;
                @media (max-width: 767px) {
                    padding: 30px;
                    padding-top: 20px;
                }
                .post_meta-wrap {
                    margin-top: -7px;
                }
                .post_categories + .post_meta-wrap {
                    margin-top: 22px;
                }
            }
        }
        blockquote cite {
            padding-left: 0;
            text-align: inherit;
        }
        &::after {
            content: '';
            display: block;
            height: 0;
            clear: both;
        }
    }
    &.blog_carousel {
        .wgl-carousel {
            padding-top: 18px;
        }
        .swiper-slide {
            margin-bottom: 0;
            &.swiper-slide {
                margin-bottom: 0;
            }
        }
        &.blog-style-standard {
            .wgl_col-6,
            .wgl_col-4,
            .wgl_col-3 {
                .blog-post {
                    margin-bottom: 0;
                }
            }
        }
    }
    .blog-post_text {
        font-size: 16px;
        margin-top: 10px;
        blockquote {
            margin-bottom: 20px;
        }
        .wp-block-pullquote:not(.has-background) {
            padding: 15px 0;
            blockquote {
                margin-bottom: 0;
            }
            &.is-style-solid-color {
                blockquote {
                    p:first-of-type {
                        margin-top: -0.225em;
                    }
                }
            }
        }
        .wp-block-archives-list,
        .wp-block-latest-posts {
            list-style: none;
        }
        .wp-block-categories-list {
            .children li {
                padding-left: 0;
            }
        }
        .more-link {
            display: none;
        }
        .wp-block-search {
            margin-bottom: 20px;
        }
    }
    .blog-post_footer {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-top: 17px;
        @media (max-width: 767px) {
            flex-direction: column-reverse;
            align-items: flex-start;
            margin-top: 16px;
            gap: 10px;
            .read-more-wrap {
                width: 100%;
                flex: unset;
            }
        }
        .post_meta-wrap {
            margin-top: 0;
            &:empty {
                display: none;
            }
        }
        .meta-data {
            font-size: 15px;
            > * {
                &:not(:last-child) {
                    margin-right: 18px;
                }
            }
        }
    }
    &.acenter .meta-data {
        justify-content: center;
    }
    &.aright .meta-data {
        justify-content: flex-end;
    }
}
//* ↑ blog module

.blog-post {
    position: relative;
    z-index: 1;
    margin-bottom: 60px;
    .blog-post_media {
        position: relative;
        z-index: 1;
        --wgl-blog-image-scale-size: 1;
        --wgl-blog-image-transition: 0.5s;
        &:hover {
            .blog-post_media_part {
                border-radius: 30px;
                img {
                    transform: scale(var(--wgl-blog-image-scale-size));
                }
            }
        }
        .post_categories {
            position: absolute;
            z-index: 1;
            top: -16px;
            left: 40px;
            width: calc(100% - 80px);
            @media (max-width: 767px) {
                left: 30px;
                width: calc(100% - 60px);
            }
        }
        .blog-post_media_part {
            position: relative;
            line-height: 0;
            border-radius: 0;
            transition: 0.4s;
            overflow: hidden;
            img {
                transition: var(--wgl-blog-image-transition) ease-out;
                border-radius: inherit;
            }
        }
    }
    &.format-gallery {
        .blog-post_media {
            .blog-post_media_part {
                overflow: hidden;
            }
            .wgl-carousel {
                .swiper-slide:not(:only-child) {
                    cursor: e-resize;
                }
            }
            .wgl-navigation_wrapper {
                align-items: flex-end;
                justify-content: flex-end;
                margin: 40px;
                gap: 0;
                @media (max-width: 767px) {
                    margin: 20px;
                }
            }
            .elementor-swiper-button {
                &-next,
                &-prev {
                    --wgl-swiper-button-diameter: 60px;
                    border-radius: 60px;
                    color: var(--burido-tertiary-color);
                    border: unset;
                    font-size: 30px;
                    background: var(--burido-secondary-color);
                    @media (max-width: 767px) {
                        --wgl-swiper-button-diameter: 40px;
                        font-size: 20px;
                    }
                    &.swiper-button-disabled {
                        pointer-events: none;
                    }
                    &:hover {
                        color: var(--burido-secondary-color);
                        background: var(--burido-primary-color);
                    }
                }
                .title{
                    display: block;
                }
            }
        }
    }
    &.standard,
    &.format-standard {
        .blog-post_media {
            margin-bottom: 12px;
        }
    }
    &.format {
        &-standard-image,
        &-image,
        &-gallery,
        &-video {
            .blog-post_content > .share_post-container {
                top: -26px;
                > a::after {
                    border-top-color: transparent;
                    border-left-color: transparent;
                    transform: rotate(44deg);
                }
                &:hover > a::after {
                    transform: rotate(44deg) scale(0.2);
                }
            }
        }
    }
    &.format-standard-image,
    &.format-image {
        .blog-post_media {
            position: relative;
            z-index: 1;
            .image-overlay {
                display: inline-block;
                position: relative;
                z-index: 1;
                filter: grayscale(0%);
                &::before,
                &::after {
                    display: block;
                    position: absolute;
                    z-index: 2;
                    top: 0;
                    left: 0;
                    width: 100%;
                    height: 100%;
                    border-radius: inherit;
                    transition: opacity 0.3s;
                }
                &::after {
                    opacity: 0;
                }
                img {
                    border-radius: inherit;
                }
            }
        }
        &:hover {
            .image-overlay::after {
                opacity: 1;
            }
        }
    }
    &.format-quote {
        --quote-offset: 67px;
        .blog-post_media {
            margin-bottom: 48px;
            margin-top: 3px;
            padding-bottom: 34px;
            border-bottom: 1px solid var(--burido-secondary-color);
        }
        .blog-post_wrapper {
            .blog-post_content {
                padding-top: 22px;
            }
        }
        .blog-post_quote-text {
            position: relative;
            z-index: 1;
            margin: 0;
            padding-left: var(--quote-offset);
            font-size: 24px;
            line-height: 1.5;
            font-weight: 500;
            min-height: 70px;
            color: var(--burido-header-font-color);
            letter-spacing: -0.03em;
            &::before {
                display: block;
                content: "";
                mask-image: var(--burido-quote-h);
                mask-position: center center;
                mask-size: 1em;
                mask-repeat: no-repeat;
                width: 0.6em;
                height: 0.5em;
                padding: 0;
                box-shadow: none;
                background-color: currentColor;
                font-style: normal;
                font-variant: normal;
                text-transform: none;
                line-height: 0;
                font-size: 80px;
                transition: transform .4s;
                color: var(--burido-primary-color);
                position: absolute;
                z-index: 1;
                left: 0;
                top: 0;
            }
        }
        .blog-post_quote-author {
            display: block;
            position: relative;
            margin-top: 14px;
            padding-left: var(--quote-offset);
            font-size: 18px;
            font-family: var(--burido-header-font-family);
            line-height: 1.3;
            font-style: normal;
            font-weight: 500;
            letter-spacing: 0;
            .blog-post_quote-image {
                display: inline-block;
                width: 30px;
                vertical-align: middle;
                margin-right: 10px;
                border-radius: 50%;
            }
            .blog-post_quote-author-name,
            .blog-post_quote-author-pos{
                vertical-align: middle;
            }
        }
    }
    &.format-link {
        .blog-post_media_part {
            overflow: visible;
        }
        .blog-post_media {
            margin-bottom: 49px;
            margin-top: 0;
            padding-bottom: 40px;
            border-bottom: 1px solid var(--burido-secondary-color);
        }
        .blog-post_wrapper {
            .blog-post_content {
                padding-top: 28px;
            }
        }
        .blog-post_link {
            margin-bottom: 0;
            position: relative;
            z-index: 1;
            line-height: inherit;
            font-size: inherit;
            .link_post {
                position: relative;
                z-index: 1;
                padding-left: 54px;
                font-size: 24px;
                line-height: 1.5;
                font-weight: 500;
                color: var(--burido-header-font-color);
                letter-spacing: -0.03em;
                margin: 0;
                &:hover {
                    opacity: 0.8;
                }
            }
            &::before {
                display: block;
                content: "";
                mask-image: var(--burido-link-h);
                mask-position: center center;
                mask-size: 1em;
                mask-repeat: no-repeat;
                width: 1em;
                height: 1em;
                padding: 0;
                box-shadow: none;
                background-color: currentColor;
                font-style: normal;
                font-variant: normal;
                text-transform: none;
                line-height: 0;
                font-size: 55px;
                transition: transform 0.4s;
                color: var(--burido-primary-color);
                position: absolute;
                z-index: 1;
                left: -4px;
                top: -12px;
                transform: rotate(-45deg);
            }
        }
    }
    &.format-audio {
        .blog-post_media {
            margin-bottom: 42px;
            margin-top: -8px;
        }
    }
}

.related_posts .format-video .blog-post_media .blog-post_media_part {
    padding-bottom: 87.5%;
    &.video_image:not(.video_parallax) {
        padding-bottom: 0;
    }
}

#main-content > .blog-posts .elementor {
    margin-left: -15px;
    margin-right: -15px;
}

//* ↓ Post Formats (affects both Grid and Single)
.format {
    &-video .blog-post_media .blog-post_media_part {
        width: 100%;
        overflow: hidden;
        .videobox_content {
            justify-content: center;
            align-items: center;
        }
        .videobox_link_wrapper {
            top: auto;
            margin: 40px;
        }
    }
    &-video {
        .blog-post_media {
            .blog-post_media_part {
                padding-bottom: 73.5%;
                &.video_image:not(.video_parallax) {
                    padding-bottom: 0;
                }
            }
            iframe {
                position: absolute;
                z-index: 1;
                height: 100%;
            }
        }
    }
    &-audio {
        iframe {
            border-radius: inherit;
        }
    }
}

//* ↓ Sticky
.blog-post.sticky-post {
    &.format-no_featured {
        border: 3px solid #cccccc;
    }
}

//* ↓ Title
.blog-posts {
    .blog-post_title {
        font-size: 36px;
        display: block;
        margin-bottom: 0;
        margin-top: 13px;
        word-wrap: break-word;
        clear: both;
        @media (max-width: 767px) {
            font-size: 20px;
            line-height: 1.4;
        }
        &:last-child {
            margin-bottom: 0;
        }
        > a {
            font: inherit;
            line-height: inherit;
            text-transform: inherit;
            letter-spacing: inherit;
            transition: 0.5s ease-in-out;
            background-repeat: no-repeat;
            background-size: 0% 0.09em;
            background-position: 0% 86%;
            transition: background-size 1.2s 0s;
            background-image: linear-gradient(to top, currentColor, currentColor);
            &:hover {
                color: var(--burido-header-font-color);
                background-size: 100% 0.09em;
            }
        }
    }
}

.blog-post_content {
    .page-link {
        margin-top: 30px;
    }
    &::after {
        content: '';
        display: block;
        clear: both;
    }
    .read-more-wrap {
        padding-top: 0;
        padding-bottom: 0;
    }
    .blog-post_title + .read-more-wrap{
        padding-top: 0;
    }
}
.blog-post_content,
#comments .comment_content > {
    p,
    p + address {
        margin-bottom: 16px;
    }
    p {
        &:last-child {
            margin-bottom: 0;
        }
        &:empty {
            display: none;
        }
    }
}

//* ↓ h[1-6]
.blog-post_content,
.row > div >,
#comments .comment_content {
    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
        margin-bottom: 22px;
    }
}

//* ↓ Posts List
.blog-posts-list {
    + .wgl-pagination {
        margin-bottom: 30px;
    }
    &::after {
        content: '';
        display: block;
        height: 0;
        clear: both;
    }
}
.archive .blog-posts-list {
    margin-top: 0;
}
.home,
.archive {
    .sidebar_none {
        > .wgl_col-12 {
            > .blog-posts {
                margin-top: 50px;
            }
        }
    }
    .sidebar_right,
    .sidebar_left {
        .blog-posts-list {
            margin-top: 0;
        }
    }
}

//* ↓ Elementor Widget
.elementor-widget-wgl-blog {
    .elementor-widget-container {
        margin-bottom: 40px;
    }
    &.nav {
        &-left .wgl-pagination {
            text-align: left;
        }
        &-center .wgl-pagination {
            text-align: center;
        }
        &-right .wgl-pagination {
            text-align: right;
        }
    }
}

.home .row.sidebar_right,
.home .row.sidebar_left {
    margin-top: 50px;
}

//* ↓ Mega Menu
.mega-ajax-content {
    .item {
        .blog-post_media {
            margin-bottom: 14px;
        }
        .blog-post_title {
            margin-bottom: 5px;
        }
        .blog-post_content {
            white-space: normal;
        }
        .meta-data {
            background: none;
            padding-left: 0;
            padding-right: 0;
        }
    }
    .format-video {
        .blog-post_media .blog-post_media_part {
            padding-bottom: 70.272%;
        }
    }
}

//* ↓ Swiper Slider
.blog_carousel {
    .wgl-carousel .swiper-pagination {
        margin-top: 0;
    }
    .wgl-carousel-wrapper {
        overflow: visible;
    }
    &_title-arrow .wgl-carousel {
        .elementor-swiper-button-prev.elementor-swiper-button,
        .elementor-swiper-button-next.elementor-swiper-button {
            display: none !important;
        }
    }
}
.slider-wrapper.wgl-carousel {
    .blog-post_media-slider_swiper {
        height: 100%;
        .swiper-slide {
            position: relative;
            z-index: 5;
            height: 100%;
            width: 100%;
            span {
                height: 100%;
                width: 100%;
                display: block;
                background-size: cover;
                background-position: center;
                transition: all 1s cubic-bezier(0.7, 0, 0.3, 1);
                overflow: hidden;
                img {
                    transform: scale(1.25, 1.25);
                    transition: 500ms ease-in-out;
                }
            }
            &.swiper-slide-active span {
                img {
                    transform: scale(1, 1);
                }
            }
        }
        .swiper-wrapper {
            height: 100%;
        }
    }
    .swiper-container {
        z-index: auto;
        backface-visibility: hidden;
        .elementor-swiper-button {
            z-index: 100;
        }
    }
}
//* ↑ swiper slider

//* ↓ Meta Data
.meta_wrapper,
.post_meta-wrap {
    display: flex;
    gap: 12px;
    flex-wrap: nowrap;
    align-items: flex-start;
    justify-content: space-between;
    &.post_meta-top {
        &:not(:first-child){
            margin-top: 18px;
            margin-bottom: 20px;
        }
    }
    .meta-data {
        > span {
            &:not(:last-child)::after {
                content: "_";
                margin: 0px 8px;
                display: inline-block;
            }
        }
        &:not(:first-child) {
            &::before,
            &::after {
                display: none;
            }
        }
    }
    .meta-data + .meta-data{
        flex-shrink: 0;
        font-style: normal;
        span {
            display: inline-block;
            vertical-align: baseline;
        }
        i {
            font-size: 14px;
        }
        .comments_post {
            i {
                margin-right: 5px;
            }
        }
        > * {
            margin-right: 15px;
            display: inline-block;
            &::after {
                display: none;
            }
            &:last-child {
                margin-right: 0;
            }
        }
    }
}
.wgl-portfolio-single_item,
.blog-post_content{
    .meta-data {
        position: relative;
        z-index: 1;
        display: flex;
        justify-content: flex-start;
        align-items: center;
        flex-wrap: wrap;
        font-weight: 500;
        color: var(--burido-content-color);
        font-size: 15px;
        line-height: 30px;
        letter-spacing: 0;
        a {
            color: inherit;
            letter-spacing: inherit;
            text-decoration: underline;
            text-decoration-color: transparent;
            text-decoration-thickness: 0.07em;
            &:hover {
                text-decoration-color: currentColor;
            }
        }
        .post_author {
            white-space: nowrap;
            img {
                border-radius: 50%;
                margin-right: 11px;
                max-width: 32px;
                margin-top: -3px;
                margin-bottom: -3px;
            }
        }
        .post_categories {
            span {
                margin-top: 3px;
                margin-bottom: 3px;
                &:last-child {
                    margin-right: 12px;
                }
            }
        }
        &:first-child {
            > * {
                display: inline-block;
                vertical-align: middle;
                color: inherit;
                padding: 0;
                margin: 0;
                line-height: inherit;
                &:last-child {
                    margin-right: 0;
                }
                a:not(:hover) {
                    color: inherit;
                }
                &.wgl-views:first-child::after {
                    content: unset;
                }
            }
        }
    }
}
@mixin meta-data-responsive {
    .meta-data {
        .views_text,
        .sl-count-text{
            display: none !important;
        }
    }
}
@media (max-width: 479px) {
    @include meta-data-responsive;
}
.blog_columns-2 {
    @media (min-width: 768px) and (max-width: 992px) {
        @include meta-data-responsive;
    }
}
.blog_columns-3,
.blog_columns-4 {
    @media (min-width: 768px) {
        @include meta-data-responsive;
    }
}
//* ↑ meta data

//* ↓ Categories List
.post_categories {
    --post-catigories-gap: 5px;
    display: inline-block;
    position: relative;
    font-size: 14px;
    font-weight: 600;
    margin-bottom: calc(var(--post-catigories-gap) * -1);
    text-transform: uppercase;
    span {
        display: inline-block;
        position: relative;
        line-height: inherit;
        transition: 0.4s;
        margin-bottom: var(--post-catigories-gap);
        &:not(:last-child) {
            margin-right: var(--post-catigories-gap);
        }
    }
    a {
        display: inline-block;
        padding: 1px 8px;
        line-height: 30px;
        color: var(--burido-header-font-color);
        background-color: var(--burido-primary-color);
        border-radius: 10px;
        transition: 0.5s ease-in-out;
        text-decoration: none !important;
        &:hover {
            background-color: var(--burido-header-font-color);
            color: var(--burido-tertiary-color);
        }
    }
    &::after {
        display: none !important;
    }

}
//* ↑ Categories List

.blog-post_text {
    + .page-link,
    + .page-link + .clear + .button-read-more,
    + .clear + .button-read-more {
        margin-bottom: 21px;
    }
    .alignleft,
    .alignright {
        &:last-child {
            margin-bottom: 10px;
        }
    }
    ins,
    kbd,
    tt,
    code {
        color: var(--burido-secondary-color);
    }
}

.read-more-wrap {
    clear: both;
    line-height: 1;
}
.button-read-more {
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    position: relative;
    z-index: 1;
    font-size: 14px;
    font-weight: 600;
    line-height: 1;
    font-family: var(--burido-header-font-family);
    white-space: nowrap;
    letter-spacing: 0.05em;
    margin-top: 6px;
    max-width: 100%;
    color: var(--burido-header-font-color);
    transition: 0.4s;
    text-transform: uppercase;
    &:hover {
        color: var(--burido-header-font-color);
    }
    &::before {
        content: '';
        position: absolute;
        z-index: 0;
        bottom: 0;
        left: -3px;
        width: 100%;
        height: 4px;
        background: var(--burido-primary-color);
        transition: 0.4s;
    }
    &::after {
        display: block;
        content: "";
        mask-image: var(--burido-arrow-down-right-h);
        mask-position: center center;
        mask-size: 1em;
        mask-repeat: no-repeat;
        width: 1em;
        height: 1em;
        padding: 0;
        box-shadow: none;
        background-color: currentColor;
        font-style: normal;
        font-variant: normal;
        text-transform: none;
        line-height: 0;
        font-size: 20px;
        transition: transform .4s;
        margin-left: 3px;
    }
    > span {
        white-space: normal;
        transition: transform .4s;
        display: inline-block;
        position: relative;
    }
    &:hover{
        color: var(--burido-header-font-color);
        &::before {
            height: 100%;
        }
        &::after {
            transform: rotate(-45deg);
        }
    }
    &.no_text{
        padding-left: 0 !important;
        margin-right: 0 !important;
        .read-more-icon,
        &::after {
            display: none;
        }
    }
}

.tagcloud-wrapper {
    .title_tags {
        font-size: 15px;
        margin-right: 18px;
    }
}

.meta-data + .post_info-divider {
    margin-top: 4px;
}

.blog-post_excerpt {
    margin: 0 0 38px;
    font-size: 20px;
    line-height: 1.8;
    font-weight: 400;
    > p:last-child {
        margin-bottom: 0;
    }
}

.blog-post_wrapper {
    position: relative;
    transition: inherit;
    .blog-post_media {
        .burido_module_videobox {
            img {
                box-shadow: none;
            }
            .videobox_link {
                border-color: transparent;
                opacity: 0.9;
            }
        }
    }
    .blog-post_content {
        .burido_module_videobox {
            .videobox_wrapper_link {
                &::before {
                    display: none;
                }
            }
        }
        > .post_meta-wrap {
            .meta-data:first-child > * {
                display: contents;
            }
        }
        .burido_module_videobox {
            margin-bottom: 50px;
        }
    }
}

.row.sidebar_left .content-container {
    float: right;
}
.container-grid.row {
    > .wgl-carousel {
        margin-left: 0;
        margin-right: 0;
        &.navigation_offset_element {
            padding-left: 40px;
            padding-right: 40px;
            overflow: hidden;
            > .swiper-container {
                overflow: visible;
            }
            .swiper-wrapper {
                overflow: hidden;
            }
        }
    }
}

.blog_subtitle {
    font-size: 18px;
    line-height: 1.4;
}

//* ↓ Attachment media
.attachment_media {
    .meta-data {
        margin-bottom: 10px;
        font-weight: 600;
        > span {
            position: relative;
            padding-left: 23px;
            &:first-child {
                padding-left: 0;
                &::before {
                    display: none;
                }
            }
        }
    }
}
.parallax-video {
    position: absolute !important;
    z-index: 2 !important;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}
.jarallax {
    position: relative;
    z-index: 0;
    > .jarallax-img {
        position: absolute;
        z-index: -1;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        //* support for plugin https://github.com/bfred-it/object-fit-images
        font-family: 'object-fit: cover;';
        object-fit: cover;
    }
}

//* ↓ Archive
.archive__heading {
    margin-bottom: 45px;
    text-align: center;
    .archive__tax_description {
        margin-top: 10px;
    }
    .archive__tax_title {
        max-width: 530px;
        display: inline-block;
        &,
        & > span {
            font-size: 36px;
            line-height: 48px;
        }
    }
}
.archive .wgl_blog_list {
    margin-bottom: 30px;
}

//* ↓ Columns
.blog_columns-2:not(.masonry) .item:nth-child(2n + 1),
.blog_columns-3:not(.masonry) .wgl_col-4:nth-child(3n + 1),
.blog_columns-4:not(.masonry) .wgl_col-3:nth-child(4n + 1) {
    clear: left;
}
@media (max-width: 1024px) {
    .blog_columns-3:not(.masonry) .wgl_col-4:nth-child(3n + 1) {
        clear: none;
    }
    .blog_columns-3:not(.masonry) .wgl_col-4:nth-child(3n + 1) {
        clear: left;
    }
    .blog_columns-4:not(.masonry) .wgl_col-3:nth-child(4n + 1) {
        clear: none;
    }
    .burido-post-navigation {
        margin-bottom: 0;
    }
}
