body {
    .title-wrapper ~ .select2-container,
    .title-wrapper ~ form .select2-container {
        margin-top: -11px;
    }
    .select2-container,
    .ui-widget.ui-datepicker{
        z-index: 999 !important;
    }
    .select2-container {
        font-family: var(--burido-content-font-family);
        font-size: 16px;
        line-height: 1.5;
        font-weight: 400;
        text-transform: none;
        color: var(--burido-header-font-color);
	    margin-top: 0;
        margin-bottom: 4px;
	    ul {
            li {
                font-size: 16px;
                line-height: 1.5;
                font-weight: 400;
                margin: 0;
            }
        }
    }
    .select2-container--default {
        .select2-search--inline {
            .select2-search__field {
                line-height: 30px;
                height: 30px;
                max-width: 100%;
                margin: 0;
                box-shadow: unset !important;
                text-transform: none;
            }
        }
        .select2-search--dropdown {
            padding: 0 10px;
            .select2-search__field {
                background-color: transparent;
                padding: 10px 0;
                height: 40px;
                border: unset;
                transition: all 0.3s;
                border-width: 0 0 1px 0 !important;
                border-style: solid;
                border-color: rgba(var(--burido-header-rgb), 1);
            }
        }
        .select2-selection--single {
            padding: 5px 0 5px 0;
            background-color: transparent;
            border-radius: unset;
            font-weight: 400;
            border-width: 0 0 1px 0;
            border-style: solid;
            border-color: rgba(var(--burido-header-rgb), 1);
            margin: 0;
            height: 40px;
            text-align: left;
            transition: all 0.3s;
            .select2-selection__clear {
                float: left;
                font-weight: normal;
                font-size: 16px;
            }
            .select2-selection__placeholder {
                color: inherit;
            }
            .select2-selection__rendered {
                line-height: 30px;
                padding-left: 0;
                color: var(--burido-header-font-color);
            }
            .select2-selection__arrow {
                top: 0;
                right: 0;
                height: 40px;
                width: 1em;
                background-image: var(--burido-bg-caret2-h);
                background-size: 10px;
                background-repeat: no-repeat;
                background-position: 100% center;
                b {
                    display: none;
                }
            }
        }
        .select2-selection--multiple {
            font-size: 0;
            padding: 11px 0 10px 0;
            background-color: transparent;
            border-radius: unset;
            border-width: 0 0 1px 0;
            border-style: solid;
            border-color: rgba(var(--burido-header-rgb), 1);
            .select2-selection__rendered {
                max-width: 100%;
                padding: 0;
                li {
                    padding-left: 0;
                    padding-right: 0;
                    margin: 0 !important;
                    max-width: 100%;
                    font-size: 16px;
                    line-height: 1.5;
                    font-weight: 400;
                    color: var(--burido-header-font-color);
                    &.select2-selection__choice {
                        background: unset;
                        padding-left: 7px;
                        border: unset;
                        margin-right: 5px;
                        &__remove {
                            font-size: 16px;
                            line-height: 16px;
                            font-weight: normal;
                            color: #b7b7b7;
                            transition: color 0.4s;
                            &:hover {
                                color: var(--burido-header-font-color);
                            }
                        }
                    }
                }
            }
        }
        &.select2-container--focus{
            .select2-selection--multiple{
                border-width: 0 0 1px 0;
                border-style: solid;
                border-color: rgba(var(--burido-header-rgb), 1);
            }
        }
        &.select2-container--below.select2-container--open {
            .select2-selection--multiple{
                border-bottom: 1px solid var(--burido-header-font-color);
                background-color: transparent;
            }
            .select2-selection--single{
                border-bottom: 1px solid var(--burido-header-font-color);
                background-color: transparent;
            }
        }
        &.select2-container--above.select2-container--open {
            .select2-selection--multiple{
                border-bottom: 1px solid var(--burido-header-font-color);
                background-color: transparent;
            }
            .select2-selection--single{
                border-bottom: 1px solid var(--burido-header-font-color);
                background-color: transparent;
            }
        }
        .select2-results__option {
            padding-left: 10px;
            line-height: 24px;
            &.select2-results__message{
                padding-bottom: 20px;
            }
            &[aria-selected='true'],
            &[data-selected='true'] {
                background-color: rgba(var(--burido-header-rgb), 0.2);
                color: inherit;
            }
            &--highlighted {
                &[aria-selected='true'],
                &[data-selected='true'] {
                    background: rgba(var(--burido-header-rgb), 0.1);
                    font-weight: var(--burido-header-font-weight);
                }
            }
        }
    }
    .select2-results {
        font-size: 16px;
    }
    .select2-dropdown {
        color: var(--burido-header-font-color);
        background-color: var(--body-background-color);
        border-bottom: 1px solid rgba(var(--burido-header-rgb), 0.15);
        box-shadow: none;
        &.select2-dropdown--below{
            border: 1px solid rgba(var(--burido-header-rgb), 1);
            border-top: none;
        }
        &.select2-dropdown--above {
            border: 1px solid rgba(var(--burido-header-rgb), 1);
        }
    }
    &.admin-bar{
        & > .select2-container{
            margin-top: -32px;
            @media screen and (max-width: 782px){
                margin-top: -46px;
            }
        }
    }
}

.woocommerce form .form-row .select2-container{
    margin: 0;
}


/* ==================== ##Shop - Combobox ↓ ==================== */
div.wc-block-components-combobox,
.wc-block-components-form div.wc-block-components-combobox {
    .wc-block-components-combobox-control {
        input.components-combobox-control__input{
            border: unset;
            border-bottom: 1px solid rgba(var(--burido-header-rgb), 1);
            box-shadow: unset;
            padding: 0;
            border-radius: unset;
            font-family: var(--burido-content-font-family);
            font-size: 16px;
            line-height: 1.7;
            font-weight: 400;
            text-transform: none;
            color: var(--burido-header-font-color);
            background: transparent;
            &:focus,
            &[aria-expanded=true]{
                box-shadow: unset;
                background: transparent;
                border-bottom: 1px solid var(--burido-header-font-color);
                color: var(--burido-header-font-color);
            }
        }
        label.components-base-control__label{
            font-family: var(--burido-content-font-family);
            font-size: 16px;
            line-height: 40px;
            font-weight: 400;
            color: var(--burido-header-font-color);
            transform: unset !important;
            left: 0;
        }
    }
    &.is-active,
    &:focus-within{
        .wc-block-components-combobox-control label.components-base-control__label{
            opacity: 0;
        }
    }
}

div.wc-block-components-radio-control {
    .wc-block-components-radio-control__option {
        color: var(--burido-header-font-color);
        font-weight: 400;
        &,
        .is-mobile &,
        .is-small &{
            padding-left: 29px;
        }
        .wc-block-components-radio-control__option-layout {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }
    }
    &--highlight-checked div.wc-block-components-radio-control-accordion-option,
    &--highlight-checked.wc-block-components-radio-control--highlight-checked--last-selected,
    &--highlight-checked .wc-block-components-radio-control__option,
    &--highlight-checked{
        &::after{
            display: none;
        }
    }
}
div.wc-blocks-components-select{
    .wc-blocks-components-select__container{
        border-radius: 15px;
        border-color: var(--burido-header-font-color);
    }
    label.wc-blocks-components-select__label{
        font-size: 11px;
        line-height: 1.5em;
        font-weight: 400;
        transform: unset !important;
        margin-left: 2px;
    }
}

