/* ==================== ##Shares Style ==================== */

@use '../../variables';

//* ↓ Post List Share
.blog-post_wrapper{
    .share_post-container {
        display: inline-block;
        position: relative;
        z-index: 1;
        user-select: none;
        padding: 0;
        margin: 0;
        cursor: pointer;
        &:hover {
            .share_social-wpapper {
                &,
                ul > li {
                    opacity: 1;
                    visibility: visible;
                }
                ul > li {
                    $delay-show: -0.08;
                    @for $i from 1 through 7 {
                        $delay-show: $delay-show + 0.08;
                        &:nth-last-child(#{$i}) {
                            transition-delay: #{$delay-show}s;
                        }
                    }
                }
            }
            > a::after {
                transform: scale(0.2);
            }
        }
        &::after{
            content: '';
            z-index: 1;
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: calc(100% + 12px);
        }
        .share_post {
            display: block;
        }
        span {
            display: block;
            line-height: inherit;
            border-radius: 50%;
            transition: all 0.45s;
        }
        & > i{
            display: inline-block;
            position: relative;
            z-index: 1;
            text-align: center;
            transition: color .3s;
        }
        .share {
            &_reddit .fab {
                background-color: variables.$reddit;
            }
            &_twitter .fab {
                background-color: variables.$twitter;
            }
            &_facebook .fab {
                background-color: variables.$facebook;
            }
            &_linkedin .fab {
                background-color: variables.$linkedin;
            }
            &_whatsapp .fab {
                background-color: variables.$whatsapp;
            }
            &_telegram .fab {
                background-color: variables.$telegram;
            }
            &_pinterest .fab {
                background-color: variables.$pinterest;
            }
        }
        .share_social-wpapper {
            display: block;
            position: absolute;
            right: -8px;
            bottom: calc(100% + 8px);
            min-width: unset;
            z-index: 2;
            box-shadow: none;
            margin: 0;
            padding: 2px;
            font-size: 0;
            line-height: 0;
            white-space: nowrap;
            opacity: 0;
            visibility: hidden;
            transition: all 0.4s ease-in-out;
            background: var(--burido-secondary-color);
            &::after {
                content: '';
                position: absolute;
                pointer-events: none;
                width: 0;
                height: 0;
                border-style: solid;
                border-width: 5px 5.5px 0 5.5px;
                border-color: currentColor transparent transparent transparent;
                right: 10px;
                bottom: -5px;
                color: var(--burido-secondary-color);
            }
            a.share_link {
                text-align: center;
                padding: 0;
                display: inline-block;
                vertical-align: top;
                transition: 0.4s;
                opacity: 1;
                background: unset !important;
                visibility: hidden;
                pointer-events: all;
                margin: 0;
                border-radius: unset;
                &:first-of-type{
                    border-top-left-radius: inherit;
                    border-bottom-left-radius: inherit;
                }
                &:last-of-type{
                    border-top-right-radius: inherit;
                    border-bottom-right-radius: inherit;
                }
                &::before {
                    display: none;
                }
                span{
                    width: 28px;
                    height: 28px;
                    line-height: 28px;
                    font-size: 11px;
                    border-radius: inherit;
                    background-color: transparent;
                    font-weight: normal;
                    color: #ffffff;
                }
                &:hover {
                    span {
                        background-color: rgba(255,255,255,.13);
                    }
                }
            }
        }
        &:hover{
            .share_social-wpapper {
                a.share_link {
                    visibility: visible;
                }
            }
        }
    }
}
//* ↑ post list share

//* ↓ Post Share
.share_social-wpapper {
    display: flex;
    justify-content: flex-end;
    &:not(:last-child){
        margin-right: 10px;
    }
    .share {
        &_facebook > span  {
            color: variables.$facebook;
        }
        &_twitter > span  {
            color: variables.$twitter;
        }
        &_pinterest  > span {
            color: variables.$pinterest;
        }
        &_linkedin  > span {
            color: variables.$linkedin;
        }
        &_whatsapp  > span {
            color: variables.$whatsapp;
        }
        &_reddit  > span {
            color: variables.$reddit;
        }
        &_telegram > span {
            color: variables.$telegram;
        }
        &_link:hover{
            &[class*="share"] > span{
                color: #ffffff;
            }
            &.share_facebook > span{
                background-color: variables.$facebook;
                border-color: variables.$facebook;
            }
            &.share_twitter > span{
                background-color: variables.$twitter;
                border-color: variables.$twitter;
            }
            &.share_pinterest > span{
                background-color: variables.$pinterest;
                border-color: variables.$pinterest;
            }
            &.share_linkedin > span{
                background-color: variables.$linkedin;
                border-color: variables.$linkedin;
            }
            &.share_whatsapp > span{
                background-color: variables.$whatsapp;
                border-color: variables.$whatsapp;
            }
            &.share_reddit > span{
                background-color: variables.$reddit;
                border-color: variables.$reddit;
            }
            &.share_telegram > span{
                background-color: variables.$telegram;
                border-color: variables.$telegram;
            }
        }
    }
    .share_link {
        border-radius: 30px;
        text-align: center;
        overflow: hidden;
        & > span {
            display: flex;
            font-size: 12px;
            line-height: 30px;
            height: 30px;
            border-radius: inherit;
            white-space: nowrap;
            max-width: 30px;
            transition: .65s;
            &::before {
                display: inline-block;
                width: 30px;
                text-align: center;
                font-family: 'Font Awesome 5 Brands';
                flex-shrink: 0;
            }
        }
        .share_name{
            display: none;
        }
        &:not(:last-of-type){
            padding-right: 10px;
        }
    }
}

//* Author Post Share
.author-info_social-wrapper {
    .author-info_social-link {
        line-height: 30px;
        &.fa {
            color: #969696;
        }
    }
}

//* Page Socials
.wgl-page-socials {
    position: absolute;
    z-index: 90;
    left: 50px;
    &.fixed {
        position: fixed;
        z-index: 90;
    }
    li {
        padding-bottom: 17px;
        line-height: 27px;
    }
    .social__link {
        font-size: 13px;
        color: #ffffff;
        white-space: nowrap;
        transition: all 0.4s, width 0s 1s;
        .social__name {
            display: inline-block;
            width: 0;
            font-weight: 700;
            text-transform: uppercase;
            vertical-align: middle;
            overflow: hidden;
            opacity: 0;
            transform-origin: -25px 50%;
            transform: translateY(-1px) rotateY(0.25turn);
            transition: inherit;
        }
        .social__icon {
            padding-right: 1.2em;
        }
        &:hover {
            transition: all 0.4s;
            .social__name {
                width: auto;
                opacity: 1;
                transform: translateY(-1px) rotateY(0turn);
            }
        }
    }
    .socials__list {
        margin: 0;
        padding: 0;
        list-style: none;
    }
    &.appearence-hovered {
        padding-top: 35px;
        height: 0;
        .socials__desc {
            position: absolute;
            top: 0;
            left: 0;
            margin: -5px -5px 0;
            padding: 5px 5px 0;
            cursor: pointer;
            .social__icon {
                color: #ffffff;
            }
            .social__name {
                display: none;
            }
        }
        .socials__list {
            visibility: hidden;
            li {
                transform: translateX(-150%);
                opacity: 0;
                visibility: hidden;
                transition: 0.45s;
                $delay: 0;
                @for $i from 1 through 10 {
                    $delay: $delay + 0.05;
                    &:nth-child(#{$i}) {
                        transition-delay: #{$delay}s;
                    }
                }
            }
        }
        .socials__desc:hover + .socials__list {
            visibility: visible;
        }
        .socials__desc:hover + .socials__list,
        .socials__list:hover {
            li {
                transform: translateX(0);
                opacity: 1;
                visibility: visible;
            }
        }
    }
    &:not(.appearence-hovered) {
        .socials__list li {
            opacity: 0;
            transform: translateX(-150%);
            animation: soc_slide_right 0.5s forwards;
            $delay: 5;
            @for $i from 1 through 10 {
                $delay: $delay + 0.1;
                &:nth-child(#{$i}) {
                    animation-delay: #{$delay}s;
                }
            }
        }
    }
    @keyframes soc_slide_right {
        0% {
            transform: translateX(-150%);
            opacity: 0;
        }
        50% {
            opacity: 1;
        }
        100% {
            transform: translateX(0);
            opacity: 1;
        }
    }
}

.wgl-social-icons {
    .wgl-icon {
        i, svg {
            transition: 0.3s;
        }
    }
}

.single_post_info {
    > * {
        margin-bottom: 20px;
    }
    .share_post-container {
        position: relative;
        z-index: 1;
        display: flex;
        align-items: center;
        &:after {
            display: none;
        }
        &:hover {
            .share_social-wpapper {
                opacity: 1;
                visibility: visible;
            }
        }
        > a {
            width: 36px;
            height: 36px;
            line-height: 36px;
            border-radius: 50%;
            z-index: 3;
            margin: 0;
            transition: all 0.45s;
            font-size: 24px;
            display: block;
            text-align: center;
            color: var(--burido-secondary-color);
            &:before {
                display: inline-block;
                vertical-align: middle;
                content: "";
                mask-image: var(--burido-share-h);
                mask-position: center center;
                mask-size: 1em;
                mask-repeat: no-repeat;
                width: 1em;
                height: 1em;
                padding: 0;
                box-shadow: none;
                background-color: currentColor;
                font-style: normal;
                font-variant: normal;
                text-transform: none;
                line-height: inherit;
                font-size: inherit;
            }
        }
        .share_social-wpapper {
            position: absolute;
            height: 40px;
            right: 0;
            top: 0;
            padding-right: 50px;
            background: transparent;
            opacity: 0;
            visibility: hidden;
            transition: 0.6s;
            &:after {
                display: none;
            }
        }
        .share_post-title {
            font-size: 14px;
            font-weight: 700;
            margin-right: 26px;
            color: var(--burido-header-font-color);
        }
        .share_link {
            line-height: 36px;
            padding: 0;
            width: 36px;
            height: 36px;
            overflow: visible;
            border-radius: 50%;
            text-align: center;
            > span {
                font-size: 16px;
                transition: 0.4s;
                width: 100%;
                height: inherit;
                line-height: inherit;
                max-width: unset;
                color: var(--burido-secondary-color);
                background: transparent;
                &:before {
                    width: inherit;
                }
            }
            &:hover[class*="share"] {
                > span {
                    color: var(--burido-secondary-color);
                    background: var(--burido-primary-color);
                }
            }
            &:not(:last-child) {
                margin-right: 6px;
            }
        }
        @media (max-width: 767px) {
            > a {
                display: none;
            }
            .share_social-wpapper {
                position: relative;
                opacity: 1;
                visibility: visible;
                padding: 0;
            }
        }
        &:only-child {
            .share_social-wpapper {
                right: unset;
                left: 0;
                padding-right: unset;
                padding-left: 50px;
            }
        }
    }
}
//* ↓ Shop Share ↓
.woocommerce div.product {
    .share_social-wpapper {
        .share_link {
            margin-right: 20px;
            font-size: 12px;
            color: #c2c2c2;
            span.fa {
                transition: 0.45s ease-in-out;
            }
            &:last-child {
                margin-right: 0;
            }
        }
    }
}
