/* ==================== ##Comments ==================== */

.single.related_posts + .row #comments {
    margin-top: 90px;
    margin-bottom: 80px;
    padding-top: 0;
}

#comments {
    padding-top: 50px;
    margin-bottom: 44px;
    clear: both;
    overflow: hidden;
    &::before {
        content: '';
        display: block;
        clear: both;
    }
    ul,
    ol {
        ul.children {
            margin: 0;
            margin-top: 10px;
            padding: 0;
            list-style: none;
        }
    }
    #respond,
    ~ #review_form_wrapper #respond {
        position: relative;
        z-index: 1;
        margin: 20px 0 50px;
        padding: 42px 50px 50px;
        background: var(--burido-form-bg-color);
        overflow: hidden;
        border-radius: 0;
        @media (max-width: 600px) {
            padding: 30px 30px 35px;
        }
    }
    > #respond {
        margin-bottom: 0;
        margin-top: 80px;
    }
    > h4 {
        position: relative;
        z-index: 10;
    }
    .comments-title {
        font-size: 36px;
        margin-bottom: 28px;
        @media (max-width: 767px) {
            font-size: 26px;
        }
        .number-comments {
            margin-left: 0.25em;
            font-size: inherit;
        }
    }
    .pingback,
    .trackback {
        .edit-link .comment-edit-link {
            font-size: 0.75em;
            color: #7e7676;
            margin-left: 0.3133em;
            &:hover {
                color: #b9a9cd;
            }
        }
        + .comment {
            margin-top: 30px;
        }
    }
    .comment-notes,
    .logged-in-as {
        margin-bottom: 28px;
    }
    .comment-notes,
    .comment-form-cookies-consent {
        font-size: 14px;
    }
    .form-submit {
        margin-bottom: 0;
        clear: both;
        input.submit {
            min-width: 200px;
        }
        .submit {
            margin-top: 6px;
            padding: 7px 30px;
            position: relative;
            z-index: 1;
        }
    }
    .commentlist {
        position: relative;
        margin: 0;
        padding: 0;
        padding-top: 35px;
        line-height: inherit;
        list-style: none;
        border-top: 1px solid rgba(var(--burido-secondary-rgb), 0.15);
        li.pingback,
        li.trackback {
            padding: 0;
            .comment-body {
                display: inline;
            }
            &::before {
                display: none;
            }
        }
        + * {
            margin-top: 46px;
        }
        .comment-respond {
            margin: 20px 0;
        }
        .comment {
            padding: 0;
            margin-bottom: 0;
            &::before,
            &::after {
                display: none;
            }
            .stand_comment {
                min-height: 100px;
                margin-bottom: 36px;
                padding: 0 0 34px 110px;
                position: relative;
                z-index: 1;
                // border-bottom: 1px solid rgba(var(--burido-secondary-rgb), 0.15);
                .thiscommentbody {
                    position: relative;
                    z-index: 1;
                    min-height: 86px;
                }
                .meta-data {
                    > span, > time {
                        line-height: inherit;
                        text-transform: none;
                    }
                }
                &::after {
                    content: '';
                    position: absolute;
                    z-index: 1;
                    height: 1px;
                    width: 300%;
                    left: 50%;
                    bottom: 0;
                    transform: translateX(-50%);
                    background: rgba(var(--burido-secondary-rgb), 0.15);
                }
            }
            .commentava {
                position: absolute;
                z-index: 1;
                top: 4px;
                left: -110px;
                width: 86px;
                height: 86px;
                img {
                    border-radius: 50%;
                }
            }
            &.pingback .stand_comment {
                padding-left: 0;
            }
            .children {
                .comment {
                    margin-left: 86px;
                }
                .stand_comment {
                    padding-left: 110px;
                    .commentava {
                        left: -110px;
                    }
                }
            }
        }
        > .comment {
            > .children > .comment {
                margin-left: 110px;
            }
            &:last-child {
                margin-bottom: -1px;
                .comment:last-child {
                    .stand_comment {
                        // border-bottom: 0;
                        // margin-bottom: 0;
                    }
                }
            }
        }
        .comment_info {
            display: block;
            font-size: 18px;
            line-height: 1;
            font-weight: 500;
            margin-bottom: 7px;
            color: var(--burido-header-font-color);
            > * {
                display: inline-block;
            }
            .meta-data {
                float: none;
                margin-bottom: 0;
                padding: 0;
                background: none;
                opacity: 1;
                color: var(--burido-header-font-color);
                font-size: 13px;
                font-weight: 500;
                font-family: var(--burido-header-font-family);
                .comment-edit-link {
                    padding-left: 5px;
                    color: inherit;
                    &:hover {
                        color: var(--burido-secondary-color);
                    }
                }
                .woocommerce-Reviews &,
                ~ .meta-data {
                    float: right;
                    transform: translateY(8px);
                    @media (max-width: 992px) {
                        float: none;
                        width: 100%;
                        transform: none;
                    }
                }
            }
        }
        .comment_author_says {
            line-height: 1.5;
            font-size: 16px;
            font-family: var(--burido-header-font-family);
            font-weight: 600;
            letter-spacing: -0.03em;
            a, span {
                color: var(--burido-header-font-color);
                font: inherit;
                transition: all 0.4s;
                letter-spacing: inherit;
            }
            a:hover{
                color: var(--burido-secondary-color);
            }
        }
        .comment_content {
            margin-top: 0;
            line-height: 28px;
            font-size: 14px;
            &:last-child{
                margin-bottom: 11px;
            }
            > ul,
            > ol {
                padding-bottom: 20px;
            }
            p:last-child {
                margin-bottom: 0;
            }
        }
    }
    .comment-reply-link {
        display: inline-flex;
        align-items: center;
        justify-content: space-between;
        position: relative;
        z-index: 1;
        font-size: 14px;
        font-weight: 600;
        line-height: 1;
        font-family: var(--burido-header-font-family);
        white-space: nowrap;
        letter-spacing: 0.05em;
        margin-top: 11px;
        padding: 2px 0;
        max-width: 100%;
        color: var(--burido-secondary-color);
        transition: 0.4s;
        &::before {
            content: '';
            position: absolute;
            z-index: 0;
            bottom: 3px;
            left: -1px;
            width: calc(100% + 2px);
            height: 4px;
            background: var(--burido-primary-color);
            transition: 0.4s;
        }
        > span{
            white-space: normal;
            transition: padding .4s;
            display: inline-block;
            position: relative;
        }
        &:hover {
            color: var(--burido-secondary-color);
            &::before {
                height: 13px;
            }
        }
    }
    #cancel-comment-reply-link {
        text-transform: capitalize;
        opacity: 0.8;
    }
    small {
        #cancel-comment-reply-link {
            font-size: 18px;
            margin-left: 10px;
            line-height: inherit;
        }
    }
    ol.commentlist > li {
        &.trackback,
        &.pingback {
            &:first-child {
                margin-top: 26px;
            }
        }
    }
}

body .comment-respond {
    .comment-reply-title {
        font-size: 30px;
        line-height: 1.333em;
        margin-bottom: 10px;
        letter-spacing: var(--burido-h4-letter-spacing);
        @media (max-width: 767px) {
            font-size: 20px;
        }
    }
    .comment-form {
        margin-left: -15px;
        margin-right: -15px;
        [class*='wgl_col-'],
        > p {
            position: relative;
            padding-left: 15px;
            padding-right: 15px;
        }
        [class*='wgl_col-'] {
            + .form-submit {
                padding-top: 2px;
            }
        }
        .logged-in-as {
            margin-bottom: 13px;
            font-size: 14px;
        }
    }
    label {
        position: relative;
        margin: 0;
        font-size: 14px;
    }
    .form_field {
        width: 100%;
    }
    textarea.form_field {
        resize: none;
    }

    &#respond .form-submit {
        .wgl-button{
            pointer-events: none;
            border-style: solid;
            input.submit,
            input#submit{
                position: relative;
                pointer-events: auto;
                color: inherit;
                z-index: 4;
            }
            &:hover{
                color: #ffffff;
            }
        }
    }
}
body .comment-form-cookies-consent {
    clear: both;
    padding-bottom: 8px;
    > input,
    > label,
    > span {
        display: inline-block;
    }
    > input {
        margin-right: 7px;
        &[type='checkbox'] + label{
            display: inline;
        }
    }
}
.wp-block-latest-comments {
    & > li {
        padding-left: 0;
    }
}
.blog-post_content {
    ol.wp-block-latest-comments {
        &.has-avatars {
            margin-left: 0;
            padding-left: 0;
            list-style: none;
            li::before {
                display: none;
            }
        }

        &:not(.has-excerpts):not(.has-avatars) li {
            article {
                display: inline-block;
            }
        }
    }
}
