/* ==================== ##Counter ==================== */

.wgl-counter {
    font-size: 0;
    position: relative;
    z-index: 1;
    .media-wrap {
        display: inline-block;
    }
    &__value-wrap {
        display: inline-block;
        color: var(--burido-primary-color);
        font-weight: normal;
        letter-spacing: -0.02em;
        font-size: 96px;
        line-height: 1;
    }
    &__value-inner {
        display: flex;
        width: 100%;
    }
    &__placeholder-wrap {
        font-weight: inherit;
        position: relative;
        white-space: nowrap;
    }
    &__value {
        position: absolute;
        z-index: 2;
        top: 0;
        right: 0;
    }
    &__placeholder {
        display: block;
        visibility: hidden;
    }
    &__prefix {
        text-align: right;
    }
    &__suffix {
        text-align: left;
    }
    &_title {
        position: relative;
        font-size: 22px;
        font-family: var(--burido-content-font-family);
        font-weight: 600;
        color: var(--burido-header-font-color);
        line-height: 1.363em;
        margin-top: 14px;
        z-index: 2;
    }
    &_content {
        font-size: 16px;
        margin-top: 6px;
    }
    &_divider {
        width: 100%;
        height: 1px;
        background: var(--burido-secondary-color);
        flex-shrink: 0;
        margin: 0 0 21px;
    }
    &.title-inline {
        .wgl-counter__value-inner{
            margin: 0;
        }
        .content-wrap {
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .wgl-counter_title{
            margin-top: -6px;
            margin-left: 30px;
        }
        .wgl-counter_divider {
            width: 1px;
            height: auto;
            margin: 0 -2px 0 18px;
            align-self: stretch;
        }
    }
    &.title-top {
        .content-wrap {
            display: flex;
            flex-direction: column-reverse;
        }
    }
    .wgl-icon {
        color: var(--burido-primary-color);
        &:hover{
            color: var(--burido-primary-color);
        }
    }
}
body{
    @mixin wgl-counter-responsive($media) {
        .elementor-widget-wgl-counter {
            &.a#{$media} {
                &left {
                    .wgl-counter_title {
                        text-align: left;
                    }
                    .title-inline {
                        .content-wrap {
                            justify-content: flex-start;
                        }
                    }
                }
                &right {
                    .wgl-counter_title {
                        text-align: right;
                    }
                    .title-inline {
                        .content-wrap {
                            justify-content: flex-end;
                        }
                    }
                }
                &center {
                    .wgl-counter_title {
                        text-align: center;
                    }
                    .title-inline {
                        .content-wrap {
                            justify-content: center;
                        }
                    }
                }
            }
        }
    }
    @include wgl-counter-responsive('');
    &:not(
        [data-elementor-device-mode="widescreen"],
        [data-elementor-device-mode="desktop"]
    ) {
        @include wgl-counter-responsive('-tablet');
    }
    &:is(
        [data-elementor-device-mode="mobile_extra"],
        [data-elementor-device-mode="mobile"]
    ) {
        @include wgl-counter-responsive('-mobile');
    }
}
