/* ==================== #Gallery ==================== */
.widget_media_gallery {
    .title-wrapper {
        margin-bottom: 27px;
    }
}
[class*='widget'][class*='media_gallery'] { //* either "widget-media_gallery" or "widget_media_gallery"
    .gallery {
        display: flex;
        flex-wrap: wrap;
        align-items: flex-start;
        margin: -8px -5px -5px -5px;
        &-item {
            margin: 0;
            .gallery-icon {
                position: relative;
                z-index: 1;
                margin: 5px;
                > a {
                    display: block;
                    border-radius: 0;
                    img {
                        transition: 0.4s;
                    }
                    &::before {
                        content: '';
                        position: absolute;
                        z-index: 1;
                        width: 100%;
                        height: 100%;
                        left: 0;
                        top: 0;
                        opacity: 0;
                        transition: 0.4s;
                        background-color: var(--burido-primary-color);
                        border-radius: inherit;
                    }
                    &::after {
                        display: block;
                        content: "";
                        mask-image: var(--burido-search-h);
                        mask-position: center center;
                        mask-size: 1em;
                        mask-repeat: no-repeat;
                        width: 1em;
                        height: 1em;
                        padding: 0;
                        box-shadow: none;
                        background-color: currentColor;
                        font-style: normal;
                        font-variant: normal;
                        text-transform: none;
                        line-height: 0;
                        font-size: 22px;
                        transition: .4s;
                        position: absolute;
                        z-index: 2;
                        opacity: 0;
                        left: 50%;
                        top: 50%;
                        color: var(--burido-secondary-color);
                        transform: translate(-50%,-50%);
                    }
                    &:hover {
                        img {
                            border-radius: 15px;
                        }
                        &::before {
                            opacity: 1;
                            border-radius: 15px;
                        }
                        &::after {
                            opacity: 1;
                        }
                    }
                }
            }
            img {
                border: 0;
                border-radius: inherit;
            }
        }
        @for $i from 1 through 9 {
            &-columns-#{$i} .gallery-item{
                width: calc(100% / #{$i});
            }
        }
        .gallery-caption {
            display: none;
        }
    }
}
.blog-post_content {
    .gallery {
        display: flex;
        flex-wrap: wrap;
        align-items: flex-start;
        margin: 10px -5px 20px;
        &-item {
            margin: 0;
            .gallery-icon {
                margin: 5px;
                text-align: center;
            }
        }
        @for $i from 1 through 9 {
            &-columns-#{$i} .gallery-item{
                width: calc(100% / #{$i});
            }
        }
        &-caption {
            margin-left: 0;
        }
    }
}