/* ==================== ##Carousel Navigation ==================== */

//* Swiper Arrows
.wgl-carousel_wrapper {
    position: relative;
    .elementor-swiper-button,
    .motion-arrow {
        --wgl-swiper-button-diameter: 60px;
        display: block;
        position: relative;
        right: unset;
        left: unset;
        top: unset;
        margin: unset;
        width: var(--wgl-swiper-button-diameter);
        height: var(--wgl-swiper-button-diameter);
        padding: 0;
        line-height: 0.5em;
        font-size: 26px;
        font-weight: normal;
        letter-spacing: unset;
        border: 1px solid transparent;
        text-align: center;
        text-indent: unset;
        background-color: rgba(var(--burido-secondary-rgb), 1);
        box-shadow: unset;
        cursor: pointer;
        transition: all 0.4s, transform 0.15s;
        transform: unset;
        border-radius: 50%;
        color: rgba(var(--burido-tertiary-rgb), 1);
        @media (max-width: 767px) {
            --wgl-swiper-button-diameter: 40px;
            font-size: 22px;
        }
        &.swiper-button-disabled {
            opacity: 0.6;
        }
        &:not(.swiper-button-disabled) {
            &:hover {
                color: rgba(var(--burido-secondary-rgb), 1);
                background-color: rgba(var(--burido-primary-rgb), 1);
            }
        }
        span{
            display: none;
            position: absolute;
            bottom: 100%;
            color: inherit;
            font-family: var(--burido-content-font-family);
            font-size: 13px;
			font-weight: var(--burido-header-font-weight);
            line-height: 1.85em;
            letter-spacing: 0.2em;
            text-align: center;
            left: -100px;
            right: -100px;
            pointer-events: none;
            &::before{
                content: '';
                position: absolute;
                top: 0;
                right: 0;
                bottom: 0;
                left: 0;
                width: var(--wgl-swiper-button-diameter);
                pointer-events: auto;
                margin: auto;
            }
        }
    }
    .elementor-swiper-button-next,
    .motion-next {
        i{
            display: inline-block;
            transform: rotate(-45deg);
        }
    }
    .elementor-swiper-button-prev,
    .motion-prev {
        i{
            display: inline-block;
            transform: rotate(-45deg) scale(-1);
        }
    }
    .swiper-pagination.swiper-pagination-fraction {
        font-size: 16px;
        line-height: 1.35;
        color: var(--burido-header-font-color);
        font-family: var(--burido-header-font-family);
        font-weight: var(--burido-header-font-weight);
        .swiper-pagination-current {
            margin-right: -1px;
        }
        .swiper-pagination-total {
            margin-left: -2px;
        }
    }
    .swiper-slide {
        font-size: initial;
        transition: .4s;
    }
    .wgl-carousel.appear-animation{
        .swiper-slide:not(.swiper-slide-duplicate) {
            opacity: 0;
            &.animate{
                opacity: 1;
            }
        }
    }
    .burido_carousel_list {
        overflow: hidden;
    }
    .wgl-navigation_wrapper{
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        pointer-events: none;
        display: flex;
        align-items: flex-start;
        justify-content: flex-end;
        gap: 8px;
        z-index: 1;
        .elementor-swiper-button,
        .motion-arrow {
            pointer-events: auto;
        }
    }
    .wgl-carousel_inner_wrapper{
        overflow: hidden;
    }
}

//* swiper Dots
div.swiper-pagination{
    .swiper-pagination-bullet{
        button{
            display: none;
        }
    }
}
body .wgl-carousel_wrapper {
    --wgl-gap: 0;
    font-size: 0;
    .swiper-container:not(.swiper-container-initialized),
    .swiper:not(.swiper-initialized) {
        .swiper-wrapper {
            gap: unset;
            overflow: unset;
        }
    }
    .swiper-pagination-bullet{
        width: auto;
        height: auto;
        border-radius: 0;
        background: initial;
        opacity: 1;
    }
    .swiper-container-horizontal{
        > .swiper-pagination-bullets{
            bottom:0;
            width: max-content;
        }
    }
    .wgl-swiper-pagination-wrapper{
        display: inline-block;
        width: 100%;
        padding: 0 15px;
    }
    .swiper-pagination {
        position: relative;
        z-index: 2;
        margin: 30px 0 0;
        padding: 0;
        display: block;
        width: auto;
        bottom: unset !important;
        left: unset;
        &:not(.swiper-pagination-fraction) {
            line-height: 0;
            font-size: 0;
        }
        .swiper-pagination-bullet {
            display: inline-block;
            vertical-align: middle;
            margin: 0;
            padding: 6px;
            font-size: 0;
            line-height: 0;
            list-style: none;
            opacity: 1;
            cursor: pointer;
            transition: 0.4s;
            button {
                display: inline-block;
                position: relative;
                z-index: 1;
                font-size: 0;
                line-height: 0;
                padding: 0;
                margin: 0;
                border: 0;
                vertical-align: bottom;
                transition: inherit;
                background-color: var(--burido-content-color);
                &:focus {
                    outline: none;
                }
                &::before {
                    transition: .4s;
                }
            }
            &-active{
                button {
                    background-color: var(--burido-tertiary-color);
                }
            }
            &:first-child {
                margin-left: 0;
            }
            &:last-child {
                margin-right: 0;
            }
            &:only-child{
                display: none;
            }
        }
        &-fraction {
            font-size: 16px;
            font-weight: var(--burido-header-font-weight);
            font-family: var(--burido-header-font-family);
            min-height: 1em;
            line-height: 1;
            color: #9e9eca;
            .swiper-pagination-current {
                margin-right: -0.25em;
            }
            .swiper-pagination-total {
                margin-left: -0.25em;
            }
        }

        &.swiper-pagination-bullets-dynamic{
            left: unset !important;
            transform: unset !important;
            .swiper-pagination-bullet{
                transition: 0.4s !important;
            }
        }
        &.swiper-pagination-progressbar{
            height: 1px;
            padding: 0;
            background-color: rgba(var(--burido-secondary-rgb),0.15);
            transform: unset !important;
            max-width: unset !important;
            .swiper-pagination-progressbar-fill{
                background-color: var(--burido-secondary-color);
            }
        }
    }
    .pagination {
        &_circle {
            .swiper-pagination li {
                padding: 0 5px;
                button {
                    border-radius: 50%;
                    width: 12px;
                    height: 12px;
                    background: rgba(var(--burido-secondary-rgb), 0.4);
                    opacity: 1;
                    transform: scale(0.5);
                }
                &:hover,
                &.swiper-pagination-bullet-active{
                    button {
                        transform: scale(1);
                        background: var(--burido-secondary-color);
                    }
                }
            }
        }
        &_circle_border {
            .swiper-pagination {
                li {
                    margin: 0;
                    padding: 0 5px;
                    button {
                        border-radius: 50%;
                        width: 9px;
                        height: 9px;
                        border-width: 1px;
                        border-style: solid;
                        border-color: var(--burido-secondary-color);
                        background: transparent;
                        opacity: 1;
                        &::before {
                            content: '';
                            display: block;
                            position: absolute;
                            top: 50%;
                            left: 50%;
                            width: 9px;
                            height: 9px;
                            margin-top: -4.5px;
                            margin-left: -4.5px;
                            border-radius: 50%;
                            background-color: var(--burido-secondary-color);
                            opacity: 0;
                            transform: scale(0);
                        }
                    }
                    &:hover,
                    &.swiper-pagination-bullet-active{
                        border-color: transparent;
                        button {
                            border-color: var(--burido-secondary-color);
                            &::before{
                                opacity: 1;
                                transform: scale(1);
                            }
                        }
                    }
                }
            }
        }
        &_square_border {
            .swiper-pagination li {
                margin: 0;
                padding: 0;
                button {
                    width: 31px;
                    height: 31px;
                    border-width: 2px;
                    border-style: solid;
                    border-color: transparent;
                    border-radius: unset;
                    background-color: transparent;
                    &::before {
                        content: '';
                        display: block;
                        position: absolute;
                        top: 50%;
                        left: 50%;
                        width: 6px;
                        height: 6px;
                        margin-top: -3px;
                        margin-left: -3px;
                        border-radius: unset;
                        background-color: #CECECE;
                    }
                }
                &:hover,
                &.swiper-pagination-bullet-active{
                    button::before {
                        background-color: var(--burido-secondary-color);
                    }
                }
                &.swiper-pagination-bullet-active button{
                    border-color: var(--burido-secondary-color);
                }
            }
        }
        &_line {
            .swiper-pagination {
                min-height: unset;
                padding: 0 calc(0.5 * var(--wgl-gap));
                max-width: 100%;
                margin-left: auto;
                margin-right: auto;
                zoom: 1.01;
                li {
                    margin: 0;
                    padding: 5px;
                    &:first-child{
                        margin-left: -5px;
                    }
                    &:last-child{
                        margin-right: -5px;
                    }
                    button {
                        width: 20px;
                        height: 3px;
                        opacity: 1;
                        background-color: rgba(var(--burido-secondary-rgb), 0.365);
                    }
                    &.swiper-pagination-bullet-active button {
                        background-color: var(--burido-secondary-color);
                        width: 40px;
                    }
                }
            }
        }
        &_square {
            .swiper-pagination li {
                button {
                    width: 8px;
                    height: 8px;
                    border-radius: unset;
                }
            }
        }
        &_line_circle {
            .swiper-pagination {
                li {
                    margin: 0;
                    padding: 10px 5px;
                    zoom: 1.01;
                    button {
                        width: 6px;
                        height: 6px;
                        border-radius: 6px;
                    }
                    &.swiper-pagination-bullet-active button {
                        width: 25px;
                    }
                }
            }
        }
    }

    .variable-width{
        .swiper-slide{
            width: auto !important;
        }
    }

    .wgl-swiper-vertical {
        margin: 0;
        padding: 0;
        > .swiper-wrapper{
            flex-direction: column;
        }
        .swiper-slide {
            padding: calc(0.5 * var(--wgl-gap));
            display: flex;
            align-items: center;
            width: 100% !important;
        }
        .row.blog_carousel & {
            padding: 0 15px; // disable margin-left/right for .row.blog_carousel
        }
    }

    .animation-style-3d {
        &.animation-direction-vertical {
            height: 600px;
            perspective: 1000px;
            .wgl-carousel_wrap {
                height: 100%;
                transform: translateZ(-288px);
                transform-style: preserve-3d;
                transition: transform 1s;
                .wgl-item{
                    & > *{
                        pointer-events: auto;
                    }
                }
                .wgl-item,
                .testimonials__wrapper {
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    position: absolute;
                    height: 100%;
                    width: 100%;
                    margin: auto 0;
                    left: 0;
                    top: 0;
                    bottom: 0;
                    opacity: 0;
                    transition: transform 0.7s, opacity 1s;
                    pointer-events: none;
                    .testimonial__item,
                    .author__thumbnail {
                        pointer-events: auto;
                        cursor: pointer;
                    }
                    &.active {
                        opacity: 0.6;
                    }
                    &.current {
                        opacity: 1;
                        .testimonial__item,
                        .author__thumbnail {
                            cursor: default;
                        }
                    }
                    // prettier-ignore
                    & {
                        &:nth-child(1) { transform: rotateX(0deg) translateZ(288px); }
                        &:nth-child(2) { transform: rotateX(40deg) translateZ(288px); }
                        &:nth-child(3) { transform: rotateX(80deg) translateZ(288px); }
                        &:nth-child(4) { transform: rotateX(120deg) translateZ(288px); }
                        &:nth-child(5) { transform: rotateX(160deg) translateZ(288px); }
                        &:nth-child(6) { transform: rotateX(200deg) translateZ(288px); }
                        &:nth-child(7) { transform: rotateX(240deg) translateZ(288px); }
                        &:nth-child(8) { transform: rotateX(280deg) translateZ(288px); }
                        &:nth-child(9) { transform: rotateX(320deg) translateZ(288px); }
                    }
                    & > div {
                        background-color: var(--burido-content-color);
                    }
                }
            }
            .motion-prev {
                transform: rotate(-90deg);
            }
            .motion-next {
                transform: rotate(-90deg);
                order: -1;
            }
        }
        &.animation-direction-horizontal {
            height: 600px;
            perspective: 1000px;
            .wgl-carousel_wrap {
                height: 100%;
                transform: translateZ(-288px);
                transform-style: preserve-3d;
                transition: transform 1s;
                .wgl-item{
                    & > *{
                        pointer-events: auto;
                    }
                }
                .wgl-item,
                .testimonials__wrapper {
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    position: absolute;
                    height: fit-content;
                    width: 700px;
                    max-width: 100%;
                    margin: auto !important;
                    left: 0;
                    right: 0;
                    top: 0;
                    bottom: 0;
                    opacity: 0;
                    transition: transform 0.7s, opacity 1s;
                    pointer-events: none;
                    @media (min-width: 600px) {
                        max-width: 75%;
                        &.active {
                            opacity: 0.6;
                        }
                    }
                    &.current {
                        opacity: 1;
                        .testimonial__item {
                            cursor: default;
                        }
                    }
                    // prettier-ignore
                    & {
                        &:nth-child(1) { transform: rotateY(0deg) translateZ(288px); }
                        &:nth-child(2) { transform: rotateY(40deg) translateZ(288px); }
                        &:nth-child(3) { transform: rotateY(80deg) translateZ(288px); }
                        &:nth-child(4) { transform: rotateY(120deg) translateZ(288px); }
                        &:nth-child(5) { transform: rotateY(160deg) translateZ(288px); }
                        &:nth-child(6) { transform: rotateY(200deg) translateZ(288px); }
                        &:nth-child(7) { transform: rotateY(240deg) translateZ(288px); }
                        &:nth-child(8) { transform: rotateY(280deg) translateZ(288px); }
                        &:nth-child(9) { transform: rotateY(320deg) translateZ(288px); }
                    }
                    & > div {
                        background-color: var(--burido-content-color);
                    }
                }
            }
        }
    }
}

body:is(
    [data-elementor-device-mode='mobile_extra'],
    [data-elementor-device-mode='mobile']) {
    .wgl-carousel.animation-style-3d {
        &.animation-direction-vertical {
            .motion-arrow {
                display: none;
            }
        }
    }
}

.elementor-widget-wgl-carousel{
    .wgl-carousel_wrapper{
        margin: 0 calc(-0.5* var(--wgl-gap, 0px));
    }
    .swiper-slide{
        padding: 0 calc(0.5 * var(--wgl-gap, 0px));
    }
}