/* ==================== ##Widgets Base ==================== */

@use '../../mixins';

.widget_block h2,
.title-wrapper .title,
.sidebar [class*='berocket_'] h3{
    position: relative;
    display: block;
    z-index: 1;
    font-size: 20px;
    line-height: 1.3;
    color: var(--burido-header-font-color);
    font-family: var(--burido-header-font-family);
    letter-spacing: var(--burido-h4-letter-spacing);
    font-weight: 600;
    transition: 0.4s;
    letter-spacing: 0;
}

.widget {
    position: relative;
    &:not(:first-child) {
        padding-top: 40px;
    }
    &:last-child{
        margin-bottom: 40px;
    }
    .wp-block-group h2,
    .title-wrapper {
        margin: 0 0 20px;
        line-height: 1.3;
        .rsswidget img {
            margin-top: 6px;
        }
    }
    ul li {
        font-size: 16px;
        font-weight: 500;
        line-height: 30px;
        margin-bottom: 1px;
        transition: 0.3s;
        a {
            line-height: 24px;
            color: inherit;
        }
    }
    > ul {
        margin-top: 0;
        margin-bottom: 0;
        margin-left: 0;
        padding-bottom: 0;
        padding-left: 0;
    }
    > ul > li ul,
    > div > ul > li ul,
    > div > div > ul > li ul {
        padding-left: 15px;
    }
    ul li{
        @include mixins.widget_post_count;
    }

    /* ↓ Categories */
    &.widget_categories,
    &.widget_product_categories,
    &.widget_layered_nav,
    &.woocommerce-widget-layered-nav,
    &.widget_archive {
        ul {
            position: relative;
            margin-bottom: -7px;
            li {
                margin: 0;
                margin-bottom: 3px;
                @include mixins.list_widget_font;
                ul{
                    margin-bottom: 0;
                }
            }
        }
        .title-wrapper + ul {
            margin-top: -8px;
        }
    }
    &_product_categories {
        ul li img {
            margin-right: 13px;
        }
    }
    &_shopping_cart{
        .widget_shopping_cart_content{
            margin-top: 24px;
            margin-bottom: 4px;
        }
    }
    /* ↑ categories */
    &_recent_entries {
        > ul > li > a {
            position: relative;
            padding-left: 20px;
            &::before {
                content: '\f15b';
                font-family: 'Font Awesome 5 Free';
                font-size: 12px;
                font-weight: 600;
                position: absolute;
                line-height: 1;
                top: 4px;
                left: 0;
                transition: color .3s;
            }
        }
        ul li {
            .post-date {
                display: block;
                font-size: 0.8em;
            }
        }
    }
    &_rss {
        .title-wrapper {
            > a {
                position: relative;
                margin-bottom: 12px;
                padding-bottom: 12px;
                font-size: 20px;
                line-height: 1.4;
                font-weight: 500;
                text-align: center;
                text-transform: capitalize;
                img {
                    display: none;
                }
            }
        }
        ul {
            margin-left: 0;
            padding-left: 0;
            list-style: none;
        }
        li {
            padding: 18px 0 0 0;
            &:first-child {
                padding-top: 0;
            }
            .rsswidget {
                display: inline-block;
                font-size: 20px;
                line-height: 26px;
                font-weight: 500;
                margin-bottom: 10px;
            }
            .rss-date {
                display: block;
                margin: 0 0 9px;
                font-size: 14px;
                font-weight: 500;
                line-height: 22px;
                color: var(--burido-content-color);
                font-style: normal;
            }
            .rssSummary {
                line-height: 26px;
                font-weight: 400;
                font-size: 14px;
                margin-bottom: 8px;
            }
            cite {
                display: block;
                position: relative;
                margin-top: 0;
                font-size: 14px;
                line-height: 24px;
                font-style: normal;
                font-weight: 700;
                color: var(--burido-secondary-color);
                &::before {
                    content: '\2013';
                    margin-right: 5px;
                }
            }
        }
    }
    &_text {
        .textwidget {
            margin-top: -9px;
        }
    }
    ul.wp-block-latest-posts {
        li {
            padding-left: 0;
        }
    }
}
ul[class*='wp-block-'] li a {
    color: inherit;
}
.wp-block-rss {
    margin-left: 0;
    padding-left: 0;
    list-style-type: none;
    font-weight: 600;
    a {
        color: inherit;
    }
    .wp-block-rss{
        &__item {
            &:not(:last-child) {
                margin-bottom: 20px;
            }
        }
        &__item-excerpt {
            color: var(--burido-content-color);
        }
    }
}
.wp-block-categories-dropdown,
.wp-block-archives-dropdown {
    display: inline-block;
    position: relative;
    margin-bottom: 10px;
    width: 100%;
}

.widget_comments > ul,
.widget_meta > ul,
.widget_archive > ul,
.widget_recent_comments > ul,
ul.wp-block-archives {
    > li::before {
        transition: inherit;
    }
}

.widget_archive ul,
.widget_recent_entries ul,
.widget_categories ul,
.widget_product_categories ul,
.widget_layered_nav ul,
.widget_meta ul,
ul.wp-block-archives {
    list-style: none;
    ul {
        margin: 0;
        padding: 0;
    }
    li {
        ul li:last-child {
            border-bottom: 0;
        }
    }
}

.widget_categories ul,
.widget_product_categories ul,
.widget_layered_nav ul,
.widget_meta ul,
.widget_archive ul,
ul.wp-block-archives {
    li {
        img {
            max-width: 40px;
            margin-top: -4px;
            margin-right: 5px;
            vertical-align: middle;
        }
        ul li {
            img {
                display: none;
            }
        }
    }
}

//* ↓ Meta
.widget_meta.widget {
    > ul {
        li a {
            position: relative;
            padding-left: 20px;
            &::before {
                content: '\f02b';
                font-family: 'Font Awesome 5 Free';
                font-size: 12px;
                font-weight: 700;
                position: absolute;
                line-height: 1;
                top: 4px;
                left: 0;
                transition: color .3s;
            }
        }
    }
}
//* ↑ meta

//* ↓ Recent Comments
.widget_recent_comments {
    > ul {
        margin-top: -10px;
        margin-bottom: -6px;
        list-style: none;
        > li {
            &::before {
                content: '\f075';
                font-family: 'Font Awesome 5 Free';
                font-size: 12px;
                font-weight: 700;
                position: absolute;
                top: 10px;
                left: 0;
                line-height: 1;
            }
        }
    }
    ul li {
        position: relative;
        padding: 3px 0 3px 20px;
        line-height: 1.5;
    }
    a{
        display: inline !important;
    }
    a[rel~='external'] {
        text-decoration: underline;
    }
}
.widget .wp-block-latest-comments {
    margin-top: 5px;
    padding-bottom: 0;
}
.wp-block-latest-comments {
    padding-left: 0;
    > li {
        padding-left: 0;
        line-height: 1.3em;
        article{
            display: inline;
        }
    }
    &__comment {
        display: flex;
        align-items: flex-start;
        margin-bottom: 20px;
        gap: 15px;
        &::before{
            display: none;
        }
        .wp-block-latest-comments__comment-meta {
            font-weight: 700;
            color: var(--burido-header-font-color);
            display: inline;
            margin-left: 0 !important;
            a {
                color: inherit;
                &:hover {
                    color: var(--burido-secondary-color);
                }
            }
        }
        .avatar,
        .wp-block-latest-comments__comment-avatar {
            width: auto;
            height: auto;
            float: none;
        }
        .wp-block-latest-comments__comment-date {
            font-size: 14px;
            line-height: 22px;
            color: var(--burido-content-color);
            margin-top: 9px;
            margin-bottom: 11px;
            display: block;
        }
        .wp-block-latest-comments__comment-excerpt {
            margin-left: 0 !important;
            p:last-child {
                margin-bottom: 0;
            }
        }
    }
}
.wp-block-latest-posts__post-author,
.wp-block-latest-posts__post-date{
    font-size: 14px;
    line-height: 22px;
    color: var(--burido-content-color);
    margin-top: 5px;
}
//* ↑ recent comments

ul.wp-block-latest-posts {
    margin-left: 0;
    padding: 0;
    list-style: none;
    li {
        position: relative;
        &:not(:first-child) {
            margin-top: 15px;
        }
        & > a {
            display: block;
            font-size: 16px;
            line-height: 24px;
            font-weight: 500;
            color: inherit;
            padding-left: 20px;
            &::before{
                content: '\f15b';
                font-family: 'Font Awesome 5 Free';
                font-size: 12px;
                font-weight: 600;
                position: absolute;
                line-height: 1;
                top: 6px;
                left: 0;
                transition: color .3s;
            }
        }
    }
    .wp-block-latest-posts__featured-image {
        margin-bottom: 10px;
    }
    .wp-block-latest-posts__post-excerpt {
        margin-bottom: 25px;
    }
    &.is-grid{
        li{
            margin: 0 20px 20px 0;
        }
    }
}
ul.wp-block-archives.wp-block-archives-list,
ul.wp-block-categories.wp-block-categories-list {
    li {
        margin: 0;
        @include mixins.list_widget_font;
        ul{
            margin-bottom: 0;
        }
        @include mixins.widget_post_count;
    }
}
.widget ul.wp-block-archives {
    padding: 0;
}
ul.wp-block-archives {
    padding: 0;
    padding-bottom: 20px;
    position: relative;
}
ul.wp-block-categories {
    position: relative;
    &,
    ul {
        list-style: none;
        margin: 0;
        padding: 0;
    }
}

//* ↓ Sidebar|Footer
aside,
footer {
    select {
        margin-bottom: 0;
    }
    .widget_calendar {
        margin-bottom: -13px;
    }
}
//* ↑ sidebar|footer