/* ==================== ##Info Box ==================== */

@property --ib-icon-clr-first {
    syntax: '<color>';
    initial-value: #fff;
    inherits: false;
}

@property --ib-icon-clr-sec {
    syntax: '<color>';
    initial-value: #000;
    inherits: false;
}
.elementor-widget-wgl-info-box {
    &.wgl-view-bubble{
        .wgl-infobox{
            .media-wrapper .wgl-icon,
            .wgl-number .number,
            .wgl-image-box_img{
                z-index: -1;
                &::after{
                    content: '';
                    position: absolute;
                    top: 0;
                    left: 0;
                    z-index: -1;
                    border-radius: 50%;
                    transition: 0.4s;
                    background-color: var(--burido-primary-color);
                }
            }
        }
        &:hover{
            .media-wrapper .wgl-icon,
            .wgl-number .number,
            .wgl-image-box_img {
                &::after {
                    background-color: var(--burido-tertiary-color);
                }
            }
        }
    }

    .wgl-icon {
        position: relative;
        width: 1em;
        height: 1em;
        box-sizing: content-box;
        fill: var(--burido-header-font-color);
        color: var(--burido-header-font-color);
        &::before{
            transition: --ib-icon-clr-first .4s, --ib-icon-clr-sec .4s;
        }

    }
    .elementor-widget-container {
        position: relative;
        .wgl-infobox__link {
            position: absolute;
            z-index: 2;
            width: 100%;
            height: 100%;
            left: 0;
            top: 0;
        }
        &::before,
        &::after{
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            border-radius: inherit;
            transition: inherit;
            pointer-events: none;
        }
        &::before {
            opacity: 0;
        }
        .wgl-infobox__link + .wgl-infobox_wrapper{
            .button-read-more{
                transition: all 0.4s;
            }
        }
        &:hover{
            &::before{
                opacity: 1;
            }
            .wgl-infobox_bg_text{
                color: rgba(var(--burido-header-rgb), 0.4);
            }
            .number-wrapper::after{
                background-color: rgba(var(--burido-header-rgb), 1);
            }
        }
    }
    .wgl-infobox {
        transition: 0.4s;
        height: 100%;
        .wgl-infobox_button {
            &.image{
                padding-left: 0;
                margin-right: 0;
            }
            &.no_media{
                --wgl-icon-gap: 0;
            }
            .wgl-infobox_button__media{
                transition: all .4s;
                display: inline-block;
                order: -1;
            }
            &:hover{
                .wgl-infobox_button__media{
                    opacity: 1;
                }
            }
        }
        .wgl-infobox_wrapper {
            display: flex;
            position: relative;
            z-index: 1;
            height: 100%;
        }
        .wgl-infobox_title {
            position: relative;
            z-index: 1;
            font-size: 22px;
            line-height: 1.64em;
            font-weight: var(--burido-header-font-weight);
            word-break: break-word;
            transition: 0.4s;
            a{
                font: inherit;
                line-height: inherit;
                text-transform: inherit;
                letter-spacing: inherit;
            }
            .wgl-infobox_title-idle{
                display: block;
                font: inherit;
                color: inherit;
                line-height: inherit;
                text-transform: inherit;
                letter-spacing: inherit;
            }
            i{
                display: inline-block;
                vertical-align: middle;
                &:not(:only-child){
                    margin: 0 0.7em;
                }
            }
        }
        .media-wrapper{
            max-width: 100%;
            font-size: 0;
            line-height: 1;
        }
        .wgl-image-box_img{
            display: inline-block;
            max-width: 100%;
            & > span{
                display: block;
            }
        }
        .wgl-infobox-title_wrapper {
            position: relative;
            display: block;
            font-size: 0;
            &::after{
                content: '';
                display: none;
                width: 100%;
                margin: 21px 0 12px 0;
                background-color: var(--burido-header-font-color);
                transition: background-color .4s;
            }
        }
        .content_wrapper{
            display: flex;
            flex-direction: column;
            width: 100%;
        }
        .wgl-infobox_content {
            font-size: 15px;
            line-height: 2em;
            position: relative;
            transition: 0.4s;
            z-index: 1;
            p:last-child {
                margin-bottom: 0;
            }
        }
        .wgl-infobox_subtitle {
            font-family: var(--burido-header-font-family);
            font-size: 18px;
            font-weight: var(--burido-header-font-weight);
            line-height: 1.3em;
            color: var(--burido-header-font-color);
            text-transform: uppercase;
            letter-spacing: var(--burido-h3-letter-spacing);
            transition: 0.4s;
        }
        .wgl-infobox_bg_text{
            position: absolute;
            display: block;
            top: 0; right: 0; bottom: 0; left: 0;
            font-family: var(--burido-header-font-family);
            font-weight: var(--burido-header-font-weight);
            font-size: 200px;
            letter-spacing: var(--burido-h3-letter-spacing);
            color: rgba(var(--burido-header-rgb), 0.15);
            line-height: 1em;
            height: fit-content;
            margin: auto;
            pointer-events: none;
            transition: --ib-icon-clr-first .4s, --ib-icon-clr-sec .4s, color .4s, background-color .4s;
        }
        .wgl-infobox-button_wrapper{
            width: 100%;
            .wgl-infobox_button{
                &.corner-attached{
                    position: absolute;
                    left: 0;
                    bottom: 0;
                    &.corner-position_right{
                        left: auto;
                        right: 0;
                    }
                }
            }
        }
        .number-wrapper{
            &::after{
                content: '';
                display: none;
                margin: -8px 0 30px 0;
                background-color: rgba(var(--burido-header-rgb), 0.15);
                width: auto;
                height: 1px;
                transition: .4s;
            }
        }
        .wgl-layout-left,
        .wgl-layout-right{
            .number-wrapper {
                display: flex;
                flex-direction: row;
                height: fit-content;
                &::after{
                    height: auto;
                    width: 1px;
                    margin: 0 10px 0 10px;
                }
            }
        }
        .wgl-layout-right{
            .number-wrapper::after{
                order: -1;
            }
        }
        .wgl-layout-top{
            .media-wrapper{
                width: 100%;
            }
        }
        .wgl-layout-top_left,
        .wgl-layout-top_right{
            .media-wrapper,
            .wgl-infobox_title-idle{
                display: inline-block;
            }
        }
        .wgl-number{
            font-family: var(--burido-additional-font-family);
            font-weight: 400;
            font-size: 90px;
            line-height: 1em;
            color: var(--burido-primary-color);
            width: unset;
            height: auto;
            transition: all .4s, transform 0s;
        }
        .wgl-image-box_img{
            position: relative;
        }
    }
    .wgl-infobox_bg_wrapper{
        position: absolute;
        top: 0; right: 0; bottom: 0; left: 0;
        border-radius: inherit;
        pointer-events: none;
        z-index: 1;
        &::before,
        &::after{
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            border-radius: inherit;
            transition: inherit;
            z-index: -1;
            pointer-events: none;
        }
    }
    &.animation {
        &_lifting {
            padding-top: 20px;
            transition: 0.5s;
            > .elementor-widget-container {
                position: relative;
                transform: translateY(0);
                will-change: transform;
                transition: 0.5s;
            }
            &:hover {
                > .elementor-widget-container {
                    transform: translateY(-10px);
                }
            }
        }
        &_toggling {
            .wgl-infobox_content{
                --dur: 0.6s;
                --dur_half: calc(var(--dur) * 0.5);
                --max-height: 250px;
                overflow: hidden;
                opacity: 0;
                max-height: 0;
                transition: all var(--dur), opacity var(--dur_half);
            }
            &:hover{
                .wgl-infobox_content {
                    opacity: 1;
                    max-height: var(--max-height);
                    transition: all var(--dur), opacity var(--dur_half) var(--dur_half);
                }
            }
        }
        &_toggling_icon {
            .content_wrapper {
                transition: 0.4s;
            }
            .media-wrapper {
                position: absolute;
                z-index: 1;
                left: 0;
                transition: 0.4s;
                opacity: 0;
                transform: translateX(-10px) scale(0.5);
            }
            .elementor-widget-container {
                &:hover .wgl-infobox{
                    .media-wrapper {
                        opacity: 1;
                        transform: translateX(0) scale(1);
                    }
                }
            }
        }
    }
    &.bg_animation{
        &-borders {
            .wgl-infobox {
                &::before,
                &::after {
                    content: '';
                    position: absolute;
                    top: 0;
                    right: 0;
                    bottom: 0;
                    left: 0;
                    opacity: 0;
                    border-radius: inherit;
                    transition: all .6s ease-in-out, opacity .4s .2s ease-in-out;
                    transform: scale(1, 1);
                    color: var(--burido-primary-color);
                    z-index: 3;
                    pointer-events: none;
                }
                &::before {
                    border-top: 1px solid currentColor;
                    border-bottom: 1px solid currentColor;
                    transform: scale(1.15, .85);
                }
                &::after {
                    border-right: 1px solid currentColor;
                    border-left: 1px solid currentColor;
                    transform: scale(.85, 1.15);
                }
            }
            .elementor-widget-container:hover {
                .wgl-infobox{
                    &::before,
                    &::after {
                        opacity: 1;
                        transform: scale(1, 1);
                        transition: all .7s ease-in-out;
                    }
                }
            }
        }
        &-gradient {
            .wgl-infobox {
                &::before {
                    content: '';
                    position: absolute;
                    top: -2560px;
                    right: -2560px;
                    bottom: -2560px;
                    left: -2560px;
                    margin: auto;
                    z-index: 1;
                    opacity: 0;
                    pointer-events: none;
                    transition: all .4s;
                }
            }
            .elementor-widget-container:hover {
                .wgl-infobox{
                    &::before {
                        opacity: 1;
                    }
                }
            }
        }
    }

    &.button_{
        &left .wgl-infobox-button_wrapper{
            text-align: left;
        }
        &center .wgl-infobox-button_wrapper{
            text-align: center;
        }
        &right .wgl-infobox-button_wrapper{
            text-align: right;
        }
        &left,
        &center,
        &right {
            .wgl-button {
                width: auto;
            }
            .button__content{
                justify-content: center;
                width: auto;
            }
        }
        &justify {
            .wgl-button {
                width: 100%;
            }
            .button__content{
                justify-content: center;
                width: auto;
            }
        }
        &space-around,
        &space-evenly,
        &space-between {
            .wgl-button,
            .button__content{
                width: 100%;
            }
        }
        &space-around {
            .button__content{
                justify-content: space-around;
            }
        }
        &space-evenly {
            .button__content{
                justify-content: space-evenly;
            }
        }
        &space-between {
            .button__content{
                justify-content: space-between;
            }
        }
    }
}

body:is( [data-elementor-device-mode='widescreen'], [data-elementor-device-mode='desktop']) .enable-rotation-yes,
body:is( [data-elementor-device-mode='tablet_extra'], [data-elementor-device-mode='tablet']) .enable-rotation-tablet-yes,
body:is( [data-elementor-device-mode='mobile_extra'], [data-elementor-device-mode='mobile']) .enable-rotation-mobile-yes{
    &.elementor-widget-wgl-info-box .wgl-number {
        transform: scale(-1);
        writing-mode: vertical-rl;
    }
}
