/* ==================== ##Pricing Table ==================== */

.wgl-pricing_plan {
    position: relative;
    z-index: 1;
    margin-left: auto;
    margin-right: auto;
    &.hover-animation {
        padding-top: 20px;
        .pricing__wrapper {
            transform: translateY(0);
        }
        &:hover .pricing__wrapper {
            transform: translateY(-20px);
        }
    }
    .pricing__wrapper {
        position: relative;
        background-size: cover;
        background-position: center;
        transition: 0.5s;
        background: #fff;
        border: 1px solid #DEDEDE;
        &::before,
        &::after{
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            border-radius: inherit;
            transition: inherit;
            z-index: -1;
            pointer-events: none;
        }
    }
    .pricing__header {
        position: relative;
        z-index: 2;
        line-height: 0;
    }
    .pricing__pretitle {
        position: absolute;
        top: 0;
        right: 0;
        z-index: 2;
        .pretitle {
            position: relative;
            display: inline-block;
            font-family: var(--burido-content-font-family);
            font-weight: 500;
            font-size: 14px;
            line-height: 1.5em;
            letter-spacing: 0;
            color: var(--burido-header-font-color);
            transition: 0.4s;
        }
    }
    .pricing__title {
        position: relative;
        font-family: var(--burido-header-font-family);
        font-weight: 600;
        font-size: 14px;
        line-height: 1.25;
        letter-spacing: 0.01em;
        text-transform: uppercase;
        transition: 0.4s;

        .title__prefix {
            display: inline-block;
            text-align: center;
            font: inherit;
            transition: inherit;
        }
        .title__suffix {
            font: inherit;
            transition: inherit;
        }
        .title {
            position: relative;
            display: inline-block;
            font: inherit;
            line-height: inherit;
            letter-spacing: inherit;
            color: inherit;
            text-transform: inherit;
            transition: none;
            z-index: 1;
        }
    }
    .pricing__price {
        display: inline-flex;
        align-items: flex-end;
        font-family: var(--burido-header-font-family);
        font-weight: 400;
        font-size: 64px;
        line-height: 1.25em;
        letter-spacing: -0.04em;
        color: var(--burido-header-font-color);
        transition: .4s;
        .price__value {
            position: relative;
            z-index: 1;
            font: inherit;
            line-height: inherit;
            color: inherit;
            vertical-align: baseline;
            text-decoration: inherit;
        }
        .price__period {
            font-family: var(--burido-header-font-family);
            font-weight: 500;
            font-size: 20px;
            line-height: 1.2em;
            display: inline-block;
            position: relative;
            letter-spacing: -0.03em;
            max-width: 100%;
        }
        .price__currency {
            font-size: inherit;
            font-weight: inherit;
        }
        .price__currency_right {
            font-weight: inherit;
        }
    }
    .pricing__content {
        position: relative;
        color: var(--burido-header-font-color);
        transition: .4s;
        z-index: 2;
        ul {
            word-break: break-word;
            &:last-child {
                padding-bottom: 0;
            }
            &[class*='burido_'] {
                display: flex;
                flex-direction: column;
            }
            li {
                &[style*='color']::before {
                    color: inherit;
                }
                i {
                    margin-right: 10px;
                }
                b {
                    color: var(--burido-header-font-color);
                }
            }
        }
        p {
            margin-bottom: 20px;
        }
    }
    .pricing__description {
        position: relative;
        font-size: 32px;
        font-weight: 700;
        line-height: 1.4;
        z-index: 2;
        transition: .4s;
    }
    .pricing__thumbnail{
        position: relative;
        z-index: 2;
    }
    .pricing__bg_text{
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        font-family: var(--burido-additional-font-family);
        font-weight: var(--burido-additional-font-weight);
        font-size: 128px;
        line-height: 1em;
        transition: 0.4s;
        max-width: 100%;
        max-height: 100%;
        pointer-events: none;
        margin: 28px 0 0 -12px;
    }
    .mask_image {
        height: auto !important;
        width: fit-content !important;
        -webkit-mask-size: contain;
        -webkit-mask-position: center center;
        -webkit-mask-repeat: no-repeat;
        overflow: hidden;
        margin: auto !important;
        transition: .4s;
        img{
            visibility: hidden;
        }
    }
    .pricing__creeping_line{
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        display: flex;
        font-size: 16px;
        font-family: var(--burido-header-font-family);
        font-weight: 600;
        line-height: 1.5em;
        letter-spacing: 0.05em;
        color: var(--burido-header-font-color);
        padding: 0 9px 0 7px;
        background-color: var(--burido-primary-color);
        text-transform: uppercase;
        overflow: hidden;
        writing-mode: vertical-rl;
        transform: rotate(180deg);
        .pricing__creeping_line__inner{
            animation: wgl_creeping_line 60s linear infinite;
            white-space: nowrap;
            display: flex;
            width: fit-content;
            span{
                padding-bottom: 15px;
            }
        }
    }
    .pricing__button {
        position: relative;
        z-index: 2;
    }
    .wgl-button {
        display: inline-flex;
        justify-content: center;
    }
    @keyframes wgl_creeping_line {
        0% {
            transform: translateY(0);
        }

        100% {
            transform: translateY(-100%);
        }
    }
}
// ↓ Alignment
body {
    @mixin wgl-pricing-content-responsive($media) {
        .elementor-widget-wgl-pricing-table {
            &.a#{$media}left {
                .pricing__content ul {
                    align-items: flex-start;
                }
            }
            &.a#{$media}center {
                .pricing__content ul {
                    align-items: center;
                }
            }
            &.a#{$media}right {
                .pricing__content ul {
                    align-items: flex-end;
                }
            }
        }
    }
    @mixin wgl-pricing-button-responsive($media) {
        .elementor-widget-wgl-pricing-table {
            &.button-align#{$media}-left {
                .pricing__button {
                    text-align: left;
                }
                .wgl-button {
                    width: auto;
                }
                .button__content{
                    justify-content: center;
                    width: auto;
                }
            }
            &.button-align#{$media}-center {
                .pricing__button {
                    text-align: center;
                }
                .wgl-button {
                    width: auto;
                }
                .button__content{
                    justify-content: center;
                    width: auto;
                }
            }
            &.button-align#{$media}-right {
                .pricing__button {
                    text-align: right;
                }
                .wgl-button {
                    width: auto;
                }
                .button__content{
                    justify-content: center;
                    width: auto;
                }
            }
            &.button-align#{$media}-justify {
                .pricing__button {
                    text-align: center;
                }
                .wgl-button {
                    width: 100%;
                }
                .button__content{
                    justify-content: center;
                    width: auto;
                }
            }
            &.button-align#{$media}-space-between {
                .pricing__button {
                    text-align: center;
                }
                .wgl-button {
                    width: 100%;
                }
                .button__content{
                    justify-content: space-between;
                    width: 100%;
                }
            }
        }
    }
    @include wgl-pricing-content-responsive('');
    @include wgl-pricing-button-responsive('');
    &:not([data-elementor-device-mode='widescreen'],[data-elementor-device-mode='desktop']) {
        @include wgl-pricing-content-responsive('-tablet');
        @include wgl-pricing-button-responsive('-tablet');
    }
    &:is(
        [data-elementor-device-mode='mobile_extra'],
        [data-elementor-device-mode='mobile']) {
        @include wgl-pricing-content-responsive('-mobile');
        @include wgl-pricing-button-responsive('-mobile');
    }
}
