/* ==================== ##Accordion ==================== */

.wgl-accordion {
    .wgl-accordion {
        &_content::after {
            content: '';
            clear: both;
            display: block;
        }
        &_header {
            display: flex;
            align-items: center;
            position: relative;
            width: 100%;
            font-family: var(--burido-header-font-family);
            font-weight: 500;
            font-size: 22px;
            line-height: 1.64em;
            letter-spacing: -0.02em;
            cursor: pointer;
            text-transform: none;
            transition: 0.4s;
            color: var(--burido-header-font-color);
            &::before{
                content: '';
                position: absolute;
                left: -100vw;
                right: -100vw;
                top: 0;
                bottom: 0;
                pointer-events: auto;
            }
            .wgl-accordion_icon {
                --icon-size: 24px;
                font-size: var(--icon-size);
                font-weight: normal;
                border: unset;
                padding: 0;
                color: var(--burido-header-font-color);
                fill: currentColor;
                transition: 0.4s, --icon-size 0s;
                &::before{
                    width: 1em;
                    height: 1em;
                    line-height: 1em;
                    display: block;
                }
            }
        }
        &_title {
            font: inherit;
            color: inherit;
            line-height: inherit;
            letter-spacing: inherit;
            transition: 0.4s;
            &-prefix {
                margin-right: 5px;
                font-size: inherit;
                line-height: inherit;
                font-weight: inherit;
                color: inherit;
                text-transform: inherit;
            }
        }
        &_content {
            display: none;
            width: 100%;
            font-size: 14px;
            line-height: 28px;
            p:last-child {
                margin-bottom: 0;
            }
        }
        &_panel {
            display: flex;
            flex-direction: column;
            align-items: center;
            position: relative;
            --acc-delimiter-size: 0;
            --acc-delimiter-color: var(--burido-header-font-color);
            transition: border-radius .4s, background .4s;
            &:last-child::before{
                --acc-delimiter-color-last: var(--acc-delimiter-color);
                border-bottom: var(--acc-delimiter-size, 1px) solid var(--acc-delimiter-color-last, transparent);
            }
            &::before{
                content: '';
                position: absolute;
                top: 0;
                right: 0;
                bottom: 0;
                left: 0;
                border-top: var(--acc-delimiter-size, 1px) solid var(--acc-delimiter-color, transparent);
                pointer-events: none;
                z-index: 1;
            }
            &::after{
                content: '';
                position: absolute;
                top: 0;
                right: 0;
                bottom: 0;
                left: 0;
                z-index: -2;
                pointer-events: none;
                transition: .4s;
            }
            &:first-child {
                margin-top: 0 !important;
            }
            &:last-child {
                margin-bottom: 0 !important;
            }
            &.active{
                .wgl-accordion_panel-inner::before {
                    opacity: 1;
                }
            }
            &-inner{
                max-width: 100%;
                &::before{
                    content: '';
                    position: absolute;
                    top: 0;
                    right: 0;
                    bottom: 0;
                    left: 0;
                    pointer-events: none;
                    opacity: 0;
                    z-index: -1;
                    transition: .4s;
                }
            }
        }
    }

    &_title-link{
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        z-index: 1;
        pointer-events: none;
        .wgl-accordion_panel.active & {
            pointer-events: auto;
        }
    }

    &.icon-plus,
    &.icon-plus_bold {
        .wgl-accordion_panel {
            .wgl-accordion_icon {
                --icon-width: 2px;
                position: relative;
                z-index: 1;
                height: var(--icon-size);
                width: var(--icon-size);
                min-width: var(--icon-size);
                box-sizing: content-box;
                &::before,
                &::after {
                    content: '';
                    display: block;
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    background-color: currentColor;
                    transform: rotate(90deg);
                    transition: transform .4s;
                }
                &::before {
                    width: inherit;
                    height: var(--icon-width);
                    margin: calc(-0.5 * var(--icon-width)) 0 0 calc(-0.5 * var(--icon-size));
                }
                &::after {
                    width: var(--icon-width);
                    height: inherit;
                    margin: calc(-0.5 * var(--icon-size)) 0 0 calc(-0.5 * var(--icon-width));
                }
            }
            &.active {
                .wgl-accordion_icon {
                    &::before,
                    &::after {
                        transform: rotate(-90deg);
                    }
                    &::before {
                        opacity: 0;
                    }
                }
            }
        }
    }
    &.icon-plus_bold{
        .wgl-accordion_panel {
            .wgl-accordion_icon {
                --icon-width: 5px;
                &::before,
                &::after {
                    border-radius: 2px;
                }
            }
        }
    }
}
