/* ==================== ##Image Hotspots ==================== */

@mixin tt-top-l {
    top: initial;
    right: 100%;
    bottom: 100%;
    left: initial;
    transform: unset;
}
@mixin tt-top {
    top: initial;
    right: initial;
    bottom: 100%;
    left: 50%;
    transform: translateX(-50%);
}
@mixin tt-top-r {
    top: initial;
    right: initial;
    bottom: 100%;
    left: 100%;
    transform: unset;
}
@mixin tt-right {
    top: 50%;
    right: initial;
    bottom: initial;
    left: 100%;
    transform: translateY(-50%);
}
@mixin tt-bottom-r {
    top: 100%;
    right: initial;
    bottom: initial;
    left: 100%;
    transform: unset;
}
@mixin tt-bottom {
    top: 100%;
    right: initial;
    bottom: initial;
    left: 50%;
    transform: translateX(-50%);
}
@mixin tt-bottom-l {
    top: 100%;
    right: 100%;
    bottom: initial;
    left: initial;
    transform: unset;
}
@mixin tt-left {
    top: 50%;
    right: 100%;
    bottom: initial;
    left: initial;
    transform: translateY(-50%);
}
@mixin hotspots-positions {
    &-top_l {
        .hotspot__tooltip { @include tt-top-l; }
        .tooltip__wrapper {
            margin: 0 10px 10px 0;
            &::after { display: none; }
        }
    }
    &-top {
        .hotspot__tooltip { @include tt-top; }
        .tooltip__wrapper {
            margin-bottom: 20px;
            &::after {
                left: 50%;
                bottom: 14px;
                transform: translateX(-50%) rotate(45deg);
            }
        }
    }
    &-top_r {
        .hotspot__tooltip { @include tt-top-r; }
        .tooltip__wrapper {
            margin: 0 0 10px 10px;
            &::after { display: none; }
        }
    }
    &-right {
        .hotspot__tooltip { @include tt-right; }
        .tooltip__wrapper {
            margin-left: 20px;
            &::after {
                top: 50%;
                left: 14px;
                transform: translateY(-50%) rotate(45deg);
            }
        }
    }
    &-bottom_r {
        .hotspot__tooltip { @include tt-bottom-r; }
        .tooltip__wrapper {
            margin: 10px 0 0 10px;
            &::after { display: none; }
        }
    }
    &-bottom {
        .hotspot__tooltip { @include tt-bottom; }
        .tooltip__wrapper {
            margin-top: 20px;
            &::after {
                left: 50%;
                top: 14px;
                transform: translateX(-50%) rotate(45deg);
            }
        }
    }
    &-bottom_l {
        .hotspot__tooltip { @include tt-bottom-l; }
        .tooltip__wrapper {
            margin: 10px 10px 0 0;
            &::after { display: none; }
        }
    }
    &-left {
        .hotspot__tooltip { @include tt-left; }
        .tooltip__wrapper {
            margin-right: 20px;
            &::after {
                top: 50%;
                right: 14px;
                transform: translateY(-50%) rotate(45deg);
            }
        }
    }
}
@mixin tooltips-hover {
    visibility: hidden;
    .tooltip__wrapper {
        opacity: 0;
        visibility: inherit;
    }
}
@mixin tooltips-hover-h {
    opacity: 1;
    visibility: visible;
    transition: 0.4s;
    .tooltip__wrapper {
        opacity: inherit;
        visibility: inherit;
        transition: inherit;
    }
}

.wgl-image-hotspots {
    display: inline-block;
    position: relative;
    z-index: 1;
    .hotspots {
        &_image-wrap {
            display: inline-block;
        }
        &__container {
            position: absolute;
            z-index: 1;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            &.appear_animation {
                .hotspots__item {
                    opacity: 0;
                    visibility: hidden;
                    transition: 1.4s;
                    &.appeared {
                        opacity: 1;
                        visibility: visible;
                    }
                }
            }
            &.loop_animation {
                &-pulse {
                    .hotspots__item {
                        animation: 5s both running infinite hotspots_pulse;
                    }
                }
                &-flash {
                    .hotspots__item {
                        animation: 5s both running infinite hotspots_flash;
                    }
                }
                &-zoom {
                    .hotspots__item {
                        animation: 5s both running infinite hotspots_zoom;
                    }
                }
                &-shake {
                    .hotspots__item {
                        animation: 5s both running infinite hotspots_shake;
                    }
                }
                &-swing {
                    .hotspots__item {
                        animation: 5s both running infinite hotspots_swing;
                    }
                }
                &-rubber {
                    .hotspots__item {
                        animation: 5s both running infinite hotspots_rubber;
                    }
                }
                .hotspots__item:hover {
                    animation-play-state: paused;
                }
            }
        }
        &__item {
            line-height: 1em;
            position: absolute;
            cursor: pointer;
            &:hover {
                .desktop-tooltips-hover {
                    @include tooltips-hover-h;
                }
                @media (max-width: 1024px) {
                    .tablet-tooltips-hover {
                        @include tooltips-hover-h;
                    }
                }
                @media (max-width: 767px) {
                    .mobile-tooltips-hover {
                        @include tooltips-hover-h;
                    }
                }
                .animation {
                    &-zoom {
                        .tooltip__wrapper {
                            transform: scale3d(1, 1, 1);
                        }
                    }
                    &-to_left,
                    &-to_top,
                    &-to_right,
                    &-to_bottom {
                        .tooltip__wrapper {
                            transform: translate(0);
                        }
                    }
                    &-shake {
                        .tooltip__wrapper {
                            animation: tooltips_shake 0.4s forwards;
                        }
                    }
                }
                .hotspots_point-icon.default {
                    transform: translate(-50%, -50%) scale(1.553);
                }
            }
        }

        &_media-wrap {
            transition: 0.4s;
        }
        &_point-wrap {
            display: flex;
            align-items: center;
            transition: 0.4s;
        }
        &_point-icon {
            line-height: 0;
            width: 1em;
            display: block;
            text-align: center;

            &.default {
                content: '';
                position: absolute;
                top: 50%;
                left: 50%;
                width: clamp(1px, 16.08%, 20px);
                height: clamp(1px, 16.08%, 20px);
                border-radius: 50%;
                background-color: #ffffff;
                transform: translate(-50%, -50%);
                transition: inherit;
            }

            svg {
                width: 1em;
                height: 1em;
                display: block;
            }
        }
        &_point-text {
            margin: 0;
            line-height: 1;
            transition: 0.4s;
        }
    }

    .hotspots__item {
        &.tt-desktop {
            @include hotspots-positions;
        }
        &.m-desktop {
            &-left {
                .hotspots_point-wrap {
                    flex-direction: row;
                }
            }
            &-top {
                .hotspots_point-wrap {
                    flex-direction: column;
                }
            }
            &-right {
                .hotspots_point-wrap {
                    flex-direction: row-reverse;
                }
            }
            &-bottom {
                .hotspots_point-wrap {
                    flex-direction: column-reverse;
                }
            }
        }
        @media (max-width: 1024px) {
            &.tt-tablet {
                @include hotspots-positions;
            }
            &.m-tablet {
                &-left {
                    .hotspots_point-wrap {
                        flex-direction: row;
                    }
                }
                &-top {
                    .hotspots_point-wrap {
                        flex-direction: column;
                    }
                }
                &-right {
                    .hotspots_point-wrap {
                        flex-direction: row-reverse;
                    }
                }
                &-bottom {
                    .hotspots_point-wrap {
                        flex-direction: column-reverse;
                    }
                }
            }
        }
        @media (max-width: 767px) {
            &.tt-mobile {
                @include hotspots-positions;
            }
            &.m-mobile {
                &-left {
                    .hotspots_point-wrap {
                        flex-direction: row;
                    }
                }
                &-top {
                    .hotspots_point-wrap {
                        flex-direction: column;
                    }
                }
                &-right {
                    .hotspots_point-wrap {
                        flex-direction: row-reverse;
                    }
                }
                &-bottom {
                    .hotspots_point-wrap {
                        flex-direction: column-reverse;
                    }
                }
            }
        }
    }
    .hotspots__item {
        &.tt-c-desktop {
            @include hotspots-positions;
        }
        @media (max-width: 1024px) {
            &.tt-c-tablet {
                @include hotspots-positions;
            }
        }
        @media (max-width: 767px) {
            &.tt-c-mobile {
                @include hotspots-positions;
            }
        }
    }

    .hotspot__tooltip {
        position: absolute;
        z-index: 1;
        pointer-events: none;
        transition: 0.2s;
        .tooltip__wrapper {
            font-size: 14px;
            font-weight: 500;
            transition: 0.2s;
            p {
                &:last-child {
                    margin-bottom: 0;
                }
                &:last-of-type {
                    display: inline;
                }
            }

            .tooltip__icon {
                display: inline-block;
                margin-left: 12px;
            }

            &::after {
                width: 20px;
                height: 20px;
                background: inherit;
                position: absolute;
                z-index: -1;
                pointer-events: none;
            }
        }
        &.desktop-tooltips {
            &-hover {
                @include tooltips-hover;
            }
            &-show {
                @include tooltips-hover-h;
            }
        }
        @media (max-width: 1024px) {
            &.tablet-tooltips {
                &-hover {
                    @include tooltips-hover;
                }
                &-show {
                    @include tooltips-hover-h;
                }
            }
        }
        @media (max-width: 767px) {
            &.mobile-tooltips {
                &-hover {
                    @include tooltips-hover;
                }
                &-show {
                    @include tooltips-hover-h;
                }
            }
        }
        &.animation {
            &-zoom {
                .tooltip__wrapper {
                    transform: scale3d(0.1, 0.1, 0.1);
                }
            }
            &-to_left {
                .tooltip__wrapper {
                    transform: translateX(20px);
                }
            }
            &-to_top {
                .tooltip__wrapper {
                    transform: translateY(20px);
                }
            }
            &-to_right {
                .tooltip__wrapper {
                    transform: translateX(-20px);
                }
            }
            &-to_bottom {
                .tooltip__wrapper {
                    transform: translateY(-20px);
                }
            }
        }
    }
    .hotspots_link {
        &:hover {
            .hotspot__tooltip {
                pointer-events: all;
            }
        }
    }
}

@keyframes tooltips_shake {
    0% {
        transform: rotate(2deg) translateY(9px);
    }
    50% {
        transform: rotate(-3deg) translateY(6px);
    }
    70% {
        transform: rotate(3deg) translateY(3px);
    }
    100% {
        transform: rotate(0deg) translateY(0);
    }
}
@keyframes hotspots_pulse {
    0%,
    89%,
    to {
        transform: scale3d(1, 1, 1);
    }

    90%,
    94%,
    98% {
        transform: scale3d(1.1, 1.1, 1.1);
    }

    92%,
    96% {
        transform: scale3d(0.9, 0.9, 0.9);
    }
}
@keyframes hotspots_flash {
    0%,
    89%,
    to {
        opacity: 1;
    }

    90%,
    94%,
    98% {
        opacity: 0;
    }

    92%,
    96% {
        opacity: 1;
    }
}
@keyframes hotspots_shake {
    0%,
    89%,
    to {
        transform: translate3d(0, 0, 0);
    }

    90%,
    94%,
    98% {
        transform: translate3d(-5px, 0, 0);
    }

    92%,
    96% {
        transform: translate3d(5px, 0, 0);
    }
}
@keyframes hotspots_zoom {
    0%,
    86%,
    to {
        transform: scale3d(1, 1, 1);
    }

    87% {
        transform: scale3d(0.9, 0.9, 0.9) rotate3d(0, 0, 1, -3deg);
    }

    90%,
    94%,
    98% {
        transform: scale3d(1.1, 1.1, 1.1) rotate3d(0, 0, 1, 3deg);
    }

    92%,
    96% {
        transform: scale3d(1.1, 1.1, 1.1) rotate3d(0, 0, 1, -3deg);
    }
}
@keyframes hotspots_rubber {
    64% {
        transform: scale3d(1, 1, 1);
    }

    73% {
        transform: scale3d(1.25, 0.75, 1);
    }

    77% {
        transform: scale3d(0.75, 1.25, 1);
    }

    81% {
        transform: scale3d(1.15, 0.85, 1);
    }

    86% {
        transform: scale3d(0.95, 1.05, 1);
    }

    90% {
        transform: scale3d(1.05, 0.95, 1);
    }

    to {
        transform: scale3d(1, 1, 1);
    }
}
@keyframes hotspots_swing {
    0%,
    75%,
    to {
        transform: rotate3d(0, 0, 1, 0deg);
    }

    80% {
        transform: rotate3d(0, 0, 1, 15deg);
    }

    85% {
        transform: rotate3d(0, 0, 1, -10deg);
    }

    90% {
        transform: rotate3d(0, 0, 1, 5deg);
    }

    95% {
        transform: rotate3d(0, 0, 1, -5deg);
    }
}
