/* ==================== ##Services 1 ==================== */

.elementor-widget-wgl-service-1{
    .wgl-service_link {
        position: absolute;
        z-index: 4;
        width: 100%;
        height: 100%;
        left: 0;
        top: 0;
        &:hover{
            & ~ .wgl-service-1 {
                pointer-events: none;
                .read-more-icon::before {
                    transform: translateX(5px);
                }
            }
        }
    }
    .wgl-service-1 {
        position: relative;
        z-index: 1;
        overflow: hidden;
        border-radius: 0;
        &::before,
        &::after{
            content: '';
            position: absolute;
            top: 0; right: 0; bottom: 0; left: 0;
            border-radius: inherit;
            pointer-events: none;
            transition: inherit;
        }
    }
    .wgl-service_button-wrapper{
        z-index: 3;
        .wgl-service_button{
            .read-more-icon{
                text-align: center;
                display: inline-block;
                line-height: 0;
                transition: background-color .4s, color .4s, transform .4s;
                will-change: transform;
                border-radius: 0;
                box-sizing: content-box;
                &::before{
                    color: unset;
                    transition: transform 0.4s;
                }
            }
        }
    }
    &.height_full {
        height: 100%;
        .elementor-widget-container,
        .wgl-service-1{
            height: 100%;
        }
    }
    &.animation {
        &_stroke{
            .wgl-service_subtitle{
                -webkit-text-stroke: 1px transparent;
            }
        }
    }
}
.wgl-service-1 {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    .wgl-service {
        &_subtitle{
            position: relative;
            z-index: 2;
            font-size: 16px;
            line-height: 1.25em;
            color: var(--burido-tertiary-color);
            backface-visibility: hidden;
            transition: all .45s;
        }
        &_title{
            position: relative;
            z-index: 2;
            font-size: 36px;
            line-height: 1.333em;
            word-break: break-word;
            transition: 0.4s;
            color: var(--burido-tertiary-color);
            .service_title{
                font: inherit;
                line-height: inherit;
                color: inherit;
                letter-spacing: inherit;
                text-decoration: inherit;
                text-transform: inherit;
                position: relative;
                display: inline-block;
            }
        }
        &_description {
            color: var(--burido-tertiary-color);
        }
        &_bg_text {
            position: absolute;
            z-index: 1;
            top: 0; right: 0; bottom: 0; left: 0;
            font-family: var(--burido-header-font-family);
            font-weight: var(--burido-header-font-weight);
            font-size: 100px;
            letter-spacing: 0;
            line-height: 1em;
            max-width: 100%;
            max-height: 100%;
            pointer-events: none;
            color: inherit;
            text-transform: inherit;
            transition: 0.4s;
        }
        &_wrapper_description{
            --dur: 0.6s;
            --dur_half: calc(var(--dur) * 0.5);
            --max-height: 250px;
            position: relative;
            z-index: 2;
            overflow: hidden;
            .toggling_content & {
                opacity: 0;
                max-height: 0;
                transition: all var(--dur), opacity var(--dur_half);
            }
            .toggling_content .elementor-widget-container:hover & {
                opacity: 1;
                max-height: var(--max-height);
                transition: all var(--dur), opacity var(--dur_half) var(--dur_half);
            }
        }
    }
    .wgl-service_media {
        position: relative;
        z-index: 2;
        --dur: 0.6s;
        --dur_half: calc(var(--dur) * 0.5);
        .wgl-image-box_img{
            display: inline-block;
        }
        .toggling_image & {
            opacity: 0;
            max-height: 0;
            overflow: hidden;
            transition: all var(--dur), opacity var(--dur_half);
        }
        .toggling_image .elementor-widget-container:hover & {
            opacity: 1;
            max-height: var(--max-height);
            transition: all var(--dur), opacity var(--dur_half) var(--dur_half);
        }
    }
    .wgl-service_button{
        display: inline-flex;
        align-items: center;
        justify-content: space-between;
        position: relative;
        z-index: 1;
        font-size: 15px;
        font-weight: 500;
        line-height: 1;
        font-family: var(--burido-content-font-family);
        white-space: nowrap;
        letter-spacing: 0.01em;
    }
}

@mixin wgl-service-responsive($media) {
    body[data-elementor-device-mode='#{$media}'] {
        .elementor-widget-wgl-service-1.toggling_content .breakpoint_on-#{$media} .wgl-service_wrapper_description {
            opacity: 1;
            max-height: var(--max-height);
        }
        .elementor-widget-wgl-service-1.toggling_image .breakpoint_on-#{$media} .wgl-service_media {
            opacity: 1;
            max-height: var(--max-height);
        }
    }
}

@include wgl-service-responsive('widescreen');
@include wgl-service-responsive('desktop');
@include wgl-service-responsive('tablet_extra');
@include wgl-service-responsive('tablet');
@include wgl-service-responsive('mobile_extra');
@include wgl-service-responsive('mobile');