/* ==================== ##Rotated Text ==================== */
.elementor-widget-wgl-rotated-text{
	.elementor-widget-container{
		transform: rotate(180deg);
		writing-mode: vertical-rl;
	}
	&.hover_links {
		.rt__link{
			& + .rt__title-wrapper {
				.rt__title {
					text-decoration: underline transparent;
					transition: color 0.3s, text-decoration-color 0.3s;
					text-decoration-thickness: 0.05em;
				}
			}
		}
		.wgl-rotated_text {
			&:hover {
				.rt__link{
					& + .rt__title-wrapper {
						.rt__title {
							text-decoration-color: currentColor;
						}
					}
				}
			}
		}
	}
}
.wgl-rotated_text {
	display: flex;
	flex-wrap: wrap;
	justify-content: center;
	align-items: center;
	.rt__title-wrapper{
		font-family: var(--burido-header-font-family);
		font-weight: var(--burido-header-font-weight);
		.rt__title{
			font: inherit;
			line-height: inherit;
			text-transform: inherit;
			letter-spacing: inherit;
			transition: color .3s;
		}
	}
	.rt-title{
		color: var(--burido-header-font-color);
	}
	.rt__subtitle{
		font-size: 16px;
		line-height: 1.3em;
		transition: color .3s;
		color: var(--burido-tertiary-color);
		height: 100%;
	}
	.rt-title,
	.rt__subtitle{
		span{
			font-family: inherit;
			font-size: inherit;
			line-height: inherit;
			font-weight: inherit;
			text-transform: inherit;
			letter-spacing: inherit;
		}
	}
	.rt__link{
		position: absolute;
		top: 0;
		right: 0;
		bottom: 0;
		left: 0;
		display: block;
		z-index: 1;
	}
	.media-wrapper{
		line-height: 0;
		transition: .4s;
	}
}

body:is( [data-elementor-device-mode='widescreen'], [data-elementor-device-mode='desktop']) .disable-rotation-yes,
body:is( [data-elementor-device-mode='tablet_extra'], [data-elementor-device-mode='tablet']) .disable-rotation-tablet-yes,
body:is( [data-elementor-device-mode='mobile_extra'], [data-elementor-device-mode='mobile']) .disable-rotation-mobile-yes{
	&.elementor-widget-wgl-rotated-text .elementor-widget-container {
		transform: unset;
		writing-mode: unset;
		height: auto;
	}
}
